/* Base Completa — Civil M01–M15: lei seca recolhida da Teoria Guiada.
   Texto dos artigos extraído do Vade Mecum do site (tools/vade.html). Gerado automaticamente. */
(function(g){'use strict';g.BC_CIV_GUIDED_LAW={"1":{"0":[["CC, art. 1º",["Art. 1º Toda pessoa é capaz de direitos e deveres na ordem civil."]],["CC, art. 2º",["Art. 2º A personalidade civil da pessoa começa do nascimento com vida; mas a lei põe a salvo, desde a concepção, os direitos do nascituro."]],["CC, art. 3º",["Art. 3º São absolutamente incapazes de exercer pessoalmente os atos da vida civil os menores de 16 (dezesseis) anos. (Artigo com redação dada pela Lei nº 13.146, de 6/7/2015, publicada no DOU de 7/7/2015, em vigor 180 dias após a publicação)","I - (Revogado pela Lei nº 13.146, de 6/7/2015, publicada no DOU de 7/7/2015, em vigor 180 dias após a publicação)","II - (Revogado pela Lei nº 13.146, de 6/7/2015, publicada no DOU de 7/7/2015, em vigor 180 dias após a publicação)","III - (Revogado pela Lei nº 13.146, de 6/7/2015, publicada no DOU de 7/7/2015, em vigor 180 dias após a publicação)"]],["CC, art. 4º",["Art. 4º São incapazes, relativamente a certos atos ou à maneira de os exercer: (“Caput” do artigo com redação dada pela Lei nº 13.146, de 6/7/2015, publicada no DOU de 7/7/2015, em vigor 180 dias após a publicação)","I - os maiores de dezesseis e menores de dezoito anos;","II - os ébrios habituais e os viciados em tóxico; (Inciso com redação dada pela Lei nº 13.146, de 6/7/2015, publicada no DOU de 7/7/2015, em vigor 180 dias após a publicação)","III - aqueles que, por causa transitória ou permanente, não puderem exprimir sua vontade; (Inciso com redação dada pela Lei nº 13.146, de 6/7/2015, publicada no DOU de 7/7/2015, em vigor 180 dias após a publicação)","IV - os pródigos.","Parágrafo único. A capacidade dos indígenas será regulada por legislação especial. (Parágrafo único com redação dada pela Lei nº 13.146, de 6/7/2015, publicada no DOU de 7/7/2015, em vigor 180 dias após a publicação)"]]],"1":[["CC, art. 2º",["Art. 2º A personalidade civil da pessoa começa do nascimento com vida; mas a lei põe a salvo, desde a concepção, os direitos do nascituro."]]],"2":[["CC, art. 3º",["Art. 3º São absolutamente incapazes de exercer pessoalmente os atos da vida civil os menores de 16 (dezesseis) anos. (Artigo com redação dada pela Lei nº 13.146, de 6/7/2015, publicada no DOU de 7/7/2015, em vigor 180 dias após a publicação)","I - (Revogado pela Lei nº 13.146, de 6/7/2015, publicada no DOU de 7/7/2015, em vigor 180 dias após a publicação)","II - (Revogado pela Lei nº 13.146, de 6/7/2015, publicada no DOU de 7/7/2015, em vigor 180 dias após a publicação)","III - (Revogado pela Lei nº 13.146, de 6/7/2015, publicada no DOU de 7/7/2015, em vigor 180 dias após a publicação)"]],["CC, art. 4º",["Art. 4º São incapazes, relativamente a certos atos ou à maneira de os exercer: (“Caput” do artigo com redação dada pela Lei nº 13.146, de 6/7/2015, publicada no DOU de 7/7/2015, em vigor 180 dias após a publicação)","I - os maiores de dezesseis e menores de dezoito anos;","II - os ébrios habituais e os viciados em tóxico; (Inciso com redação dada pela Lei nº 13.146, de 6/7/2015, publicada no DOU de 7/7/2015, em vigor 180 dias após a publicação)","III - aqueles que, por causa transitória ou permanente, não puderem exprimir sua vontade; (Inciso com redação dada pela Lei nº 13.146, de 6/7/2015, publicada no DOU de 7/7/2015, em vigor 180 dias após a publicação)","IV - os pródigos.","Parágrafo único. A capacidade dos indígenas será regulada por legislação especial. (Parágrafo único com redação dada pela Lei nº 13.146, de 6/7/2015, publicada no DOU de 7/7/2015, em vigor 180 dias após a publicação)"]]],"3":[["CC, art. 5º",["Art. 5º A menoridade cessa aos dezoito anos completos, quando a pessoa fica habilitada à prática de todos os atos da vida civil.","Parágrafo único. Cessará, para os menores, a incapacidade:","I - pela concessão dos pais, ou de um deles na falta do outro, mediante instrumento público, independentemente de homologação judicial, ou por sentença do juiz, ouvido o tutor, se o menor tiver dezesseis anos completos;","II - pelo casamento;","III - pelo exercício de emprego público efetivo;","IV - pela colação de grau em curso de ensino superior;","V - pelo estabelecimento civil ou comercial, ou pela existência de relação de emprego, desde que, em função deles, o menor com dezesseis anos completos tenha economia própria."]]],"4":[["CC, art. 6º",["Art. 6º A existência da pessoa natural termina com a morte; presume-se esta, quanto aos ausentes, nos casos em que a lei autoriza a abertura de sucessão definitiva."]],["CC, art. 7º",["Art. 7º Pode ser declarada a morte presumida, sem decretação de ausência:","I - se for extremamente provável a morte de quem estava em perigo de vida;","II - se alguém, desaparecido em campanha ou feito prisioneiro, não for encontrado até dois anos após o término da guerra.","Parágrafo único. A declaração da morte presumida, nesses casos, somente poderá ser requerida depois de esgotadas as buscas e averiguações, devendo a sentença fixar a data provável do falecimento."]]],"5":[["CC, art. 8º",["Art. 8º Se dois ou mais indivíduos falecerem na mesma ocasião, não se podendo averiguar se algum dos comorientes precedeu aos outros, presumir-se-ão simultaneamente mortos."]]],"6":[["CC, art. 9º",["Art. 9º Serão registrados em registro público:","I - os nascimentos, casamentos e óbitos;","II - a emancipação por outorga dos pais ou por sentença do juiz;","III - a interdição por incapacidade absoluta ou relativa;","IV - a sentença declaratória de ausência e de morte presumida."]],["CC, art. 10",["Art. 10. Far-se-á averbação em registro público:","I - das sentenças que decretarem a nulidade ou anulação do casamento, o divórcio, a separação judicial e o restabelecimento da sociedade conjugal;","II - dos atos judiciais ou extrajudiciais que declararem ou reconhecerem a filiação;","III - (Revogado pela Lei nº 12.010, de 3/8/2009, publicada no DOU de 4/8/2009, em vigor 90 dias após a publicação)"]]],"7":[["CC, art. 11",["Art. 11. Com exceção dos casos previstos em lei, os direitos da personalidade são intransmissíveis e irrenunciáveis, não podendo o seu exercício sofrer limitação voluntária."]]],"8":[["CC, art. 16",["Art. 16. Toda pessoa tem direito ao nome, nele compreendidos o prenome e o sobrenome."]],["CC, art. 17",["Art. 17. O nome da pessoa não pode ser empregado por outrem em publicações ou representações que a exponham ao desprezo público, ainda quando não haja intenção difamatória."]],["CC, art. 18",["Art. 18. Sem autorização, não se pode usar o nome alheio em propaganda comercial."]],["CC, art. 19",["Art. 19. O pseudônimo adotado para atividades lícitas goza da proteção que se dá ao nome."]],["CC, art. 20",["Art. 20. Salvo se autorizadas, ou se necessárias à administração da justiça ou à manutenção da ordem pública, a divulgação de escritos, a transmissão da palavra, ou a publicação, a exposição ou a utilização da imagem de uma pessoa poderão ser proibidas, a seu requerimento e sem prejuízo da indenização que couber, se lhe atingirem a honra, a boa fama ou a respeitabilidade, ou se se destinarem a fins comerciais. (Vide ADIN nº 4.815/2012, publicada no DOU de 26/6/2015, p. 1)","Parágrafo único. Em se tratando de morto ou de ausente, são partes legítimas para requerer essa proteção o cônjuge, os ascendentes ou os descendentes."]],["CC, art. 21",["Art. 21. A vida privada da pessoa natural é inviolável, e o juiz, a requerimento do interessado, adotará as providências necessárias para impedir ou fazer cessar ato contrário a esta norma. (Vide ADIN nº 4.815/2012, publicada no DOU de 26/6/2015, p. 1)"]]],"9":[["CC, art. 13",["Art. 13. Salvo por exigência médica, é defeso o ato de disposição do próprio corpo, quando importar diminuição permanente da integridade física, ou contrariar os bons costumes.","Parágrafo único. O ato previsto neste artigo será admitido para fins de transplante, na forma estabelecida em lei especial."]],["CC, art. 14",["Art. 14. É válida, com objetivo científico, ou altruístico, a disposição gratuita do próprio corpo, no todo ou em parte, para depois da morte.","Parágrafo único. O ato de disposição pode ser livremente revogado a qualquer tempo."]],["CC, art. 15",["Art. 15. Ninguém pode ser constrangido a submeter-se, com risco de vida, a tratamento médico ou a intervenção cirúrgica."]]],"10":[["CC, art. 22",["Art. 22. Desaparecendo uma pessoa do seu domicílio sem dela haver notícia, se não houver deixado representante ou procurador a quem caiba administrar-lhe os bens, o juiz, a requerimento de qualquer interessado ou do Ministério Público, declarará a ausência, e nomear-lhe-á curador."]],["CC, art. 23",["Art. 23. Também se declarará a ausência, e se nomeará curador, quando o ausente deixar mandatário que não queira ou não possa exercer ou continuar o mandato, ou se os seus poderes forem insuficientes."]],["CC, art. 24",["Art. 24. O juiz, que nomear o curador, fixar-lhe-á os poderes e obrigações, conforme as circunstâncias, observando, no que for aplicável, o disposto a respeito dos tutores e curadores."]],["CC, art. 25",["Art. 25. O cônjuge do ausente, sempre que não esteja separado judicialmente, ou de fato por mais de dois anos antes da declaração da ausência, será o seu legítimo curador.","§ 1º Em falta do cônjuge, a curadoria dos bens do ausente incumbe aos pais ou aos descendentes, nesta ordem, não havendo impedimento que os iniba de exercer o cargo.","§ 2º Entre os descendentes, os mais próximos precedem os mais remotos.","§ 3º Na falta das pessoas mencionadas, compete ao juiz a escolha do curador."]],["CC, art. 26",["Art. 26. Decorrido um ano da arrecadação dos bens do ausente, ou, se ele deixou representante ou procurador, em se passando três anos, poderão os interessados requerer que se declare a ausência e se abra provisoriamente a sucessão."]],["CC, art. 27",["Art. 27. Para o efeito previsto no artigo anterior, somente se consideram interessados:","I - o cônjuge não separado judicialmente;","II - os herdeiros presumidos, legítimos ou testamentários;","III - os que tiverem sobre os bens do ausente direito dependente de sua morte;","IV - os credores de obrigações vencidas e não pagas."]],["CC, art. 28",["Art. 28. A sentença que determinar a abertura da sucessão provisória só produzirá efeito cento e oitenta dias depois de publicada pela imprensa; mas, logo que passe em julgado, proceder-se-á à abertura do testamento, se houver, e ao inventário e partilha dos bens, como se o ausente fosse falecido.","§ 1º Findo o prazo a que se refere o art. 26, e não havendo interessados na sucessão provisória, cumpre ao Ministério Público requerê-la ao juízo competente.","§ 2º Não comparecendo herdeiro ou interessado para requerer o inventário até trinta dias depois de passar em julgado a sentença que mandar abrir a sucessão provisória, proceder-se-á à arrecadação dos bens do ausente pela forma estabelecida nos arts. 1.819 a 1.823."]],["CC, art. 29",["Art. 29. Antes da partilha, o juiz, quando julgar conveniente, ordenará a conversão dos bens móveis, sujeitos a deterioração ou a extravio, em imóveis ou em títulos garantidos pela União."]],["CC, art. 30",["Art. 30. Os herdeiros, para se imitirem na posse dos bens do ausente, darão garantias da restituição deles, mediante penhores ou hipotecas equivalentes aos quinhões respectivos.","§ 1º Aquele que tiver direito à posse provisória, mas não puder prestar a garantia exigida neste artigo, será excluído, mantendo-se os bens que lhe deviam caber sob a administração do curador, ou de outro herdeiro designado pelo juiz, e que preste essa garantia.","§ 2º Os ascendentes, os descendentes e o cônjuge, uma vez provada a sua qualidade de herdeiros, poderão, independentemente de garantia, entrar na posse dos bens do ausente."]],["CC, art. 31",["Art. 31. Os imóveis do ausente só se poderão alienar, não sendo por desapropriação, ou hipotecar, quando o ordene o juiz, para lhes evitar a ruína."]],["CC, art. 32",["Art. 32. Empossados nos bens, os sucessores provisórios ficarão representando ativa e passivamente o ausente, de modo que contra eles correrão as ações pendentes e as que de futuro àquele forem movidas."]],["CC, art. 33",["Art. 33. O descendente, ascendente ou cônjuge que for sucessor provisório do ausente, fará seus todos os frutos e rendimentos dos bens que a este couberem; os outros sucessores, porém, deverão capitalizar metade desses frutos e rendimentos, segundo o disposto no art. 29, de acordo com o representante do Ministério Público, e prestar anualmente contas ao juiz competente.","Parágrafo único. Se o ausente aparecer, e ficar provado que a ausência foi voluntária e injustificada, perderá ele, em favor do sucessor, sua parte nos frutos e rendimentos."]],["CC, art. 34",["Art. 34. O excluído, segundo o art. 30, da posse provisória poderá, justificando falta de meios, requerer lhe seja entregue metade dos rendimentos do quinhão que lhe tocaria."]],["CC, art. 35",["Art. 35. Se durante a posse provisória se provar a época exata do falecimento do ausente, considerar-se-á, nessa data, aberta a sucessão em favor dos herdeiros, que o eram àquele tempo."]],["CC, art. 36",["Art. 36. Se o ausente aparecer, ou se lhe provar a existência, depois de estabelecida a posse provisória, cessarão para logo as vantagens dos sucessores nela imitidos, ficando, todavia, obrigados a tomar as medidas assecuratórias precisas, até a entrega dos bens a seu dono."]],["CC, art. 37",["Art. 37. Dez anos depois de passada em julgado a sentença que concede a abertura da sucessão provisória, poderão os interessados requerer a sucessão definitiva e o levantamento das cauções prestadas."]],["CC, art. 38",["Art. 38. Pode-se requerer a sucessão definitiva, também, provando-se que o ausente conta oitenta anos de idade, e que de cinco datam as últimas notícias dele."]],["CC, art. 39",["Art. 39. Regressando o ausente nos dez anos seguintes à abertura da sucessão definitiva, ou algum de seus descendentes ou ascendentes, aquele ou estes haverão só os bens existentes no estado em que se acharem, os sub-rogados em seu lugar, ou o preço que os herdeiros e demais interessados houverem recebido pelos bens alienados depois daquele tempo.","Parágrafo único. Se, nos dez anos a que se refere este artigo, o ausente não regressar, e nenhum interessado promover a sucessão definitiva, os bens arrecadados passarão ao domínio do Município ou do Distrito Federal, se localizados nas respectivas circunscrições, incorporando-se ao domínio da União, quando situados em território federal."]],["CC, art. 7º",["Art. 7º Pode ser declarada a morte presumida, sem decretação de ausência:","I - se for extremamente provável a morte de quem estava em perigo de vida;","II - se alguém, desaparecido em campanha ou feito prisioneiro, não for encontrado até dois anos após o término da guerra.","Parágrafo único. A declaração da morte presumida, nesses casos, somente poderá ser requerida depois de esgotadas as buscas e averiguações, devendo a sentença fixar a data provável do falecimento."]]]},"2":{"0":[["CC, art. 40",["Art. 40. As pessoas jurídicas são de direito público, interno ou externo, e de direito privado."]],["CC, art. 41",["Art. 41. São pessoas jurídicas de direito público interno:","I - a União;","II - os Estados, o Distrito Federal e os Territórios;","III - os Municípios;","IV - as autarquias, inclusive as associações públicas; (Inciso com nova redação dada pela Lei nº 11.107, de 6/4/2005)","V - as demais entidades de caráter público criadas por lei.","Parágrafo único. Salvo disposição em contrário, as pessoas jurídicas de direito público, a que se tenha dado estrutura de direito privado, regem-se, no que couber, quanto ao seu funcionamento, pelas normas deste Código."]],["CC, art. 42",["Art. 42. São pessoas jurídicas de direito público externo os Estados estrangeiros e todas as pessoas que forem regidas pelo direito internacional público."]],["CC, art. 43",["Art. 43. As pessoas jurídicas de direito público interno são civilmente responsáveis por atos dos seus agentes que nessa qualidade causem danos a terceiros, ressalvado direito regressivo contra os causadores do dano, se houver, por parte destes, culpa ou dolo."]],["CC, art. 44",["Art. 44. São pessoas jurídicas de direito privado:","I - as associações;","II - as sociedades;","III - as fundações.","IV - as organizações religiosas; (Inciso acrescido pela Lei nº 10.825, de 22/12/2003)","V - os partidos políticos; (Inciso acrescido pela Lei nº 10.825, de 22/12/2003)","VI - (Inciso acrescido pela Lei nº 12.441, de 11/7/2011, e revogado pela Medida Provisória nº 1.085, de 27/12/2021 , convertida na Lei nº 14.382, de 27/6/2022)","VII - os empreendimentos de economia solidária. (Inciso acrescido pela Lei nº 15.068, de 23/12/2024)","§ 1º São livres a criação, a organização, a estruturação interna e o funcionamento das organizações religiosas, sendo vedado ao poder público negar-lhes reconhecimento ou registro dos atos constitutivos e necessários ao seu funcionamento. (Parágrafo acrescido pela Lei nº 10.825, de 22/12/2003)","§ 2º As disposições concernentes às associações aplicam-se subsidiariamente aos empreendimentos de economia solidária e às sociedades que são objeto do Livro II da Parte Especial deste Código. (Parágrafo único transformado em § 2º pela Lei nº 10.825, de 22/12/2003 , e com redação dada pela Lei nº 15.068, de 23/12/2024)","§ 3º Os partidos políticos serão organizados e funcionarão conforme o disposto em lei específica. (Parágrafo acrescido pela Lei nº 10.825, de 22/12/2003)"]]],"1":[["CC, art. 45",["Art. 45. Começa a existência legal das pessoas jurídicas de direito privado com a inscrição do ato constitutivo no respectivo registro, precedida, quando necessário, de autorização ou aprovação do Poder Executivo, averbando-se no registro todas as alterações por que passar o ato constitutivo.","Parágrafo único. Decai em três anos o direito de anular a constituição das pessoas jurídicas de direito privado, por defeito do ato respectivo, contado o prazo da publicação de sua inscrição no registro."]],["CC, art. 51",["Art. 51. Nos casos de dissolução da pessoa jurídica ou cassada a autorização para seu funcionamento, ela subsistirá para os fins de liquidação, até que esta se conclua.","§ 1º Far-se-á, no registro onde a pessoa jurídica estiver inscrita, a averbação de sua dissolução.","§ 2º As disposições para a liquidação das sociedades aplicam-se, no que couber, às demais pessoas jurídicas de direito privado.","§ 3º Encerrada a liquidação, promover-se-á o cancelamento da inscrição da pessoa jurídica."]]],"2":[["CC, art. 49-A",["Art. 49-A. A pessoa jurídica não se confunde com os seus sócios, associados, instituidores ou administradores.","Parágrafo único. A autonomia patrimonial das pessoas jurídicas é um instrumento lícito de alocação e segregação de riscos, estabelecido pela lei com a finalidade de estimular empreendimentos, para a geração de empregos, tributo, renda e inovação em benefício de todos. (Artigo acrescido pela Lei nº 13.874, de 20/9/2019)"]]],"3":[["CC, art. 50",["Art. 50. Em caso de abuso da personalidade jurídica, caracterizado pelo desvio de finalidade ou pela confusão patrimonial, pode o juiz, a requerimento da parte, ou do Ministério Público quando lhe couber intervir no processo, desconsiderá-la para que os efeitos de certas e determinadas relações de obrigações sejam estendidos aos bens particulares de administradores ou de sócios da pessoa jurídica beneficiados direta ou indiretamente pelo abuso. (“Caput” do artigo com redação dada pela Medida Provisória nº 881, de 30/4/2019, convertida na Lei nº 13.874, de 20/9/2019)","§ 1º Para os fins do disposto neste artigo, desvio de finalidade é a utilização da pessoa jurídica com o propósito de lesar credores e para a prática de atos ilícitos de qualquer natureza. (Parágrafo acrescido pela Medida Provisória nº 881, de 30/4/2019, convertida e com redação dada pela Lei nº 13.874, de 20/9/2019)","§ 2º Entende-se por confusão patrimonial a ausência de separação de fato entre os patrimônios, caracterizada por:","I - cumprimento repetitivo pela sociedade de obrigações do sócio ou do administrador ou vice-versa;","II - transferência de ativos ou de passivos sem efetivas contraprestações, exceto os de valor proporcionalmente insignificante; e","III - outros atos de descumprimento da autonomia patrimonial. (Parágrafo acrescido pela Medida Provisória nº 881, de 30/4/2019, convertida na Lei nº 13.874, de 20/9/2019)","§ 3º O disposto no caput e nos §§ 1º e 2º deste artigo também se aplica à extensão das obrigações de sócios ou de administradores à pessoa jurídica. (Parágrafo acrescido pela Medida Provisória nº 881, de 30/4/2019, convertida na Lei nº 13.874, de 20/9/2019)","§ 4º A mera existência de grupo econômico sem a presença dos requisitos de que trata o caput deste artigo não autoriza a desconsideração da personalidade da pessoa jurídica. (Parágrafo acrescido pela Medida Provisória nº 881, de 30/4/2019, convertida na Lei nº 13.874, de 20/9/2019)","§ 5º Não constitui desvio de finalidade a mera expansão ou a alteração da finalidade original da atividade econômica específica da pessoa jurídica. (Parágrafo acrescido pela Medida Provisória nº 881, de 30/4/2019, convertida na Lei nº 13.874, de 20/9/2019)"]]],"4":[["CC, art. 41",["Art. 41. São pessoas jurídicas de direito público interno:","I - a União;","II - os Estados, o Distrito Federal e os Territórios;","III - os Municípios;","IV - as autarquias, inclusive as associações públicas; (Inciso com nova redação dada pela Lei nº 11.107, de 6/4/2005)","V - as demais entidades de caráter público criadas por lei.","Parágrafo único. Salvo disposição em contrário, as pessoas jurídicas de direito público, a que se tenha dado estrutura de direito privado, regem-se, no que couber, quanto ao seu funcionamento, pelas normas deste Código."]],["CC, art. 42",["Art. 42. São pessoas jurídicas de direito público externo os Estados estrangeiros e todas as pessoas que forem regidas pelo direito internacional público."]],["CC, art. 43",["Art. 43. As pessoas jurídicas de direito público interno são civilmente responsáveis por atos dos seus agentes que nessa qualidade causem danos a terceiros, ressalvado direito regressivo contra os causadores do dano, se houver, por parte destes, culpa ou dolo."]],["CF/88, art. 37",["Art. 37. A administração pública direta e indireta de qualquer dos Poderes da União, dos Estados, do Distrito Federal e dos Municípios obedecerá aos princípios de legalidade, impessoalidade, moralidade, publicidade e eficiência e, também, ao seguinte:","[…]","§ 6º As pessoas jurídicas de direito público e as de direito privado prestadoras de serviços públicos responderão pelos danos que seus agentes, nessa qualidade, causarem a terceiros, assegurado o direito de regresso contra o responsável nos casos de dolo ou culpa."]]],"5":[["CC, art. 53",["Art. 53. Constituem-se as associações pela união de pessoas que se organizem para fins não econômicos.","Parágrafo único. Não há, entre os associados, direitos e obrigações recíprocos."]],["CC, art. 54",["Art. 54. Sob pena de nulidade, o estatuto das associações conterá:","I - a denominação, os fins e a sede da associação;","II - os requisitos para a admissão, demissão e exclusão dos associados;","III - os direitos e deveres dos associados;","IV - as fontes de recursos para sua manutenção;","V - o modo de constituição e de funcionamento dos órgãos deliberativos; (Inciso com redação dada pela Lei nº 11.127, de 28/6/2005)","VI - as condições para a alteração das disposições estatutárias e para a dissolução.","VII - a forma de gestão administrativa e de aprovação das respectivas contas. (Inciso acrescido pela Lei nº 11.127, de 28/6/2005)"]],["CC, art. 55",["Art. 55. Os associados devem ter iguais direitos, mas o estatuto poderá instituir categorias com vantagens especiais."]]],"6":[["CC, art. 57",["Art. 57. A exclusão do associado só é admissível havendo justa causa, assim reconhecida em procedimento que assegure direito de defesa e de recurso, nos termos previstos no estatuto. (“Caput” do artigo com redação dada pela Lei nº 11.127, de 28/6/2005)","Parágrafo único. (Revogado pela Lei nº 11.127, de 28/6/2005)"]]],"7":[["CC, art. 62",["Art. 62. Para criar uma fundação, o seu instituidor fará, por escritura pública ou testamento, dotação especial de bens livres, especificando o fim a que se destina, e declarando, se quiser, a maneira de administrá-la.","Parágrafo único. A fundação somente poderá constituir-se para fins de: (“Caput” do parágrafo único com redação dada pela Lei nº 13.151, de 28/7/2015)","I - assistência social; (Inciso acrescido pela Lei nº 13.151, de 28/7/2015)","II - cultura, defesa e conservação do patrimônio histórico e artístico; (Inciso acrescido pela Lei nº 13.151, de 28/7/2015)","III - educação; (Inciso acrescido pela Lei nº 13.151, de 28/7/2015)","IV - saúde; (Inciso acrescido pela Lei nº 13.151, de 28/7/2015)","V - segurança alimentar e nutricional; (Inciso acrescido pela Lei nº 13.151, de 28/7/2015)","VI - defesa, preservação e conservação do meio ambiente e promoção do desenvolvimento sustentável; (Inciso acrescido pela Lei nº 13.151, de 28/7/2015)","VII - pesquisa científica, desenvolvimento de tecnologias alternativas, modernização de sistemas de gestão, produção e divulgação de informações e conhecimentos técnicos e científicos; (Inciso acrescido pela Lei nº 13.151, de 28/7/2015)","VIII - promoção da ética, da cidadania, da democracia e dos direitos humanos; (Inciso acrescido pela Lei nº 13.151, de 28/7/2015)","IX - atividades religiosas; e (Inciso acrescido pela Lei nº 13.151, de 28/7/2015)","X - (VETADO na Lei nº 13.151, de 28/7/2015)"]],["CC, art. 66",["Art. 66. Velará pelas fundações o Ministério Público do Estado onde situadas.","§ 1º Se funcionarem no Distrito Federal ou em Território, caberá o encargo ao Ministério Público do Distrito Federal e Territórios. (Parágrafo com redação dada pela Lei nº 13.151, de 28/7/2015)","§ 2º Se estenderem a atividade por mais de um Estado, caberá o encargo, em cada um deles, ao respectivo Ministério Público."]]],"8":[["CC, art. 63",["Art. 63. Quando insuficientes para constituir a fundação, os bens a ela destinados serão, se de outro modo não dispuser o instituidor, incorporados em outra fundação que se proponha a fim igual ou semelhante."]],["CC, art. 67",["Art. 67. Para que se possa alterar o estatuto da fundação é mister que a reforma:","I - seja deliberada por dois terços dos competentes para gerir e representar a fundação;","II - não contrarie ou desvirtue o fim desta;","III - seja aprovada pelo órgão do Ministério Público no prazo máximo de 45 (quarenta e cinco) dias, findo o qual ou no caso de o Ministério Público a denegar, poderá o juiz supri-la, a requerimento do interessado. (Inciso com redação dada pela Lei nº 13.151, de 28/7/2015)"]],["CC, art. 68",["Art. 68. Quando a alteração não houver sido aprovada por votação unânime, os administradores da fundação, ao submeterem o estatuto ao órgão do Ministério Público, requererão que se dê ciência à minoria vencida para impugná-la, se quiser, em dez dias."]],["CC, art. 69",["Art. 69. Tornando-se ilícita, impossível ou inútil a finalidade a que visa a fundação, ou vencido o prazo de sua existência, o órgão do Ministério Público, ou qualquer interessado, lhe promoverá a extinção, incorporando-se o seu patrimônio, salvo disposição em contrário no ato constitutivo, ou no estatuto, em outra fundação, designada pelo juiz, que se proponha a fim igual ou semelhante."]]],"9":[["CC, art. 70",["Art. 70. O domicílio da pessoa natural é o lugar onde ela estabelece a sua residência com ânimo definitivo."]],["CC, art. 71",["Art. 71. Se, porém, a pessoa natural tiver diversas residências, onde, alternadamente, viva, considerar-se-á domicílio seu qualquer delas."]],["CC, art. 72",["Art. 72. É também domicílio da pessoa natural, quanto às relações concernentes à profissão, o lugar onde esta é exercida.","Parágrafo único. Se a pessoa exercitar profissão em lugares diversos, cada um deles constituirá domicílio para as relações que lhe corresponderem."]],["CC, art. 73",["Art. 73. Ter-se-á por domicílio da pessoa natural, que não tenha residência habitual, o lugar onde for encontrada."]]],"10":[["CC, art. 74",["Art. 74. Muda-se o domicílio, transferindo a residência, com a intenção manifesta de o mudar.","Parágrafo único. A prova da intenção resultará do que declarar a pessoa às municipalidades dos lugares, que deixa, e para onde vai, ou, se tais declarações não fizer, da própria mudança, com as circunstâncias que a acompanharem."]],["CC, art. 75",["Art. 75. Quanto às pessoas jurídicas, o domicílio é:","I - da União, o Distrito Federal;","II - dos Estados e Territórios, as respectivas capitais;","III - do Município, o lugar onde funcione a administração municipal;","IV - das demais pessoas jurídicas, o lugar onde funcionarem as respectivas diretorias e administrações, ou onde elegerem domicílio especial no seu estatuto ou atos constitutivos.","§ 1º Tendo a pessoa jurídica diversos estabelecimentos em lugares diferentes, cada um deles será considerado domicílio para os atos nele praticados.","§ 2º Se a administração, ou diretoria, tiver a sede no estrangeiro, haver-se-á por domicílio da pessoa jurídica, no tocante às obrigações contraídas por cada uma das suas agências, o lugar do estabelecimento, sito no Brasil, a que ela corresponder."]],["CC, art. 76",["Art. 76. Têm domicílio necessário o incapaz, o servidor público, o militar, o marítimo e o preso.","Parágrafo único. O domicílio do incapaz é o do seu representante ou assistente; o do servidor público, o lugar em que exercer permanentemente suas funções; o do militar, onde servir, e, sendo da Marinha ou da Aeronáutica, a sede do comando a que se encontrar imediatamente subordinado; o do marítimo, onde o navio estiver matriculado; e o do preso, o lugar em que cumprir a sentença."]],["CC, art. 77",["Art. 77. O agente diplomático do Brasil, que, citado no estrangeiro, alegar extraterritorialidade sem designar onde tem, no país, o seu domicílio, poderá ser demandado no Distrito Federal ou no último ponto do território brasileiro onde o teve."]],["CC, art. 78",["Art. 78. Nos contratos escritos, poderão os contratantes especificar domicílio onde se exercitem e cumpram os direitos e obrigações deles resultantes."]]]},"3":{"0":[["CC, art. 79",["Art. 79. São bens imóveis o solo e tudo quanto se lhe incorporar natural ou artificialmente."]],["CC, art. 80",["Art. 80. Consideram-se imóveis para os efeitos legais:","I - os direitos reais sobre imóveis e as ações que os asseguram;","II - o direito à sucessão aberta."]],["CC, art. 81",["Art. 81. Não perdem o caráter de imóveis:","I - as edificações que, separadas do solo, mas conservando a sua unidade, forem removidas para outro local;","II - os materiais provisoriamente separados de um prédio, para nele se reempregarem."]],["CC, art. 82",["Art. 82. São móveis os bens suscetíveis de movimento próprio, ou de remoção por força alheia, sem alteração da substância ou da destinação econômico-social."]],["CC, art. 83",["Art. 83. Consideram-se móveis para os efeitos legais:","I - as energias que tenham valor econômico;","II - os direitos reais sobre objetos móveis e as ações correspondentes;","III - os direitos pessoais de caráter patrimonial e respectivas ações."]],["CC, art. 84",["Art. 84. Os materiais destinados a alguma construção, enquanto não forem empregados, conservam sua qualidade de móveis; readquirem essa qualidade os provenientes da demolição de algum prédio."]],["CC, art. 85",["Art. 85. São fungíveis os móveis que podem substituir-se por outros da mesma espécie, qualidade e quantidade."]],["CC, art. 86",["Art. 86. São consumíveis os bens móveis cujo uso importa destruição imediata da própria substância, sendo também considerados tais os destinados à alienação."]],["CC, art. 87",["Art. 87. Bens divisíveis são os que se podem fracionar sem alteração na sua substância, diminuição considerável de valor, ou prejuízo do uso a que se destinam."]],["CC, art. 88",["Art. 88. Os bens naturalmente divisíveis podem tornar-se indivisíveis por determinação da lei ou por vontade das partes."]],["CC, art. 89",["Art. 89. São singulares os bens que, embora reunidos, se consideram de per si , independentemente dos demais."]],["CC, art. 90",["Art. 90. Constitui universalidade de fato a pluralidade de bens singulares que, pertinentes à mesma pessoa, tenham destinação unitária.","Parágrafo único. Os bens que formam essa universalidade podem ser objeto de relações jurídicas próprias."]],["CC, art. 91",["Art. 91. Constitui universalidade de direito o complexo de relações jurídicas, de uma pessoa, dotadas de valor econômico."]],["CC, art. 92",["Art. 92. Principal é o bem que existe sobre si, abstrata ou concretamente; acessório, aquele cuja existência supõe a do principal."]],["CC, art. 93",["Art. 93. São pertenças os bens que, não constituindo partes integrantes, se destinam, de modo duradouro, ao uso, ao serviço ou ao aformoseamento de outro."]],["CC, art. 94",["Art. 94. Os negócios jurídicos que dizem respeito ao bem principal não abrangem as pertenças, salvo se o contrário resultar da lei, da manifestação de vontade, ou das circunstâncias do caso."]],["CC, art. 95",["Art. 95. Apesar de ainda não separados do bem principal, os frutos e produtos podem ser objeto de negócio jurídico."]],["CC, art. 96",["Art. 96. As benfeitorias podem ser voluptuárias, úteis ou necessárias.","§ 1º São voluptuárias as de mero deleite ou recreio, que não aumentam o uso habitual do bem, ainda que o tornem mais agradável ou sejam de elevado valor.","§ 2º São úteis as que aumentam ou facilitam o uso do bem.","§ 3º º São necessárias as que têm por fim conservar o bem ou evitar que se deteriore."]],["CC, art. 97",["Art. 97. Não se consideram benfeitorias os melhoramentos ou acréscimos sobrevindos ao bem sem a intervenção do proprietário, possuidor ou detentor."]],["CC, art. 98",["Art. 98. São públicos os bens do domínio nacional pertencentes às pessoas jurídicas de direito público interno; todos os outros são particulares, seja qual for a pessoa a que pertencerem."]],["CC, art. 99",["Art. 99. São bens públicos:","I - os de uso comum do povo, tais como rios, mares, estradas, ruas e praças;","II - os de uso especial, tais como edifícios ou terrenos destinados a serviço ou estabelecimento da administração federal, estadual, territorial ou municipal, inclusive os de suas autarquias;","III - os dominicais, que constituem o patrimônio das pessoas jurídicas de direito público, como objeto de direito pessoal, ou real, de cada uma dessas entidades.","Parágrafo único. Não dispondo a lei em contrário, consideram-se dominicais os bens pertencentes às pessoas jurídicas de direito público a que se tenha dado estrutura de direito privado."]],["CC, art. 100",["Art. 100. Os bens públicos de uso comum do povo e os de uso especial são inalienáveis, enquanto conservarem a sua qualificação, na forma que a lei determinar."]],["CC, art. 101",["Art. 101. Os bens públicos dominicais podem ser alienados, observadas as exigências da lei."]],["CC, art. 102",["Art. 102. Os bens públicos não estão sujeitos a usucapião."]],["CC, art. 103",["Art. 103. O uso comum dos bens públicos pode ser gratuito ou retribuído, conforme for estabelecido legalmente pela entidade a cuja administração pertencerem."]]],"1":[["CC, art. 79",["Art. 79. São bens imóveis o solo e tudo quanto se lhe incorporar natural ou artificialmente."]],["CC, art. 80",["Art. 80. Consideram-se imóveis para os efeitos legais:","I - os direitos reais sobre imóveis e as ações que os asseguram;","II - o direito à sucessão aberta."]],["CC, art. 81",["Art. 81. Não perdem o caráter de imóveis:","I - as edificações que, separadas do solo, mas conservando a sua unidade, forem removidas para outro local;","II - os materiais provisoriamente separados de um prédio, para nele se reempregarem."]]],"2":[["CC, art. 82",["Art. 82. São móveis os bens suscetíveis de movimento próprio, ou de remoção por força alheia, sem alteração da substância ou da destinação econômico-social."]],["CC, art. 83",["Art. 83. Consideram-se móveis para os efeitos legais:","I - as energias que tenham valor econômico;","II - os direitos reais sobre objetos móveis e as ações correspondentes;","III - os direitos pessoais de caráter patrimonial e respectivas ações."]],["CC, art. 84",["Art. 84. Os materiais destinados a alguma construção, enquanto não forem empregados, conservam sua qualidade de móveis; readquirem essa qualidade os provenientes da demolição de algum prédio."]]],"3":[["CC, art. 85",["Art. 85. São fungíveis os móveis que podem substituir-se por outros da mesma espécie, qualidade e quantidade."]]],"4":[["CC, art. 86",["Art. 86. São consumíveis os bens móveis cujo uso importa destruição imediata da própria substância, sendo também considerados tais os destinados à alienação."]]],"5":[["CC, art. 87",["Art. 87. Bens divisíveis são os que se podem fracionar sem alteração na sua substância, diminuição considerável de valor, ou prejuízo do uso a que se destinam."]],["CC, art. 88",["Art. 88. Os bens naturalmente divisíveis podem tornar-se indivisíveis por determinação da lei ou por vontade das partes."]]],"6":[["CC, art. 89",["Art. 89. São singulares os bens que, embora reunidos, se consideram de per si , independentemente dos demais."]],["CC, art. 90",["Art. 90. Constitui universalidade de fato a pluralidade de bens singulares que, pertinentes à mesma pessoa, tenham destinação unitária.","Parágrafo único. Os bens que formam essa universalidade podem ser objeto de relações jurídicas próprias."]],["CC, art. 91",["Art. 91. Constitui universalidade de direito o complexo de relações jurídicas, de uma pessoa, dotadas de valor econômico."]]],"7":[["CC, art. 92",["Art. 92. Principal é o bem que existe sobre si, abstrata ou concretamente; acessório, aquele cuja existência supõe a do principal."]],["CC, art. 95",["Art. 95. Apesar de ainda não separados do bem principal, os frutos e produtos podem ser objeto de negócio jurídico."]]],"8":[["CC, art. 93",["Art. 93. São pertenças os bens que, não constituindo partes integrantes, se destinam, de modo duradouro, ao uso, ao serviço ou ao aformoseamento de outro."]],["CC, art. 94",["Art. 94. Os negócios jurídicos que dizem respeito ao bem principal não abrangem as pertenças, salvo se o contrário resultar da lei, da manifestação de vontade, ou das circunstâncias do caso."]]],"9":[["CC, art. 96",["Art. 96. As benfeitorias podem ser voluptuárias, úteis ou necessárias.","§ 1º São voluptuárias as de mero deleite ou recreio, que não aumentam o uso habitual do bem, ainda que o tornem mais agradável ou sejam de elevado valor.","§ 2º São úteis as que aumentam ou facilitam o uso do bem.","§ 3º º São necessárias as que têm por fim conservar o bem ou evitar que se deteriore."]]],"10":[["CC, art. 98",["Art. 98. São públicos os bens do domínio nacional pertencentes às pessoas jurídicas de direito público interno; todos os outros são particulares, seja qual for a pessoa a que pertencerem."]],["CC, art. 99",["Art. 99. São bens públicos:","I - os de uso comum do povo, tais como rios, mares, estradas, ruas e praças;","II - os de uso especial, tais como edifícios ou terrenos destinados a serviço ou estabelecimento da administração federal, estadual, territorial ou municipal, inclusive os de suas autarquias;","III - os dominicais, que constituem o patrimônio das pessoas jurídicas de direito público, como objeto de direito pessoal, ou real, de cada uma dessas entidades.","Parágrafo único. Não dispondo a lei em contrário, consideram-se dominicais os bens pertencentes às pessoas jurídicas de direito público a que se tenha dado estrutura de direito privado."]],["CC, art. 100",["Art. 100. Os bens públicos de uso comum do povo e os de uso especial são inalienáveis, enquanto conservarem a sua qualificação, na forma que a lei determinar."]],["CC, art. 101",["Art. 101. Os bens públicos dominicais podem ser alienados, observadas as exigências da lei."]]],"11":[["CC, art. 100",["Art. 100. Os bens públicos de uso comum do povo e os de uso especial são inalienáveis, enquanto conservarem a sua qualificação, na forma que a lei determinar."]],["CC, art. 101",["Art. 101. Os bens públicos dominicais podem ser alienados, observadas as exigências da lei."]],["CC, art. 102",["Art. 102. Os bens públicos não estão sujeitos a usucapião."]],["CC, art. 103",["Art. 103. O uso comum dos bens públicos pode ser gratuito ou retribuído, conforme for estabelecido legalmente pela entidade a cuja administração pertencerem."]],["CF/88, art. 183",["Art. 183. Aquele que possuir como sua área urbana de até duzentos e cinqüenta metros quadrados, por cinco anos, ininterruptamente e sem oposição, utilizando-a para sua moradia ou de sua família, adquirir-lhe-á o domínio, desde que não seja proprietário de outro imóvel urbano ou rural.","[…]","§ 3º Os imóveis públicos não serão adquiridos por usucapião."]],["CF/88, art. 191",["Art. 191. Aquele que, não sendo proprietário de imóvel rural ou urbano, possua como seu, por cinco anos ininterruptos, sem oposição, área de terra, em zona rural, não superior a cinqüenta hectares, tornando-a produtiva por seu trabalho ou de sua família, tendo nela sua moradia, adquirir-lhe-á a propriedade.","Parágrafo único. Os imóveis públicos não serão adquiridos por usucapião."]]]},"4":{"0":[["CC, art. 104",["Art. 104. A validade do negócio jurídico requer:","I - agente capaz;","II - objeto lícito, possível, determinado ou determinável;","III - forma prescrita ou não defesa em lei."]],["CC, art. 105",["Art. 105. A incapacidade relativa de uma das partes não pode ser invocada pela outra em benefício próprio, nem aproveita aos co-interessados capazes, salvo se, neste caso, for indivisível o objeto do direito ou da obrigação comum."]],["CC, art. 106",["Art. 106. A impossibilidade inicial do objeto não invalida o negócio jurídico se for relativa, ou se cessar antes de realizada a condição a que ele estiver subordinado."]],["CC, art. 107",["Art. 107. A validade da declaração de vontade não dependerá de forma especial, senão quando a lei expressamente a exigir."]],["CC, art. 108",["Art. 108. Não dispondo a lei em contrário, a escritura pública é essencial à validade dos negócios jurídicos que visem à constituição, transferência, modificação ou renúncia de direitos reais sobre imóveis de valor superior a trinta vezes o maior salário mínimo vigente no País."]],["CC, art. 109",["Art. 109. No negócio jurídico celebrado com a cláusula de não valer sem instrumento público, este é da substância do ato."]],["CC, art. 110",["Art. 110. A manifestação de vontade subsiste ainda que o seu autor haja feito a reserva mental de não querer o que manifestou, salvo se dela o destinatário tinha conhecimento."]],["CC, art. 111",["Art. 111. O silêncio importa anuência, quando as circunstâncias ou os usos o autorizarem, e não for necessária a declaração de vontade expressa."]],["CC, art. 112",["Art. 112. Nas declarações de vontade se atenderá mais à intenção nelas consubstanciada do que ao sentido literal da linguagem."]],["CC, art. 113",["Art. 113. Os negócios jurídicos devem ser interpretados conforme a boa-fé e os usos do lugar de sua celebração.","§ 1º A interpretação do negócio jurídico deve lhe atribuir o sentido que:","I - for confirmado pelo comportamento das partes posterior à celebração do negócio;","II - corresponder aos usos, costumes e práticas do mercado relativas ao tipo de negócio;","III - corresponder à boa-fé;","IV - for mais benéfico à parte que não redigiu o dispositivo, se identificável; e","V - corresponder a qual seria a razoável negociação das partes sobre a questão discutida, inferida das demais disposições do negócio e da racionalidade econômica das partes, consideradas as informações disponíveis no momento de sua celebração. (Parágrafo acrescido pela Lei nº 13.874, de 20/9/2019)","§ 2º As partes poderão livremente pactuar regras de interpretação, de preenchimento de lacunas e de integração dos negócios jurídicos diversas daquelas previstas em lei. (Parágrafo acrescido pela Lei nº 13.874, de 20/9/2019)"]],["CC, art. 114",["Art. 114. Os negócios jurídicos benéficos e a renúncia interpretam-se estritamente."]]],"1":[["CC, art. 104",["Art. 104. A validade do negócio jurídico requer:","I - agente capaz;","II - objeto lícito, possível, determinado ou determinável;","III - forma prescrita ou não defesa em lei."]]],"2":[["CC, art. 106",["Art. 106. A impossibilidade inicial do objeto não invalida o negócio jurídico se for relativa, ou se cessar antes de realizada a condição a que ele estiver subordinado."]],["CC, art. 107",["Art. 107. A validade da declaração de vontade não dependerá de forma especial, senão quando a lei expressamente a exigir."]],["CC, art. 108",["Art. 108. Não dispondo a lei em contrário, a escritura pública é essencial à validade dos negócios jurídicos que visem à constituição, transferência, modificação ou renúncia de direitos reais sobre imóveis de valor superior a trinta vezes o maior salário mínimo vigente no País."]],["CC, art. 109",["Art. 109. No negócio jurídico celebrado com a cláusula de não valer sem instrumento público, este é da substância do ato."]]],"3":[["CC, art. 112",["Art. 112. Nas declarações de vontade se atenderá mais à intenção nelas consubstanciada do que ao sentido literal da linguagem."]],["CC, art. 113",["Art. 113. Os negócios jurídicos devem ser interpretados conforme a boa-fé e os usos do lugar de sua celebração.","§ 1º A interpretação do negócio jurídico deve lhe atribuir o sentido que:","I - for confirmado pelo comportamento das partes posterior à celebração do negócio;","II - corresponder aos usos, costumes e práticas do mercado relativas ao tipo de negócio;","III - corresponder à boa-fé;","IV - for mais benéfico à parte que não redigiu o dispositivo, se identificável; e","V - corresponder a qual seria a razoável negociação das partes sobre a questão discutida, inferida das demais disposições do negócio e da racionalidade econômica das partes, consideradas as informações disponíveis no momento de sua celebração. (Parágrafo acrescido pela Lei nº 13.874, de 20/9/2019)","§ 2º As partes poderão livremente pactuar regras de interpretação, de preenchimento de lacunas e de integração dos negócios jurídicos diversas daquelas previstas em lei. (Parágrafo acrescido pela Lei nº 13.874, de 20/9/2019)"]],["CC, art. 114",["Art. 114. Os negócios jurídicos benéficos e a renúncia interpretam-se estritamente."]]],"4":[["CC, art. 110",["Art. 110. A manifestação de vontade subsiste ainda que o seu autor haja feito a reserva mental de não querer o que manifestou, salvo se dela o destinatário tinha conhecimento."]],["CC, art. 111",["Art. 111. O silêncio importa anuência, quando as circunstâncias ou os usos o autorizarem, e não for necessária a declaração de vontade expressa."]]],"5":[["CC, art. 115",["Art. 115. Os poderes de representação conferem-se por lei ou pelo interessado."]],["CC, art. 116",["Art. 116. A manifestação de vontade pelo representante, nos limites de seus poderes, produz efeitos em relação ao representado."]],["CC, art. 117",["Art. 117. Salvo se o permitir a lei ou o representado, é anulável o negócio jurídico que o representante, no seu interesse ou por conta de outrem, celebrar consigo mesmo.","Parágrafo único. Para esse efeito, tem-se como celebrado pelo representante o negócio realizado por aquele em quem os poderes houverem sido subestabelecidos."]],["CC, art. 118",["Art. 118. O representante é obrigado a provar às pessoas, com quem tratar em nome do representado, a sua qualidade e a extensão de seus poderes, sob pena de, não o fazendo, responder pelos atos que a estes excederem."]],["CC, art. 119",["Art. 119. É anulável o negócio concluído pelo representante em conflito de interesses com o representado, se tal fato era ou devia ser do conhecimento de quem com aquele tratou.","Parágrafo único. É de cento e oitenta dias, a contar da conclusão do negócio ou da cessação da incapacidade, o prazo de decadência para pleitear-se a anulação prevista neste artigo."]],["CC, art. 120",["Art. 120. Os requisitos e os efeitos da representação legal são os estabelecidos nas normas respectivas; os da representação voluntária são os da Parte Especial deste Código."]]],"6":[["CC, art. 117",["Art. 117. Salvo se o permitir a lei ou o representado, é anulável o negócio jurídico que o representante, no seu interesse ou por conta de outrem, celebrar consigo mesmo.","Parágrafo único. Para esse efeito, tem-se como celebrado pelo representante o negócio realizado por aquele em quem os poderes houverem sido subestabelecidos."]],["CC, art. 119",["Art. 119. É anulável o negócio concluído pelo representante em conflito de interesses com o representado, se tal fato era ou devia ser do conhecimento de quem com aquele tratou.","Parágrafo único. É de cento e oitenta dias, a contar da conclusão do negócio ou da cessação da incapacidade, o prazo de decadência para pleitear-se a anulação prevista neste artigo."]]],"7":[["CC, art. 121",["Art. 121. Considera-se condição a cláusula que, derivando exclusivamente da vontade das partes, subordina o efeito do negócio jurídico a evento futuro e incerto."]],["CC, art. 122",["Art. 122. São lícitas, em geral, todas as condições não contrárias à lei, à ordem pública ou aos bons costumes; entre as condições defesas se incluem as que privarem de todo efeito o negócio jurídico, ou o sujeitarem ao puro arbítrio de uma das partes."]],["CC, art. 123",["Art. 123. Invalidam os negócios jurídicos que lhes são subordinados:","I - as condições física ou juridicamente impossíveis, quando suspensivas;","II - as condições ilícitas, ou de fazer coisa ilícita;","III - as condições incompreensíveis ou contraditórias."]],["CC, art. 124",["Art. 124. Têm-se por inexistentes as condições impossíveis, quando resolutivas, e as de não fazer coisa impossível."]],["CC, art. 125",["Art. 125. Subordinando-se a eficácia do negócio jurídico à condição suspensiva, enquanto esta se não verificar, não se terá adquirido o direito, a que ele visa."]],["CC, art. 126",["Art. 126. Se alguém dispuser de uma coisa sob condição suspensiva, e, pendente esta, fizer quanto àquela novas disposições, estas não terão valor, realizada a condição, se com ela forem incompatíveis."]],["CC, art. 127",["Art. 127. Se for resolutiva a condição, enquanto esta se não realizar, vigorará o negócio jurídico, podendo exercer-se desde a conclusão deste o direito por ele estabelecido."]],["CC, art. 128",["Art. 128. Sobrevindo a condição resolutiva, extingue-se, para todos os efeitos, o direito a que ela se opõe; mas, se aposta a um negócio de execução continuada ou periódica, a sua realização, salvo disposição em contrário, não tem eficácia quanto aos atos já praticados, desde que compatíveis com a natureza da condição pendente e conforme aos ditames de boa-fé."]],["CC, art. 129",["Art. 129. Reputa-se verificada, quanto aos efeitos jurídicos, a condição cujo implemento for maliciosamente obstado pela parte a quem desfavorecer, considerando-se, ao contrário, não verificada a condição maliciosamente levada a efeito por aquele a quem aproveita o seu implemento."]],["CC, art. 130",["Art. 130. Ao titular do direito eventual, nos casos de condição suspensiva ou resolutiva, é permitido praticar os atos destinados a conservá-lo."]],["CC, art. 131",["Art. 131. O termo inicial suspende o exercício, mas não a aquisição do direito."]],["CC, art. 132",["Art. 132. Salvo disposição legal ou convencional em contrário, computam-se os prazos, excluído o dia do começo, e incluído o do vencimento.","§ 1º Se o dia do vencimento cair em feriado, considerar-se-á prorrogado o prazo até o seguinte dia útil.","§ 2º Meado considera-se, em qualquer mês, o seu décimo quinto dia.","§ 3º Os prazos de meses e anos expiram no dia de igual número do de início, ou no imediato, se faltar exata correspondência.","§ 4º Os prazos fixados por hora contar-se-ão de minuto a minuto."]],["CC, art. 133",["Art. 133. Nos testamentos, presume-se o prazo em favor do herdeiro, e, nos contratos, em proveito do devedor, salvo, quanto a esses, se do teor do instrumento, ou das circunstâncias, resultar que se estabeleceu a benefício do credor, ou de ambos os contratantes."]],["CC, art. 134",["Art. 134. Os negócios jurídicos entre vivos, sem prazo, são exeqüíveis desde logo, salvo se a execução tiver de ser feita em lugar diverso ou depender de tempo."]],["CC, art. 135",["Art. 135. Ao termo inicial e final aplicam-se, no que couber, as disposições relativas à condição suspensiva e resolutiva."]],["CC, art. 136",["Art. 136. O encargo não suspende a aquisição nem o exercício do direito, salvo quando expressamente imposto no negócio jurídico, pelo disponente, como condição suspensiva."]],["CC, art. 137",["Art. 137. Considera-se não escrito o encargo ilícito ou impossível, salvo se constituir o motivo determinante da liberalidade, caso em que se invalida o negócio jurídico."]]],"8":[["CC, art. 138",["Art. 138. São anuláveis os negócios jurídicos, quando as declarações de vontade emanarem de erro substancial que poderia ser percebido por pessoa de diligência normal, em face das circunstâncias do negócio."]],["CC, art. 139",["Art. 139. O erro é substancial quando:","I - interessa à natureza do negócio, ao objeto principal da declaração, ou a alguma das qualidades a ele essenciais;","II - concerne à identidade ou à qualidade essencial da pessoa a quem se refira a declaração de vontade, desde que tenha influído nesta de modo relevante;","III - sendo de direito e não implicando recusa à aplicação da lei, for o motivo único ou principal do negócio jurídico."]],["CC, art. 140",["Art. 140. O falso motivo só vicia a declaração de vontade quando expresso como razão determinante."]],["CC, art. 141",["Art. 141. A transmissão errônea da vontade por meios interpostos é anulável nos mesmos casos em que o é a declaração direta."]],["CC, art. 142",["Art. 142. O erro de indicação da pessoa ou da coisa, a que se referir a declaração de vontade, não viciará o negócio quando, por seu contexto e pelas circunstâncias, se puder identificar a coisa ou pessoa cogitada."]],["CC, art. 143",["Art. 143. O erro de cálculo apenas autoriza a retificação da declaração de vontade."]],["CC, art. 144",["Art. 144. O erro não prejudica a validade do negócio jurídico quando a pessoa, a quem a manifestação de vontade se dirige, se oferecer para executá-la na conformidade da vontade real do manifestante."]],["CC, art. 145",["Art. 145. São os negócios jurídicos anuláveis por dolo, quando este for a sua causa."]],["CC, art. 146",["Art. 146. O dolo acidental só obriga à satisfação das perdas e danos, e é acidental quando, a seu despeito, o negócio seria realizado, embora por outro modo."]],["CC, art. 147",["Art. 147. Nos negócios jurídicos bilaterais, o silêncio intencional de uma das partes a respeito de fato ou qualidade que a outra parte haja ignorado, constitui omissão dolosa, provando-se que sem ela o negócio não se teria celebrado."]],["CC, art. 148",["Art. 148. Pode também ser anulado o negócio jurídico por dolo de terceiro, se a parte a quem aproveite dele tivesse ou devesse ter conhecimento; em caso contrário, ainda que subsista o negócio jurídico, o terceiro responderá por todas as perdas e danos da parte a quem ludibriou."]],["CC, art. 149",["Art. 149. O dolo do representante legal de uma das partes só obriga o representado a responder civilmente até a importância do proveito que teve; se, porém, o dolo for do representante convencional, o representado responderá solidariamente com ele por perdas e danos."]],["CC, art. 150",["Art. 150. Se ambas as partes procederem com dolo, nenhuma pode alegá-lo para anular o negócio, ou reclamar indenização."]]],"9":[["CC, art. 151",["Art. 151. A coação, para viciar a declaração da vontade, há de ser tal que incuta ao paciente fundado temor de dano iminente e considerável à sua pessoa, à sua família, ou aos seus bens.","Parágrafo único. Se disser respeito a pessoa não pertencente à família do paciente, o juiz, com base nas circunstâncias, decidirá se houve coação."]],["CC, art. 152",["Art. 152. No apreciar a coação, ter-se-ão em conta o sexo, a idade, a condição, a saúde, o temperamento do paciente e todas as demais circunstâncias que possam influir na gravidade dela."]],["CC, art. 153",["Art. 153. Não se considera coação a ameaça do exercício normal de um direito, nem o simples temor reverencial."]],["CC, art. 154",["Art. 154. Vicia o negócio jurídico a coação exercida por terceiro, se dela tivesse ou devesse ter conhecimento a parte a que aproveite, e esta responderá solidariamente com aquele por perdas e danos."]],["CC, art. 155",["Art. 155. Subsistirá o negócio jurídico, se a coação decorrer de terceiro, sem que a parte a que aproveite dela tivesse ou devesse ter conhecimento; mas o autor da coação responderá por todas as perdas e danos que houver causado ao coacto."]],["CC, art. 156",["Art. 156. Configura-se o estado de perigo quando alguém, premido da necessidade de salvar-se, ou a pessoa de sua família, de grave dano conhecido pela outra parte, assume obrigação excessivamente onerosa.","Parágrafo único. Tratando-se de pessoa não pertencente à família do declarante, o juiz decidirá segundo as circunstâncias."]],["CC, art. 178",["Art. 178. É de quatro anos o prazo de decadência para pleitear-se a anulação do negócio jurídico, contado:","I - no caso de coação, do dia em que ela cessar;"]]],"10":[["CC, art. 157",["Art. 157. Ocorre a lesão quando uma pessoa, sob premente necessidade, ou por inexperiência, se obriga a prestação manifestamente desproporcional ao valor da prestação oposta.","§ 1º Aprecia-se a desproporção das prestações segundo os valores vigentes ao tempo em que foi celebrado o negócio jurídico.","§ 2º Não se decretará a anulação do negócio, se for oferecido suplemento suficiente, ou se a parte favorecida concordar com a redução do proveito."]],["CC, art. 158",["Art. 158. Os negócios de transmissão gratuita de bens ou remissão de dívida, se os praticar o devedor já insolvente, ou por eles reduzido à insolvência, ainda quando o ignore, poderão ser anulados pelos credores quirografários, como lesivos dos seus direitos.","§ 1º Igual direito assiste aos credores cuja garantia se tornar insuficiente.","§ 2º Só os credores que já o eram ao tempo daqueles atos podem pleitear a anulação deles."]],["CC, art. 159",["Art. 159. Serão igualmente anuláveis os contratos onerosos do devedor insolvente, quando a insolvência for notória, ou houver motivo para ser conhecida do outro contratante."]],["CC, art. 160",["Art. 160. Se o adquirente dos bens do devedor insolvente ainda não tiver pago o preço e este for, aproximadamente, o corrente, desobrigar-se-á depositando-o em juízo, com a citação de todos os interessados.","Parágrafo único. Se inferior, o adquirente, para conservar os bens, poderá depositar o preço que lhes corresponda ao valor real."]],["CC, art. 161",["Art. 161. A ação, nos casos dos arts. 158 e 159, poderá ser intentada contra o devedor insolvente, a pessoa que com ele celebrou a estipulação considerada fraudulenta, ou terceiros adquirentes que hajam procedido de má-fé."]],["CC, art. 162",["Art. 162. O credor quirografário, que receber do devedor insolvente o pagamento da dívida ainda não vencida, ficará obrigado a repor, em proveito do acervo sobre que se tenha de efetuar o concurso de credores, aquilo que recebeu."]],["CC, art. 163",["Art. 163. Presumem-se fraudatórias dos direitos dos outros credores as garantias de dívidas que o devedor insolvente tiver dado a algum credor."]],["CC, art. 164",["Art. 164. Presumem-se, porém, de boa-fé e valem os negócios ordinários indispensáveis à manutenção de estabelecimento mercantil, rural, ou industrial, ou à subsistência do devedor e de sua família."]],["CC, art. 165",["Art. 165. Anulados os negócios fraudulentos, a vantagem resultante reverterá em proveito do acervo sobre que se tenha de efetuar o concurso de credores.","Parágrafo único. Se esses negócios tinham por único objeto atribuir direitos preferenciais, mediante hipoteca, penhor ou anticrese, sua invalidade importará somente na anulação da preferência ajustada."]]],"11":[["CC, art. 166",["Art. 166. É nulo o negócio jurídico quando:","I - celebrado por pessoa absolutamente incapaz;","II - for ilícito, impossível ou indeterminável o seu objeto;","III - o motivo determinante, comum a ambas as partes, for ilícito;","IV - não revestir a forma prescrita em lei;","V - for preterida alguma solenidade que a lei considere essencial para a sua validade;","VI - tiver por objetivo fraudar lei imperativa;","VII - a lei taxativamente o declarar nulo, ou proibir-lhe a prática, sem cominar sanção."]],["CC, art. 167",["Art. 167. É nulo o negócio jurídico simulado, mas subsistirá o que se dissimulou, se válido for na substância e na forma.","§ 1º Haverá simulação nos negócios jurídicos quando:","I - aparentarem conferir ou transmitir direitos a pessoas diversas daquelas às quais realmente se conferem, ou transmitem;","II - contiverem declaração, confissão, condição ou cláusula não verdadeira;","III - os instrumentos particulares forem antedatados, ou pós-datados.","§ 2º Ressalvam-se os direitos de terceiros de boa-fé em face dos contraentes do negócio jurídico simulado."]],["CC, art. 168",["Art. 168. As nulidades dos artigos antecedentes podem ser alegadas por qualquer interessado, ou pelo Ministério Público, quando lhe couber intervir.","Parágrafo único. As nulidades devem ser pronunciadas pelo juiz, quando conhecer do negócio jurídico ou dos seus efeitos e as encontrar provadas, não lhe sendo permitido supri-las, ainda que a requerimento das partes."]],["CC, art. 169",["Art. 169. O negócio jurídico nulo não é suscetível de confirmação, nem convalesce pelo decurso do tempo."]],["CC, art. 170",["Art. 170. Se, porém, o negócio jurídico nulo contiver os requisitos de outro, subsistirá este quando o fim a que visavam as partes permitir supor que o teriam querido, se houvessem previsto a nulidade."]],["CC, art. 171",["Art. 171. Além dos casos expressamente declarados na lei, é anulável o negócio jurídico:","I - por incapacidade relativa do agente;","II - por vício resultante de erro, dolo, coação, estado de perigo, lesão ou fraude contra credores."]],["CC, art. 172",["Art. 172. O negócio anulável pode ser confirmado pelas partes, salvo direito de terceiro."]],["CC, art. 173",["Art. 173. O ato de confirmação deve conter a substância do negócio celebrado e a vontade expressa de mantê-lo."]],["CC, art. 174",["Art. 174. É escusada a confirmação expressa, quando o negócio já foi cumprido em parte pelo devedor, ciente do vício que o inquinava."]],["CC, art. 175",["Art. 175. A confirmação expressa, ou a execução voluntária de negócio anulável, nos termos dos arts. 172 a 174, importa a extinção de todas as ações, ou exceções, de que contra ele dispusesse o devedor."]],["CC, art. 176",["Art. 176. Quando a anulabilidade do ato resultar da falta de autorização de terceiro, será validado se este a der posteriormente."]],["CC, art. 177",["Art. 177. A anulabilidade não tem efeito antes de julgada por sentença, nem se pronuncia de ofício; só os interessados a podem alegar, e aproveita exclusivamente aos que a alegarem, salvo o caso de solidariedade ou indivisibilidade."]],["CC, art. 178",["Art. 178. É de quatro anos o prazo de decadência para pleitear-se a anulação do negócio jurídico, contado:","I - no caso de coação, do dia em que ela cessar;","II - no de erro, dolo, fraude contra credores, estado de perigo ou lesão, do dia em que se realizou o negócio jurídico;","III - no de atos de incapazes, do dia em que cessar a incapacidade."]],["CC, art. 179",["Art. 179. Quando a lei dispuser que determinado ato é anulável, sem estabelecer prazo para pleitear-se a anulação, será este de dois anos, a contar da data da conclusão do ato."]],["CC, art. 180",["Art. 180. O menor, entre dezesseis e dezoito anos, não pode, para eximir-se de uma obrigação, invocar a sua idade se dolosamente a ocultou quando inquirido pela outra parte, ou se, no ato de obrigar-se, declarou-se maior."]],["CC, art. 181",["Art. 181. Ninguém pode reclamar o que, por uma obrigação anulada, pagou a um incapaz, se não provar que reverteu em proveito dele a importância paga."]],["CC, art. 182",["Art. 182. Anulado o negócio jurídico, restituir-se-ão as partes ao estado em que antes dele se achavam, e, não sendo possível restituí-las, serão indenizadas com o equivalente."]],["CC, art. 183",["Art. 183. A invalidade do instrumento não induz a do negócio jurídico sempre que este puder provar-se por outro meio."]],["CC, art. 184",["Art. 184. Respeitada a intenção das partes, a invalidade parcial de um negócio jurídico não o prejudicará na parte válida, se esta for separável; a invalidade da obrigação principal implica a das obrigações acessórias, mas a destas não induz a da obrigação principal."]]]},"5":{"0":[["CC, art. 189",["Art. 189. Violado o direito, nasce para o titular a pretensão, a qual se extingue, pela prescrição, nos prazos a que aludem os arts. 205 e 206."]]],"1":[["CC, art. 189",["Art. 189. Violado o direito, nasce para o titular a pretensão, a qual se extingue, pela prescrição, nos prazos a que aludem os arts. 205 e 206."]],["CC, art. 190",["Art. 190. A exceção prescreve no mesmo prazo em que a pretensão."]],["CC, art. 191",["Art. 191. A renúncia da prescrição pode ser expressa ou tácita, e só valerá, sendo feita, sem prejuízo de terceiro, depois que a prescrição se consumar; tácita é a renúncia quando se presume de fatos do interessado, incompatíveis com a prescrição."]],["CC, art. 192",["Art. 192. Os prazos de prescrição não podem ser alterados por acordo das partes."]],["CC, art. 193",["Art. 193. A prescrição pode ser alegada em qualquer grau de jurisdição, pela parte a quem aproveita."]],["CC, art. 194",["Art. 194. (Revogado pela Lei nº 11.280, de 16/2/2006, publicada no DOU de 17/2/2006, em vigor 90 dias após a publicação)"]],["CC, art. 195",["Art. 195. Os relativamente incapazes e as pessoas jurídicas têm ação contra os seus assistentes ou representantes legais, que derem causa à prescrição, ou não a alegarem oportunamente."]],["CC, art. 196",["Art. 196. A prescrição iniciada contra uma pessoa continua a correr contra o seu sucessor."]],["CC, art. 197",["Art. 197. Não corre a prescrição:","I - entre os cônjuges, na constância da sociedade conjugal;","II - entre ascendentes e descendentes, durante o poder familiar;","III - entre tutelados ou curatelados e seus tutores ou curadores, durante a tutela ou curatela."]],["CC, art. 198",["Art. 198. Também não corre a prescrição:","I - contra os incapazes de que trata o art. 3 o ;","II - contra os ausentes do País em serviço público da União, dos Estados ou dos Municípios;","III - contra os que se acharem servindo nas Forças Armadas, em tempo de guerra."]],["CC, art. 199",["Art. 199. Não corre igualmente a prescrição:","I - pendendo condição suspensiva;","II - não estando vencido o prazo;","III - pendendo ação de evicção."]],["CC, art. 200",["Art. 200. Quando a ação se originar de fato que deva ser apurado no juízo criminal, não correrá a prescrição antes da respectiva sentença definitiva."]],["CC, art. 201",["Art. 201. Suspensa a prescrição em favor de um dos credores solidários, só aproveitam os outros se a obrigação for indivisível."]],["CC, art. 202",["Art. 202. A interrupção da prescrição, que somente poderá ocorrer uma vez, dar-se-á:","I - por despacho do juiz, mesmo incompetente, que ordenar a citação, se o interessado a promover no prazo e na forma da lei processual;","II - por protesto, nas condições do inciso antecedente;","III - por protesto cambial;","IV - pela apresentação do título de crédito em juízo de inventário ou em concurso de credores;","V - por qualquer ato judicial que constitua em mora o devedor;","VI - por qualquer ato inequívoco, ainda que extrajudicial, que importe reconhecimento do direito pelo devedor.","Parágrafo único. A prescrição interrompida recomeça a correr da data do ato que a interrompeu, ou do último ato do processo para a interromper."]],["CC, art. 203",["Art. 203. A prescrição pode ser interrompida por qualquer interessado."]],["CC, art. 204",["Art. 204. A interrupção da prescrição por um credor não aproveita aos outros; semelhantemente, a interrupção operada contra o co-devedor, ou seu herdeiro, não prejudica aos demais coobrigados.","§ 1º A interrupção por um dos credores solidários aproveita aos outros; assim como a interrupção efetuada contra o devedor solidário envolve os demais e seus herdeiros.","§ 2º A interrupção operada contra um dos herdeiros do devedor solidário não prejudica os outros herdeiros ou devedores, senão quando se trate de obrigações e direitos indivisíveis.","§ 3º A interrupção produzida contra o principal devedor prejudica o fiador."]],["CC, art. 205",["Art. 205. A prescrição ocorre em dez anos, quando a lei não lhe haja fixado prazo menor."]],["CC, art. 206",["Art. 206. Prescreve:","§ 1º Em um ano:","I - a pretensão dos hospedeiros ou fornecedores de víveres destinados a consumo no próprio estabelecimento, para o pagamento da hospedagem ou dos alimentos;","II - a pretensão do segurado contra o segurador, ou a deste contra aquele, contado o prazo: (Vide Lei nº 15.040, de 9/12/2024)","a) para o segurado, no caso de seguro de responsabilidade civil, da data em que é citado para responder à ação de indenização proposta pelo terceiro prejudicado, ou da data que a este indeniza, com a anuência do segurador;","b) quanto aos demais seguros, da ciência do fato gerador da pretensão;","III - a pretensão dos tabeliães, auxiliares da justiça, serventuários judiciais, árbitros e peritos, pela percepção de emolumentos, custas e honorários;","IV - a pretensão contra os peritos, pela avaliação dos bens que entraram para a formação do capital de sociedade anônima, contado da publicação da ata da assembléia que aprovar o laudo;","V - a pretensão dos credores não pagos contra os sócios ou acionistas e os liquidantes, contado o prazo da publicação da ata de encerramento da liquidação da sociedade.","§ 2º Em dois anos, a pretensão para haver prestações alimentares, a partir da data em que se vencerem.","§ 3º Em três anos:","I - a pretensão relativa a aluguéis de prédios urbanos ou rústicos;","II - a pretensão para receber prestações vencidas de rendas temporárias ou vitalícias;","III - a pretensão para haver juros, dividendos ou quaisquer prestações acessórias, pagáveis, em períodos não maiores de um ano, com capitalização ou sem ela;","IV - a pretensão de ressarcimento de enriquecimento sem causa;","V - a pretensão de reparação civil;","VI - a pretensão de restituição dos lucros ou dividendos recebidos de má-fé, correndo o prazo da data em que foi deliberada a distribuição;","VII - a pretensão contra as pessoas em seguida indicadas por violação da lei ou do estatuto, contado o prazo:","a) para os fundadores, da publicação dos atos constitutivos da sociedade anônima;","b) para os administradores, ou fiscais, da apresentação, aos sócios, do balanço referente ao exercício em que a violação tenha sido praticada, ou da reunião ou assembléia geral que dela deva tomar conhecimento;","c) para os liquidantes, da primeira assembléia semestral posterior à violação;","VIII - a pretensão para haver o pagamento de título de crédito, a contar do vencimento, ressalvadas as disposições de lei especial;","IX - a pretensão do beneficiário contra o segurador, e a do terceiro prejudicado, no caso de seguro de responsabilidade civil obrigatório.","§ 4º Em quatro anos, a pretensão relativa à tutela, a contar da data da aprovação das contas.","§ 5º Em cinco anos:","I - a pretensão de cobrança de dívidas líquidas constantes de instrumento público ou particular;","II - a pretensão dos profissionais liberais em geral, procuradores judiciais, curadores e professores pelos seus honorários, contado o prazo da conclusão dos serviços, da cessação dos respectivos contratos ou mandato;","III - a pretensão do vencedor para haver do vencido o que despendeu em juízo."]],["CC, art. 206-A",["Art. 206-A. A prescrição intercorrente observará o mesmo prazo de prescrição da pretensão, observadas as causas de impedimento, de suspensão e de interrupção da prescrição previstas neste Código e observado o disposto no art. 921 da Lei nº 13.105, de 16 de março de 2015 (Código de Processo Civil). (Artigo acrescido pela Medida Provisória nº 1.040, de 29/3/2021, convertida na Lei nº 14.195, de 26/8/2021 , com redação dada pela Medida Provisória nº 1.085, de 27/12/2021 , convertida na Lei nº 14.382, de 27/6/2022)"]],["CC, art. 207",["Art. 207. Salvo disposição legal em contrário, não se aplicam à decadência as normas que impedem, suspendem ou interrompem a prescrição."]],["CC, art. 208",["Art. 208. Aplica-se à decadência o disposto nos arts. 195 e 198, inciso I."]],["CC, art. 209",["Art. 209. É nula a renúncia à decadência fixada em lei."]],["CC, art. 210",["Art. 210. Deve o juiz, de ofício, conhecer da decadência, quando estabelecida por lei."]],["CC, art. 211",["Art. 211. Se a decadência for convencional, a parte a quem aproveita pode alegá-la em qualquer grau de jurisdição, mas o juiz não pode suprir a alegação."]]],"2":[["CC, art. 205",["Art. 205. A prescrição ocorre em dez anos, quando a lei não lhe haja fixado prazo menor."]],["CC, art. 206",["Art. 206. Prescreve:","§ 1º Em um ano:","I - a pretensão dos hospedeiros ou fornecedores de víveres destinados a consumo no próprio estabelecimento, para o pagamento da hospedagem ou dos alimentos;","II - a pretensão do segurado contra o segurador, ou a deste contra aquele, contado o prazo: (Vide Lei nº 15.040, de 9/12/2024)","a) para o segurado, no caso de seguro de responsabilidade civil, da data em que é citado para responder à ação de indenização proposta pelo terceiro prejudicado, ou da data que a este indeniza, com a anuência do segurador;","b) quanto aos demais seguros, da ciência do fato gerador da pretensão;","III - a pretensão dos tabeliães, auxiliares da justiça, serventuários judiciais, árbitros e peritos, pela percepção de emolumentos, custas e honorários;","IV - a pretensão contra os peritos, pela avaliação dos bens que entraram para a formação do capital de sociedade anônima, contado da publicação da ata da assembléia que aprovar o laudo;","V - a pretensão dos credores não pagos contra os sócios ou acionistas e os liquidantes, contado o prazo da publicação da ata de encerramento da liquidação da sociedade.","§ 2º Em dois anos, a pretensão para haver prestações alimentares, a partir da data em que se vencerem.","§ 3º Em três anos:","I - a pretensão relativa a aluguéis de prédios urbanos ou rústicos;","II - a pretensão para receber prestações vencidas de rendas temporárias ou vitalícias;","III - a pretensão para haver juros, dividendos ou quaisquer prestações acessórias, pagáveis, em períodos não maiores de um ano, com capitalização ou sem ela;","IV - a pretensão de ressarcimento de enriquecimento sem causa;","V - a pretensão de reparação civil;","VI - a pretensão de restituição dos lucros ou dividendos recebidos de má-fé, correndo o prazo da data em que foi deliberada a distribuição;","VII - a pretensão contra as pessoas em seguida indicadas por violação da lei ou do estatuto, contado o prazo:","a) para os fundadores, da publicação dos atos constitutivos da sociedade anônima;","b) para os administradores, ou fiscais, da apresentação, aos sócios, do balanço referente ao exercício em que a violação tenha sido praticada, ou da reunião ou assembléia geral que dela deva tomar conhecimento;","c) para os liquidantes, da primeira assembléia semestral posterior à violação;","VIII - a pretensão para haver o pagamento de título de crédito, a contar do vencimento, ressalvadas as disposições de lei especial;","IX - a pretensão do beneficiário contra o segurador, e a do terceiro prejudicado, no caso de seguro de responsabilidade civil obrigatório.","§ 4º Em quatro anos, a pretensão relativa à tutela, a contar da data da aprovação das contas.","§ 5º Em cinco anos:","I - a pretensão de cobrança de dívidas líquidas constantes de instrumento público ou particular;","II - a pretensão dos profissionais liberais em geral, procuradores judiciais, curadores e professores pelos seus honorários, contado o prazo da conclusão dos serviços, da cessação dos respectivos contratos ou mandato;","III - a pretensão do vencedor para haver do vencido o que despendeu em juízo."]],["CC, art. 206",["Art. 206. Prescreve:","[…]","V - a pretensão dos credores não pagos contra os sócios ou acionistas e os liquidantes, contado o prazo da publicação da ata de encerramento da liquidação da sociedade.","[…]","§ 3º Em três anos:"]]],"3":[["CC, art. 191",["Art. 191. A renúncia da prescrição pode ser expressa ou tácita, e só valerá, sendo feita, sem prejuízo de terceiro, depois que a prescrição se consumar; tácita é a renúncia quando se presume de fatos do interessado, incompatíveis com a prescrição."]],["CC, art. 192",["Art. 192. Os prazos de prescrição não podem ser alterados por acordo das partes."]]],"4":[["CC, art. 197",["Art. 197. Não corre a prescrição:","I - entre os cônjuges, na constância da sociedade conjugal;","II - entre ascendentes e descendentes, durante o poder familiar;","III - entre tutelados ou curatelados e seus tutores ou curadores, durante a tutela ou curatela."]],["CC, art. 198",["Art. 198. Também não corre a prescrição:","I - contra os incapazes de que trata o art. 3 o ;","II - contra os ausentes do País em serviço público da União, dos Estados ou dos Municípios;","III - contra os que se acharem servindo nas Forças Armadas, em tempo de guerra."]],["CC, art. 199",["Art. 199. Não corre igualmente a prescrição:","I - pendendo condição suspensiva;","II - não estando vencido o prazo;","III - pendendo ação de evicção."]],["CC, art. 200",["Art. 200. Quando a ação se originar de fato que deva ser apurado no juízo criminal, não correrá a prescrição antes da respectiva sentença definitiva."]],["CC, art. 201",["Art. 201. Suspensa a prescrição em favor de um dos credores solidários, só aproveitam os outros se a obrigação for indivisível."]]],"5":[["CC, art. 202",["Art. 202. A interrupção da prescrição, que somente poderá ocorrer uma vez, dar-se-á:","I - por despacho do juiz, mesmo incompetente, que ordenar a citação, se o interessado a promover no prazo e na forma da lei processual;","II - por protesto, nas condições do inciso antecedente;","III - por protesto cambial;","IV - pela apresentação do título de crédito em juízo de inventário ou em concurso de credores;","V - por qualquer ato judicial que constitua em mora o devedor;","VI - por qualquer ato inequívoco, ainda que extrajudicial, que importe reconhecimento do direito pelo devedor.","Parágrafo único. A prescrição interrompida recomeça a correr da data do ato que a interrompeu, ou do último ato do processo para a interromper."]],["CC, art. 203",["Art. 203. A prescrição pode ser interrompida por qualquer interessado."]],["CC, art. 204",["Art. 204. A interrupção da prescrição por um credor não aproveita aos outros; semelhantemente, a interrupção operada contra o co-devedor, ou seu herdeiro, não prejudica aos demais coobrigados.","§ 1º A interrupção por um dos credores solidários aproveita aos outros; assim como a interrupção efetuada contra o devedor solidário envolve os demais e seus herdeiros.","§ 2º A interrupção operada contra um dos herdeiros do devedor solidário não prejudica os outros herdeiros ou devedores, senão quando se trate de obrigações e direitos indivisíveis.","§ 3º A interrupção produzida contra o principal devedor prejudica o fiador."]]],"6":[["CC, art. 197",["Art. 197. Não corre a prescrição:","I - entre os cônjuges, na constância da sociedade conjugal;","II - entre ascendentes e descendentes, durante o poder familiar;","III - entre tutelados ou curatelados e seus tutores ou curadores, durante a tutela ou curatela."]],["CC, art. 198",["Art. 198. Também não corre a prescrição:","I - contra os incapazes de que trata o art. 3 o ;","II - contra os ausentes do País em serviço público da União, dos Estados ou dos Municípios;","III - contra os que se acharem servindo nas Forças Armadas, em tempo de guerra."]]],"7":[["CC, art. 207",["Art. 207. Salvo disposição legal em contrário, não se aplicam à decadência as normas que impedem, suspendem ou interrompem a prescrição."]],["CC, art. 208",["Art. 208. Aplica-se à decadência o disposto nos arts. 195 e 198, inciso I."]],["CC, art. 209",["Art. 209. É nula a renúncia à decadência fixada em lei."]],["CC, art. 210",["Art. 210. Deve o juiz, de ofício, conhecer da decadência, quando estabelecida por lei."]],["CC, art. 211",["Art. 211. Se a decadência for convencional, a parte a quem aproveita pode alegá-la em qualquer grau de jurisdição, mas o juiz não pode suprir a alegação."]]],"8":[["CC, art. 178",["Art. 178. É de quatro anos o prazo de decadência para pleitear-se a anulação do negócio jurídico, contado:","I - no caso de coação, do dia em que ela cessar;","II - no de erro, dolo, fraude contra credores, estado de perigo ou lesão, do dia em que se realizou o negócio jurídico;","III - no de atos de incapazes, do dia em que cessar a incapacidade."]],["CC, art. 119",["Art. 119. É anulável o negócio concluído pelo representante em conflito de interesses com o representado, se tal fato era ou devia ser do conhecimento de quem com aquele tratou.","Parágrafo único. É de cento e oitenta dias, a contar da conclusão do negócio ou da cessação da incapacidade, o prazo de decadência para pleitear-se a anulação prevista neste artigo."]]],"9":[["CC, art. 212",["Art. 212. Salvo o negócio a que se impõe forma especial, o fato jurídico pode ser provado mediante:","I - confissão;","II - documento;","III - testemunha;","IV - presunção;","V - perícia."]]],"10":[["CC, art. 214",["Art. 214. A confissão é irrevogável, mas pode ser anulada se decorreu de erro de fato ou de coação."]]],"11":[["CC, art. 215",["Art. 215. A escritura pública, lavrada em notas de tabelião, é documento dotado de fé pública, fazendo prova plena.","§ 1º Salvo quando exigidos por lei outros requisitos, a escritura pública deve conter:","I - data e local de sua realização;","II - reconhecimento da identidade e capacidade das partes e de quantos hajam comparecido ao ato, por si, como representantes, intervenientes ou testemunhas;","III - nome, nacionalidade, estado civil, profissão, domicílio e residência das partes e demais comparecentes, com a indicação, quando necessário, do regime de bens do casamento, nome do outro cônjuge e filiação;","IV - manifestação clara da vontade das partes e dos intervenientes;","V - referência ao cumprimento das exigências legais e fiscais inerentes à legitimidade do ato;","VI - declaração de ter sido lida na presença das partes e demais comparecentes, ou de que todos a leram;","VII - assinatura das partes e dos demais comparecentes, bem como a do tabelião ou seu substituto legal, encerrando o ato.","§ 2º Se algum comparecente não puder ou não souber escrever, outra pessoa capaz assinará por ele, a seu rogo.","§ 3º A escritura será redigida na língua nacional.","§ 4º Se qualquer dos comparecentes não souber a língua nacional e o tabelião não entender o idioma em que se expressa, deverá comparecer tradutor público para servir de intérprete, ou, não o havendo na localidade, outra pessoa capaz que, a juízo do tabelião, tenha idoneidade e conhecimento bastantes.","§ 5º Se algum dos comparecentes não for conhecido do tabelião, nem puder identificar-se por documento, deverão participar do ato pelo menos duas testemunhas que o conheçam e atestem sua identidade."]],["CC, art. 216",["Art. 216. Farão a mesma prova que os originais as certidões textuais de qualquer peça judicial, do protocolo das audiências, ou de outro qualquer livro a cargo do escrivão, sendo extraídas por ele, ou sob a sua vigilância, e por ele subscritas, assim como os traslados de autos, quando por outro escrivão consertados."]],["CC, art. 217",["Art. 217. Terão a mesma força probante os traslados e as certidões, extraídos por tabelião ou oficial de registro, de instrumentos ou documentos lançados em suas notas."]],["CC, art. 218",["Art. 218. Os traslados e as certidões considerar-se-ão instrumentos públicos, se os originais se houverem produzido em juízo como prova de algum ato."]],["CC, art. 219",["Art. 219. As declarações constantes de documentos assinados presumem-se verdadeiras em relação aos signatários.","Parágrafo único. Não tendo relação direta, porém, com as disposições principais ou com a legitimidade das partes, as declarações enunciativas não eximem os interessados em sua veracidade do ônus de prová-las."]],["CC, art. 220",["Art. 220. A anuência ou a autorização de outrem, necessária à validade de um ato, provar-se-á do mesmo modo que este, e constará, sempre que se possa, do próprio instrumento."]],["CC, art. 221",["Art. 221. O instrumento particular, feito e assinado, ou somente assinado por quem esteja na livre disposição e administração de seus bens, prova as obrigações convencionais de qualquer valor; mas os seus efeitos, bem como os da cessão, não se operam, a respeito de terceiros, antes de registrado no registro público.","Parágrafo único. A prova do instrumento particular pode suprir-se pelas outras de caráter legal."]],["CC, art. 222",["Art. 222. O telegrama, quando lhe for contestada a autenticidade, faz prova mediante conferência com o original assinado."]],["CC, art. 223",["Art. 223. A cópia fotográfica de documento, conferida por tabelião de notas, valerá como prova de declaração da vontade, mas, impugnada sua autenticidade, deverá ser exibido o original.","Parágrafo único. A prova não supre a ausência do título de crédito, ou do original, nos casos em que a lei ou as circunstâncias condicionarem o exercício do direito à sua exibição."]],["CC, art. 224",["Art. 224. Os documentos redigidos em língua estrangeira serão traduzidos para o português para ter efeitos legais no País."]],["CC, art. 225",["Art. 225. As reproduções fotográficas, cinematográficas, os registros fonográficos e, em geral, quaisquer outras reproduções mecânicas ou eletrônicas de fatos ou de coisas fazem prova plena destes, se a parte, contra quem forem exibidos, não lhes impugnar a exatidão."]],["CC, art. 226",["Art. 226. Os livros e fichas dos empresários e sociedades provam contra as pessoas a que pertencem, e, em seu favor, quando, escriturados sem vício extrínseco ou intrínseco, forem confirmados por outros subsídios.","Parágrafo único. A prova resultante dos livros e fichas não é bastante nos casos em que a lei exige escritura pública, ou escrito particular revestido de requisitos especiais, e pode ser ilidida pela comprovação da falsidade ou inexatidão dos lançamentos."]],["CC, art. 227",["Art. 227. (“Caput” do artigo revogado pela Lei nº 13.105, de 16/3/2015, publicada no DOU de 17/3/2015, em vigor após 1 ano da publicação)","Parágrafo único. Qualquer que seja o valor do negócio jurídico, a prova testemunhal é admissível como subsidiária ou complementar da prova por escrito."]],["CC, art. 228",["Art. 228. Não podem ser admitidos como testemunhas:","I - os menores de dezesseis anos;","II - (Revogado pela Lei nº 13.146, de 6/7/2015, publicada no DOU de 7/7/2015, em vigor 180 dias após a publicação)","III - (Revogado pela Lei nº 13.146, de 6/7/2015, publicada no DOU de 7/7/2015, em vigor 180 dias após a publicação)","IV - o interessado no litígio, o amigo íntimo ou o inimigo capital das partes;","V - os cônjuges, os ascendentes, os descendentes e os colaterais, até o terceiro grau de alguma das partes, por consangüinidade, ou afinidade.","§ 1º Para a prova de fatos que só elas conheçam, pode o juiz admitir o depoimento das pessoas a que se refere este artigo. (Parágrafo único transformado em § 1º pela Lei nº 13.146, de 6/7/2015, publicada no DOU de 7/7/2015, em vigor 180 dias após a publicação)","§ 2º A pessoa com deficiência poderá testemunhar em igualdade de condições com as demais pessoas, sendo-lhe assegurados todos os recursos de tecnologia assistiva. (Parágrafo acrescido pela Lei nº 13.146, de 6/7/2015, publicada no DOU de 7/7/2015, em vigor 180 dias após a publicação)"]],["CC, art. 229",["Art. 229. (Revogado pela Lei nº 13.105, de 16/3/2015, publicada no DOU de 17/3/2015, em vigor após 1 ano da publicação)"]],["CC, art. 230",["Art. 230. (Revogado pela Lei nº 13.105, de 16/3/2015, publicada no DOU de 17/3/2015, em vigor após 1 ano da publicação)"]],["CC, art. 231",["Art. 231. Aquele que se nega a submeter-se a exame médico necessário não poderá aproveitar-se de sua recusa."]],["CC, art. 232",["Art. 232. A recusa à perícia médica ordenada pelo juiz poderá suprir a prova que se pretendia obter com o exame."]]]},"6":{"1":[["CC, art. 233",["Art. 233. A obrigação de dar coisa certa abrange os acessórios dela embora não mencionados, salvo se o contrário resultar do título ou das circunstâncias do caso."]],["CC, art. 234",["Art. 234. Se, no caso do artigo antecedente, a coisa se perder, sem culpa do devedor, antes da tradição, ou pendente a condição suspensiva, fica resolvida a obrigação para ambas as partes; se a perda resultar de culpa do devedor, responderá este pelo equivalente e mais perdas e danos."]],["CC, art. 235",["Art. 235. Deteriorada a coisa, não sendo o devedor culpado, poderá o credor resolver a obrigação, ou aceitar a coisa, abatido de seu preço o valor que perdeu."]],["CC, art. 236",["Art. 236. Sendo culpado o devedor, poderá o credor exigir o equivalente, ou aceitar a coisa no estado em que se acha, com direito a reclamar, em um ou em outro caso, indenização das perdas e danos."]],["CC, art. 237",["Art. 237. Até a tradição pertence ao devedor a coisa, com os seus melhoramentos e acrescidos, pelos quais poderá exigir aumento no preço; se o credor não anuir, poderá o devedor resolver a obrigação.","Parágrafo único. Os frutos percebidos são do devedor, cabendo ao credor os pendentes."]],["CC, art. 238",["Art. 238. Se a obrigação for de restituir coisa certa, e esta, sem culpa do devedor, se perder antes da tradição, sofrerá o credor a perda, e a obrigação se resolverá, ressalvados os seus direitos até o dia da perda."]],["CC, art. 239",["Art. 239. Se a coisa se perder por culpa do devedor, responderá este pelo equivalente, mais perdas e danos."]],["CC, art. 240",["Art. 240. Se a coisa restituível se deteriorar sem culpa do devedor, recebê-la-á o credor, tal qual se ache, sem direito a indenização; se por culpa do devedor, observar-se-á o disposto no art. 239."]],["CC, art. 241",["Art. 241. Se, no caso do art. 238, sobrevier melhoramento ou acréscimo à coisa, sem despesa ou trabalho do devedor, lucrará o credor, desobrigado de indenização."]],["CC, art. 242",["Art. 242. Se para o melhoramento, ou aumento, empregou o devedor trabalho ou dispêndio, o caso se regulará pelas normas deste Código atinentes às benfeitorias realizadas pelo possuidor de boa-fé ou de má-fé.","Parágrafo único. Quanto aos frutos percebidos, observar-se-á, do mesmo modo, o disposto neste Código, acerca do possuidor de boa-fé ou de má-fé."]]],"2":[["CC, art. 243",["Art. 243. A coisa incerta será indicada, ao menos, pelo gênero e pela quantidade."]],["CC, art. 244",["Art. 244. Nas coisas determinadas pelo gênero e pela quantidade, a escolha pertence ao devedor, se o contrário não resultar do título da obrigação; mas não poderá dar a coisa pior, nem será obrigado a prestar a melhor."]],["CC, art. 245",["Art. 245. Cientificado da escolha o credor, vigorará o disposto na Seção antecedente."]],["CC, art. 246",["Art. 246. Antes da escolha, não poderá o devedor alegar perda ou deterioração da coisa, ainda que por força maior ou caso fortuito."]]],"3":[["CC, art. 247",["Art. 247. Incorre na obrigação de indenizar perdas e danos o devedor que recusar a prestação a ele só imposta, ou só por ele exeqüível."]],["CC, art. 248",["Art. 248. Se a prestação do fato tornar-se impossível sem culpa do devedor, resolver-se-á a obrigação; se por culpa dele, responderá por perdas e danos."]],["CC, art. 249",["Art. 249. Se o fato puder ser executado por terceiro, será livre ao credor mandá-lo executar à custa do devedor, havendo recusa ou mora deste, sem prejuízo da indenização cabível.","Parágrafo único. Em caso de urgência, pode o credor, independentemente de autorização judicial, executar ou mandar executar o fato, sendo depois ressarcido."]],["CC, art. 250",["Art. 250. Extingue-se a obrigação de não fazer, desde que, sem culpa do devedor, se lhe torne impossível abster-se do ato, que se obrigou a não praticar."]],["CC, art. 251",["Art. 251. Praticado pelo devedor o ato, a cuja abstenção se obrigara, o credor pode exigir dele que o desfaça, sob pena de se desfazer à sua custa, ressarcindo o culpado perdas e danos.","Parágrafo único. Em caso de urgência, poderá o credor desfazer ou mandar desfazer, independentemente de autorização judicial, sem prejuízo do ressarcimento devido."]]],"4":[["CC, art. 252",["Art. 252. Nas obrigações alternativas, a escolha cabe ao devedor, se outra coisa não se estipulou.","§ 1º Não pode o devedor obrigar o credor a receber parte em uma prestação e parte em outra.","§ 2º Quando a obrigação for de prestações periódicas, a faculdade de opção poderá ser exercida em cada período.","§ 3º No caso de pluralidade de optantes, não havendo acordo unânime entre eles, decidirá o juiz, findo o prazo por este assinado para a deliberação.","§ 4º Se o título deferir a opção a terceiro, e este não quiser, ou não puder exercê-la, caberá ao juiz a escolha se não houver acordo entre as partes."]],["CC, art. 253",["Art. 253. Se uma das duas prestações não puder ser objeto de obrigação ou se tornada inexeqüível, subsistirá o débito quanto à outra."]],["CC, art. 254",["Art. 254. Se, por culpa do devedor, não se puder cumprir nenhuma das prestações, não competindo ao credor a escolha, ficará aquele obrigado a pagar o valor da que por último se impossibilitou, mais as perdas e danos que o caso determinar."]],["CC, art. 255",["Art. 255. Quando a escolha couber ao credor e uma das prestações tornar-se impossível por culpa do devedor, o credor terá direito de exigir a prestação subsistente ou o valor da outra, com perdas e danos; se, por culpa do devedor, ambas as prestações se tornarem inexeqüíveis, poderá o credor reclamar o valor de qualquer das duas, além da indenização por perdas e danos."]],["CC, art. 256",["Art. 256. Se todas as prestações se tornarem impossíveis sem culpa do devedor, extinguir-se-á a obrigação."]],["CC, art. 257",["Art. 257. Havendo mais de um devedor ou mais de um credor em obrigação divisível, esta presume-se dividida em tantas obrigações, iguais e distintas, quantos os credores ou devedores."]],["CC, art. 258",["Art. 258. A obrigação é indivisível quando a prestação tem por objeto uma coisa ou um fato não suscetíveis de divisão, por sua natureza, por motivo de ordem econômica, ou dada a razão determinante do negócio jurídico."]],["CC, art. 259",["Art. 259. Se, havendo dois ou mais devedores, a prestação não for divisível, cada um será obrigado pela dívida toda.","Parágrafo único. O devedor, que paga a dívida, sub-roga-se no direito do credor em relação aos outros coobrigados."]],["CC, art. 260",["Art. 260. Se a pluralidade for dos credores, poderá cada um destes exigir a dívida inteira; mas o devedor ou devedores se desobrigarão, pagando:","I - a todos conjuntamente;","II - a um, dando este caução de ratificação dos outros credores."]],["CC, art. 261",["Art. 261. Se um só dos credores receber a prestação por inteiro, a cada um dos outros assistirá o direito de exigir dele em dinheiro a parte que lhe caiba no total."]],["CC, art. 262",["Art. 262. Se um dos credores remitir a dívida, a obrigação não ficará extinta para com os outros; mas estes só a poderão exigir, descontada a quota do credor remitente.","Parágrafo único. O mesmo critério se observará no caso de transação, novação, compensação ou confusão."]],["CC, art. 263",["Art. 263. Perde a qualidade de indivisível a obrigação que se resolver em perdas e danos.","§ 1º Se, para efeito do disposto neste artigo, houver culpa de todos os devedores, responderão todos por partes iguais.","§ 2º Se for de um só a culpa, ficarão exonerados os outros, respondendo só esse pelas perdas e danos."]]],"5":[["CC, art. 264",["Art. 264. Há solidariedade, quando na mesma obrigação concorre mais de um credor, ou mais de um devedor, cada um com direito, ou obrigado, à dívida toda."]],["CC, art. 265",["Art. 265. A solidariedade não se presume; resulta da lei ou da vontade das partes."]],["CC, art. 266",["Art. 266. A obrigação solidária pode ser pura e simples para um dos co-credores ou co-devedores, e condicional, ou a prazo, ou pagável em lugar diferente, para o outro."]],["CC, art. 267",["Art. 267. Cada um dos credores solidários tem direito a exigir do devedor o cumprimento da prestação por inteiro."]],["CC, art. 268",["Art. 268. Enquanto alguns dos credores solidários não demandarem o devedor comum, a qualquer daqueles poderá este pagar."]],["CC, art. 269",["Art. 269. O pagamento feito a um dos credores solidários extingue a dívida até o montante do que foi pago."]],["CC, art. 270",["Art. 270. Se um dos credores solidários falecer deixando herdeiros, cada um destes só terá direito a exigir e receber a quota do crédito que corresponder ao seu quinhão hereditário, salvo se a obrigação for indivisível."]],["CC, art. 271",["Art. 271. Convertendo-se a prestação em perdas e danos, subsiste, para todos os efeitos, a solidariedade."]],["CC, art. 272",["Art. 272. O credor que tiver remitido a dívida ou recebido o pagamento responderá aos outros pela parte que lhes caiba."]],["CC, art. 273",["Art. 273. A um dos credores solidários não pode o devedor opor as exceções pessoais oponíveis aos outros."]],["CC, art. 274",["Art. 274. O julgamento contrário a um dos credores solidários não atinge os demais, mas o julgamento favorável aproveita-lhes, sem prejuízo de exceção pessoal que o devedor tenha direito de invocar em relação a qualquer deles. (Artigo com redação dada pela Lei nº 13.105, de 16/3/2015, publicada no DOU de 16/3/2015, em vigor 1 ano após a publicação)"]],["CC, art. 275",["Art. 275. O credor tem direito a exigir e receber de um ou de alguns dos devedores, parcial ou totalmente, a dívida comum; se o pagamento tiver sido parcial, todos os demais devedores continuam obrigados solidariamente pelo resto.","Parágrafo único. Não importará renúncia da solidariedade a propositura de ação pelo credor contra um ou alguns dos devedores."]],["CC, art. 276",["Art. 276. Se um dos devedores solidários falecer deixando herdeiros, nenhum destes será obrigado a pagar senão a quota que corresponder ao seu quinhão hereditário, salvo se a obrigação for indivisível; mas todos reunidos serão considerados como um devedor solidário em relação aos demais devedores."]],["CC, art. 277",["Art. 277. O pagamento parcial feito por um dos devedores e a remissão por ele obtida não aproveitam aos outros devedores, senão até à concorrência da quantia paga ou relevada."]],["CC, art. 278",["Art. 278. Qualquer cláusula, condição ou obrigação adicional, estipulada entre um dos devedores solidários e o credor, não poderá agravar a posição dos outros sem consentimento destes."]],["CC, art. 279",["Art. 279. Impossibilitando-se a prestação por culpa de um dos devedores solidários, subsiste para todos o encargo de pagar o equivalente; mas pelas perdas e danos só responde o culpado."]],["CC, art. 280",["Art. 280. Todos os devedores respondem pelos juros da mora, ainda que a ação tenha sido proposta somente contra um; mas o culpado responde aos outros pela obrigação acrescida."]],["CC, art. 281",["Art. 281. O devedor demandado pode opor ao credor as exceções que lhe forem pessoais e as comuns a todos; não lhe aproveitando as exceções pessoais a outro co-devedor."]],["CC, art. 282",["Art. 282. O credor pode renunciar à solidariedade em favor de um, de alguns ou de todos os devedores.","Parágrafo único. Se o credor exonerar da solidariedade um ou mais devedores, subsistirá a dos demais."]],["CC, art. 283",["Art. 283. O devedor que satisfez a dívida por inteiro tem direito a exigir de cada um dos co-devedores a sua quota, dividindo-se igualmente por todos a do insolvente, se o houver, presumindo-se iguais, no débito, as partes de todos os co-devedores."]],["CC, art. 284",["Art. 284. No caso de rateio entre os co-devedores, contribuirão também os exonerados da solidariedade pelo credor, pela parte que na obrigação incumbia ao insolvente."]],["CC, art. 285",["Art. 285. Se a dívida solidária interessar exclusivamente a um dos devedores, responderá este por toda ela para com aquele que pagar."]]],"6":[["CC, art. 286",["Art. 286. O credor pode ceder o seu crédito, se a isso não se opuser a natureza da obrigação, a lei, ou a convenção com o devedor; a cláusula proibitiva da cessão não poderá ser oposta ao cessionário de boa-fé, se não constar do instrumento da obrigação."]],["CC, art. 287",["Art. 287. Salvo disposição em contrário, na cessão de um crédito abrangem-se todos os seus acessórios."]],["CC, art. 288",["Art. 288. É ineficaz, em relação a terceiros, a transmissão de um crédito, se não celebrar-se mediante instrumento público, ou instrumento particular revestido das solenidades do § 1 o do art. 654."]],["CC, art. 289",["Art. 289. O cessionário de crédito hipotecário tem o direito de fazer averbar a cessão no registro do imóvel."]],["CC, art. 290",["Art. 290. A cessão do crédito não tem eficácia em relação ao devedor, senão quando a este notificada; mas por notificado se tem o devedor que, em escrito público ou particular, se declarou ciente da cessão feita."]],["CC, art. 291",["Art. 291. Ocorrendo várias cessões do mesmo crédito, prevalece a que se completar com a tradição do título do crédito cedido."]],["CC, art. 292",["Art. 292. Fica desobrigado o devedor que, antes de ter conhecimento da cessão, paga ao credor primitivo, ou que, no caso de mais de uma cessão notificada, paga ao cessionário que lhe apresenta, com o título de cessão, o da obrigação cedida; quando o crédito constar de escritura pública, prevalecerá a prioridade da notificação."]],["CC, art. 293",["Art. 293. Independentemente do conhecimento da cessão pelo devedor, pode o cessionário exercer os atos conservatórios do direito cedido."]],["CC, art. 294",["Art. 294. O devedor pode opor ao cessionário as exceções que lhe competirem, bem como as que, no momento em que veio a ter conhecimento da cessão, tinha contra o cedente."]],["CC, art. 295",["Art. 295. Na cessão por título oneroso, o cedente, ainda que não se responsabilize, fica responsável ao cessionário pela existência do crédito ao tempo em que lhe cedeu; a mesma responsabilidade lhe cabe nas cessões por título gratuito, se tiver procedido de má-fé."]],["CC, art. 296",["Art. 296. Salvo estipulação em contrário, o cedente não responde pela solvência do devedor."]],["CC, art. 297",["Art. 297. O cedente, responsável ao cessionário pela solvência do devedor, não responde por mais do que daquele recebeu, com os respectivos juros; mas tem de ressarcir-lhe as despesas da cessão e as que o cessionário houver feito com a cobrança."]],["CC, art. 298",["Art. 298. O crédito, uma vez penhorado, não pode mais ser transferido pelo credor que tiver conhecimento da penhora; mas o devedor que o pagar, não tendo notificação dela, fica exonerado, subsistindo somente contra o credor os direitos de terceiro."]],["CC, art. 299",["Art. 299. É facultado a terceiro assumir a obrigação do devedor, com o consentimento expresso do credor, ficando exonerado o devedor primitivo, salvo se aquele, ao tempo da assunção, era insolvente e o credor o ignorava.","Parágrafo único. Qualquer das partes pode assinar prazo ao credor para que consinta na assunção da dívida, interpretando-se o seu silêncio como recusa."]],["CC, art. 300",["Art. 300. Salvo assentimento expresso do devedor primitivo, consideram-se extintas, a partir da assunção da dívida, as garantias especiais por ele originariamente dadas ao credor."]],["CC, art. 301",["Art. 301. Se a substituição do devedor vier a ser anulada, restaura-se o débito, com todas as suas garantias, salvo as garantias prestadas por terceiros, exceto se este conhecia o vício que inquinava a obrigação."]],["CC, art. 302",["Art. 302. O novo devedor não pode opor ao credor as exceções pessoais que competiam ao devedor primitivo."]],["CC, art. 303",["Art. 303. O adquirente de imóvel hipotecado pode tomar a seu cargo o pagamento do crédito garantido; se o credor, notificado, não impugnar em trinta dias a transferência do débito, entender-se-á dado o assentimento."]]],"8":[["CC, art. 334",["Art. 334. Considera-se pagamento, e extingue a obrigação, o depósito judicial ou em estabelecimento bancário da coisa devida, nos casos e forma legais."]],["CC, art. 335",["Art. 335. A consignação tem lugar:","I - se o credor não puder, ou, sem justa causa, recusar receber o pagamento, ou dar quitação na devida forma;","II - se o credor não for, nem mandar receber a coisa no lugar, tempo e condição devidos;","III - se o credor for incapaz de receber, for desconhecido, declarado ausente, ou residir em lugar incerto ou de acesso perigoso ou difícil;","IV - se ocorrer dúvida sobre quem deva legitimamente receber o objeto do pagamento;","V - se pender litígio sobre o objeto do pagamento."]],["CC, art. 336",["Art. 336. Para que a consignação tenha força de pagamento, será mister concorram, em relação às pessoas, ao objeto, modo e tempo, todos os requisitos sem os quais não é válido o pagamento."]],["CC, art. 337",["Art. 337. O depósito requerer-se-á no lugar do pagamento, cessando, tanto que se efetue, para o depositante, os juros da dívida e os riscos, salvo se for julgado improcedente."]],["CC, art. 338",["Art. 338. Enquanto o credor não declarar que aceita o depósito, ou não o impugnar, poderá o devedor requerer o levantamento, pagando as respectivas despesas, e subsistindo a obrigação para todas as conseqüências de direito."]],["CC, art. 339",["Art. 339. Julgado procedente o depósito, o devedor já não poderá levantá-lo, embora o credor consinta, senão de acordo com os outros devedores e fiadores."]],["CC, art. 340",["Art. 340. O credor que, depois de contestar a lide ou aceitar o depósito, aquiescer no levantamento, perderá a preferência e a garantia que lhe competiam com respeito à coisa consignada, ficando para logo desobrigados os co-devedores e fiadores que não tenham anuído."]],["CC, art. 341",["Art. 341. Se a coisa devida for imóvel ou corpo certo que deva ser entregue no mesmo lugar onde está, poderá o devedor citar o credor para vir ou mandar recebê-la, sob pena de ser depositada."]],["CC, art. 342",["Art. 342. Se a escolha da coisa indeterminada competir ao credor, será ele citado para esse fim, sob cominação de perder o direito e de ser depositada a coisa que o devedor escolher; feita a escolha pelo devedor, proceder-se-á como no artigo antecedente."]],["CC, art. 343",["Art. 343. As despesas com o depósito, quando julgado procedente, correrão à conta do credor, e, no caso contrário, à conta do devedor."]],["CC, art. 344",["Art. 344. O devedor de obrigação litigiosa exonerar-se-á mediante consignação, mas, se pagar a qualquer dos pretendidos credores, tendo conhecimento do litígio, assumirá o risco do pagamento."]],["CC, art. 345",["Art. 345. Se a dívida se vencer, pendendo litígio entre credores que se pretendem mutuamente excluir, poderá qualquer deles requerer a consignação."]],["CC, art. 346",["Art. 346. A sub-rogação opera-se, de pleno direito, em favor:","I - do credor que paga a dívida do devedor comum;","II - do adquirente do imóvel hipotecado, que paga a credor hipotecário, bem como do terceiro que efetiva o pagamento para não ser privado de direito sobre imóvel;","III - do terceiro interessado, que paga a dívida pela qual era ou podia ser obrigado, no todo ou em parte."]],["CC, art. 347",["Art. 347. A sub-rogação é convencional:","I - quando o credor recebe o pagamento de terceiro e expressamente lhe transfere todos os seus direitos;","II - quando terceira pessoa empresta ao devedor a quantia precisa para solver a dívida, sob a condição expressa de ficar o mutuante sub-rogado nos direitos do credor satisfeito."]],["CC, art. 348",["Art. 348. Na hipótese do inciso I do artigo antecedente, vigorará o disposto quanto à cessão do crédito."]],["CC, art. 349",["Art. 349. A sub-rogação transfere ao novo credor todos os direitos, ações, privilégios e garantias do primitivo, em relação à dívida, contra o devedor principal e os fiadores."]],["CC, art. 350",["Art. 350. Na sub-rogação legal o sub-rogado não poderá exercer os direitos e as ações do credor, senão até à soma que tiver desembolsado para desobrigar o devedor."]],["CC, art. 351",["Art. 351. O credor originário, só em parte reembolsado, terá preferência ao sub-rogado, na cobrança da dívida restante, se os bens do devedor não chegarem para saldar inteiramente o que a um e outro dever."]]],"9":[["CC, art. 352",["Art. 352. A pessoa obrigada por dois ou mais débitos da mesma natureza, a um só credor, tem o direito de indicar a qual deles oferece pagamento, se todos forem líquidos e vencidos."]],["CC, art. 353",["Art. 353. Não tendo o devedor declarado em qual das dívidas líquidas e vencidas quer imputar o pagamento, se aceitar a quitação de uma delas, não terá direito a reclamar contra a imputação feita pelo credor, salvo provando haver ele cometido violência ou dolo."]],["CC, art. 354",["Art. 354. Havendo capital e juros, o pagamento imputar-se-á primeiro nos juros vencidos, e depois no capital, salvo estipulação em contrário, ou se o credor passar a quitação por conta do capital."]],["CC, art. 355",["Art. 355. Se o devedor não fizer a indicação do art. 352, e a quitação for omissa quanto à imputação, esta se fará nas dívidas líquidas e vencidas em primeiro lugar. Se as dívidas forem todas líquidas e vencidas ao mesmo tempo, a imputação far-se-á na mais onerosa."]],["CC, art. 356",["Art. 356. O credor pode consentir em receber prestação diversa da que lhe é devida."]],["CC, art. 357",["Art. 357. Determinado o preço da coisa dada em pagamento, as relações entre as partes regular-se-ão pelas normas do contrato de compra e venda."]],["CC, art. 358",["Art. 358. Se for título de crédito a coisa dada em pagamento, a transferência importará em cessão."]],["CC, art. 359",["Art. 359. Se o credor for evicto da coisa recebida em pagamento, restabelecer-se-á a obrigação primitiva, ficando sem efeito a quitação dada, ressalvados os direitos de terceiros."]],["CC, art. 360",["Art. 360. Dá-se a novação:","I - quando o devedor contrai com o credor nova dívida para extinguir e substituir a anterior;","II - quando novo devedor sucede ao antigo, ficando este quite com o credor;","III - quando, em virtude de obrigação nova, outro credor é substituído ao antigo, ficando o devedor quite com este."]],["CC, art. 361",["Art. 361. Não havendo ânimo de novar, expresso ou tácito mas inequívoco, a segunda obrigação confirma simplesmente a primeira."]],["CC, art. 362",["Art. 362. A novação por substituição do devedor pode ser efetuada independentemente de consentimento deste."]],["CC, art. 363",["Art. 363. Se o novo devedor for insolvente, não tem o credor, que o aceitou, ação regressiva contra o primeiro, salvo se este obteve por má-fé a substituição."]],["CC, art. 364",["Art. 364. A novação extingue os acessórios e garantias da dívida, sempre que não houver estipulação em contrário. Não aproveitará, contudo, ao credor ressalvar o penhor, a hipoteca ou a anticrese, se os bens dados em garantia pertencerem a terceiro que não foi parte na novação."]],["CC, art. 365",["Art. 365. Operada a novação entre o credor e um dos devedores solidários, somente sobre os bens do que contrair a nova obrigação subsistem as preferências e garantias do crédito novado. Os outros devedores solidários ficam por esse fato exonerados."]],["CC, art. 366",["Art. 366. Importa exoneração do fiador a novação feita sem seu consenso com o devedor principal."]],["CC, art. 367",["Art. 367. Salvo as obrigações simplesmente anuláveis, não podem ser objeto de novação obrigações nulas ou extintas."]]],"10":[["CC, art. 368",["Art. 368. Se duas pessoas forem ao mesmo tempo credor e devedor uma da outra, as duas obrigações extinguem-se, até onde se compensarem."]],["CC, art. 369",["Art. 369. A compensação efetua-se entre dívidas líquidas, vencidas e de coisas fungíveis."]],["CC, art. 370",["Art. 370. Embora sejam do mesmo gênero as coisas fungíveis, objeto das duas prestações, não se compensarão, verificando-se que diferem na qualidade, quando especificada no contrato."]],["CC, art. 371",["Art. 371. O devedor somente pode compensar com o credor o que este lhe dever; mas o fiador pode compensar sua dívida com a de seu credor ao afiançado."]],["CC, art. 372",["Art. 372. Os prazos de favor, embora consagrados pelo uso geral, não obstam a compensação."]],["CC, art. 373",["Art. 373. A diferença de causa nas dívidas não impede a compensação, exceto:","I - se provier de esbulho, furto ou roubo;","II - se uma se originar de comodato, depósito ou alimentos;","III - se uma for de coisa não suscetível de penhora."]],["CC, art. 374",["Art. 374 . (Revogado pela Lei nº 10.677, de 22/5/2003 )"]],["CC, art. 375",["Art. 375. Não haverá compensação quando as partes, por mútuo acordo, a excluírem, ou no caso de renúncia prévia de uma delas."]],["CC, art. 376",["Art. 376. Obrigando-se por terceiro uma pessoa, não pode compensar essa dívida com a que o credor dele lhe dever."]],["CC, art. 377",["Art. 377. O devedor que, notificado, nada opõe à cessão que o credor faz a terceiros dos seus direitos, não pode opor ao cessionário a compensação, que antes da cessão teria podido opor ao cedente. Se, porém, a cessão lhe não tiver sido notificada, poderá opor ao cessionário compensação do crédito que antes tinha contra o cedente."]],["CC, art. 378",["Art. 378. Quando as duas dívidas não são pagáveis no mesmo lugar, não se podem compensar sem dedução das despesas necessárias à operação."]],["CC, art. 379",["Art. 379. Sendo a mesma pessoa obrigada por várias dívidas compensáveis, serão observadas, no compensá-las, as regras estabelecidas quanto à imputação do pagamento."]],["CC, art. 380",["Art. 380. Não se admite a compensação em prejuízo de direito de terceiro. O devedor que se torne credor do seu credor, depois de penhorado o crédito deste, não pode opor ao exeqüente a compensação, de que contra o próprio credor disporia."]],["CC, art. 381",["Art. 381. Extingue-se a obrigação, desde que na mesma pessoa se confundam as qualidades de credor e devedor."]],["CC, art. 382",["Art. 382. A confusão pode verificar-se a respeito de toda a dívida, ou só de parte dela."]],["CC, art. 383",["Art. 383. A confusão operada na pessoa do credor ou devedor solidário só extingue a obrigação até a concorrência da respectiva parte no crédito, ou na dívida, subsistindo quanto ao mais a solidariedade."]],["CC, art. 384",["Art. 384. Cessando a confusão, para logo se restabelece, com todos os seus acessórios, a obrigação anterior."]],["CC, art. 385",["Art. 385. A remissão da dívida, aceita pelo devedor, extingue a obrigação, mas sem prejuízo de terceiro."]],["CC, art. 386",["Art. 386. A devolução voluntária do título da obrigação, quando por escrito particular, prova desoneração do devedor e seus co-obrigados, se o credor for capaz de alienar, e o devedor capaz de adquirir."]],["CC, art. 387",["Art. 387. A restituição voluntária do objeto empenhado prova a renúncia do credor à garantia real, não a extinção da dívida."]],["CC, art. 388",["Art. 388. A remissão concedida a um dos co-devedores extingue a dívida na parte a ele correspondente; de modo que, ainda reservando o credor a solidariedade contra os outros, já lhes não pode cobrar o débito sem dedução da parte remitida."]]],"11":[["CC, art. 389",["Art. 389. Não cumprida a obrigação, responde o devedor por perdas e danos, mais juros, atualização monetária e honorários de advogado. (“Caput” do artigo com redação dada pela Lei nº 14.905, de 28/6/2024, publicada no DOU de 1º/7/2024, em vigor 60 dias após a publicação)","Parágrafo único. Na hipótese de o índice de atualização monetária não ter sido convencionado ou não estar previsto em lei específica, será aplicada a variação do Índice Nacional de Preços ao Consumidor Amplo (IPCA), apurado e divulgado pela Fundação Instituto Brasileiro de Geografia e Estatística (IBGE), ou do índice que vier a substituí-lo. (Parágrafo único acrescido pela Lei nº 14.905, de 28/6/2024, publicada no DOU de 1º/7/2024, em vigor 60 dias após a publicação)"]],["CC, art. 390",["Art. 390. Nas obrigações negativas o devedor é havido por inadimplente desde o dia em que executou o ato de que se devia abster."]],["CC, art. 391",["Art. 391. Pelo inadimplemento das obrigações respondem todos os bens do devedor."]],["CC, art. 392",["Art. 392. Nos contratos benéficos, responde por simples culpa o contratante, a quem o contrato aproveite, e por dolo aquele a quem não favoreça. Nos contratos onerosos, responde cada uma das partes por culpa, salvo as exceções previstas em lei."]],["CC, art. 393",["Art. 393. O devedor não responde pelos prejuízos resultantes de caso fortuito ou força maior, se expressamente não se houver por eles responsabilizado.","Parágrafo único. O caso fortuito ou de força maior verifica-se no fato necessário, cujos efeitos não era possível evitar ou impedir."]],["CC, art. 394",["Art. 394. Considera-se em mora o devedor que não efetuar o pagamento e o credor que não quiser recebê-lo no tempo, lugar e forma que a lei ou a convenção estabelecer."]],["CC, art. 395",["Art. 395. Responde o devedor pelos prejuízos a que sua mora der causa, mais juros, atualização dos valores monetários e honorários de advogado. (“Caput” do artigo com redação dada pela Lei nº 14.905, de 28/6/2024, publicada no DOU de 1º/7/2024, em vigor 60 dias após a publicação)","Parágrafo único. Se a prestação, devido à mora, se tornar inútil ao credor, este poderá enjeitá-la, e exigir a satisfação das perdas e danos."]],["CC, art. 396",["Art. 396. Não havendo fato ou omissão imputável ao devedor, não incorre este em mora."]],["CC, art. 397",["Art. 397. O inadimplemento da obrigação, positiva e líquida, no seu termo, constitui de pleno direito em mora o devedor.","Parágrafo único. Não havendo termo, a mora se constitui mediante interpelação judicial ou extrajudicial."]],["CC, art. 398",["Art. 398. Nas obrigações provenientes de ato ilícito, considera-se o devedor em mora, desde que o praticou."]],["CC, art. 399",["Art. 399. O devedor em mora responde pela impossibilidade da prestação, embora essa impossibilidade resulte de caso fortuito ou de força maior, se estes ocorrerem durante o atraso; salvo se provar isenção de culpa, ou que o dano sobreviria ainda quando a obrigação fosse oportunamente desempenhada."]],["CC, art. 400",["Art. 400. A mora do credor subtrai o devedor isento de dolo à responsabilidade pela conservação da coisa, obriga o credor a ressarcir as despesas empregadas em conservá-la, e sujeita-o a recebê-la pela estimação mais favorável ao devedor, se o seu valor oscilar entre o dia estabelecido para o pagamento e o da sua efetivação."]],["CC, art. 401",["Art. 401. Purga-se a mora:","I - por parte do devedor, oferecendo este a prestação mais a importância dos prejuízos decorrentes do dia da oferta;","II - por parte do credor, oferecendo-se este a receber o pagamento e sujeitando-se aos efeitos da mora até a mesma data."]]],"12":[["CC, art. 389",["Art. 389. Não cumprida a obrigação, responde o devedor por perdas e danos, mais juros, atualização monetária e honorários de advogado. (“Caput” do artigo com redação dada pela Lei nº 14.905, de 28/6/2024, publicada no DOU de 1º/7/2024, em vigor 60 dias após a publicação)","Parágrafo único. Na hipótese de o índice de atualização monetária não ter sido convencionado ou não estar previsto em lei específica, será aplicada a variação do Índice Nacional de Preços ao Consumidor Amplo (IPCA), apurado e divulgado pela Fundação Instituto Brasileiro de Geografia e Estatística (IBGE), ou do índice que vier a substituí-lo. (Parágrafo único acrescido pela Lei nº 14.905, de 28/6/2024, publicada no DOU de 1º/7/2024, em vigor 60 dias após a publicação)"]],["CC, art. 406",["Art. 406. Quando não forem convencionados, ou quando o forem sem taxa estipulada, ou quando provierem de determinação da lei, os juros serão fixados de acordo com a taxa legal. (“Caput” do artigo com redação dada pela Lei nº 14.905, de 28/6/2024, publicada no DOU de 1º/7/2024, em vigor 60 dias após a publicação)","§ 1º A taxa legal corresponderá à taxa referencial do Sistema Especial de Liquidação e de Custódia (Selic), deduzido o índice de atualização monetária de que trata o parágrafo único do art. 389 deste Código. (Parágrafo acrescido pela Lei nº 14.905, de 28/6/2024, publicada no DOU de 1º/7/2024, em vigor 60 dias após a publicação)","§ 2º A metodologia de cálculo da taxa legal e sua forma de aplicação serão definidas pelo Conselho Monetário Nacional e divulgadas pelo Banco Central do Brasil. (Parágrafo acrescido pela Lei nº 14.905, de 28/6/2024)","§ 3º Caso a taxa legal apresente resultado negativo, este será considerado igual a 0 (zero) para efeito de cálculo dos juros no período de referência. (Parágrafo acrescido pela Lei nº 14.905, de 28/6/2024, publicada no DOU de 1º/7/2024, em vigor 60 dias após a publicação)"]]],"13":[["CC, art. 408",["Art. 408. Incorre de pleno direito o devedor na cláusula penal, desde que, culposamente, deixe de cumprir a obrigação ou se constitua em mora."]],["CC, art. 409",["Art. 409. A cláusula penal estipulada conjuntamente com a obrigação, ou em ato posterior, pode referir-se à inexecução completa da obrigação, à de alguma cláusula especial ou simplesmente à mora."]],["CC, art. 410",["Art. 410. Quando se estipular a cláusula penal para o caso de total inadimplemento da obrigação, esta converter-se-á em alternativa a benefício do credor."]],["CC, art. 411",["Art. 411. Quando se estipular a cláusula penal para o caso de mora, ou em segurança especial de outra cláusula determinada, terá o credor o arbítrio de exigir a satisfação da pena cominada, juntamente com o desempenho da obrigação principal."]],["CC, art. 412",["Art. 412. O valor da cominação imposta na cláusula penal não pode exceder o da obrigação principal."]],["CC, art. 413",["Art. 413. A penalidade deve ser reduzida eqüitativamente pelo juiz se a obrigação principal tiver sido cumprida em parte, ou se o montante da penalidade for manifestamente excessivo, tendo-se em vista a natureza e a finalidade do negócio."]],["CC, art. 414",["Art. 414. Sendo indivisível a obrigação, todos os devedores, caindo em falta um deles, incorrerão na pena; mas esta só se poderá demandar integralmente do culpado, respondendo cada um dos outros somente pela sua quota.","Parágrafo único. Aos não culpados fica reservada a ação regressiva contra aquele que deu causa à aplicação da pena."]],["CC, art. 415",["Art. 415. Quando a obrigação for divisível, só incorre na pena o devedor ou o herdeiro do devedor que a infringir, e proporcionalmente à sua parte na obrigação."]],["CC, art. 416",["Art. 416. Para exigir a pena convencional, não é necessário que o credor alegue prejuízo.","Parágrafo único. Ainda que o prejuízo exceda ao previsto na cláusula penal, não pode o credor exigir indenização suplementar se assim não foi convencionado. Se o tiver sido, a pena vale como mínimo da indenização, competindo ao credor provar o prejuízo excedente."]],["CC, art. 417",["Art. 417. Se, por ocasião da conclusão do contrato, uma parte der à outra, a título de arras, dinheiro ou outro bem móvel, deverão as arras, em caso de execução, ser restituídas ou computadas na prestação devida, se do mesmo gênero da principal."]],["CC, art. 418",["Art. 418. Na hipótese de inexecução do contrato, se esta se der: (“Caput” do artigo com redação dada pela Lei nº 14.905, de 28/6/2024, publicada no DOU de 1º/7/2024, em vigor 60 dias após a publicação)","I - por parte de quem deu as arras, poderá a outra parte ter o contrato por desfeito, retendo-as; (Inciso acrescido pela Lei nº 14.905, de 28/6/2024, publicada no DOU de 1º/7/2024, em vigor 60 dias após a publicação)","II - por parte de quem recebeu as arras, poderá quem as deu haver o contrato por desfeito e exigir a sua devolução mais o equivalente, com atualização monetária, juros e honorários de advogado. (Inciso acrescido pela Lei nº 14.905, de 28/6/2024, publicada no DOU de 1º/7/2024, em vigor 60 dias após a publicação)"]],["CC, art. 419",["Art. 419. A parte inocente pode pedir indenização suplementar, se provar maior prejuízo, valendo as arras como taxa mínima. Pode, também, a parte inocente exigir a execução do contrato, com as perdas e danos, valendo as arras como o mínimo da indenização."]],["CC, art. 420",["Art. 420. Se no contrato for estipulado o direito de arrependimento para qualquer das partes, as arras ou sinal terão função unicamente indenizatória. Neste caso, quem as deu perdê-las-á em benefício da outra parte; e quem as recebeu devolvê-las-á, mais o equivalente. Em ambos os casos não haverá direito a indenização suplementar."]]],"14":[["CC, art. 886",["Art. 886. Não caberá a restituição por enriquecimento, se a lei conferir ao lesado outros meios para se ressarcir do prejuízo sofrido."]]],"15":[["CC, art. 955",["Art. 955. Procede-se à declaração de insolvência toda vez que as dívidas excedam à importância dos bens do devedor."]],["CC, art. 956",["Art. 956. A discussão entre os credores pode versar quer sobre a preferência entre eles disputada, quer sobre a nulidade, simulação, fraude, ou falsidade das dívidas e contratos."]],["CC, art. 957",["Art. 957. Não havendo título legal à preferência, terão os credores igual direito sobre os bens do devedor comum."]],["CC, art. 958",["Art. 958. Os títulos legais de preferência são os privilégios e os direitos reais."]],["CC, art. 959",["Art. 959. Conservam seus respectivos direitos os credores, hipotecários ou privilegiados:","I - sobre o preço do seguro da coisa gravada com hipoteca ou privilégio, ou sobre a indenização devida, havendo responsável pela perda ou danificação da coisa;","II - sobre o valor da indenização, se a coisa obrigada a hipoteca ou privilégio for desapropriada."]],["CC, art. 960",["Art. 960. Nos casos a que se refere o artigo antecedente, o devedor do seguro, ou da indenização, exonera-se pagando sem oposição dos credores hipotecários ou privilegiados."]],["CC, art. 961",["Art. 961. O crédito real prefere ao pessoal de qualquer espécie; o crédito pessoal privilegiado, ao simples; e o privilégio especial, ao geral."]],["CC, art. 962",["Art. 962. Quando concorrerem aos mesmos bens, e por título igual, dois ou mais credores da mesma classe especialmente privilegiados, haverá entre eles rateio proporcional ao valor dos respectivos créditos, se o produto não bastar para o pagamento integral de todos."]],["CC, art. 963",["Art. 963. O privilégio especial só compreende os bens sujeitos, por expressa disposição de lei, ao pagamento do crédito que ele favorece; e o geral, todos os bens não sujeitos a crédito real nem a privilégio especial."]],["CC, art. 964",["Art. 964. Têm privilégio especial:","I - sobre a coisa arrecadada e liquidada, o credor de custas e despesas judiciais feitas com a arrecadação e liquidação;","II - sobre a coisa salvada, o credor por despesas de salvamento;","III - sobre a coisa beneficiada, o credor por benfeitorias necessárias ou úteis;","IV - sobre os prédios rústicos ou urbanos, fábricas, oficinas, ou quaisquer outras construções, o credor de materiais, dinheiro, ou serviços para a sua edificação, reconstrução, ou melhoramento;","V - sobre os frutos agrícolas, o credor por sementes, instrumentos e serviços à cultura, ou à colheita;","VI - sobre as alfaias e utensílios de uso doméstico, nos prédios rústicos ou urbanos, o credor de aluguéis, quanto às prestações do ano corrente e do anterior;","VII - sobre os exemplares da obra existente na massa do editor, o autor dela, ou seus legítimos representantes, pelo crédito fundado contra aquele no contrato da edição;","VIII - sobre o produto da colheita, para a qual houver concorrido com o seu trabalho, e precipuamente a quaisquer outros créditos, ainda que reais, o trabalhador agrícola, quanto à dívida dos seus salários;","IX - sobre os produtos do abate, o credor por animais. (Inciso acrescido pela Lei nº 13.176, de 21/10/2015)"]],["CC, art. 965",["Art. 965. Goza de privilégio geral, na ordem seguinte, sobre os bens do devedor:","I - o crédito por despesa de seu funeral, feito segundo a condição do morto e o costume do lugar;","II - o crédito por custas judiciais, ou por despesas com a arrecadação e liquidação da massa;","III - o crédito por despesas com o luto do cônjuge sobrevivo e dos filhos do devedor falecido, se foram moderadas;","IV - o crédito por despesas com a doença de que faleceu o devedor, no semestre anterior à sua morte;","V - o crédito pelos gastos necessários à mantença do devedor falecido e sua família, no trimestre anterior ao falecimento;","VI - o crédito pelos impostos devidos à Fazenda Pública, no ano corrente e no anterior;","VII - o crédito pelos salários dos empregados do serviço doméstico do devedor, nos seus derradeiros seis meses de vida;","VIII - os demais créditos de privilégio geral."]]]},"7":{"0":[["CC, art. 421",["Art. 421. A liberdade contratual será exercida nos limites da função social do contrato. (“Caput” com redação dada pela Lei nº 13.874, de 20/9/2019)","Parágrafo único. Nas relações contratuais privadas, prevalecerão o princípio da intervenção mínima e a excepcionalidade da revisão contratual. (Parágrafo único acrescido pela Medida Provisória nº 881, de 30/4/2019, convertida e com redação dada pela Lei nº 13.874, de 20/9/2019)"]],["CC, art. 421-A",["Art. 421-A. Os contratos civis e empresariais presumem-se paritários e simétricos até a presença de elementos concretos que justifiquem o afastamento dessa presunção, ressalvados os regimes jurídicos previstos em leis especiais, garantido também que:","I - as partes negociantes poderão estabelecer parâmetros objetivos para a interpretação das cláusulas negociais e de seus pressupostos de revisão ou de resolução;","II - a alocação de riscos definida pelas partes deve ser respeitada e observada; e","III - a revisão contratual somente ocorrerá de maneira excepcional e limitada. (Artigo acrescido pela Lei nº 13.874, de 20/9/2019)"]]],"1":[["CC, art. 422",["Art. 422. Os contratantes são obrigados a guardar, assim na conclusão do contrato, como em sua execução, os princípios de probidade e boa-fé."]]],"2":[["CC, art. 423",["Art. 423. Quando houver no contrato de adesão cláusulas ambíguas ou contraditórias, dever-se-á adotar a interpretação mais favorável ao aderente."]],["CC, art. 424",["Art. 424. Nos contratos de adesão, são nulas as cláusulas que estipulem a renúncia antecipada do aderente a direito resultante da natureza do negócio."]],["CC, art. 425",["Art. 425. É lícito às partes estipular contratos atípicos, observadas as normas gerais fixadas neste Código."]]],"3":[["CC, art. 427",["Art. 427. A proposta de contrato obriga o proponente, se o contrário não resultar dos termos dela, da natureza do negócio, ou das circunstâncias do caso."]],["CC, art. 428",["Art. 428. Deixa de ser obrigatória a proposta:","I - se, feita sem prazo a pessoa presente, não foi imediatamente aceita. Considera-se também presente a pessoa que contrata por telefone ou por meio de comunicação semelhante;","II - se, feita sem prazo a pessoa ausente, tiver decorrido tempo suficiente para chegar a resposta ao conhecimento do proponente;","III - se, feita a pessoa ausente, não tiver sido expedida a resposta dentro do prazo dado;","IV - se, antes dela, ou simultaneamente, chegar ao conhecimento da outra parte a retratação do proponente."]],["CC, art. 429",["Art. 429. A oferta ao público equivale a proposta quando encerra os requisitos essenciais ao contrato, salvo se o contrário resultar das circunstâncias ou dos usos.","Parágrafo único. Pode revogar-se a oferta pela mesma via de sua divulgação, desde que ressalvada esta faculdade na oferta realizada."]],["CC, art. 430",["Art. 430. Se a aceitação, por circunstância imprevista, chegar tarde ao conhecimento do proponente, este comunicá-lo-á imediatamente ao aceitante, sob pena de responder por perdas e danos."]],["CC, art. 431",["Art. 431. A aceitação fora do prazo, com adições, restrições, ou modificações, importará nova proposta."]],["CC, art. 432",["Art. 432. Se o negócio for daqueles em que não seja costume a aceitação expressa, ou o proponente a tiver dispensado, reputar-se-á concluído o contrato, não chegando a tempo a recusa."]],["CC, art. 433",["Art. 433. Considera-se inexistente a aceitação, se antes dela ou com ela chegar ao proponente a retratação do aceitante."]],["CC, art. 434",["Art. 434. Os contratos entre ausentes tornam-se perfeitos desde que a aceitação é expedida, exceto:","I - no caso do artigo antecedente;","II - se o proponente se houver comprometido a esperar resposta;","III - se ela não chegar no prazo convencionado."]],["CC, art. 435",["Art. 435. Reputar-se-á celebrado o contrato no lugar em que foi proposto."]]],"4":[["CC, art. 436",["Art. 436. O que estipula em favor de terceiro pode exigir o cumprimento da obrigação.","Parágrafo único. Ao terceiro, em favor de quem se estipulou a obrigação, também é permitido exigi-la, ficando, todavia, sujeito às condições e normas do contrato, se a ele anuir, e o estipulante não o inovar nos termos do art. 438."]],["CC, art. 437",["Art. 437. Se ao terceiro, em favor de quem se fez o contrato, se deixar o direito de reclamar-lhe a execução, não poderá o estipulante exonerar o devedor."]],["CC, art. 438",["Art. 438. O estipulante pode reservar-se o direito de substituir o terceiro designado no contrato, independentemente da sua anuência e da do outro contratante.","Parágrafo único. A substituição pode ser feita por ato entre vivos ou por disposição de última vontade."]],["CC, art. 439",["Art. 439. Aquele que tiver prometido fato de terceiro responderá por perdas e danos, quando este o não executar.","Parágrafo único. Tal responsabilidade não existirá se o terceiro for o cônjuge do promitente, dependendo da sua anuência o ato a ser praticado, e desde que, pelo regime do casamento, a indenização, de algum modo, venha a recair sobre os seus bens."]],["CC, art. 440",["Art. 440. Nenhuma obrigação haverá para quem se comprometer por outrem, se este, depois de se ter obrigado, faltar à prestação."]]],"5":[["CC, art. 441",["Art. 441. A coisa recebida em virtude de contrato comutativo pode ser enjeitada por vícios ou defeitos ocultos, que a tornem imprópria ao uso a que é destinada, ou lhe diminuam o valor.","Parágrafo único. É aplicável a disposição deste artigo às doações onerosas."]],["CC, art. 442",["Art. 442. Em vez de rejeitar a coisa, redibindo o contrato (art. 441), pode o adquirente reclamar abatimento no preço."]],["CC, art. 443",["Art. 443. Se o alienante conhecia o vício ou defeito da coisa, restituirá o que recebeu com perdas e danos; se o não conhecia, tão-somente restituirá o valor recebido, mais as despesas do contrato."]],["CC, art. 444",["Art. 444. A responsabilidade do alienante subsiste ainda que a coisa pereça em poder do alienatário, se perecer por vício oculto, já existente ao tempo da tradição."]],["CC, art. 445",["Art. 445. O adquirente decai do direito de obter a redibição ou abatimento no preço no prazo de trinta dias se a coisa for móvel, e de um ano se for imóvel, contado da entrega efetiva; se já estava na posse, o prazo conta-se da alienação, reduzido à metade.","§ 1º Quando o vício, por sua natureza, só puder ser conhecido mais tarde, o prazo contar-se-á do momento em que dele tiver ciência, até o prazo máximo de cento e oitenta dias, em se tratando de bens móveis; e de um ano, para os imóveis.","§ 2º Tratando-se de venda de animais, os prazos de garantia por vícios ocultos serão os estabelecidos em lei especial, ou, na falta desta, pelos usos locais, aplicando-se o disposto no parágrafo antecedente se não houver regras disciplinando a matéria."]],["CC, art. 446",["Art. 446. Não correrão os prazos do artigo antecedente na constância de cláusula de garantia; mas o adquirente deve denunciar o defeito ao alienante nos trinta dias seguintes ao seu descobrimento, sob pena de decadência."]]],"6":[["CC, art. 447",["Art. 447. Nos contratos onerosos, o alienante responde pela evicção. Subsiste esta garantia ainda que a aquisição se tenha realizado em hasta pública."]],["CC, art. 448",["Art. 448. Podem as partes, por cláusula expressa, reforçar, diminuir ou excluir a responsabilidade pela evicção."]],["CC, art. 449",["Art. 449. Não obstante a cláusula que exclui a garantia contra a evicção, se esta se der, tem direito o evicto a receber o preço que pagou pela coisa evicta, se não soube do risco da evicção, ou, dele informado, não o assumiu."]],["CC, art. 450",["Art. 450. Salvo estipulação em contrário, tem direito o evicto, além da restituição integral do preço ou das quantias que pagou:","I - à indenização dos frutos que tiver sido obrigado a restituir;","II - à indenização pelas despesas dos contratos e pelos prejuízos que diretamente resultarem da evicção;","III - às custas judiciais e aos honorários do advogado por ele constituído.","Parágrafo único. O preço, seja a evicção total ou parcial, será o do valor da coisa, na época em que se evenceu, e proporcional ao desfalque sofrido, no caso de evicção parcial."]],["CC, art. 451",["Art. 451. Subsiste para o alienante esta obrigação, ainda que a coisa alienada esteja deteriorada, exceto havendo dolo do adquirente."]],["CC, art. 452",["Art. 452. Se o adquirente tiver auferido vantagens das deteriorações, e não tiver sido condenado a indenizá-las, o valor das vantagens será deduzido da quantia que lhe houver de dar o alienante."]],["CC, art. 453",["Art. 453. As benfeitorias necessárias ou úteis, não abonadas ao que sofreu a evicção, serão pagas pelo alienante."]],["CC, art. 454",["Art. 454. Se as benfeitorias abonadas ao que sofreu a evicção tiverem sido feitas pelo alienante, o valor delas será levado em conta na restituição devida."]],["CC, art. 455",["Art. 455. Se parcial, mas considerável, for a evicção, poderá o evicto optar entre a rescisão do contrato e a restituição da parte do preço correspondente ao desfalque sofrido. Se não for considerável, caberá somente direito a indenização."]],["CC, art. 456",["Art. 456. (Revogado pela Lei nº 13.105, de 16/3/2015, publicada no DOU de 17/3/2015, em vigor após 1 ano da publicação)"]],["CC, art. 457",["Art. 457. Não pode o adquirente demandar pela evicção, se sabia que a coisa era alheia ou litigiosa."]]],"7":[["CC, art. 458",["Art. 458. Se o contrato for aleatório, por dizer respeito a coisas ou fatos futuros, cujo risco de não virem a existir um dos contratantes assuma, terá o outro direito de receber integralmente o que lhe foi prometido, desde que de sua parte não tenha havido dolo ou culpa, ainda que nada do avençado venha a existir."]],["CC, art. 459",["Art. 459. Se for aleatório, por serem objeto dele coisas futuras, tomando o adquirente a si o risco de virem a existir em qualquer quantidade, terá também direito o alienante a todo o preço, desde que de sua parte não tiver concorrido culpa, ainda que a coisa venha a existir em quantidade inferior à esperada.","Parágrafo único. Mas, se da coisa nada vier a existir, alienação não haverá, e o alienante restituirá o preço recebido."]],["CC, art. 460",["Art. 460. Se for aleatório o contrato, por se referir a coisas existentes, mas expostas a risco, assumido pelo adquirente, terá igualmente direito o alienante a todo o preço, posto que a coisa já não existisse, em parte, ou de todo, no dia do contrato."]],["CC, art. 461",["Art. 461. A alienação aleatória a que se refere o artigo antecedente poderá ser anulada como dolosa pelo prejudicado, se provar que o outro contratante não ignorava a consumação do risco, a que no contrato se considerava exposta a coisa."]]],"8":[["CC, art. 462",["Art. 462. O contrato preliminar, exceto quanto à forma, deve conter todos os requisitos essenciais ao contrato a ser celebrado."]],["CC, art. 463",["Art. 463. Concluído o contrato preliminar, com observância do disposto no artigo antecedente, e desde que dele não conste cláusula de arrependimento, qualquer das partes terá o direito de exigir a celebração do definitivo, assinando prazo à outra para que o efetive.","Parágrafo único. O contrato preliminar deverá ser levado ao registro competente."]],["CC, art. 464",["Art. 464. Esgotado o prazo, poderá o juiz, a pedido do interessado, suprir a vontade da parte inadimplente, conferindo caráter definitivo ao contrato preliminar, salvo se a isto se opuser a natureza da obrigação."]],["CC, art. 465",["Art. 465. Se o estipulante não der execução ao contrato preliminar, poderá a outra parte considerá-lo desfeito, e pedir perdas e danos."]],["CC, art. 466",["Art. 466. Se a promessa de contrato for unilateral, o credor, sob pena de ficar a mesma sem efeito, deverá manifestar-se no prazo nela previsto, ou, inexistindo este, no que lhe for razoavelmente assinado pelo devedor."]],["CC, art. 467",["Art. 467. No momento da conclusão do contrato, pode uma das partes reservar-se a faculdade de indicar a pessoa que deve adquirir os direitos e assumir as obrigações dele decorrentes."]],["CC, art. 468",["Art. 468. Essa indicação deve ser comunicada à outra parte no prazo de cinco dias da conclusão do contrato, se outro não tiver sido estipulado.","Parágrafo único. A aceitação da pessoa nomeada não será eficaz se não se revestir da mesma forma que as partes usaram para o contrato."]],["CC, art. 469",["Art. 469. A pessoa, nomeada de conformidade com os artigos antecedentes, adquire os direitos e assume as obrigações decorrentes do contrato, a partir do momento em que este foi celebrado."]],["CC, art. 470",["Art. 470. O contrato será eficaz somente entre os contratantes originários:","I - se não houver indicação de pessoa, ou se o nomeado se recusar a aceitá-la;","II - se a pessoa nomeada era insolvente, e a outra pessoa o desconhecia no momento da indicação."]],["CC, art. 471",["Art. 471. Se a pessoa a nomear era incapaz ou insolvente no momento da nomeação, o contrato produzirá seus efeitos entre os contratantes originários."]]],"9":[["CC, art. 472",["Art. 472. O distrato faz-se pela mesma forma exigida para o contrato."]],["CC, art. 473",["Art. 473. A resilição unilateral, nos casos em que a lei expressa ou implicitamente o permita, opera mediante denúncia notificada à outra parte.","Parágrafo único. Se, porém, dada a natureza do contrato, uma das partes houver feito investimentos consideráveis para a sua execução, a denúncia unilateral só produzirá efeito depois de transcorrido prazo compatível com a natureza e o vulto dos investimentos."]]],"10":[["CC, art. 474",["Art. 474. A cláusula resolutiva expressa opera de pleno direito; a tácita depende de interpelação judicial."]],["CC, art. 475",["Art. 475. A parte lesada pelo inadimplemento pode pedir a resolução do contrato, se não preferir exigir-lhe o cumprimento, cabendo, em qualquer dos casos, indenização por perdas e danos."]],["CC, art. 476",["Art. 476. Nos contratos bilaterais, nenhum dos contratantes, antes de cumprida a sua obrigação, pode exigir o implemento da do outro."]],["CC, art. 477",["Art. 477. Se, depois de concluído o contrato, sobrevier a uma das partes contratantes diminuição em seu patrimônio capaz de comprometer ou tornar duvidosa a prestação pela qual se obrigou, pode a outra recusar-se à prestação que lhe incumbe, até que aquela satisfaça a que lhe compete ou dê garantia bastante de satisfazê-la."]]],"11":[["CC, art. 478",["Art. 478. Nos contratos de execução continuada ou diferida, se a prestação de uma das partes se tornar excessivamente onerosa, com extrema vantagem para a outra, em virtude de acontecimentos extraordinários e imprevisíveis, poderá o devedor pedir a resolução do contrato. Os efeitos da sentença que a decretar retroagirão à data da citação."]],["CC, art. 479",["Art. 479. A resolução poderá ser evitada, oferecendo-se o réu a modificar eqüitativamente as condições do contrato."]],["CC, art. 480",["Art. 480. Se no contrato as obrigações couberem a apenas uma das partes, poderá ela pleitear que a sua prestação seja reduzida, ou alterado o modo de executá-la, a fim de evitar a onerosidade excessiva."]]]},"8":{"3":[["CC, art. 533",["Art. 533. Aplicam-se à troca as disposições referentes à compra e venda, com as seguintes modificações:","I - salvo disposição em contrário, cada um dos contratantes pagará por metade as despesas com o instrumento da troca;","II - é anulável a troca de valores desiguais entre ascendentes e descendentes, sem consentimento dos outros descendentes e do cônjuge do alienante."]],["CC, art. 534",["Art. 534. Pelo contrato estimatório, o consignante entrega bens móveis ao consignatário, que fica autorizado a vendê-los, pagando àquele o preço ajustado, salvo se preferir, no prazo estabelecido, restituir-lhe a coisa consignada."]],["CC, art. 535",["Art. 535. O consignatário não se exonera da obrigação de pagar o preço, se a restituição da coisa, em sua integridade, se tornar impossível, ainda que por fato a ele não imputável."]],["CC, art. 536",["Art. 536. A coisa consignada não pode ser objeto de penhora ou seqüestro pelos credores do consignatário, enquanto não pago integralmente o preço."]],["CC, art. 537",["Art. 537. O consignante não pode dispor da coisa antes de lhe ser restituída ou de lhe ser comunicada a restituição."]]],"5":[["CC, art. 565",["Art. 565. Na locação de coisas, uma das partes se obriga a ceder à outra, por tempo determinado ou não, o uso e gozo de coisa não fungível, mediante certa retribuição."]],["CC, art. 566",["Art. 566. O locador é obrigado:","I - a entregar ao locatário a coisa alugada, com suas pertenças, em estado de servir ao uso a que se destina, e a mantê-la nesse estado, pelo tempo do contrato, salvo cláusula expressa em contrário;","II - a garantir-lhe, durante o tempo do contrato, o uso pacífico da coisa."]],["CC, art. 567",["Art. 567. Se, durante a locação, se deteriorar a coisa alugada, sem culpa do locatário, a este caberá pedir redução proporcional do aluguel, ou resolver o contrato, caso já não sirva a coisa para o fim a que se destinava."]],["CC, art. 568",["Art. 568. O locador resguardará o locatário dos embaraços e turbações de terceiros, que tenham ou pretendam ter direitos sobre a coisa alugada, e responderá pelos seus vícios, ou defeitos, anteriores à locação."]],["CC, art. 569",["Art. 569. O locatário é obrigado:","I - a servir-se da coisa alugada para os usos convencionados ou presumidos, conforme a natureza dela e as circunstâncias, bem como tratá-la com o mesmo cuidado como se sua fosse;","II - a pagar pontualmente o aluguel nos prazos ajustados, e, em falta de ajuste, segundo o costume do lugar;","III - a levar ao conhecimento do locador as turbações de terceiros, que se pretendam fundadas em direito;","IV - a restituir a coisa, finda a locação, no estado em que a recebeu, salvas as deteriorações naturais ao uso regular."]],["CC, art. 570",["Art. 570. Se o locatário empregar a coisa em uso diverso do ajustado, ou do a que se destina, ou se ela se danificar por abuso do locatário, poderá o locador, além de rescindir o contrato, exigir perdas e danos."]],["CC, art. 571",["Art. 571. Havendo prazo estipulado à duração do contrato, antes do vencimento não poderá o locador reaver a coisa alugada, senão ressarcindo ao locatário as perdas e danos resultantes, nem o locatário devolvê-la ao locador, senão pagando, proporcionalmente, a multa prevista no contrato.","Parágrafo único. O locatário gozará do direito de retenção, enquanto não for ressarcido."]],["CC, art. 572",["Art. 572. Se a obrigação de pagar o aluguel pelo tempo que faltar constituir indenização excessiva, será facultado ao juiz fixá-la em bases razoáveis."]],["CC, art. 573",["Art. 573. A locação por tempo determinado cessa de pleno direito findo o prazo estipulado, independentemente de notificação ou aviso."]],["CC, art. 574",["Art. 574. Se, findo o prazo, o locatário continuar na posse da coisa alugada, sem oposição do locador, presumir-se-á prorrogada a locação pelo mesmo aluguel, mas sem prazo determinado."]],["CC, art. 575",["Art. 575. Se, notificado o locatário, não restituir a coisa, pagará, enquanto a tiver em seu poder, o aluguel que o locador arbitrar, e responderá pelo dano que ela venha a sofrer, embora proveniente de caso fortuito.","Parágrafo único. Se o aluguel arbitrado for manifestamente excessivo, poderá o juiz reduzi-lo, mas tendo sempre em conta o seu caráter de penalidade."]],["CC, art. 576",["Art. 576. Se a coisa for alienada durante a locação, o adquirente não ficará obrigado a respeitar o contrato, se nele não for consignada a cláusula da sua vigência no caso de alienação, e não constar de registro.","§ 1º O registro a que se refere este artigo será o de Títulos e Documentos do domicílio do locador, quando a coisa for móvel; e será o Registro de Imóveis da respectiva circunscrição, quando imóvel.","§ 2º Em se tratando de imóvel, e ainda no caso em que o locador não esteja obrigado a respeitar o contrato, não poderá ele despedir o locatário, senão observado o prazo de noventa dias após a notificação."]],["CC, art. 577",["Art. 577. Morrendo o locador ou o locatário, transfere-se aos seus herdeiros a locação por tempo determinado."]],["CC, art. 578",["Art. 578. Salvo disposição em contrário, o locatário goza do direito de retenção, no caso de benfeitorias necessárias, ou no de benfeitorias úteis, se estas houverem sido feitas com expresso consentimento do locador."]]],"6":[["CC, art. 579",["Art. 579. O comodato é o empréstimo gratuito de coisas não fungíveis. Perfaz-se com a tradição do objeto."]],["CC, art. 580",["Art. 580. Os tutores, curadores e em geral todos os administradores de bens alheios não poderão dar em comodato, sem autorização especial, os bens confiados à sua guarda."]],["CC, art. 581",["Art. 581. Se o comodato não tiver prazo convencional, presumir-se-lhe-á o necessário para o uso concedido; não podendo o comodante, salvo necessidade imprevista e urgente, reconhecida pelo juiz, suspender o uso e gozo da coisa emprestada, antes de findo o prazo convencional, ou o que se determine pelo uso outorgado."]],["CC, art. 582",["Art. 582. O comodatário é obrigado a conservar, como se sua própria fora, a coisa emprestada, não podendo usá-la senão de acordo com o contrato ou a natureza dela, sob pena de responder por perdas e danos. O comodatário constituído em mora, além de por ela responder, pagará, até restituí-la, o aluguel da coisa que for arbitrado pelo comodante."]],["CC, art. 583",["Art. 583. Se, correndo risco o objeto do comodato juntamente com outros do comodatário, antepuser este a salvação dos seus abandonando o do comodante, responderá pelo dano ocorrido, ainda que se possa atribuir a caso fortuito, ou força maior."]],["CC, art. 584",["Art. 584. O comodatário não poderá jamais recobrar do comodante as despesas feitas com o uso e gozo da coisa emprestada."]],["CC, art. 585",["Art. 585. Se duas ou mais pessoas forem simultaneamente comodatárias de uma coisa, ficarão solidariamente responsáveis para com o comodante."]],["CC, art. 586",["Art. 586. O mútuo é o empréstimo de coisas fungíveis. O mutuário é obrigado a restituir ao mutuante o que dele recebeu em coisa do mesmo gênero, qualidade e quantidade."]],["CC, art. 587",["Art. 587. Este empréstimo transfere o domínio da coisa emprestada ao mutuário, por cuja conta correm todos os riscos dela desde a tradição."]],["CC, art. 588",["Art. 588. O mútuo feito a pessoa menor, sem prévia autorização daquele sob cuja guarda estiver, não pode ser reavido nem do mutuário, nem de seus fiadores."]],["CC, art. 589",["Art. 589. Cessa a disposição do artigo antecedente:","I - se a pessoa, de cuja autorização necessitava o mutuário para contrair o empréstimo, o ratificar posteriormente;","II - se o menor, estando ausente essa pessoa, se viu obrigado a contrair o empréstimo para os seus alimentos habituais;","III - se o menor tiver bens ganhos com o seu trabalho. Mas, em tal caso, a execução do credor não lhes poderá ultrapassar as forças;","IV - se o empréstimo reverteu em benefício do menor;","V - se o menor obteve o empréstimo maliciosamente."]],["CC, art. 590",["Art. 590. O mutuante pode exigir garantia da restituição, se antes do vencimento o mutuário sofrer notória mudança em sua situação econômica."]],["CC, art. 591",["Art. 591. Destinando-se o mútuo a fins econômicos, presumem-se devidos juros. (“Caput” do artigo com redação dada pela Lei nº 14.905, de 28/6/2024, publicada no DOU de 1º/7/2024, em vigor 60 dias após a publicação)","Parágrafo único. Se a taxa de juros não for pactuada, aplica-se a taxa legal prevista no art. 406 deste Código. (Parágrafo único acrescido pela Lei nº 14.905, de 28/6/2024, publicada no DOU de 1º/7/2024, em vigor 60 dias após a publicação)"]],["CC, art. 592",["Art. 592. Não se tendo convencionado expressamente, o prazo do mútuo será:","I - até a próxima colheita, se o mútuo for de produtos agrícolas, assim para o consumo, como para semeadura;","II - de trinta dias, pelo menos, se for de dinheiro;","III - do espaço de tempo que declarar o mutuante, se for de qualquer outra coisa fungível."]]],"12":[["CC, art. 133",["Art. 133. Nos testamentos, presume-se o prazo em favor do herdeiro, e, nos contratos, em proveito do devedor, salvo, quanto a esses, se do teor do instrumento, ou das circunstâncias, resultar que se estabeleceu a benefício do credor, ou de ambos os contratantes."]],["CC, art. 134",["Art. 134. Os negócios jurídicos entre vivos, sem prazo, são exeqüíveis desde logo, salvo se a execução tiver de ser feita em lugar diverso ou depender de tempo."]],["CC, art. 757",["Art. 757. Pelo contrato de seguro, o segurador se obriga, mediante o pagamento do prêmio, a garantir interesse legítimo do segurado, relativo a pessoa ou a coisa, contra riscos predeterminados.","Parágrafo único. Somente pode ser parte, no contrato de seguro, como segurador, entidade para tal fim legalmente autorizada. (Vide Lei nº 15.040, de 9/12/2024)"]]],"13":[["CC, art. 818",["Art. 818. Pelo contrato de fiança, uma pessoa garante satisfazer ao credor uma obrigação assumida pelo devedor, caso este não a cumpra."]],["CC, art. 819",["Art. 819. A fiança dar-se-á por escrito, e não admite interpretação extensiva."]],["CC, art. 819-A",["Art. 819-A. (VETADO na Lei nº 10.931, de 2/8/2004)"]],["CC, art. 820",["Art. 820. Pode-se estipular a fiança, ainda que sem consentimento do devedor ou contra a sua vontade."]],["CC, art. 821",["Art. 821. As dívidas futuras podem ser objeto de fiança; mas o fiador, neste caso, não será demandado senão depois que se fizer certa e líquida a obrigação do principal devedor."]],["CC, art. 822",["Art. 822. Não sendo limitada, a fiança compreenderá todos os acessórios da dívida principal, inclusive as despesas judiciais, desde a citação do fiador."]],["CC, art. 823",["Art. 823. A fiança pode ser de valor inferior ao da obrigação principal e contraída em condições menos onerosas, e, quando exceder o valor da dívida, ou for mais onerosa que ela, não valerá senão até ao limite da obrigação afiançada."]],["CC, art. 824",["Art. 824. As obrigações nulas não são suscetíveis de fiança, exceto se a nulidade resultar apenas de incapacidade pessoal do devedor.","Parágrafo único. A exceção estabelecida neste artigo não abrange o caso de mútuo feito a menor."]],["CC, art. 825",["Art. 825. Quando alguém houver de oferecer fiador, o credor não pode ser obrigado a aceitá-lo se não for pessoa idônea, domiciliada no município onde tenha de prestar a fiança, e não possua bens suficientes para cumprir a obrigação."]],["CC, art. 826",["Art. 826. Se o fiador se tornar insolvente ou incapaz, poderá o credor exigir que seja substituído."]],["CC, art. 827",["Art. 827. O fiador demandado pelo pagamento da dívida tem direito a exigir, até a contestação da lide, que sejam primeiro executados os bens do devedor.","Parágrafo único. O fiador que alegar o benefício de ordem, a que se refere este artigo, deve nomear bens do devedor, sitos no mesmo município, livres e desembargados, quantos bastem para solver o débito."]],["CC, art. 828",["Art. 828. Não aproveita este benefício ao fiador:","I - se ele o renunciou expressamente;","II - se se obrigou como principal pagador, ou devedor solidário;","III - se o devedor for insolvente, ou falido."]],["CC, art. 829",["Art. 829. A fiança conjuntamente prestada a um só débito por mais de uma pessoa importa o compromisso de solidariedade entre elas, se declaradamente não se reservarem o benefício de divisão.","Parágrafo único. Estipulado este benefício, cada fiador responde unicamente pela parte que, em proporção, lhe couber no pagamento."]],["CC, art. 830",["Art. 830. Cada fiador pode fixar no contrato a parte da dívida que toma sob sua responsabilidade, caso em que não será por mais obrigado."]],["CC, art. 831",["Art. 831. O fiador que pagar integralmente a dívida fica sub-rogado nos direitos do credor; mas só poderá demandar a cada um dos outros fiadores pela respectiva quota.","Parágrafo único. A parte do fiador insolvente distribuir-se-á pelos outros."]],["CC, art. 832",["Art. 832. O devedor responde também perante o fiador por todas as perdas e danos que este pagar, e pelos que sofrer em razão da fiança."]],["CC, art. 833",["Art. 833. O fiador tem direito aos juros do desembolso pela taxa estipulada na obrigação principal, e, não havendo taxa convencionada, aos juros legais da mora."]],["CC, art. 834",["Art. 834. Quando o credor, sem justa causa, demorar a execução iniciada contra o devedor, poderá o fiador promover-lhe o andamento."]],["CC, art. 835",["Art. 835. O fiador poderá exonerar-se da fiança que tiver assinado sem limitação de tempo, sempre que lhe convier, ficando obrigado por todos os efeitos da fiança, durante sessenta dias após a notificação do credor."]],["CC, art. 836",["Art. 836. A obrigação do fiador passa aos herdeiros; mas a responsabilidade da fiança se limita ao tempo decorrido até a morte do fiador, e não pode ultrapassar as forças da herança."]],["CC, art. 837",["Art. 837. O fiador pode opor ao credor as exceções que lhe forem pessoais, e as extintivas da obrigação que competem ao devedor principal, se não provierem simplesmente de incapacidade pessoal, salvo o caso do mútuo feito a pessoa menor."]],["CC, art. 838",["Art. 838. O fiador, ainda que solidário, ficará desobrigado:","I - se, sem consentimento seu, o credor conceder moratória ao devedor;","II - se, por fato do credor, for impossível a sub-rogação nos seus direitos e preferências;","III - se o credor, em pagamento da dívida, aceitar amigavelmente do devedor objeto diverso do que este era obrigado a lhe dar, ainda que depois venha a perdê-lo por evicção."]],["CC, art. 839",["Art. 839. Se for invocado o benefício da excussão e o devedor, retardando-se a execução, cair em insolvência, ficará exonerado o fiador que o invocou, se provar que os bens por ele indicados eram, ao tempo da penhora, suficientes para a solução da dívida afiançada."]]],"14":[["CC, art. 853-A",["Art. 853-A. Qualquer garantia poderá ser constituída, levada a registro, gerida e ter a sua execução pleiteada por agente de garantia, que será designado pelos credores da obrigação garantida para esse fim e atuará em nome próprio e em benefício dos credores, inclusive em ações judiciais que envolvam discussões sobre a existência, a validade ou a eficácia do ato jurídico do crédito garantido, vedada qualquer cláusula que afaste essa regra em desfavor do devedor ou, se for o caso, do terceiro prestador da garantia.","§ 1º O agente de garantia poderá valer-se da execução extrajudicial da garantia, quando houver previsão na legislação especial aplicável à modalidade de garantia.","§ 2º O agente de garantia terá dever fiduciário em relação aos credores da obrigação garantida e responderá perante os credores por todos os seus atos.","§ 3º O agente de garantia poderá ser substituído, a qualquer tempo, por decisão do credor único ou dos titulares que representarem a maioria simples dos créditos garantidos, reunidos em assembleia, mas a substituição do agente de garantia somente será eficaz após ter sido tornada pública pela mesma forma por meio da qual tenha sido dada publicidade à garantia.","§ 4º Os requisitos de convocação e de instalação das assembleias dos titulares dos créditos garantidos estarão previstos em ato de designação ou de contratação do agente de garantia.","§ 5º O produto da realização da garantia, enquanto não transferido para os credores garantidos, constitui patrimônio separado daquele do agente de garantia e não poderá responder por suas obrigações pelo período de até 180 (cento e oitenta) dias, contado da data de recebimento do produto da garantia.","§ 6º Após receber o valor do produto da realização da garantia, o agente de garantia disporá do prazo de 10 (dez) dias úteis para efetuar o pagamento aos credores.","§ 7º Paralelamente ao contrato de que trata este artigo, o agente de garantia poderá manter contratos com o devedor para:","I - pesquisa de ofertas de crédito mais vantajosas entre os diversos fornecedores;","II - auxílio nos procedimentos necessários à formalização de contratos de operações de crédito e de garantias reais;","III - intermediação na resolução de questões relativas aos contratos de operações de crédito ou às garantias reais; e","IV - outros serviços não vedados em lei.","§ 8º Na hipótese do § 7º deste artigo, o agente de garantia deverá agir com estrita boa-fé perante o devedor. (Artigo acrescido pela Lei nº 14.711, de 30/10/2023)"]]]},"9":{"0":[["CC, art. 186",["Art. 186. Aquele que, por ação ou omissão voluntária, negligência ou imprudência, violar direito e causar dano a outrem, ainda que exclusivamente moral, comete ato ilícito. (Vide ADIs nºs 6.792 e 7.055 )"]],["CC, art. 187",["Art. 187. Também comete ato ilícito o titular de um direito que, ao exercê-lo, excede manifestamente os limites impostos pelo seu fim econômico ou social, pela boa-fé ou pelos bons costumes."]],["CC, art. 188",["Art. 188. Não constituem atos ilícitos:","I - os praticados em legítima defesa ou no exercício regular de um direito reconhecido;","II - a deterioração ou destruição da coisa alheia, ou a lesão a pessoa, a fim de remover perigo iminente.","Parágrafo único. No caso do inciso II, o ato será legítimo somente quando as circunstâncias o tornarem absolutamente necessário, não excedendo os limites do indispensável para a remoção do perigo."]]],"1":[["CC, art. 186",["Art. 186. Aquele que, por ação ou omissão voluntária, negligência ou imprudência, violar direito e causar dano a outrem, ainda que exclusivamente moral, comete ato ilícito. (Vide ADIs nºs 6.792 e 7.055 )"]],["CC, art. 187",["Art. 187. Também comete ato ilícito o titular de um direito que, ao exercê-lo, excede manifestamente os limites impostos pelo seu fim econômico ou social, pela boa-fé ou pelos bons costumes."]]],"2":[["CC, art. 188",["Art. 188. Não constituem atos ilícitos:","I - os praticados em legítima defesa ou no exercício regular de um direito reconhecido;","II - a deterioração ou destruição da coisa alheia, ou a lesão a pessoa, a fim de remover perigo iminente.","Parágrafo único. No caso do inciso II, o ato será legítimo somente quando as circunstâncias o tornarem absolutamente necessário, não excedendo os limites do indispensável para a remoção do perigo."]],["CC, art. 929",["Art. 929. Se a pessoa lesada, ou o dono da coisa, no caso do inciso II do art. 188, não forem culpados do perigo, assistir-lhes-á direito à indenização do prejuízo que sofreram."]],["CC, art. 930",["Art. 930. No caso do inciso II do art. 188, se o perigo ocorrer por culpa de terceiro, contra este terá o autor do dano ação regressiva para haver a importância que tiver ressarcido ao lesado.","Parágrafo único. A mesma ação competirá contra aquele em defesa de quem se causou o dano (art. 188, inciso I)."]]],"3":[["CC, art. 927",["Art. 927. Aquele que, por ato ilícito (arts. 186 e 187), causar dano a outrem, fica obrigado a repará-lo. (Vide ADIs nºs 6.792 e 7.055 )","Parágrafo único. Haverá obrigação de reparar o dano, independentemente de culpa, nos casos especificados em lei, ou quando a atividade normalmente desenvolvida pelo autor do dano implicar, por sua natureza, risco para os direitos de outrem."]]],"4":[["CC, art. 932",["Art. 932. São também responsáveis pela reparação civil:","I - os pais, pelos filhos menores que estiverem sob sua autoridade e em sua companhia;","II - o tutor e o curador, pelos pupilos e curatelados, que se acharem nas mesmas condições;","III - o empregador ou comitente, por seus empregados, serviçais e prepostos, no exercício do trabalho que lhes competir, ou em razão dele;","IV - os donos de hotéis, hospedarias, casas ou estabelecimentos onde se albergue por dinheiro, mesmo para fins de educação, pelos seus hóspedes, moradores e educandos;","V - os que gratuitamente houverem participado nos produtos do crime, até a concorrente quantia."]],["CC, art. 933",["Art. 933. As pessoas indicadas nos incisos I a V do artigo antecedente, ainda que não haja culpa de sua parte, responderão pelos atos praticados pelos terceiros ali referidos."]],["CC, art. 934",["Art. 934. Aquele que ressarcir o dano causado por outrem pode reaver o que houver pago daquele por quem pagou, salvo se o causador do dano for descendente seu, absoluta ou relativamente incapaz."]]],"5":[["CC, art. 936",["Art. 936. O dono, ou detentor, do animal ressarcirá o dano por este causado, se não provar culpa da vítima ou força maior."]],["CC, art. 937",["Art. 937. O dono de edifício ou construção responde pelos danos que resultarem de sua ruína, se esta provier de falta de reparos, cuja necessidade fosse manifesta.","§ 1º (VETADO na Lei nº 13.425, 30/3/2017)","§ 2º (VETADO na Lei nº 13.425, 30/3/2017)"]],["CC, art. 938",["Art. 938. Aquele que habitar prédio, ou parte dele, responde pelo dano proveniente das coisas que dele caírem ou forem lançadas em lugar indevido."]]],"6":[["CC, art. 945",["Art. 945. Se a vítima tiver concorrido culposamente para o evento danoso, a sua indenização será fixada tendo-se em conta a gravidade de sua culpa em confronto com a do autor do dano."]]],"7":[["CC, art. 402",["Art. 402. Salvo as exceções expressamente previstas em lei, as perdas e danos devidas ao credor abrangem, além do que ele efetivamente perdeu, o que razoavelmente deixou de lucrar."]],["CC, art. 403",["Art. 403. Ainda que a inexecução resulte de dolo do devedor, as perdas e danos só incluem os prejuízos efetivos e os lucros cessantes por efeito dela direto e imediato, sem prejuízo do disposto na lei processual."]],["CC, art. 944",["Art. 944. A indenização mede-se pela extensão do dano.","Parágrafo único. Se houver excessiva desproporção entre a gravidade da culpa e o dano, poderá o juiz reduzir, eqüitativamente, a indenização."]]],"8":[["CC, art. 186",["Art. 186. Aquele que, por ação ou omissão voluntária, negligência ou imprudência, violar direito e causar dano a outrem, ainda que exclusivamente moral, comete ato ilícito. (Vide ADIs nºs 6.792 e 7.055 )"]]],"9":[["CC, art. 944",["Art. 944. A indenização mede-se pela extensão do dano.","Parágrafo único. Se houver excessiva desproporção entre a gravidade da culpa e o dano, poderá o juiz reduzir, eqüitativamente, a indenização."]]],"10":[["CC, art. 948",["Art. 948. No caso de homicídio, a indenização consiste, sem excluir outras reparações:","I - no pagamento das despesas com o tratamento da vítima, seu funeral e o luto da família;","II - na prestação de alimentos às pessoas a quem o morto os devia, levando-se em conta a duração provável da vida da vítima."]],["CC, art. 949",["Art. 949. No caso de lesão ou outra ofensa à saúde, o ofensor indenizará o ofendido das despesas do tratamento e dos lucros cessantes até ao fim da convalescença, além de algum outro prejuízo que o ofendido prove haver sofrido."]],["CC, art. 950",["Art. 950. Se da ofensa resultar defeito pelo qual o ofendido não possa exercer o seu ofício ou profissão, ou se lhe diminua a capacidade de trabalho, a indenização, além das despesas do tratamento e lucros cessantes até ao fim da convalescença, incluirá pensão correspondente à importância do trabalho para que se inabilitou, ou da depreciação que ele sofreu.","Parágrafo único. O prejudicado, se preferir, poderá exigir que a indenização seja arbitrada e paga de uma só vez."]]],"11":[["CC, art. 935",["Art. 935. A responsabilidade civil é independente da criminal, não se podendo questionar mais sobre a existência do fato, ou sobre quem seja o seu autor, quando estas questões se acharem decididas no juízo criminal."]]]},"10":{"0":[["CC, art. 966",["Art. 966. Considera-se empresário quem exerce profissionalmente atividade econômica organizada para a produção ou a circulação de bens ou de serviços.","Parágrafo único. Não se considera empresário quem exerce profissão intelectual, de natureza científica, literária ou artística, ainda com o concurso de auxiliares ou colaboradores, salvo se o exercício da profissão constituir elemento de empresa."]]],"1":[["CC, art. 966",["Art. 966. Considera-se empresário quem exerce profissionalmente atividade econômica organizada para a produção ou a circulação de bens ou de serviços.","Parágrafo único. Não se considera empresário quem exerce profissão intelectual, de natureza científica, literária ou artística, ainda com o concurso de auxiliares ou colaboradores, salvo se o exercício da profissão constituir elemento de empresa."]]],"2":[["CC, art. 966",["Art. 966. Considera-se empresário quem exerce profissionalmente atividade econômica organizada para a produção ou a circulação de bens ou de serviços.","Parágrafo único. Não se considera empresário quem exerce profissão intelectual, de natureza científica, literária ou artística, ainda com o concurso de auxiliares ou colaboradores, salvo se o exercício da profissão constituir elemento de empresa."]]],"3":[["CC, art. 967",["Art. 967. É obrigatória a inscrição do empresário no Registro Público de Empresas Mercantis da respectiva sede, antes do início de sua atividade."]],["CC, art. 971",["Art. 971. O empresário, cuja atividade rural constitua sua principal profissão, pode, observadas as formalidades de que tratam o art. 968 e seus parágrafos, requerer inscrição no Registro Público de Empresas Mercantis da respectiva sede, caso em que, depois de inscrito, ficará equiparado, para todos os efeitos, ao empresário sujeito a registro.","Parágrafo único. Aplica-se o disposto no caput deste artigo à associação que desenvolva atividade futebolística em caráter habitual e profissional, caso em que, com a inscrição, será considerada empresária, para todos os efeitos. (Parágrafo único acrescido pela Lei nº 14.193, de 6/8/2021)"]]],"4":[["CC, art. 972",["Art. 972. Podem exercer a atividade de empresário os que estiverem em pleno gozo da capacidade civil e não forem legalmente impedidos."]],["CC, art. 973",["Art. 973. A pessoa legalmente impedida de exercer atividade própria de empresário, se a exercer, responderá pelas obrigações contraídas."]],["CC, art. 974",["Art. 974. Poderá o incapaz, por meio de representante ou devidamente assistido, continuar a empresa antes exercida por ele enquanto capaz, por seus pais ou pelo autor de herança.","§ 1º Nos casos deste artigo, precederá autorização judicial, após exame das circunstâncias e dos riscos da empresa, bem como da conveniência em continuá-la, podendo a autorização ser revogada pelo juiz, ouvidos os pais, tutores ou representantes legais do menor ou do interdito, sem prejuízo dos direitos adquiridos por terceiros.","§ 2º Não ficam sujeitos ao resultado da empresa os bens que o incapaz já possuía, ao tempo da sucessão ou da interdição, desde que estranhos ao acervo daquela, devendo tais fatos constar do alvará que conceder a autorização.","§ 3º O Registro Público de Empresas Mercantis a cargo das Juntas Comerciais deverá registrar contratos ou alterações contratuais de sociedade que envolva sócio incapaz, desde que atendidos, de forma conjunta, os seguintes pressupostos:","I - o sócio incapaz não pode exercer a administração da sociedade;","II - o capital social deve ser totalmente integralizado;","III - o sócio relativamente incapaz deve ser assistido e o absolutamente incapaz deve ser representado por seus representantes legais. (Parágrafo acrescido pela Lei nº 12.399, de 1/4/2011)"]],["CC, art. 975",["Art. 975. Se o representante ou assistente do incapaz for pessoa que, por disposição de lei, não puder exercer atividade de empresário, nomeará, com a aprovação do juiz, um ou mais gerentes.","§ 1º Do mesmo modo será nomeado gerente em todos os casos em que o juiz entender ser conveniente.","§ 2º A aprovação do juiz não exime o representante ou assistente do menor ou do interdito da responsabilidade pelos atos dos gerentes nomeados."]],["CC, art. 976",["Art. 976. A prova da emancipação e da autorização do incapaz, nos casos do art. 974, e a de eventual revogação desta, serão inscritas ou averbadas no Registro Público de Empresas Mercantis.","Parágrafo único. O uso da nova firma caberá, conforme o caso, ao gerente; ou ao representante do incapaz; ou a este, quando puder ser autorizado."]],["CC, art. 977",["Art. 977. Faculta-se aos cônjuges contratar sociedade, entre si ou com terceiros, desde que não tenham casado no regime da comunhão universal de bens, ou no da separação obrigatória."]],["CC, art. 978",["Art. 978. O empresário casado pode, sem necessidade de outorga conjugal, qualquer que seja o regime de bens, alienar os imóveis que integrem o patrimônio da empresa ou gravá-los de ônus real."]],["CC, art. 979",["Art. 979. Além de no Registro Civil, serão arquivados e averbados, no Registro Público de Empresas Mercantis, os pactos e declarações antenupciais do empresário, o título de doação, herança, ou legado, de bens clausulados de incomunicabilidade ou inalienabilidade."]],["CC, art. 980",["Art. 980. A sentença que decretar ou homologar a separação judicial do empresário e o ato de reconciliação não podem ser opostos a terceiros, antes de arquivados e averbados no Registro Público de Empresas Mercantis."]]],"5":[["CC, art. 981",["Art. 981. Celebram contrato de sociedade as pessoas que reciprocamente se obrigam a contribuir, com bens ou serviços, para o exercício de atividade econômica e a partilha, entre si, dos resultados.","Parágrafo único. A atividade pode restringir-se à realização de um ou mais negócios determinados."]],["CC, art. 982",["Art. 982. Salvo as exceções expressas, considera-se empresária a sociedade que tem por objeto o exercício de atividade própria de empresário sujeito a registro (art. 967); e, simples, as demais.","Parágrafo único. Independentemente de seu objeto, considera-se empresária a sociedade por ações; e, simples, a cooperativa."]],["CC, art. 983",["Art. 983. A sociedade empresária deve constituir-se segundo um dos tipos regulados nos arts. 1.039 a 1.092; a sociedade simples pode constituir-se de conformidade com um desses tipos, e, não o fazendo, subordina-se às normas que lhe são próprias.","Parágrafo único. Ressalvam-se as disposições concernentes à sociedade em conta de participação e à cooperativa, bem como as constantes de leis especiais que, para o exercício de certas atividades, imponham a constituição da sociedade segundo determinado tipo."]],["CC, art. 984",["Art. 984. A sociedade que tenha por objeto o exercício de atividade própria de empresário rural e seja constituída, ou transformada, de acordo com um dos tipos de sociedade empresária, pode, com as formalidades do art. 968, requerer inscrição no Registro Público de Empresas Mercantis da sua sede, caso em que, depois de inscrita, ficará equiparada, para todos os efeitos, à sociedade empresária.","Parágrafo único. Embora já constituída a sociedade segundo um daqueles tipos, o pedido de inscrição se subordinará, no que for aplicável, às normas que regem a transformação."]],["CC, art. 985",["Art. 985. A sociedade adquire personalidade jurídica com a inscrição, no registro próprio e na forma da lei, dos seus atos constitutivos (arts. 45 e 1.150)."]],["CC, art. 1.150",["Art. 1.150. O empresário e a sociedade empresária vinculam-se ao Registro Público de Empresas Mercantis a cargo das Juntas Comerciais, e a sociedade simples ao Registro Civil das Pessoas Jurídicas, o qual deverá obedecer às normas fixadas para aquele registro, se a sociedade simples adotar um dos tipos de sociedade empresária."]]],"6":[["CC, art. 986",["Art. 986. Enquanto não inscritos os atos constitutivos, reger-se-á a sociedade, exceto por ações em organização, pelo disposto neste Capítulo, observadas, subsidiariamente e no que com ele forem compatíveis, as normas da sociedade simples."]],["CC, art. 987",["Art. 987. Os sócios, nas relações entre si ou com terceiros, somente por escrito podem provar a existência da sociedade, mas os terceiros podem prová-la de qualquer modo."]],["CC, art. 988",["Art. 988. Os bens e dívidas sociais constituem patrimônio especial, do qual os sócios são titulares em comum."]],["CC, art. 989",["Art. 989. Os bens sociais respondem pelos atos de gestão praticados por qualquer dos sócios, salvo pacto expresso limitativo de poderes, que somente terá eficácia contra o terceiro que o conheça ou deva conhecer."]],["CC, art. 990",["Art. 990. Todos os sócios respondem solidária e ilimitadamente pelas obrigações sociais, excluído do benefício de ordem, previsto no art. 1.024, aquele que contratou pela sociedade."]],["CC, art. 991",["Art. 991. Na sociedade em conta de participação, a atividade constitutiva do objeto social é exercida unicamente pelo sócio ostensivo, em seu nome individual e sob sua própria e exclusiva responsabilidade, participando os demais dos resultados correspondentes.","Parágrafo único. Obriga-se perante terceiro tão-somente o sócio ostensivo; e, exclusivamente perante este, o sócio participante, nos termos do contrato social."]],["CC, art. 992",["Art. 992. A constituição da sociedade em conta de participação independe de qualquer formalidade e pode provar-se por todos os meios de direito."]],["CC, art. 993",["Art. 993. O contrato social produz efeito somente entre os sócios, e a eventual inscrição de seu instrumento em qualquer registro não confere personalidade jurídica à sociedade.","Parágrafo único. Sem prejuízo do direito de fiscalizar a gestão dos negócios sociais, o sócio participante não pode tomar parte nas relações do sócio ostensivo com terceiros, sob pena de responder solidariamente com este pelas obrigações em que intervier."]],["CC, art. 994",["Art. 994. A contribuição do sócio participante constitui, com a do sócio ostensivo, patrimônio especial, objeto da conta de participação relativa aos negócios sociais.","§ 1º A especialização patrimonial somente produz efeitos em relação aos sócios.","§ 2º A falência do sócio ostensivo acarreta a dissolução da sociedade e a liquidação da respectiva conta, cujo saldo constituirá crédito quirografário.","§ 3º Falindo o sócio participante, o contrato social fica sujeito às normas que regulam os efeitos da falência nos contratos bilaterais do falido."]],["CC, art. 995",["Art. 995. Salvo estipulação em contrário, o sócio ostensivo não pode admitir novo sócio sem o consentimento expresso dos demais."]],["CC, art. 996",["Art. 996. Aplica-se à sociedade em conta de participação, subsidiariamente e no que com ela for compatível, o disposto para a sociedade simples, e a sua liquidação rege-se pelas normas relativas à prestação de contas, na forma da lei processual.","Parágrafo único. Havendo mais de um sócio ostensivo, as respectivas contas serão prestadas e julgadas no mesmo processo."]]],"10":[["CC, art. 1.142",["Art. 1.142. Considera-se estabelecimento todo complexo de bens organizado, para exercício da empresa, por empresário, ou por sociedade empresária.","§ 1º O estabelecimento não se confunde com o local onde se exerce a atividade empresarial, que poderá ser físico ou virtual. (Parágrafo acrescido pela Lei nº 14.195, de 26/8/2021 , com redação dada pela Medida Provisória nº 1.085, de 27/12/2021 , convertida na Lei nº 14.382, de 27/6/2022)","§ 2º Quando o local onde se exerce a atividade empresarial for virtual, o endereço informado para fins de registro poderá ser, conforme o caso, o endereço do empresário individual ou o de um dos sócios da sociedade empresária. (Parágrafo acrescido pela Lei nº 14.195, de 26/8/2021 , com redação dada pela Medida Provisória nº 1.085, de 27/12/2021 , convertida na Lei nº 14.382, de 27/6/2022)","§ 3º Quando o local onde se exerce a atividade empresarial for físico, a fixação do horário de funcionamento competirá ao Município, observada a regra geral prevista no inciso II do caput do art. 3º da Lei nº 13.874, de 20 de setembro de 2019. (Parágrafo acrescido pela Lei nº 14.195, de 26/8/2021 , com redação dada pela Medida Provisória nº 1.085, de 27/12/2021 , convertida na Lei nº 14.382, de 27/6/2022)"]],["CC, art. 1.143",["Art. 1.143. Pode o estabelecimento ser objeto unitário de direitos e de negócios jurídicos, translativos ou constitutivos, que sejam compatíveis com a sua natureza."]],["CC, art. 1.144",["Art. 1.144. O contrato que tenha por objeto a alienação, o usufruto ou arrendamento do estabelecimento, só produzirá efeitos quanto a terceiros depois de averbado à margem da inscrição do empresário, ou da sociedade empresária, no Registro Público de Empresas Mercantis, e de publicado na imprensa oficial."]],["CC, art. 1.145",["Art. 1.145. Se ao alienante não restarem bens suficientes para solver o seu passivo, a eficácia da alienação do estabelecimento depende do pagamento de todos os credores, ou do consentimento destes, de modo expresso ou tácito, em trinta dias a partir de sua notificação."]],["CC, art. 1.146",["Art. 1.146. O adquirente do estabelecimento responde pelo pagamento dos débitos anteriores à transferência, desde que regularmente contabilizados, continuando o devedor primitivo solidariamente obrigado pelo prazo de um ano, a partir, quanto aos créditos vencidos, da publicação, e, quanto aos outros, da data do vencimento."]],["CC, art. 1.147",["Art. 1.147. Não havendo autorização expressa, o alienante do estabelecimento não pode fazer concorrência ao adquirente, nos cinco anos subseqüentes à transferência.","Parágrafo único. No caso de arrendamento ou usufruto do estabelecimento, a proibição prevista neste artigo persistirá durante o prazo do contrato."]],["CC, art. 1.148",["Art. 1.148. Salvo disposição em contrário, a transferência importa a sub-rogação do adquirente nos contratos estipulados para exploração do estabelecimento, se não tiverem caráter pessoal, podendo os terceiros rescindir o contrato em noventa dias a contar da publicação da transferência, se ocorrer justa causa, ressalvada, neste caso, a responsabilidade do alienante."]],["CC, art. 1.149",["Art. 1.149. A cessão dos créditos referentes ao estabelecimento transferido produzirá efeito em relação aos respectivos devedores, desde o momento da publicação da transferência, mas o devedor ficará exonerado se de boa-fé pagar ao cedente."]]],"11":[["CC, art. 1.150",["Art. 1.150. O empresário e a sociedade empresária vinculam-se ao Registro Público de Empresas Mercantis a cargo das Juntas Comerciais, e a sociedade simples ao Registro Civil das Pessoas Jurídicas, o qual deverá obedecer às normas fixadas para aquele registro, se a sociedade simples adotar um dos tipos de sociedade empresária."]],["CC, art. 1.151",["Art. 1.151. O registro dos atos sujeitos à formalidade exigida no artigo antecedente será requerido pela pessoa obrigada em lei, e, no caso de omissão ou demora, pelo sócio ou qualquer interessado.","§ 1º Os documentos necessários ao registro deverão ser apresentados no prazo de trinta dias, contado da lavratura dos atos respectivos.","§ 2º Requerido além do prazo previsto neste artigo, o registro somente produzirá efeito a partir da data de sua concessão.","§ 3º As pessoas obrigadas a requerer o registro responderão por perdas e danos, em caso de omissão ou demora."]],["CC, art. 1.152",["Art. 1.152. Cabe ao órgão incumbido do registro verificar a regularidade das publicações determinadas em lei, de acordo com o disposto nos parágrafos deste artigo.","§ 1º Salvo exceção expressa, as publicações ordenadas neste Livro serão feitas no órgão oficial da União ou do Estado, conforme o local da sede do empresário ou da sociedade, e em jornal de grande circulação.","§ 2º As publicações das sociedades estrangeiras serão feitas nos órgãos oficiais da União e do Estado onde tiverem sucursais, filiais ou agências.","§ 3º O anúncio de convocação da assembléia de sócios será publicado por três vezes, ao menos, devendo mediar, entre a data da primeira inserção e a da realização da assembléia, o prazo mínimo de oito dias, para a primeira convocação, e de cinco dias, para as posteriores."]],["CC, art. 1.153",["Art. 1.153. Cumpre à autoridade competente, antes de efetivar o registro, verificar a autenticidade e a legitimidade do signatário do requerimento, bem como fiscalizar a observância das prescrições legais concernentes ao ato ou aos documentos apresentados.","Parágrafo único. Das irregularidades encontradas deve ser notificado o requerente, que, se for o caso, poderá saná-las, obedecendo às formalidades da lei."]],["CC, art. 1.154",["Art. 1.154. O ato sujeito a registro, ressalvadas disposições especiais da lei, não pode, antes do cumprimento das respectivas formalidades, ser oposto a terceiro, salvo prova de que este o conhecia.","Parágrafo único. O terceiro não pode alegar ignorância, desde que cumpridas as referidas formalidades."]],["CC, art. 1.155",["Art. 1.155. Considera-se nome empresarial a firma ou a denominação adotada, de conformidade com este Capítulo, para o exercício de empresa.","Parágrafo único. Equipara-se ao nome empresarial, para os efeitos da proteção da lei, a denominação das sociedades simples, associações e fundações."]],["CC, art. 1.156",["Art. 1.156. O empresário opera sob firma constituída por seu nome, completo ou abreviado, aditando-lhe, se quiser, designação mais precisa da sua pessoa ou do gênero de atividade."]],["CC, art. 1.157",["Art. 1.157. A sociedade em que houver sócios de responsabilidade ilimitada operará sob firma, na qual somente os nomes daqueles poderão figurar, bastando para formá-la aditar ao nome de um deles a expressão \"e companhia\" ou sua abreviatura.","Parágrafo único. Ficam solidária e ilimitadamente responsáveis pelas obrigações contraídas sob a firma social aqueles que, por seus nomes, figurarem na firma da sociedade de que trata este artigo."]],["CC, art. 1.158",["Art. 1.158. Pode a sociedade limitada adotar firma ou denominação, integradas pela palavra final \"limitada\" ou a sua abreviatura.","§ 1º A firma será composta com o nome de um ou mais sócios, desde que pessoas físicas, de modo indicativo da relação social.","§ 2º A denominação deve designar o objeto da sociedade, sendo permitido nela figurar o nome de um ou mais sócios.","§ 3º A omissão da palavra \"limitada\" determina a responsabilidade solidária e ilimitada dos administradores que assim empregarem a firma ou a denominação da sociedade."]],["CC, art. 1.159",["Art. 1.159. A sociedade cooperativa funciona sob denominação integrada pelo vocábulo \"cooperativa\"."]],["CC, art. 1.160",["Art. 1.160. A sociedade anônima opera sob denominação integrada pelas expressões sociedade anônima ou companhia, por extenso ou abreviadamente, facultada a designação do objeto social. (“Caput” do artigo com redação dada pela Medida Provisória nº 1.085, de 27/12/2021 , convertida na Lei nº 14.382, de 27/6/2022)","Parágrafo único. Pode constar da denominação o nome do fundador, acionista, ou pessoa que haja concorrido para o bom êxito da formação da empresa."]],["CC, art. 1.161",["Art. 1.161. A sociedade em comandita por ações pode, em lugar de firma, adotar denominação aditada da expressão comandita por ações, facultada a designação do objeto social. (Artigo com redação dada pela Medida Provisória nº 1.085, de 27/12/2021 , convertida na Lei nº 14.382, de 27/6/2022)"]],["CC, art. 1.162",["Art. 1.162. A sociedade em conta de participação não pode ter firma ou denominação."]],["CC, art. 1.163",["Art. 1.163. O nome de empresário deve distinguir-se de qualquer outro já inscrito no mesmo registro.","Parágrafo único. Se o empresário tiver nome idêntico ao de outros já inscritos, deverá acrescentar designação que o distinga."]],["CC, art. 1.164",["Art. 1.164. O nome empresarial não pode ser objeto de alienação.","Parágrafo único. O adquirente de estabelecimento, por ato entre vivos, pode, se o contrato o permitir, usar o nome do alienante, precedido do seu próprio, com a qualificação de sucessor."]],["CC, art. 1.165",["Art. 1.165. O nome de sócio que vier a falecer, for excluído ou se retirar, não pode ser conservado na firma social."]],["CC, art. 1.166",["Art. 1.166. A inscrição do empresário, ou dos atos constitutivos das pessoas jurídicas, ou as respectivas averbações, no registro próprio, asseguram o uso exclusivo do nome nos limites do respectivo Estado.","Parágrafo único. O uso previsto neste artigo estender-se-á a todo o território nacional, se registrado na forma da lei especial."]],["CC, art. 1.167",["Art. 1.167. Cabe ao prejudicado, a qualquer tempo, ação para anular a inscrição do nome empresarial feita com violação da lei ou do contrato."]],["CC, art. 1.168",["Art. 1.168. A inscrição do nome empresarial será cancelada, a requerimento de qualquer interessado, quando cessar o exercício da atividade para que foi adotado, ou quando ultimar-se a liquidação da sociedade que o inscreveu."]]],"12":[["CC, art. 1.169",["Art. 1.169. O preposto não pode, sem autorização escrita, fazer-se substituir no desempenho da preposição, sob pena de responder pessoalmente pelos atos do substituto e pelas obrigações por ele contraídas."]],["CC, art. 1.170",["Art. 1.170. O preposto, salvo autorização expressa, não pode negociar por conta própria ou de terceiro, nem participar, embora indiretamente, de operação do mesmo gênero da que lhe foi cometida, sob pena de responder por perdas e danos e de serem retidos pelo preponente os lucros da operação."]],["CC, art. 1.171",["Art. 1.171. Considera-se perfeita a entrega de papéis, bens ou valores ao preposto, encarregado pelo preponente, se os recebeu sem protesto, salvo nos casos em que haja prazo para reclamação."]],["CC, art. 1.172",["Art. 1.172. Considera-se gerente o preposto permanente no exercício da empresa, na sede desta, ou em sucursal, filial ou agência."]],["CC, art. 1.173",["Art. 1.173. Quando a lei não exigir poderes especiais, considera-se o gerente autorizado a praticar todos os atos necessários ao exercício dos poderes que lhe foram outorgados.","Parágrafo único. Na falta de estipulação diversa, consideram-se solidários os poderes conferidos a dois ou mais gerentes."]],["CC, art. 1.174",["Art. 1.174. As limitações contidas na outorga de poderes, para serem opostas a terceiros, dependem do arquivamento e averbação do instrumento no Registro Público de Empresas Mercantis, salvo se provado serem conhecidas da pessoa que tratou com o gerente.","Parágrafo único. Para o mesmo efeito e com idêntica ressalva, deve a modificação ou revogação do mandato ser arquivada e averbada no Registro Público de Empresas Mercantis."]],["CC, art. 1.175",["Art. 1.175. O preponente responde com o gerente pelos atos que este pratique em seu próprio nome, mas à conta daquele."]],["CC, art. 1.176",["Art. 1.176. O gerente pode estar em juízo em nome do preponente, pelas obrigações resultantes do exercício da sua função."]],["CC, art. 1.177",["Art. 1.177. Os assentos lançados nos livros ou fichas do preponente, por qualquer dos prepostos encarregados de sua escrituração, produzem, salvo se houver procedido de má-fé, os mesmos efeitos como se o fossem por aquele.","Parágrafo único. No exercício de suas funções, os prepostos são pessoalmente responsáveis, perante os preponentes, pelos atos culposos; e, perante terceiros, solidariamente com o preponente, pelos atos dolosos."]],["CC, art. 1.178",["Art. 1.178. Os preponentes são responsáveis pelos atos de quaisquer prepostos, praticados nos seus estabelecimentos e relativos à atividade da empresa, ainda que não autorizados por escrito.","Parágrafo único. Quando tais atos forem praticados fora do estabelecimento, somente obrigarão o preponente nos limites dos poderes conferidos por escrito, cujo instrumento pode ser suprido pela certidão ou cópia autêntica do seu teor."]]],"13":[["CC, art. 1.179",["Art. 1.179. O empresário e a sociedade empresária são obrigados a seguir um sistema de contabilidade, mecanizado ou não, com base na escrituração uniforme de seus livros, em correspondência com a documentação respectiva, e a levantar anualmente o balanço patrimonial e o de resultado econômico.","§ 1º Salvo o disposto no art. 1.180, o número e a espécie de livros ficam a critério dos interessados.","§ 2º É dispensado das exigências deste artigo o pequeno empresário a que se refere o art. 970."]],["CC, art. 1.180",["Art. 1.180. Além dos demais livros exigidos por lei, é indispensável o Diário, que pode ser substituído por fichas no caso de escrituração mecanizada ou eletrônica.","Parágrafo único. A adoção de fichas não dispensa o uso de livro apropriado para o lançamento do balanço patrimonial e do de resultado econômico."]],["CC, art. 1.181",["Art. 1.181. Salvo disposição especial de lei, os livros obrigatórios e, se for o caso, as fichas, antes de postos em uso, devem ser autenticados no Registro Público de Empresas Mercantis.","Parágrafo único. A autenticação não se fará sem que esteja inscrito o empresário, ou a sociedade empresária, que poderá fazer autenticar livros não obrigatórios."]],["CC, art. 1.182",["Art. 1.182. Sem prejuízo do disposto no art. 1.174, a escrituração ficará sob a responsabilidade de contabilista legalmente habilitado, salvo se nenhum houver na localidade."]],["CC, art. 1.183",["Art. 1.183. A escrituração será feita em idioma e moeda corrente nacionais e em forma contábil, por ordem cronológica de dia, mês e ano, sem intervalos em branco, nem entrelinhas, borrões, rasuras, emendas ou transportes para as margens.","Parágrafo único. É permitido o uso de código de números ou de abreviaturas, que constem de livro próprio, regularmente autenticado."]],["CC, art. 1.184",["Art. 1.184. No Diário serão lançadas, com individuação, clareza e caracterização do documento respectivo, dia a dia, por escrita direta ou reprodução, todas as operações relativas ao exercício da empresa.","§ 1º Admite-se a escrituração resumida do Diário, com totais que não excedam o período de trinta dias, relativamente a contas cujas operações sejam numerosas ou realizadas fora da sede do estabelecimento, desde que utilizados livros auxiliares regularmente autenticados, para registro individualizado, e conservados os documentos que permitam a sua perfeita verificação.","§ 2º Serão lançados no Diário o balanço patrimonial e o de resultado econômico, devendo ambos ser assinados por técnico em Ciências Contábeis legalmente habilitado e pelo empresário ou sociedade empresária."]],["CC, art. 1.185",["Art. 1.185. O empresário ou sociedade empresária que adotar o sistema de fichas de lançamentos poderá substituir o livro Diário pelo livro Balancetes Diários e Balanços, observadas as mesmas formalidades extrínsecas exigidas para aquele."]],["CC, art. 1.186",["Art. 1.186. O livro Balancetes Diários e Balanços será escriturado de modo que registre:","I - a posição diária de cada uma das contas ou títulos contábeis, pelo respectivo saldo, em forma de balancetes diários;","II - o balanço patrimonial e o de resultado econômico, no encerramento do exercício."]],["CC, art. 1.187",["Art. 1.187. Na coleta dos elementos para o inventário serão observados os critérios de avaliação a seguir determinados:","I - os bens destinados à exploração da atividade serão avaliados pelo custo de aquisição, devendo, na avaliação dos que se desgastam ou depreciam com o uso, pela ação do tempo ou outros fatores, atender-se à desvalorização respectiva, criando-se fundos de amortização para assegurar-lhes a substituição ou a conservação do valor;","II - os valores mobiliários, matéria-prima, bens destinados à alienação, ou que constituem produtos ou artigos da indústria ou comércio da empresa, podem ser estimados pelo custo de aquisição ou de fabricação, ou pelo preço corrente, sempre que este for inferior ao preço de custo, e quando o preço corrente ou venal estiver acima do valor do custo de aquisição, ou fabricação, e os bens forem avaliados pelo preço corrente, a diferença entre este e o preço de custo não será levada em conta para a distribuição de lucros, nem para as percentagens referentes a fundos de reserva;","III - o valor das ações e dos títulos de renda fixa pode ser determinado com base na respectiva cotação da Bolsa de Valores; os não cotados e as participações não acionárias serão considerados pelo seu valor de aquisição;","IV - os créditos serão considerados de conformidade com o presumível valor de realização, não se levando em conta os prescritos ou de difícil liqüidação, salvo se houver, quanto aos últimos, previsão equivalente.","Parágrafo único. Entre os valores do ativo podem figurar, desde que se preceda, anualmente, à sua amortização:","I - as despesas de instalação da sociedade, até o limite correspondente a dez por cento do capital social;","II - os juros pagos aos acionistas da sociedade anônima, no período antecedente ao início das operações sociais, à taxa não superior a doze por cento ao ano, fixada no estatuto;","III - a quantia efetivamente paga a título de aviamento de estabelecimento adquirido pelo empresário ou sociedade."]],["CC, art. 1.188",["Art. 1.188. O balanço patrimonial deverá exprimir, com fidelidade e clareza, a situação real da empresa e, atendidas as peculiaridades desta, bem como as disposições das leis especiais, indicará, distintamente, o ativo e o passivo.","Parágrafo único. Lei especial disporá sobre as informações que acompanharão o balanço patrimonial, em caso de sociedades coligadas."]],["CC, art. 1.189",["Art. 1.189. O balanço de resultado econômico, ou demonstração da conta de lucros e perdas, acompanhará o balanço patrimonial e dele constarão crédito e débito, na forma da lei especial."]],["CC, art. 1.190",["Art. 1.190. Ressalvados os casos previstos em lei, nenhuma autoridade, juiz ou tribunal, sob qualquer pretexto, poderá fazer ou ordenar diligência para verificar se o empresário ou a sociedade empresária observam, ou não, em seus livros e fichas, as formalidades prescritas em lei."]],["CC, art. 1.191",["Art. 1.191. O juiz só poderá autorizar a exibição integral dos livros e papéis de escrituração quando necessária para resolver questões relativas a sucessão, comunhão ou sociedade, administração ou gestão à conta de outrem, ou em caso de falência.","§ 1º O juiz ou tribunal que conhecer de medida cautelar ou de ação pode, a requerimento ou de ofício, ordenar que os livros de qualquer das partes, ou de ambas, sejam examinados na presença do empresário ou da sociedade empresária a que pertencerem, ou de pessoas por estes nomeadas, para deles se extrair o que interessar à questão.","§ 2º Achando-se os livros em outra jurisdição, nela se fará o exame, perante o respectivo juiz."]],["CC, art. 1.192",["Art. 1.192. Recusada a apresentação dos livros, nos casos do artigo antecedente, serão apreendidos judicialmente e, no do seu § 1 o , ter-se-á como verdadeiro o alegado pela parte contrária para se provar pelos livros.","Parágrafo único. A confissão resultante da recusa pode ser elidida por prova documental em contrário."]],["CC, art. 1.193",["Art. 1.193. As restrições estabelecidas neste Capítulo ao exame da escrituração, em parte ou por inteiro, não se aplicam às autoridades fazendárias, no exercício da fiscalização do pagamento de impostos, nos termos estritos das respectivas leis especiais."]],["CC, art. 1.194",["Art. 1.194. O empresário e a sociedade empresária são obrigados a conservar em boa guarda toda a escrituração, correspondência e mais papéis concernentes à sua atividade, enquanto não ocorrer prescrição ou decadência no tocante aos atos neles consignados."]],["CC, art. 1.195",["Art. 1.195. As disposições deste Capítulo aplicam-se às sucursais, filiais ou agências, no Brasil, do empresário ou sociedade com sede em país estrangeiro."]]],"15":[["CC, art. 910",["Art. 910. O endosso deve ser lançado pelo endossante no verso ou anverso do próprio título.","§ 1º Pode o endossante designar o endossatário, e para validade do endosso, dado no verso do título, é suficiente a simples assinatura do endossante.","§ 2º A transferência por endosso completa-se com a tradição do título.","§ 3º Considera-se não escrito o endosso cancelado, total ou parcialmente."]],["CC, art. 911",["Art. 911. Considera-se legítimo possuidor o portador do título à ordem com série regular e ininterrupta de endossos, ainda que o último seja em branco.","Parágrafo único. Aquele que paga o título está obrigado a verificar a regularidade da série de endossos, mas não a autenticidade das assinaturas."]],["CC, art. 912",["Art. 912. Considera-se não escrita no endosso qualquer condição a que o subordine o endossante.","Parágrafo único. É nulo o endosso parcial."]],["CC, art. 913",["Art. 913. O endossatário de endosso em branco pode mudá-lo para endosso em preto, completando-o com o seu nome ou de terceiro; pode endossar novamente o título, em branco ou em preto; ou pode transferi-lo sem novo endosso."]],["CC, art. 914",["Art. 914. Ressalvada cláusula expressa em contrário, constante do endosso, não responde o endossante pelo cumprimento da prestação constante do título.","§ 1º Assumindo responsabilidade pelo pagamento, o endossante se torna devedor solidário.","§ 2º Pagando o título, tem o endossante ação de regresso contra os coobrigados anteriores."]],["CC, art. 915",["Art. 915. O devedor, além das exceções fundadas nas relações pessoais que tiver com o portador, só poderá opor a este as exceções relativas à forma do título e ao seu conteúdo literal, à falsidade da própria assinatura, a defeito de capacidade ou de representação no momento da subscrição, e à falta de requisito necessário ao exercício da ação."]],["CC, art. 916",["Art. 916. As exceções, fundadas em relação do devedor com os portadores precedentes, somente poderão ser por ele opostas ao portador, se este, ao adquirir o título, tiver agido de má-fé."]],["CC, art. 917",["Art. 917. A cláusula constitutiva de mandato, lançada no endosso, confere ao endossatário o exercício dos direitos inerentes ao título, salvo restrição expressamente estatuída.","§ 1º O endossatário de endosso-mandato só pode endossar novamente o título na qualidade de procurador, com os mesmos poderes que recebeu.","§ 2º Com a morte ou a superveniente incapacidade do endossante, não perde eficácia o endosso-mandato.","§ 3º Pode o devedor opor ao endossatário de endosso-mandato somente as exceções que tiver contra o endossante."]],["CC, art. 918",["Art. 918. A cláusula constitutiva de penhor, lançada no endosso, confere ao endossatário o exercício dos direitos inerentes ao título.","§ 1º O endossatário de endosso-penhor só pode endossar novamente o título na qualidade de procurador.","§ 2º Não pode o devedor opor ao endossatário de endosso-penhor as exceções que tinha contra o endossante, salvo se aquele tiver agido de má-fé."]],["CC, art. 919",["Art. 919. A aquisição de título à ordem, por meio diverso do endosso, tem efeito de cessão civil."]],["CC, art. 920",["Art. 920. O endosso posterior ao vencimento produz os mesmos efeitos do anterior."]],["CC, art. 921",["Art. 921. É título nominativo o emitido em favor de pessoa cujo nome conste no registro do emitente."]],["CC, art. 922",["Art. 922. Transfere-se o título nominativo mediante termo, em registro do emitente, assinado pelo proprietário e pelo adquirente."]],["CC, art. 923",["Art. 923. O título nominativo também pode ser transferido por endosso que contenha o nome do endossatário.","§ 1º A transferência mediante endosso só tem eficácia perante o emitente, uma vez feita a competente averbação em seu registro, podendo o emitente exigir do endossatário que comprove a autenticidade da assinatura do endossante.","§ 2º O endossatário, legitimado por série regular e ininterrupta de endossos, tem o direito de obter a averbação no registro do emitente, comprovada a autenticidade das assinaturas de todos os endossantes.","§ 3º Caso o título original contenha o nome do primitivo proprietário, tem direito o adquirente a obter do emitente novo título, em seu nome, devendo a emissão do novo título constar no registro do emitente."]],["CC, art. 924",["Art. 924. Ressalvada proibição legal, pode o título nominativo ser transformado em à ordem ou ao portador, a pedido do proprietário e à sua custa."]],["CC, art. 925",["Art. 925. Fica desonerado de responsabilidade o emitente que de boa-fé fizer a transferência pelos modos indicados nos artigos antecedentes."]],["CC, art. 926",["Art. 926. Qualquer negócio ou medida judicial, que tenha por objeto o título, só produz efeito perante o emitente ou terceiros, uma vez feita a competente averbação no registro do emitente."]]]},"11":{"0":[["CC, art. 1.196",["Art. 1.196. Considera-se possuidor todo aquele que tem de fato o exercício, pleno ou não, de algum dos poderes inerentes à propriedade."]],["CC, art. 1.198",["Art. 1.198. Considera-se detentor aquele que, achando-se em relação de dependência para com outro, conserva a posse em nome deste e em cumprimento de ordens ou instruções suas.","Parágrafo único. Aquele que começou a comportar-se do modo como prescreve este artigo, em relação ao bem e à outra pessoa, presume-se detentor, até que prove o contrário."]]],"1":[["CC, art. 1.197",["Art. 1.197. A posse direta, de pessoa que tem a coisa em seu poder, temporariamente, em virtude de direito pessoal, ou real, não anula a indireta, de quem aquela foi havida, podendo o possuidor direto defender a sua posse contra o indireto."]]],"2":[["CC, art. 1.200",["Art. 1.200. É justa a posse que não for violenta, clandestina ou precária."]],["CC, art. 1.201",["Art. 1.201. É de boa-fé a posse, se o possuidor ignora o vício, ou o obstáculo que impede a aquisição da coisa.","Parágrafo único. O possuidor com justo título tem por si a presunção de boa-fé, salvo prova em contrário, ou quando a lei expressamente não admite esta presunção."]]],"3":[["CC, art. 1.199",["Art. 1.199. Se duas ou mais pessoas possuírem coisa indivisa, poderá cada uma exercer sobre ela atos possessórios, contanto que não excluam os dos outros compossuidores."]]],"4":[["CC, art. 1.204",["Art. 1.204. Adquire-se a posse desde o momento em que se torna possível o exercício, em nome próprio, de qualquer dos poderes inerentes à propriedade."]]],"5":[["CC, art. 1.204",["Art. 1.204. Adquire-se a posse desde o momento em que se torna possível o exercício, em nome próprio, de qualquer dos poderes inerentes à propriedade."]],["CC, art. 1.267",["Art. 1.267. A propriedade das coisas não se transfere pelos negócios jurídicos antes da tradição.","Parágrafo único. Subentende-se a tradição quando o transmitente continua a possuir pelo constituto possessório; quando cede ao adquirente o direito à restituição da coisa, que se encontra em poder de terceiro; ou quando o adquirente já está na posse da coisa, por ocasião do negócio jurídico."]]],"6":[["CC, art. 1.198",["Art. 1.198. Considera-se detentor aquele que, achando-se em relação de dependência para com outro, conserva a posse em nome deste e em cumprimento de ordens ou instruções suas.","Parágrafo único. Aquele que começou a comportar-se do modo como prescreve este artigo, em relação ao bem e à outra pessoa, presume-se detentor, até que prove o contrário."]],["CC, art. 1.208",["Art. 1.208. Não induzem posse os atos de mera permissão ou tolerância assim como não autorizam a sua aquisição os atos violentos, ou clandestinos, senão depois de cessar a violência ou a clandestinidade."]]],"7":[["CC, art. 1.214",["Art. 1.214. O possuidor de boa-fé tem direito, enquanto ela durar, aos frutos percebidos.","Parágrafo único. Os frutos pendentes ao tempo em que cessar a boa-fé devem ser restituídos, depois de deduzidas as despesas da produção e custeio; devem ser também restituídos os frutos colhidos com antecipação."]],["CC, art. 1.215",["Art. 1.215. Os frutos naturais e industriais reputam-se colhidos e percebidos, logo que são separados; os civis reputam-se percebidos dia por dia."]],["CC, art. 1.216",["Art. 1.216. O possuidor de má-fé responde por todos os frutos colhidos e percebidos, bem como pelos que, por culpa sua, deixou de perceber, desde o momento em que se constituiu de má-fé; tem direito às despesas da produção e custeio."]]],"8":[["CC, art. 1.217",["Art. 1.217. O possuidor de boa-fé não responde pela perda ou deterioração da coisa, a que não der causa."]],["CC, art. 1.218",["Art. 1.218. O possuidor de má-fé responde pela perda, ou deterioração da coisa, ainda que acidentais, salvo se provar que de igual modo se teriam dado, estando ela na posse do reivindicante."]]],"9":[["CC, art. 1.219",["Art. 1.219. O possuidor de boa-fé tem direito à indenização das benfeitorias necessárias e úteis, bem como, quanto às voluptuárias, se não lhe forem pagas, a levantá-las, quando o puder sem detrimento da coisa, e poderá exercer o direito de retenção pelo valor das benfeitorias necessárias e úteis."]],["CC, art. 1.220",["Art. 1.220. Ao possuidor de má-fé serão ressarcidas somente as benfeitorias necessárias; não lhe assiste o direito de retenção pela importância destas, nem o de levantar as voluptuárias."]],["CC, art. 1.221",["Art. 1.221. As benfeitorias compensam-se com os danos, e só obrigam ao ressarcimento se ao tempo da evicção ainda existirem."]],["CC, art. 1.222",["Art. 1.222. O reivindicante, obrigado a indenizar as benfeitorias ao possuidor de má-fé, tem o direito de optar entre o seu valor atual e o seu custo; ao possuidor de boa-fé indenizará pelo valor atual."]]],"10":[["CC, art. 1.210",["Art. 1.210. O possuidor tem direito a ser mantido na posse em caso de turbação, restituído no de esbulho, e segurado de violência iminente, se tiver justo receio de ser molestado.","§ 1º O possuidor turbado, ou esbulhado, poderá manter-se ou restituir-se por sua própria força, contanto que o faça logo; os atos de defesa, ou de desforço, não podem ir além do indispensável à manutenção, ou restituição da posse.","§ 2º Não obsta à manutenção ou reintegração na posse a alegação de propriedade, ou de outro direito sobre a coisa."]],["CPC, art. 554",["Art. 554. A propositura de uma ação possessória em vez de outra não obstará a que o juiz conheça do pedido e outorgue a proteção legal correspondente àquela cujos pressupostos estejam provados.","§ 1º No caso de ação possessória em que figure no polo passivo grande número de pessoas, serão feitas a citação pessoal dos ocupantes que forem encontrados no local e a citação por edital dos demais, determinando-se, ainda, a intimação do Ministério Público e, se envolver pessoas em situação de hipossuficiência econômica, da Defensoria Pública.","§ 2º Para fim da citação pessoal prevista no § 1º, o oficial de justiça procurará os ocupantes no local por uma vez, citando-se por edital os que não forem encontrados.","§ 3º O juiz deverá determinar que se dê ampla publicidade da existência da ação prevista no § 1º e dos respectivos prazos processuais, podendo, para tanto, valer-se de anúncios em jornal ou rádio locais, da publicação de cartazes na região do conflito e de outros meios."]],["CPC, art. 555",["Art. 555. É lícito ao autor cumular ao pedido possessório o de:","I - condenação em perdas e danos;","II - indenização dos frutos.","Parágrafo único. Pode o autor requerer, ainda, imposição de medida necessária e adequada para:","I - evitar nova turbação ou esbulho;","II - cumprir-se a tutela provisória ou final."]],["CPC, art. 556",["Art. 556. É lícito ao réu, na contestação, alegando que foi o ofendido em sua posse, demandar a proteção possessória e a indenização pelos prejuízos resultantes da turbação ou do esbulho cometido pelo autor."]],["CPC, art. 557",["Art. 557. Na pendência de ação possessória é vedado, tanto ao autor quanto ao réu, propor ação de reconhecimento do domínio, exceto se a pretensão for deduzida em face de terceira pessoa.","Parágrafo único. Não obsta à manutenção ou à reintegração de posse a alegação de propriedade ou de outro direito sobre a coisa."]],["CPC, art. 558",["Art. 558. Regem o procedimento de manutenção e de reintegração de posse as normas da Seção II deste Capítulo quando a ação for proposta dentro de ano e dia da turbação ou do esbulho afirmado na petição inicial.","Parágrafo único. Passado o prazo referido no caput , será comum o procedimento, não perdendo, contudo, o caráter possessório."]],["CPC, art. 559",["Art. 559. Se o réu provar, em qualquer tempo, que o autor provisoriamente mantido ou reintegrado na posse carece de idoneidade financeira para, no caso de sucumbência, responder por perdas e danos, o juiz designar-lhe-á o prazo de 5 (cinco) dias para requerer caução, real ou fidejussória, sob pena de ser depositada a coisa litigiosa, ressalvada a impossibilidade da parte economicamente hipossuficiente."]],["CPC, art. 560",["Art. 560. O possuidor tem direito a ser mantido na posse em caso de turbação e reintegrado em caso de esbulho."]],["CPC, art. 561",["Art. 561. Incumbe ao autor provar:","I - a sua posse;","II - a turbação ou o esbulho praticado pelo réu;","III - a data da turbação ou do esbulho;","IV - a continuação da posse, embora turbada, na ação de manutenção, ou a perda da posse, na ação de reintegração."]],["CPC, art. 562",["Art. 562. Estando a petição inicial devidamente instruída, o juiz deferirá, sem ouvir o réu, a expedição do mandado liminar de manutenção ou de reintegração, caso contrário, determinará que o autor justifique previamente o alegado, citando-se o réu para comparecer à audiência que for designada.","Parágrafo único. Contra as pessoas jurídicas de direito público não será deferida a manutenção ou a reintegração liminar sem prévia audiência dos respectivos representantes judiciais."]],["CPC, art. 563",["Art. 563. Considerada suficiente a justificação, o juiz fará logo expedir mandado de manutenção ou de reintegração."]],["CPC, art. 564",["Art. 564. Concedido ou não o mandado liminar de manutenção ou de reintegração, o autor promoverá, nos 5 (cinco) dias subsequentes, a citação do réu para, querendo, contestar a ação no prazo de 15 (quinze) dias.","Parágrafo único. Quando for ordenada a justificação prévia, o prazo para contestar será contado da intimação da decisão que deferir ou não a medida liminar."]],["CPC, art. 565",["Art. 565. No litígio coletivo pela posse de imóvel, quando o esbulho ou a turbação afirmado na petição inicial houver ocorrido há mais de ano e dia, o juiz, antes de apreciar o pedido de concessão da medida liminar, deverá designar audiência de mediação, a realizar-se em até 30 (trinta) dias, que observará o disposto nos §§ 2º e 4º.","§ 1º Concedida a liminar, se essa não for executada no prazo de 1 (um) ano, a contar da data de distribuição, caberá ao juiz designar audiência de mediação, nos termos dos §§ 2º a 4º deste artigo.","§ 2º O Ministério Público será intimado para comparecer à audiência, e a Defensoria Pública será intimada sempre que houver parte beneficiária de gratuidade da justiça.","§ 3º O juiz poderá comparecer à área objeto do litígio quando sua presença se fizer necessária à efetivação da tutela jurisdicional.","§ 4º Os órgãos responsáveis pela política agrária e pela política urbana da União, de Estado ou do Distrito Federal e de Município onde se situe a área objeto do litígio poderão ser intimados para a audiência, a fim de se manifestarem sobre seu interesse no processo e sobre a existência de possibilidade de solução para o conflito possessório.","§ 5º Aplica-se o disposto neste artigo ao litígio sobre propriedade de imóvel."]],["CPC, art. 566",["Art. 566. Aplica-se, quanto ao mais, o procedimento comum."]],["CPC, art. 567",["Art. 567. O possuidor direto ou indireto que tenha justo receio de ser molestado na posse poderá requerer ao juiz que o segure da turbação ou esbulho iminente, mediante mandado proibitório em que se comine ao réu determinada pena pecuniária caso transgrida o preceito."]],["CPC, art. 568",["Art. 568. Aplica-se ao interdito proibitório o disposto na Seção II deste Capítulo."]]],"11":[["CC, art. 1.210",["Art. 1.210. O possuidor tem direito a ser mantido na posse em caso de turbação, restituído no de esbulho, e segurado de violência iminente, se tiver justo receio de ser molestado.","§ 1º O possuidor turbado, ou esbulhado, poderá manter-se ou restituir-se por sua própria força, contanto que o faça logo; os atos de defesa, ou de desforço, não podem ir além do indispensável à manutenção, ou restituição da posse."]],["CPC, art. 558",["Art. 558. Regem o procedimento de manutenção e de reintegração de posse as normas da Seção II deste Capítulo quando a ação for proposta dentro de ano e dia da turbação ou do esbulho afirmado na petição inicial.","Parágrafo único. Passado o prazo referido no caput , será comum o procedimento, não perdendo, contudo, o caráter possessório."]]],"12":[["CF/88, art. 5º",["Art. 5º Todos são iguais perante a lei, sem distinção de qualquer natureza, garantindo-se aos brasileiros e aos estrangeiros residentes no País a inviolabilidade do direito à vida, à liberdade, à igualdade, à segurança e à propriedade, nos termos seguintes:","[…]","XXII - é garantido o direito de propriedade;"]],["CPC, art. 565",["Art. 565. No litígio coletivo pela posse de imóvel, quando o esbulho ou a turbação afirmado na petição inicial houver ocorrido há mais de ano e dia, o juiz, antes de apreciar o pedido de concessão da medida liminar, deverá designar audiência de mediação, a realizar-se em até 30 (trinta) dias, que observará o disposto nos §§ 2º e 4º.","§ 1º Concedida a liminar, se essa não for executada no prazo de 1 (um) ano, a contar da data de distribuição, caberá ao juiz designar audiência de mediação, nos termos dos §§ 2º a 4º deste artigo.","§ 2º O Ministério Público será intimado para comparecer à audiência, e a Defensoria Pública será intimada sempre que houver parte beneficiária de gratuidade da justiça.","§ 3º O juiz poderá comparecer à área objeto do litígio quando sua presença se fizer necessária à efetivação da tutela jurisdicional.","§ 4º Os órgãos responsáveis pela política agrária e pela política urbana da União, de Estado ou do Distrito Federal e de Município onde se situe a área objeto do litígio poderão ser intimados para a audiência, a fim de se manifestarem sobre seu interesse no processo e sobre a existência de possibilidade de solução para o conflito possessório.","§ 5º Aplica-se o disposto neste artigo ao litígio sobre propriedade de imóvel."]]]},"12":{"0":[["CC, art. 1.225",["Art. 1.225. São direitos reais:","I - a propriedade;","II - a superfície;","III - as servidões;","IV - o usufruto;","V - o uso;","VI - a habitação;","VII - o direito do promitente comprador do imóvel;","VIII - o penhor;","IX - a hipoteca;","X - a anticrese;","XI - a concessão de uso especial para fins de moradia; (Inciso acrescido pela Lei nº 11.481, de 31/5/2007)","XII - a concessão de direito real de uso; (Inciso acrescido pela Lei nº 11.481, de 31/5/2007, e com nova redação dada pela Lei nº 14.620, de 13/7/2023)","XIII - a laje; (Inciso acrescido pela Medida Provisória nº 759, de 22/12/2016, convertida na Lei nº 13.465, de 11/7/2017, e com nova redação dada pela Lei nº 14.620, de 13/7/2023)","XIV - os direitos oriundos da imissão provisória na posse, quando concedida à União, aos Estados, ao Distrito Federal, aos Municípios ou às suas entidades delegadas e a respectiva cessão e promessa de cessão. (Inciso acrescido pela Lei nº 14.620, de 13/7/2023)"]],["CC, art. 1.226",["Art. 1.226. Os direitos reais sobre coisas móveis, quando constituídos, ou transmitidos por atos entre vivos, só se adquirem com a tradição."]],["CC, art. 1.227",["Art. 1.227. Os direitos reais sobre imóveis constituídos, ou transmitidos por atos entre vivos, só se adquirem com o registro no Cartório de Registro de Imóveis dos referidos títulos (arts. 1.245 a 1.247), salvo os casos expressos neste Código."]],["CC, art. 1.228",["Art. 1.228. O proprietário tem a faculdade de usar, gozar e dispor da coisa, e o direito de reavê-la do poder de quem quer que injustamente a possua ou detenha.","§ 1º O direito de propriedade deve ser exercido em consonância com as suas finalidades econômicas e sociais e de modo que sejam preservados, de conformidade com o estabelecido em lei especial, a flora, a fauna, as belezas naturais, o equilíbrio ecológico e o patrimônio histórico e artístico, bem como evitada a poluição do ar e das águas.","§ 2º São defesos os atos que não trazem ao proprietário qualquer comodidade, ou utilidade, e sejam animados pela intenção de prejudicar outrem.","§ 3º O proprietário pode ser privado da coisa, nos casos de desapropriação, por necessidade ou utilidade pública ou interesse social, bem como no de requisição, em caso de perigo público iminente.","§ 4º O proprietário também pode ser privado da coisa se o imóvel reivindicado consistir em extensa área, na posse ininterrupta e de boa-fé, por mais de cinco anos, de considerável número de pessoas, e estas nela houverem realizado, em conjunto ou separadamente, obras e serviços considerados pelo juiz de interesse social e econômico relevante.","§ 5º No caso do parágrafo antecedente, o juiz fixará a justa indenização devida ao proprietário; pago o preço, valerá a sentença como título para o registro do imóvel em nome dos possuidores."]],["CF/88, art. 5º",["Art. 5º Todos são iguais perante a lei, sem distinção de qualquer natureza, garantindo-se aos brasileiros e aos estrangeiros residentes no País a inviolabilidade do direito à vida, à liberdade, à igualdade, à segurança e à propriedade, nos termos seguintes:","[…]","XXII - é garantido o direito de propriedade;"]]],"1":[["CC, art. 1.227",["Art. 1.227. Os direitos reais sobre imóveis constituídos, ou transmitidos por atos entre vivos, só se adquirem com o registro no Cartório de Registro de Imóveis dos referidos títulos (arts. 1.245 a 1.247), salvo os casos expressos neste Código."]],["CC, art. 1.245",["Art. 1.245. Transfere-se entre vivos a propriedade mediante o registro do título translativo no Registro de Imóveis.","§ 1º Enquanto não se registrar o título translativo, o alienante continua a ser havido como dono do imóvel."]]],"2":[["CC, art. 1.238",["Art. 1.238. Aquele que, por quinze anos, sem interrupção, nem oposição, possuir como seu um imóvel, adquire-lhe a propriedade, independentemente de título e boa-fé; podendo requerer ao juiz que assim o declare por sentença, a qual servirá de título para o registro no Cartório de Registro de Imóveis.","Parágrafo único. O prazo estabelecido neste artigo reduzir-se-á a dez anos se o possuidor houver estabelecido no imóvel a sua moradia habitual, ou nele realizado obras ou serviços de caráter produtivo."]],["CC, art. 1.239",["Art. 1.239. Aquele que, não sendo proprietário de imóvel rural ou urbano, possua como sua, por cinco anos ininterruptos, sem oposição, área de terra em zona rural não superior a cinqüenta hectares, tornando-a produtiva por seu trabalho ou de sua família, tendo nela sua moradia, adquirir-lhe-á a propriedade."]],["CC, art. 1.240",["Art. 1.240. Aquele que possuir, como sua, área urbana de até duzentos e cinqüenta metros quadrados, por cinco anos ininterruptamente e sem oposição, utilizando-a para sua moradia ou de sua família, adquirir-lhe-á o domínio, desde que não seja proprietário de outro imóvel urbano ou rural.","§ 1º O título de domínio e a concessão de uso serão conferidos ao homem ou à mulher, ou a ambos, independentemente do estado civil.","§ 2º O direito previsto no parágrafo antecedente não será reconhecido ao mesmo possuidor mais de uma vez."]],["CC, art. 1.240-A",["Art. 1.240-A Aquele que exercer, por 2 (dois) anos ininterruptamente e sem oposição, posse direta, com exclusividade, sobre imóvel urbano de até 250m² (duzentos e cinquenta metros quadrados) cuja propriedade divida com ex-cônjuge ou ex-companheiro que abandonou o lar, utilizando-o para sua moradia ou de sua família, adquirir-lhe-á o domínio integral, desde que não seja proprietário de outro imóvel urbano ou rural.","§ 1º O direito previsto no caput não será reconhecido ao mesmo possuidor mais de uma vez.","§ 2º (VETADO) (Artigo acrescido pela Lei nº 12.424, de 16/6/2011)"]],["CC, art. 1.241",["Art. 1.241. Poderá o possuidor requerer ao juiz seja declarada adquirida, mediante usucapião, a propriedade imóvel.","Parágrafo único. A declaração obtida na forma deste artigo constituirá título hábil para o registro no Cartório de Registro de Imóveis."]],["CC, art. 1.242",["Art. 1.242. Adquire também a propriedade do imóvel aquele que, contínua e incontestadamente, com justo título e boa-fé, o possuir por dez anos.","Parágrafo único. Será de cinco anos o prazo previsto neste artigo se o imóvel houver sido adquirido, onerosamente, com base no registro constante do respectivo cartório, cancelada posteriormente, desde que os possuidores nele tiverem estabelecido a sua moradia, ou realizado investimentos de interesse social e econômico."]],["CC, art. 1.243",["Art. 1.243. O possuidor pode, para o fim de contar o tempo exigido pelos artigos antecedentes, acrescentar à sua posse a dos seus antecessores (art. 1.207), contanto que todas sejam contínuas, pacíficas e, nos casos do art. 1.242, com justo título e de boa-fé."]],["CC, art. 1.244",["Art. 1.244. Estende-se ao possuidor o disposto quanto ao devedor acerca das causas que obstam, suspendem ou interrompem a prescrição, as quais também se aplicam à usucapião."]],["CF/88, art. 183",["Art. 183. Aquele que possuir como sua área urbana de até duzentos e cinqüenta metros quadrados, por cinco anos, ininterruptamente e sem oposição, utilizando-a para sua moradia ou de sua família, adquirir-lhe-á o domínio, desde que não seja proprietário de outro imóvel urbano ou rural.","§ 1º O título de domínio e a concessão de uso serão conferidos ao homem ou à mulher, ou a ambos, independentemente do estado civil.","§ 2º Esse direito não será reconhecido ao mesmo possuidor mais de uma vez.","§ 3º Os imóveis públicos não serão adquiridos por usucapião."]],["CF/88, art. 191",["Art. 191. Aquele que, não sendo proprietário de imóvel rural ou urbano, possua como seu, por cinco anos ininterruptos, sem oposição, área de terra, em zona rural, não superior a cinqüenta hectares, tornando-a produtiva por seu trabalho ou de sua família, tendo nela sua moradia, adquirir-lhe-á a propriedade.","Parágrafo único. Os imóveis públicos não serão adquiridos por usucapião."]]],"3":[["CC, art. 1.248",["Art. 1.248. A acessão pode dar-se:","I - por formação de ilhas;","II - por aluvião;","III - por avulsão;","IV - por abandono de álveo;","V - por plantações ou construções."]],["CC, art. 1.249",["Art. 1.249. As ilhas que se formarem em correntes comuns ou particulares pertencem aos proprietários ribeirinhos fronteiros, observadas as regras seguintes:","I - as que se formarem no meio do rio consideram-se acréscimos sobrevindos aos terrenos ribeirinhos fronteiros de ambas as margens, na proporção de suas testadas, até a linha que dividir o álveo em duas partes iguais;","II - as que se formarem entre a referida linha e uma das margens consideram-se acréscimos aos terrenos ribeirinhos fronteiros desse mesmo lado;","III - as que se formarem pelo desdobramento de um novo braço do rio continuam a pertencer aos proprietários dos terrenos à custa dos quais se constituíram."]],["CC, art. 1.250",["Art. 1.250. Os acréscimos formados, sucessiva e imperceptivelmente, por depósitos e aterros naturais ao longo das margens das correntes, ou pelo desvio das águas destas, pertencem aos donos dos terrenos marginais, sem indenização.","Parágrafo único. O terreno aluvial, que se formar em frente de prédios de proprietários diferentes, dividir-se-á entre eles, na proporção da testada de cada um sobre a antiga margem."]],["CC, art. 1.251",["Art. 1.251. Quando, por força natural violenta, uma porção de terra se destacar de um prédio e se juntar a outro, o dono deste adquirirá a propriedade do acréscimo, se indenizar o dono do primeiro ou, sem indenização, se, em um ano, ninguém houver reclamado.","Parágrafo único. Recusando-se ao pagamento de indenização, o dono do prédio a que se juntou a porção de terra deverá aquiescer a que se remova a parte acrescida."]],["CC, art. 1.252",["Art. 1.252. O álveo abandonado de corrente pertence aos proprietários ribeirinhos das duas margens, sem que tenham indenização os donos dos terrenos por onde as águas abrirem novo curso, entendendo-se que os prédios marginais se estendem até o meio do álveo."]],["CC, art. 1.253",["Art. 1.253. Toda construção ou plantação existente em um terreno presume-se feita pelo proprietário e à sua custa, até que se prove o contrário."]],["CC, art. 1.254",["Art. 1.254. Aquele que semeia, planta ou edifica em terreno próprio com sementes, plantas ou materiais alheios, adquire a propriedade destes; mas fica obrigado a pagar-lhes o valor, além de responder por perdas e danos, se agiu de má-fé."]],["CC, art. 1.255",["Art. 1.255. Aquele que semeia, planta ou edifica em terreno alheio perde, em proveito do proprietário, as sementes, plantas e construções; se procedeu de boa-fé, terá direito a indenização.","Parágrafo único. Se a construção ou a plantação exceder consideravelmente o valor do terreno, aquele que, de boa-fé, plantou ou edificou, adquirirá a propriedade do solo, mediante pagamento da indenização fixada judicialmente, se não houver acordo."]],["CC, art. 1.256",["Art. 1.256. Se de ambas as partes houve má-fé, adquirirá o proprietário as sementes, plantas e construções, devendo ressarcir o valor das acessões.","Parágrafo único. Presume-se má-fé no proprietário, quando o trabalho de construção, ou lavoura, se fez em sua presença e sem impugnação sua."]],["CC, art. 1.257",["Art. 1.257. O disposto no artigo antecedente aplica-se ao caso de não pertencerem as sementes, plantas ou materiais a quem de boa-fé os empregou em solo alheio.","Parágrafo único. O proprietário das sementes, plantas ou materiais poderá cobrar do proprietário do solo a indenização devida, quando não puder havê-la do plantador ou construtor."]],["CC, art. 1.258",["Art. 1.258. Se a construção, feita parcialmente em solo próprio, invade solo alheio em proporção não superior à vigésima parte deste, adquire o construtor de boa-fé a propriedade da parte do solo invadido, se o valor da construção exceder o dessa parte, e responde por indenização que represente, também, o valor da área perdida e a desvalorização da área remanescente.","Parágrafo único. Pagando em décuplo as perdas e danos previstos neste artigo, o construtor de má-fé adquire a propriedade da parte do solo que invadiu, se em proporção à vigésima parte deste e o valor da construção exceder consideravelmente o dessa parte e não se puder demolir a porção invasora sem grave prejuízo para a construção."]],["CC, art. 1.259",["Art. 1.259. Se o construtor estiver de boa-fé, e a invasão do solo alheio exceder a vigésima parte deste, adquire a propriedade da parte do solo invadido, e responde por perdas e danos que abranjam o valor que a invasão acrescer à construção, mais o da área perdida e o da desvalorização da área remanescente; se de má-fé, é obrigado a demolir o que nele construiu, pagando as perdas e danos apurados, que serão devidos em dobro."]]],"4":[["CC, art. 1.260",["Art. 1.260. Aquele que possuir coisa móvel como sua, contínua e incontestadamente durante três anos, com justo título e boa-fé, adquirir-lhe-á a propriedade."]],["CC, art. 1.261",["Art. 1.261. Se a posse da coisa móvel se prolongar por cinco anos, produzirá usucapião, independentemente de título ou boa-fé."]],["CC, art. 1.262",["Art. 1.262. Aplica-se à usucapião das coisas móveis o disposto nos arts. 1.243 e 1.244."]],["CC, art. 1.263",["Art. 1.263. Quem se assenhorear de coisa sem dono para logo lhe adquire a propriedade, não sendo essa ocupação defesa por lei."]],["CC, art. 1.264",["Art. 1.264. O depósito antigo de coisas preciosas, oculto e de cujo dono não haja memória, será dividido por igual entre o proprietário do prédio e o que achar o tesouro casualmente."]],["CC, art. 1.265",["Art. 1.265. O tesouro pertencerá por inteiro ao proprietário do prédio, se for achado por ele, ou em pesquisa que ordenou, ou por terceiro não autorizado."]],["CC, art. 1.266",["Art. 1.266. Achando-se em terreno aforado, o tesouro será dividido por igual entre o descobridor e o enfiteuta, ou será deste por inteiro quando ele mesmo seja o descobridor."]],["CC, art. 1.267",["Art. 1.267. A propriedade das coisas não se transfere pelos negócios jurídicos antes da tradição.","Parágrafo único. Subentende-se a tradição quando o transmitente continua a possuir pelo constituto possessório; quando cede ao adquirente o direito à restituição da coisa, que se encontra em poder de terceiro; ou quando o adquirente já está na posse da coisa, por ocasião do negócio jurídico."]],["CC, art. 1.268",["Art. 1.268. Feita por quem não seja proprietário, a tradição não aliena a propriedade, exceto se a coisa, oferecida ao público, em leilão ou estabelecimento comercial, for transferida em circunstâncias tais que, ao adquirente de boa-fé, como a qualquer pessoa, o alienante se afigurar dono.","§ 1º Se o adquirente estiver de boa-fé e o alienante adquirir depois a propriedade, considera-se realizada a transferência desde o momento em que ocorreu a tradição.","§ 2º Não transfere a propriedade a tradição, quando tiver por título um negócio jurídico nulo."]],["CC, art. 1.269",["Art. 1.269. Aquele que, trabalhando em matéria-prima em parte alheia, obtiver espécie nova, desta será proprietário, se não se puder restituir à forma anterior."]],["CC, art. 1.270",["Art. 1.270. Se toda a matéria for alheia, e não se puder reduzir à forma precedente, será do especificador de boa-fé a espécie nova.","§ 1º Sendo praticável a redução, ou quando impraticável, se a espécie nova se obteve de má-fé, pertencerá ao dono da matéria-prima.","§ 2º Em qualquer caso, inclusive o da pintura em relação à tela, da escultura, escritura e outro qualquer trabalho gráfico em relação à matéria-prima, a espécie nova será do especificador, se o seu valor exceder consideravelmente o da matéria-prima."]],["CC, art. 1.271",["Art. 1.271. Aos prejudicados, nas hipóteses dos arts. 1.269 e 1.270, se ressarcirá o dano que sofrerem, menos ao especificador de má-fé, no caso do § 1 o do artigo antecedente, quando irredutível a especificação."]],["CC, art. 1.272",["Art. 1.272. As coisas pertencentes a diversos donos, confundidas, misturadas ou adjuntadas sem o consentimento deles, continuam a pertencer-lhes, sendo possível separá-las sem deterioração.","§ 1º Não sendo possível a separação das coisas, ou exigindo dispêndio excessivo, subsiste indiviso o todo, cabendo a cada um dos donos quinhão proporcional ao valor da coisa com que entrou para a mistura ou agregado.","§ 2º Se uma das coisas puder considerar-se principal, o dono sê-lo-á do todo, indenizando os outros."]],["CC, art. 1.273",["Art. 1.273. Se a confusão, comissão ou adjunção se operou de má-fé, à outra parte caberá escolher entre adquirir a propriedade do todo, pagando o que não for seu, abatida a indenização que lhe for devida, ou renunciar ao que lhe pertencer, caso em que será indenizado."]],["CC, art. 1.274",["Art. 1.274. Se da união de matérias de natureza diversa se formar espécie nova, à confusão, comissão ou adjunção aplicam-se as normas dos arts. 1.272 e 1.273."]]],"5":[["CC, art. 1.275",["Art. 1.275. Além das causas consideradas neste Código, perde-se a propriedade:","I - por alienação;","II - pela renúncia;","III - por abandono;","IV - por perecimento da coisa;","V - por desapropriação.","Parágrafo único. Nos casos dos incisos I e II, os efeitos da perda da propriedade imóvel serão subordinados ao registro do título transmissivo ou do ato renunciativo no Registro de Imóveis."]],["CC, art. 1.276",["Art. 1.276. O imóvel urbano que o proprietário abandonar, com a intenção de não mais o conservar em seu patrimônio, e que se não encontrar na posse de outrem, poderá ser arrecadado, como bem vago, e passar, três anos depois, à propriedade do Município ou à do Distrito Federal, se se achar nas respectivas circunscrições.","§ 1º O imóvel situado na zona rural, abandonado nas mesmas circunstâncias, poderá ser arrecadado, como bem vago, e passar, três anos depois, à propriedade da União, onde quer que ele se localize.","§ 2º Presumir-se-á de modo absoluto a intenção a que se refere este artigo, quando, cessados os atos de posse, deixar o proprietário de satisfazer os ônus fiscais."]]],"6":[["CC, art. 1.277",["Art. 1.277. O proprietário ou o possuidor de um prédio tem o direito de fazer cessar as interferências prejudiciais à segurança, ao sossego e à saúde dos que o habitam, provocadas pela utilização de propriedade vizinha.","Parágrafo único. Proíbem-se as interferências considerando-se a natureza da utilização, a localização do prédio, atendidas as normas que distribuem as edificações em zonas, e os limites ordinários de tolerância dos moradores da vizinhança."]],["CC, art. 1.278",["Art. 1.278. O direito a que se refere o artigo antecedente não prevalece quando as interferências forem justificadas por interesse público, caso em que o proprietário ou o possuidor, causador delas, pagará ao vizinho indenização cabal."]],["CC, art. 1.279",["Art. 1.279. Ainda que por decisão judicial devam ser toleradas as interferências, poderá o vizinho exigir a sua redução, ou eliminação, quando estas se tornarem possíveis."]],["CC, art. 1.280",["Art. 1.280. O proprietário ou o possuidor tem direito a exigir do dono do prédio vizinho a demolição, ou a reparação deste, quando ameace ruína, bem como que lhe preste caução pelo dano iminente."]],["CC, art. 1.281",["Art. 1.281. O proprietário ou o possuidor de um prédio, em que alguém tenha direito de fazer obras, pode, no caso de dano iminente, exigir do autor delas as necessárias garantias contra o prejuízo eventual."]]],"7":[["CC, art. 1.282",["Art. 1.282. A árvore, cujo tronco estiver na linha divisória, presume-se pertencer em comum aos donos dos prédios confinantes."]],["CC, art. 1.283",["Art. 1.283. As raízes e os ramos de árvore, que ultrapassarem a estrema do prédio, poderão ser cortados, até o plano vertical divisório, pelo proprietário do terreno invadido."]],["CC, art. 1.284",["Art. 1.284. Os frutos caídos de árvore do terreno vizinho pertencem ao dono do solo onde caíram, se este for de propriedade particular."]],["CC, art. 1.285",["Art. 1.285. O dono do prédio que não tiver acesso a via pública, nascente ou porto, pode, mediante pagamento de indenização cabal, constranger o vizinho a lhe dar passagem, cujo rumo será judicialmente fixado, se necessário.","§ 1º Sofrerá o constrangimento o vizinho cujo imóvel mais natural e facilmente se prestar à passagem.","§ 2º Se ocorrer alienação parcial do prédio, de modo que uma das partes perca o acesso a via pública, nascente ou porto, o proprietário da outra deve tolerar a passagem.","§ 3º Aplica-se o disposto no parágrafo antecedente ainda quando, antes da alienação, existia passagem através de imóvel vizinho, não estando o proprietário deste constrangido, depois, a dar uma outra."]],["CC, art. 1.286",["Art. 1.286. Mediante recebimento de indenização que atenda, também, à desvalorização da área remanescente, o proprietário é obrigado a tolerar a passagem, através de seu imóvel, de cabos, tubulações e outros condutos subterrâneos de serviços de utilidade pública, em proveito de proprietários vizinhos, quando de outro modo for impossível ou excessivamente onerosa.","Parágrafo único. O proprietário prejudicado pode exigir que a instalação seja feita de modo menos gravoso ao prédio onerado, bem como, depois, seja removida, à sua custa, para outro local do imóvel."]],["CC, art. 1.287",["Art. 1.287. Se as instalações oferecerem grave risco, será facultado ao proprietário do prédio onerado exigir a realização de obras de segurança."]],["CC, art. 1.288",["Art. 1.288. O dono ou o possuidor do prédio inferior é obrigado a receber as águas que correm naturalmente do superior, não podendo realizar obras que embaracem o seu fluxo; porém a condição natural e anterior do prédio inferior não pode ser agravada por obras feitas pelo dono ou possuidor do prédio superior."]],["CC, art. 1.289",["Art. 1.289. Quando as águas, artificialmente levadas ao prédio superior, ou aí colhidas, correrem dele para o inferior, poderá o dono deste reclamar que se desviem, ou se lhe indenize o prejuízo que sofrer.","Parágrafo único. Da indenização será deduzido o valor do benefício obtido."]],["CC, art. 1.290",["Art. 1.290. O proprietário de nascente, ou do solo onde caem águas pluviais, satisfeitas as necessidades de seu consumo, não pode impedir, ou desviar o curso natural das águas remanescentes pelos prédios inferiores."]],["CC, art. 1.291",["Art. 1.291. O possuidor do imóvel superior não poderá poluir as águas indispensáveis às primeiras necessidades da vida dos possuidores dos imóveis inferiores; as demais, que poluir, deverá recuperar, ressarcindo os danos que estes sofrerem, se não for possível a recuperação ou o desvio do curso artificial das águas."]],["CC, art. 1.292",["Art. 1.292. O proprietário tem direito de construir barragens, açudes, ou outras obras para represamento de água em seu prédio; se as águas represadas invadirem prédio alheio, será o seu proprietário indenizado pelo dano sofrido, deduzido o valor do benefício obtido."]],["CC, art. 1.293",["Art. 1.293. É permitido a quem quer que seja, mediante prévia indenização aos proprietários prejudicados, construir canais, através de prédios alheios, para receber as águas a que tenha direito, indispensáveis às primeiras necessidades da vida, e, desde que não cause prejuízo considerável à agricultura e à indústria, bem como para o escoamento de águas supérfluas ou acumuladas, ou a drenagem de terrenos.","§ 1º Ao proprietário prejudicado, em tal caso, também assiste direito a ressarcimento pelos danos que de futuro lhe advenham da infiltração ou irrupção das águas, bem como da deterioração das obras destinadas a canalizá-las.","§ 2º O proprietário prejudicado poderá exigir que seja subterrânea a canalização que atravessa áreas edificadas, pátios, hortas, jardins ou quintais.","§ 3º O aqueduto será construído de maneira que cause o menor prejuízo aos proprietários dos imóveis vizinhos, e a expensas do seu dono, a quem incumbem também as despesas de conservação."]],["CC, art. 1.294",["Art. 1.294. Aplica-se ao direito de aqueduto o disposto nos arts. 1.286 e 1.287."]],["CC, art. 1.295",["Art. 1.295. O aqueduto não impedirá que os proprietários cerquem os imóveis e construam sobre ele, sem prejuízo para a sua segurança e conservação; os proprietários dos imóveis poderão usar das águas do aqueduto para as primeiras necessidades da vida."]],["CC, art. 1.296",["Art. 1.296. Havendo no aqueduto águas supérfluas, outros poderão canalizá-las, para os fins previstos no art. 1.293, mediante pagamento de indenização aos proprietários prejudicados e ao dono do aqueduto, de importância equivalente às despesas que então seriam necessárias para a condução das águas até o ponto de derivação.","Parágrafo único. Têm preferência os proprietários dos imóveis atravessados pelo aqueduto."]]],"8":[["CC, art. 1.297",["Art. 1.297. O proprietário tem direito a cercar, murar, valar ou tapar de qualquer modo o seu prédio, urbano ou rural, e pode constranger o seu confinante a proceder com ele à demarcação entre os dois prédios, a aviventar rumos apagados e a renovar marcos destruídos ou arruinados, repartindo-se proporcionalmente entre os interessados as respectivas despesas.","§ 1º Os intervalos, muros, cercas e os tapumes divisórios, tais como sebes vivas, cercas de arame ou de madeira, valas ou banquetas, presumem-se, até prova em contrário, pertencer a ambos os proprietários confinantes, sendo estes obrigados, de conformidade com os costumes da localidade, a concorrer, em partes iguais, para as despesas de sua construção e conservação.","§ 2º As sebes vivas, as árvores, ou plantas quaisquer, que servem de marco divisório, só podem ser cortadas, ou arrancadas, de comum acordo entre proprietários.","§ 3º A construção de tapumes especiais para impedir a passagem de animais de pequeno porte, ou para outro fim, pode ser exigida de quem provocou a necessidade deles, pelo proprietário, que não está obrigado a concorrer para as despesas."]],["CC, art. 1.298",["Art. 1.298. Sendo confusos, os limites, em falta de outro meio, se determinarão de conformidade com a posse justa; e, não se achando ela provada, o terreno contestado se dividirá por partes iguais entre os prédios, ou, não sendo possível a divisão cômoda, se adjudicará a um deles, mediante indenização ao outro."]],["CC, art. 1.299",["Art. 1.299. O proprietário pode levantar em seu terreno as construções que lhe aprouver, salvo o direito dos vizinhos e os regulamentos administrativos."]],["CC, art. 1.300",["Art. 1.300. O proprietário construirá de maneira que o seu prédio não despeje águas, diretamente, sobre o prédio vizinho."]],["CC, art. 1.301",["Art. 1.301. É defeso abrir janelas, ou fazer eirado, terraço ou varanda, a menos de metro e meio do terreno vizinho.","§ 1º As janelas cuja visão não incida sobre a linha divisória, bem como as perpendiculares, não poderão ser abertas a menos de setenta e cinco centímetros.","§ 2º As disposições deste artigo não abrangem as aberturas para luz ou ventilação, não maiores de dez centímetros de largura sobre vinte de comprimento e construídas a mais de dois metros de altura de cada piso."]],["CC, art. 1.302",["Art. 1.302. O proprietário pode, no lapso de ano e dia após a conclusão da obra, exigir que se desfaça janela, sacada, terraço ou goteira sobre o seu prédio; escoado o prazo, não poderá, por sua vez, edificar sem atender ao disposto no artigo antecedente, nem impedir, ou dificultar, o escoamento das águas da goteira, com prejuízo para o prédio vizinho.","Parágrafo único. Em se tratando de vãos, ou aberturas para luz, seja qual for a quantidade, altura e disposição, o vizinho poderá, a todo tempo, levantar a sua edificação, ou contramuro, ainda que lhes vede a claridade."]],["CC, art. 1.303",["Art. 1.303. Na zona rural, não será permitido levantar edificações a menos de três metros do terreno vizinho."]],["CC, art. 1.304",["Art. 1.304. Nas cidades, vilas e povoados cuja edificação estiver adstrita a alinhamento, o dono de um terreno pode nele edificar, madeirando na parede divisória do prédio contíguo, se ela suportar a nova construção; mas terá de embolsar ao vizinho metade do valor da parede e do chão correspondentes."]],["CC, art. 1.305",["Art. 1.305. O confinante, que primeiro construir, pode assentar a parede divisória até meia espessura no terreno contíguo, sem perder por isso o direito a haver meio valor dela se o vizinho a travejar, caso em que o primeiro fixará a largura e a profundidade do alicerce.","Parágrafo único. Se a parede divisória pertencer a um dos vizinhos, e não tiver capacidade para ser travejada pelo outro, não poderá este fazer-lhe alicerce ao pé sem prestar caução àquele, pelo risco a que expõe a construção anterior."]],["CC, art. 1.306",["Art. 1.306. O condômino da parede-meia pode utilizá-la até ao meio da espessura, não pondo em risco a segurança ou a separação dos dois prédios, e avisando previamente o outro condômino das obras que ali tenciona fazer; não pode sem consentimento do outro, fazer, na parede-meia, armários, ou obras semelhantes, correspondendo a outras, da mesma natureza, já feitas do lado oposto."]],["CC, art. 1.307",["Art. 1.307. Qualquer dos confinantes pode altear a parede divisória, se necessário reconstruindo-a, para suportar o alteamento; arcará com todas as despesas, inclusive de conservação, ou com metade, se o vizinho adquirir meação também na parte aumentada."]],["CC, art. 1.308",["Art. 1.308. Não é lícito encostar à parede divisória chaminés, fogões, fornos ou quaisquer aparelhos ou depósitos suscetíveis de produzir infiltrações ou interferências prejudiciais ao vizinho.","Parágrafo único. A disposição anterior não abrange as chaminés ordinárias e os fogões de cozinha."]],["CC, art. 1.309",["Art. 1.309. São proibidas construções capazes de poluir, ou inutilizar, para uso ordinário, a água do poço, ou nascente alheia, a elas preexistentes."]],["CC, art. 1.310",["Art. 1.310. Não é permitido fazer escavações ou quaisquer obras que tirem ao poço ou à nascente de outrem a água indispensável às suas necessidades normais."]],["CC, art. 1.311",["Art. 1.311. Não é permitida a execução de qualquer obra ou serviço suscetível de provocar desmoronamento ou deslocação de terra, ou que comprometa a segurança do prédio vizinho, senão após haverem sido feitas as obras acautelatórias.","Parágrafo único. O proprietário do prédio vizinho tem direito a ressarcimento pelos prejuízos que sofrer, não obstante haverem sido realizadas as obras acautelatórias."]],["CC, art. 1.312",["Art. 1.312. Todo aquele que violar as proibições estabelecidas nesta Seção é obrigado a demolir as construções feitas, respondendo por perdas e danos."]],["CC, art. 1.313",["Art. 1.313. O proprietário ou ocupante do imóvel é obrigado a tolerar que o vizinho entre no prédio, mediante prévio aviso, para:","I - dele temporariamente usar, quando indispensável à reparação, construção, reconstrução ou limpeza de sua casa ou do muro divisório;","II - apoderar-se de coisas suas, inclusive animais que aí se encontrem casualmente.","§ 1º O disposto neste artigo aplica-se aos casos de limpeza ou reparação de esgotos, goteiras, aparelhos higiênicos, poços e nascentes e ao aparo de cerca viva.","§ 2º Na hipótese do inciso II, uma vez entregues as coisas buscadas pelo vizinho, poderá ser impedida a sua entrada no imóvel.","§ 3º Se do exercício do direito assegurado neste artigo provier dano, terá o prejudicado direito a ressarcimento."]]],"9":[["CC, art. 1.314",["Art. 1.314. Cada condômino pode usar da coisa conforme sua destinação, sobre ela exercer todos os direitos compatíveis com a indivisão, reivindicá-la de terceiro, defender a sua posse e alhear a respectiva parte ideal, ou gravá-la.","Parágrafo único. Nenhum dos condôminos pode alterar a destinação da coisa comum, nem dar posse, uso ou gozo dela a estranhos, sem o consenso dos outros."]],["CC, art. 1.315",["Art. 1.315. O condômino é obrigado, na proporção de sua parte, a concorrer para as despesas de conservação ou divisão da coisa, e a suportar os ônus a que estiver sujeita.","Parágrafo único. Presumem-se iguais as partes ideais dos condôminos."]],["CC, art. 1.316",["Art. 1.316. Pode o condômino eximir-se do pagamento das despesas e dívidas, renunciando à parte ideal.","§ 1º Se os demais condôminos assumem as despesas e as dívidas, a renúncia lhes aproveita, adquirindo a parte ideal de quem renunciou, na proporção dos pagamentos que fizerem.","§ 2º Se não há condômino que faça os pagamentos, a coisa comum será dividida."]],["CC, art. 1.317",["Art. 1.317. Quando a dívida houver sido contraída por todos os condôminos, sem se discriminar a parte de cada um na obrigação, nem se estipular solidariedade, entende-se que cada qual se obrigou proporcionalmente ao seu quinhão na coisa comum."]],["CC, art. 1.318",["Art. 1.318. As dívidas contraídas por um dos condôminos em proveito da comunhão, e durante ela, obrigam o contratante; mas terá este ação regressiva contra os demais."]],["CC, art. 1.319",["Art. 1.319. Cada condômino responde aos outros pelos frutos que percebeu da coisa e pelo dano que lhe causou."]],["CC, art. 1.320",["Art. 1.320. A todo tempo será lícito ao condômino exigir a divisão da coisa comum, respondendo o quinhão de cada um pela sua parte nas despesas da divisão.","§ 1º Podem os condôminos acordar que fique indivisa a coisa comum por prazo não maior de cinco anos, suscetível de prorrogação ulterior.","§ 2º Não poderá exceder de cinco anos a indivisão estabelecida pelo doador ou pelo testador.","§ 3º A requerimento de qualquer interessado e se graves razões o aconselharem, pode o juiz determinar a divisão da coisa comum antes do prazo."]],["CC, art. 1.321",["Art. 1.321. Aplicam-se à divisão do condomínio, no que couber, as regras de partilha de herança (arts. 2.013 a 2.022)."]],["CC, art. 1.322",["Art. 1.322. Quando a coisa for indivisível, e os consortes não quiserem adjudicá-la a um só, indenizando os outros, será vendida e repartido o apurado, preferindo-se, na venda, em condições iguais de oferta, o condômino ao estranho, e entre os condôminos aquele que tiver na coisa benfeitorias mais valiosas, e, não as havendo, o de quinhão maior.","Parágrafo único. Se nenhum dos condôminos tem benfeitorias na coisa comum e participam todos do condomínio em partes iguais, realizar-se-á licitação entre estranhos e, antes de adjudicada a coisa àquele que ofereceu maior lanço, proceder-se-á à licitação entre os condôminos, a fim de que a coisa seja adjudicada a quem afinal oferecer melhor lanço, preferindo, em condições iguais, o condômino ao estranho."]],["CC, art. 1.323",["Art. 1.323. Deliberando a maioria sobre a administração da coisa comum, escolherá o administrador, que poderá ser estranho ao condomínio; resolvendo alugá-la, preferir-se-á, em condições iguais, o condômino ao que não o é."]],["CC, art. 1.324",["Art. 1.324. O condômino que administrar sem oposição dos outros presume-se representante comum."]],["CC, art. 1.325",["Art. 1.325. A maioria será calculada pelo valor dos quinhões.","§ 1º As deliberações serão obrigatórias, sendo tomadas por maioria absoluta.","§ 2º Não sendo possível alcançar maioria absoluta, decidirá o juiz, a requerimento de qualquer condômino, ouvidos os outros.","§ 3º Havendo dúvida quanto ao valor do quinhão, será este avaliado judicialmente."]],["CC, art. 1.326",["Art. 1.326. Os frutos da coisa comum, não havendo em contrário estipulação ou disposição de última vontade, serão partilhados na proporção dos quinhões."]],["CC, art. 1.327",["Art. 1.327. O condomínio por meação de paredes, cercas, muros e valas regula-se pelo disposto neste Código (arts. 1.297 e 1.298; 1.304 a 1.307)."]],["CC, art. 1.328",["Art. 1.328. O proprietário que tiver direito a estremar um imóvel com paredes, cercas, muros, valas ou valados, tê-lo-á igualmente a adquirir meação na parede, muro, valado ou cerca do vizinho, embolsando-lhe metade do que atualmente valer a obra e o terreno por ela ocupado (art. 1.297)."]],["CC, art. 1.329",["Art. 1.329. Não convindo os dois no preço da obra, será este arbitrado por peritos, a expensas de ambos os confinantes."]],["CC, art. 1.330",["Art. 1.330. Qualquer que seja o valor da meação, enquanto aquele que pretender a divisão não o pagar ou depositar, nenhum uso poderá fazer na parede, muro, vala, cerca ou qualquer outra obra divisória."]]],"11":[["CC, art. 1.341",["Art. 1.341. A realização de obras no condomínio depende:","I - se voluptuárias, de voto de dois terços dos condôminos;","II - se úteis, de voto da maioria dos condôminos.","§ 1º As obras ou reparações necessárias podem ser realizadas, independentemente de autorização, pelo síndico, ou, em caso de omissão ou impedimento deste, por qualquer condômino.","§ 2º Se as obras ou reparos necessários forem urgentes e importarem em despesas excessivas, determinada sua realização, o síndico ou o condômino que tomou a iniciativa delas dará ciência à assembléia, que deverá ser convocada imediatamente.","§ 3º Não sendo urgentes, as obras ou reparos necessários, que importarem em despesas excessivas, somente poderão ser efetuadas após autorização da assembléia, especialmente convocada pelo síndico, ou, em caso de omissão ou impedimento deste, por qualquer dos condôminos.","§ 4º O condômino que realizar obras ou reparos necessários será reembolsado das despesas que efetuar, não tendo direito à restituição das que fizer com obras ou reparos de outra natureza, embora de interesse comum."]],["CC, art. 1.342",["Art. 1.342. A realização de obras, em partes comuns, em acréscimo às já existentes, a fim de lhes facilitar ou aumentar a utilização, depende da aprovação de dois terços dos votos dos condôminos, não sendo permitidas construções, nas partes comuns, suscetíveis de prejudicar a utilização, por qualquer dos condôminos, das partes próprias, ou comuns."]],["CC, art. 1.343",["Art. 1.343. A construção de outro pavimento, ou, no solo comum, de outro edifício, destinado a conter novas unidades imobiliárias, depende da aprovação da unanimidade dos condôminos."]],["CC, art. 1.344",["Art. 1.344. Ao proprietário do terraço de cobertura incumbem as despesas da sua conservação, de modo que não haja danos às unidades imobiliárias inferiores."]],["CC, art. 1.345",["Art. 1.345. O adquirente de unidade responde pelos débitos do alienante, em relação ao condomínio, inclusive multas e juros moratórios."]],["CC, art. 1.346",["Art. 1.346. É obrigatório o seguro de toda a edificação contra o risco de incêndio ou destruição, total ou parcial."]],["CC, art. 1.347",["Art. 1.347. A assembléia escolherá um síndico, que poderá não ser condômino, para administrar o condomínio, por prazo não superior a dois anos, o qual poderá renovar-se."]],["CC, art. 1.348",["Art. 1.348. Compete ao síndico:","I - convocar a assembléia dos condôminos;","II - representar, ativa e passivamente, o condomínio, praticando, em juízo ou fora dele, os atos necessários à defesa dos interesses comuns;","III - dar imediato conhecimento à assembléia da existência de procedimento judicial ou administrativo, de interesse do condomínio;","IV - cumprir e fazer cumprir a convenção, o regimento interno e as determinações da assembléia;","V - diligenciar a conservação e a guarda das partes comuns e zelar pela prestação dos serviços que interessem aos possuidores;","VI - elaborar o orçamento da receita e da despesa relativa a cada ano;","VII - cobrar dos condôminos as suas contribuições, bem como impor e cobrar as multas devidas;","VIII - prestar contas à assembléia, anualmente e quando exigidas;","IX - realizar o seguro da edificação.","§ 1º Poderá a assembléia investir outra pessoa, em lugar do síndico, em poderes de representação.","§ 2º O síndico pode transferir a outrem, total ou parcialmente, os poderes de representação ou as funções administrativas, mediante aprovação da assembléia, salvo disposição em contrário da convenção."]],["CC, art. 1.349",["Art. 1.349. A assembléia, especialmente convocada para o fim estabelecido no § 2 o do artigo antecedente, poderá, pelo voto da maioria absoluta de seus membros, destituir o síndico que praticar irregularidades, não prestar contas, ou não administrar convenientemente o condomínio."]],["CC, art. 1.350",["Art. 1.350. Convocará o síndico, anualmente, reunião da assembléia dos condôminos, na forma prevista na convenção, a fim de aprovar o orçamento das despesas, as contribuições dos condôminos e a prestação de contas, e eventualmente eleger-lhe o substituto e alterar o regimento interno.","§ 1º Se o síndico não convocar a assembléia, um quarto dos condôminos poderá fazê-lo.","§ 2º Se a assembléia não se reunir, o juiz decidirá, a requerimento de qualquer condômino."]],["CC, art. 1.351",["Art. 1.351. Depende da aprovação de 2/3 (dois terços) dos votos dos condôminos a alteração da convenção, bem como a mudança da destinação do edifício ou da unidade imobiliária. (Artigo com redação dada pela Lei nº 14.405, de 12/7/2022)"]],["CC, art. 1.352",["Art. 1.352. Salvo quando exigido quorum especial, as deliberações da assembléia serão tomadas, em primeira convocação, por maioria de votos dos condôminos presentes que representem pelo menos metade das frações ideais.","Parágrafo único. Os votos serão proporcionais às frações ideais no solo e nas outras partes comuns pertencentes a cada condômino, salvo disposição diversa da convenção de constituição do condomínio."]],["CC, art. 1.353",["Art. 1.353. Em segunda convocação, a assembléia poderá deliberar por maioria dos votos dos presentes, salvo quando exigido quorum especial.","§ 1º Quando a deliberação exigir quórum especial previsto em lei ou em convenção e ele não for atingido, a assembleia poderá, por decisão da maioria dos presentes, autorizar o presidente a converter a reunião em sessão permanente, desde que cumulativamente:","I - sejam indicadas a data e a hora da sessão em seguimento, que não poderá ultrapassar 60 (sessenta) dias, e identificadas as deliberações pretendidas, em razão do quórum especial não atingido;","II - fiquem expressamente convocados os presentes e sejam obrigatoriamente convocadas as unidades ausentes, na forma prevista em convenção;","III - seja lavrada ata parcial, relativa ao segmento presencial da reunião da assembleia, da qual deverão constar as transcrições circunstanciadas de todos os argumentos até então apresentados relativos à ordem do dia, que deverá ser remetida aos condôminos ausentes;","IV - seja dada continuidade às deliberações no dia e na hora designados, e seja a ata correspondente lavrada em seguimento à que estava parcialmente redigida, com a consolidação de todas as deliberações. (Parágrafo acrescido pela Lei nº 14.309, de 8/3/2022)","§ 2º Os votos consignados na primeira sessão ficarão registrados, sem que haja necessidade de comparecimento dos condôminos para sua confirmação, os quais poderão, se estiverem presentes no encontro seguinte, requerer a alteração do seu voto até o desfecho da deliberação pretendida. (Parágrafo acrescido pela Lei nº 14.309, de 8/3/2022)","§ 3º A sessão permanente poderá ser prorrogada tantas vezes quantas necessárias, desde que a assembleia seja concluída no prazo total de 90 (noventa) dias, contado da data de sua abertura inicial. (Parágrafo acrescido pela Lei nº 14.309, de 8/3/2022)"]],["CC, art. 1.354",["Art. 1.354. A assembléia não poderá deliberar se todos os condôminos não forem convocados para a reunião."]],["CC, art. 1.354-A",["Art. 1.354-A. A convocação, a realização e a deliberação de quaisquer modalidades de assembleia poderão dar-se de forma eletrônica, desde que:","I - tal possibilidade não seja vedada na convenção de condomínio;","II - sejam preservados aos condôminos os direitos de voz, de debate e de voto.","§ 1º Do instrumento de convocação deverá constar que a assembleia será realizada por meio eletrônico, bem como as instruções sobre acesso, manifestação e forma de coleta de votos dos condôminos.","§ 2º A administração do condomínio não poderá ser responsabilizada por problemas decorrentes dos equipamentos de informática ou da conexão à internet dos condôminos ou de seus representantes nem por quaisquer outras situações que não estejam sob o seu controle.","§ 3º Somente após a somatória de todos os votos e a sua divulgação será lavrada a respectiva ata, também eletrônica, e encerrada a assembleia geral.","§ 4º A assembleia eletrônica deverá obedecer aos preceitos de instalação, de funcionamento e de encerramento previstos no edital de convocação e poderá ser realizada de forma híbrida, com a presença física e virtual de condôminos concomitantemente no mesmo ato.","§ 5º Normas complementares relativas às assembleias eletrônicas poderão ser previstas no regimento interno do condomínio e definidas mediante aprovação da maioria simples dos presentes em assembleia convocada para essa finalidade.","§ 6º Os documentos pertinentes à ordem do dia poderão ser disponibilizados de forma física ou eletrônica aos participantes. (Artigo acrescido pela Lei nº 14.309, de 8/3/2022)"]],["CC, art. 1.355",["Art. 1.355. Assembléias extraordinárias poderão ser convocadas pelo síndico ou por um quarto dos condôminos."]]],"12":[["CC, art. 1.358-B",["Art. 1.358-B. A multipropriedade reger-se-á pelo disposto neste Capítulo e, de forma supletiva e subsidiária, pelas demais disposições deste Código e pelas disposições das Leis nºs 4.591, de 16 de dezembro de 1964, e 8.078, de 11 de setembro de 1990 (Código de Defesa do Consumidor). (Artigo acrescido pela Lei nº 13.777, de 20/12/2018, publicada no DOU de 21/12/2018, em vigor 45 dias após a publicação)"]],["CC, art. 1.358-C",["Art. 1.358-C. Multipropriedade é o regime de condomínio em que cada um dos proprietários de um mesmo imóvel é titular de uma fração de tempo, à qual corresponde a faculdade de uso e gozo, com exclusividade, da totalidade do imóvel, a ser exercida pelos proprietários de forma alternada.","Parágrafo único. A multipropriedade não se extinguirá automaticamente se todas as frações de tempo forem do mesmo multiproprietário. (Artigo acrescido pela Lei nº 13.777, de 20/12/2018, publicada no DOU de 21/12/2018, em vigor 45 dias após a publicação)"]],["CC, art. 1.358-D",["Art. 1.358-D. O imóvel objeto da multipropriedade:","I - é indivisível, não se sujeitando a ação de divisão ou de extinção de condomínio;","II - inclui as instalações, os equipamentos e o mobiliário destinados a seu uso e gozo. (Artigo acrescido pela Lei nº 13.777, de 20/12/2018, publicada no DOU de 21/12/2018, em vigor 45 dias após a publicação)"]],["CC, art. 1.358-E",["Art. 1.358-E. Cada fração de tempo é indivisível.","§ 1º O período correspondente a cada fração de tempo será de, no mínimo, 7 (sete) dias, seguidos ou intercalados, e poderá ser:","I - fixo e determinado, no mesmo período de cada ano;","II - flutuante, caso em que a determinação do período será realizada de forma periódica, mediante procedimento objetivo que respeite, em relação a todos os multiproprietários, o princípio da isonomia, devendo ser previamente divulgado; ou","III - misto, combinando os sistemas fixo e flutuante.","§ 2º Todos os multiproprietários terão direito a uma mesma quantidade mínima de dias seguidos durante o ano, podendo haver a aquisição de frações maiores que a mínima, com o correspondente direito ao uso por períodos também maiores. (Artigo acrescido pela Lei nº 13.777, de 20/12/2018, publicada no DOU de 21/12/2018, em vigor 45 dias após a publicação)"]],["CC, art. 1.358-F",["Art. 1.358-F. Institui-se a multipropriedade por ato entre vivos ou testamento, registrado no competente cartório de registro de imóveis, devendo constar daquele ato a duração dos períodos correspondentes a cada fração de tempo. (Artigo acrescido pela Lei nº 13.777, de 20/12/2018, publicada no DOU de 21/12/2018, em vigor 45 dias após a publicação)"]],["CC, art. 1.358-G",["Art. 1.358-G. Além das cláusulas que os multiproprietários decidirem estipular, a convenção de condomínio em multipropriedade determinará:","I - os poderes e deveres dos multiproprietários, especialmente em matéria de instalações, equipamentos e mobiliário do imóvel, de manutenção ordinária e extraordinária, de conservação e limpeza e de pagamento da contribuição condominial;","II - o número máximo de pessoas que podem ocupar simultaneamente o imóvel no período correspondente a cada fração de tempo;","III - as regras de acesso do administrador condominial ao imóvel para cumprimento do dever de manutenção, conservação e limpeza;","IV - a criação de fundo de reserva para reposição e manutenção dos equipamentos, instalações e mobiliário;","V - o regime aplicável em caso de perda ou destruição parcial ou total do imóvel, inclusive para efeitos de participação no risco ou no valor do seguro, da indenização ou da parte restante;","VI - as multas aplicáveis ao multiproprietário nas hipóteses de descumprimento de deveres. (Artigo acrescido pela Lei nº 13.777, de 20/12/2018, publicada no DOU de 21/12/2018, em vigor 45 dias após a publicação)"]],["CC, art. 1.358-H",["Art. 1.358-H. O instrumento de instituição da multipropriedade ou a convenção de condomínio em multipropriedade poderá estabelecer o limite máximo de frações de tempo no mesmo imóvel que poderão ser detidas pela mesma pessoa natural ou jurídica.","Parágrafo único. Em caso de instituição da multipropriedade para posterior venda das frações de tempo a terceiros, o atendimento a eventual limite de frações de tempo por titular estabelecido no instrumento de instituição será obrigatório somente após a venda das frações. (Artigo acrescido pela Lei nº 13.777, de 20/12/2018, publicada no DOU de 21/12/2018, em vigor 45 dias após a publicação)"]],["CC, art. 1.358-I",["Art. 1.358-I. São direitos do multiproprietário, além daqueles previstos no instrumento de instituição e na convenção de condomínio em multipropriedade:","I - usar e gozar, durante o período correspondente à sua fração de tempo, do imóvel e de suas instalações, equipamentos e mobiliário;","II - ceder a fração de tempo em locação ou comodato;","III - alienar a fração de tempo, por ato entre vivos ou por causa de morte, a título oneroso ou gratuito, ou onerá-la, devendo a alienação e a qualificação do sucessor, ou a oneração, ser informadas ao administrador;","IV - participar e votar, pessoalmente ou por intermédio de representante ou procurador, desde que esteja quite com as obrigações condominiais, em:","a) assembleia geral do condomínio em multipropriedade, e o voto do multiproprietário corresponderá à quota de sua fração de tempo no imóvel;","b) assembleia geral do condomínio edilício, quando for o caso, e o voto do multiproprietário corresponderá à quota de sua fração de tempo em relação à quota de poder político atribuído à unidade autônoma na respectiva convenção de condomínio edilício. (Artigo acrescido pela Lei nº 13.777, de 20/12/2018, publicada no DOU de 21/12/2018, em vigor 45 dias após a publicação)"]],["CC, art. 1.358-J",["Art. 1.358-J. São obrigações do multiproprietário, além daquelas previstas no instrumento de instituição e na convenção de condomínio em multipropriedade:","I - pagar a contribuição condominial do condomínio em multipropriedade e, quando for o caso, do condomínio edilício, ainda que renuncie ao uso e gozo, total ou parcial, do imóvel, das áreas comuns ou das respectivas instalações, equipamentos e mobiliário;","II - responder por danos causados ao imóvel, às instalações, aos equipamentos e ao mobiliário por si, por qualquer de seus acompanhantes, convidados ou prepostos ou por pessoas por ele autorizadas;","III - comunicar imediatamente ao administrador os defeitos, avarias e vícios no imóvel dos quais tiver ciência durante a utilização;","IV - não modificar, alterar ou substituir o mobiliário, os equipamentos e as instalações do imóvel;","V - manter o imóvel em estado de conservação e limpeza condizente com os fins a que se destina e com a natureza da respectiva construção;","VI - usar o imóvel, bem como suas instalações, equipamentos e mobiliário, conforme seu destino e natureza;","VII - usar o imóvel exclusivamente durante o período correspondente à sua fração de tempo;","VIII - desocupar o imóvel, impreterivelmente, até o dia e hora fixados no instrumento de instituição ou na convenção de condomínio em multipropriedade, sob pena de multa diária, conforme convencionado no instrumento pertinente;","IX - permitir a realização de obras ou reparos urgentes.","§ 1º Conforme previsão que deverá constar da respectiva convenção de condomínio em multipropriedade, o multiproprietário estará sujeito a:","I - multa, no caso de descumprimento de qualquer de seus deveres;","II - multa progressiva e perda temporária do direito de utilização do imóvel no período correspondente à sua fração de tempo, no caso de descumprimento reiterado de deveres.","§ 2º A responsabilidade pelas despesas referentes a reparos no imóvel, bem como suas instalações, equipamentos e mobiliário, será:","I - de todos os multiproprietários, quando decorrentes do uso normal e do desgaste natural do imóvel;","II - exclusivamente do multiproprietário responsável pelo uso anormal, sem prejuízo de multa, quando decorrentes de uso anormal do imóvel.","§ 3º (VETADO na Lei nº 13.777, de 20/12/2018)","§ 4º (VETADO na Lei nº 13.777, de 20/12/2018)","§ 5º (VETADO na Lei nº 13.777, de 20/12/2018) (Artigo acrescido pela Lei nº 13.777, de 20/12/2018, publicada no DOU de 21/12/2018, em vigor 45 dias após a publicação)"]],["CC, art. 1.358-K",["Art. 1.358-K. Para os efeitos do disposto nesta Seção, são equiparados aos multiproprietários os promitentes compradores e os cessionários de direitos relativos a cada fração de tempo. (Artigo acrescido pela Lei nº 13.777, de 20/12/2018, publicada no DOU de 21/12/2018, em vigor 45 dias após a publicação)"]],["CC, art. 1.358-L",["Art. 1.358-L. A transferência do direito de multipropriedade e a sua produção de efeitos perante terceiros dar-se-ão na forma da lei civil e não dependerão da anuência ou cientificação dos demais multiproprietários.","§ 1º Não haverá direito de preferência na alienação de fração de tempo, salvo se estabelecido no instrumento de instituição ou na convenção do condomínio em multipropriedade em favor dos demais multiproprietários ou do instituidor do condomínio em multipropriedade.","§ 2º O adquirente será solidariamente responsável com o alienante pelas obrigações de que trata o § 5º do art. 1.358-J deste Código caso não obtenha a declaração de inexistência de débitos referente à fração de tempo no momento de sua aquisição. (Artigo acrescido pela Lei nº 13.777, de 20/12/2018, publicada no DOU de 21/12/2018, em vigor 45 dias após a publicação)"]],["CC, art. 1.358-M",["Art. 1.358-M. A administração do imóvel e de suas instalações, equipamentos e mobiliário será de responsabilidade da pessoa indicada no instrumento de instituição ou na convenção de condomínio em multipropriedade, ou, na falta de indicação, de pessoa escolhida em assembleia geral dos condôminos.","§ 1º O administrador exercerá, além daquelas previstas no instrumento de instituição e na convenção de condomínio em multipropriedade, as seguintes atribuições:","I - coordenação da utilização do imóvel pelos multiproprietários durante o período correspondente a suas respectivas frações de tempo;","II - determinação, no caso dos sistemas flutuante ou misto, dos períodos concretos de uso e gozo exclusivos de cada multiproprietário em cada ano;","III - manutenção, conservação e limpeza do imóvel;","IV - troca ou substituição de instalações, equipamentos ou mobiliário, inclusive:","a) determinar a necessidade da troca ou substituição;","b) providenciar os orçamentos necessários para a troca ou substituição;","c) submeter os orçamentos à aprovação pela maioria simples dos condôminos em assembleia;","V - elaboração do orçamento anual, com previsão das receitas e despesas;","VI - cobrança das quotas de custeio de responsabilidade dos multiproprietários;","VII - pagamento, por conta do condomínio edilício ou voluntário, com os fundos comuns arrecadados, de todas as despesas comuns.","§ 2º A convenção de condomínio em multipropriedade poderá regrar de forma diversa a atribuição prevista no inciso IV do § 1º deste artigo. (Artigo acrescido pela Lei nº 13.777, de 20/12/2018, publicada no DOU de 21/12/2018, em vigor 45 dias após a publicação)"]],["CC, art. 1.358-N",["Art. 1.358-N. O instrumento de instituição poderá prever fração de tempo destinada à realização, no imóvel e em suas instalações, em seus equipamentos e em seu mobiliário, de reparos indispensáveis ao exercício normal do direito de multipropriedade.","§ 1º A fração de tempo de que trata o caput deste artigo poderá ser atribuída:","I - ao instituidor da multipropriedade; ou","II - aos multiproprietários, proporcionalmente às respectivas frações.","§ 2º Em caso de emergência, os reparos de que trata o caput deste artigo poderão ser feitos durante o período correspondente à fração de tempo de um dos multiproprietários. (Artigo acrescido pela Lei nº 13.777, de 20/12/2018, publicada no DOU de 21/12/2018, em vigor 45 dias após a publicação)"]],["CC, art. 1.358-O",["Art. 1.358-O. condomínio edilício poderá adotar o regime de multipropriedade em parte ou na totalidade de suas unidades autônomas, mediante:","I - previsão no instrumento de instituição; ou","II - deliberação da maioria absoluta dos condôminos.","Parágrafo único. No caso previsto no inciso I do caput deste artigo, a iniciativa e a responsabilidade para a instituição do regime da multipropriedade serão atribuídas às mesmas pessoas e observarão os mesmos requisitos indicados nas alíneas a , b e c e no § 1º do art. 31 da Lei nº 4.591, de 16 de dezembro de 1964. (Artigo acrescido pela Lei nº 13.777, de 20/12/2018, publicada no DOU de 21/12/2018, em vigor 45 dias após a publicação)"]],["CC, art. 1.358-P",["Art. 1.358-P. Na hipótese do art. 1.358-O, a convenção de condomínio edilício deve prever, além das matérias elencadas nos arts. 1.332, 1.334 e, se for o caso, 1.358-G deste Código:","I - a identificação das unidades sujeitas ao regime da multipropriedade, no caso de empreendimentos mistos;","II - a indicação da duração das frações de tempo de cada unidade autônoma sujeita ao regime da multipropriedade;","III - a forma de rateio, entre os multiproprietários de uma mesma unidade autônoma, das contribuições condominiais relativas à unidade, que, salvo se disciplinada de forma diversa no instrumento de instituição ou na convenção de condomínio em multipropriedade, será proporcional à fração de tempo de cada multiproprietário;","IV - a especificação das despesas ordinárias, cujo custeio será obrigatório, independentemente do uso e gozo do imóvel e das áreas comuns;","V - os órgãos de administração da multipropriedade;","VI - a indicação, se for o caso, de que o empreendimento conta com sistema de administração de intercâmbio, na forma prevista no § 2º do art. 23 da Lei nº 11.771, de 17 de setembro de 2008, seja do período de fruição da fração de tempo, seja do local de fruição, caso em que a responsabilidade e as obrigações da companhia de intercâmbio limitam-se ao contido na documentação de sua contratação;","VII - a competência para a imposição de sanções e o respectivo procedimento, especialmente nos casos de mora no cumprimento das obrigações de custeio e nos casos de descumprimento da obrigação de desocupar o imóvel até o dia e hora previstos;","VIII - o quórum exigido para a deliberação de adjudicação da fração de tempo na hipótese de inadimplemento do respectivo multiproprietário;","IX - o quórum exigido para a deliberação de alienação, pelo condomínio edilício, da fração de tempo adjudicada em virtude do inadimplemento do respectivo multiproprietário. (Artigo acrescido pela Lei nº 13.777, de 20/12/2018, publicada no DOU de 21/12/2018, em vigor 45 dias após a publicação)"]],["CC, art. 1.358-Q",["Art. 1.358-Q. Na hipótese do art. 1.358-O deste Código, o regimento interno do condomínio edilício deve prever:","I - os direitos dos multiproprietários sobre as partes comuns do condomínio edilício;","II - os direitos e obrigações do administrador, inclusive quanto ao acesso ao imóvel para cumprimento do dever de manutenção, conservação e limpeza;","III - as condições e regras para uso das áreas comuns;","IV - os procedimentos a serem observados para uso e gozo dos imóveis e das instalações, equipamentos e mobiliário destinados ao regime da multipropriedade;","V - o número máximo de pessoas que podem ocupar simultaneamente o imóvel no período correspondente a cada fração de tempo;","VI - as regras de convivência entre os multiproprietários e os ocupantes de unidades autônomas não sujeitas ao regime da multipropriedade, quando se tratar de empreendimentos mistos;","VII - a forma de contribuição, destinação e gestão do fundo de reserva específico para cada imóvel, para reposição e manutenção dos equipamentos, instalações e mobiliário, sem prejuízo do fundo de reserva do condomínio edilício;","VIII - a possibilidade de realização de assembleias não presenciais, inclusive por meio eletrônico;","IX - os mecanismos de participação e representação dos titulares;","X - o funcionamento do sistema de reserva, os meios de confirmação e os requisitos a serem cumpridos pelo multiproprietário quando não exercer diretamente sua faculdade de uso;","XI - a descrição dos serviços adicionais, se existentes, e as regras para seu uso e custeio.","Parágrafo único. O regimento interno poderá ser instituído por escritura pública ou por instrumento particular. (Artigo acrescido pela Lei nº 13.777, de 20/12/2018, publicada no DOU de 21/12/2018, em vigor 45 dias após a publicação)"]],["CC, art. 1.358-R",["Art. 1.358-R. O condomínio edilício em que tenha sido instituído o regime de multipropriedade em parte ou na totalidade de suas unidades autônomas terá necessariamente um administrador profissional.","§ 1º O prazo de duração do contrato de administração será livremente convencionado.","§ 2º O administrador do condomínio referido no caput deste artigo será também o administrador de todos os condomínios em multipropriedade de suas unidades autônomas.","§ 3º O administrador será mandatário legal de todos os multiproprietários, exclusivamente para a realização dos atos de gestão ordinária da multipropriedade, incluindo manutenção, conservação e limpeza do imóvel e de suas instalações, equipamentos e mobiliário.","§ 4º O administrador poderá modificar o regimento interno quanto aos aspectos estritamente operacionais da gestão da multipropriedade no condomínio edilício.","§ 5º O administrador pode ser ou não um prestador de serviços de hospedagem. (Artigo acrescido pela Lei nº 13.777, de 20/12/2018, publicada no DOU de 21/12/2018, em vigor 45 dias após a publicação)"]],["CC, art. 1.358-S",["Art. 1.358-S. Na hipótese de inadimplemento, por parte do multiproprietário, da obrigação de custeio das despesas ordinárias ou extraordinárias, é cabível, na forma da lei processual civil, a adjudicação ao condomínio edilício da fração de tempo correspondente.","Parágrafo único. Na hipótese de o imóvel objeto da multipropriedade ser parte integrante de empreendimento em que haja sistema de locação das frações de tempo no qual os titulares possam ou sejam obrigados a locar suas frações de tempo exclusivamente por meio de uma administração única, repartindo entre si as receitas das locações independentemente da efetiva ocupação de cada unidade autônoma, poderá a convenção do condomínio edilício regrar que em caso de inadimplência:","I - o inadimplente fique proibido de utilizar o imóvel até a integral quitação da dívida;","II - a fração de tempo do inadimplente passe a integrar o pool da administradora;","III - a administradora do sistema de locação fique automaticamente munida de poderes e obrigada a, por conta e ordem do inadimplente, utilizar a integralidade dos valores líquidos a que o inadimplente tiver direito para amortizar suas dívidas condominiais, seja do condomínio edilício, seja do condomínio em multipropriedade, até sua integral quitação, devendo eventual saldo ser imediatamente repassado ao multiproprietário. (Artigo acrescido pela Lei nº 13.777, de 20/12/2018, publicada no DOU de 21/12/2018, em vigor 45 dias após a publicação)"]],["CC, art. 1.358-T",["Art. 1.358-T. O multiproprietário somente poderá renunciar de forma translativa a seu direito de multipropriedade em favor do condomínio edilício.","Parágrafo único. A renúncia de que trata o caput deste artigo só é admitida se o multiproprietário estiver em dia com as contribuições condominiais, com os tributos imobiliários e, se houver, com o foro ou a taxa de ocupação. (Artigo acrescido pela Lei nº 13.777, de 20/12/2018, publicada no DOU de 21/12/2018, em vigor 45 dias após a publicação)"]],["CC, art. 1.358-U",["Art. 1.358-U. As convenções dos condomínios edilícios, os memoriais de loteamentos e os instrumentos de venda dos lotes em loteamentos urbanos poderão limitar ou impedir a instituição da multipropriedade nos respectivos imóveis, vedação que somente poderá ser alterada no mínimo pela maioria absoluta dos condôminos. (Artigo acrescido pela Lei nº 13.777, de 20/12/2018, publicada no DOU de 21/12/2018, em vigor 45 dias após a publicação)"]]],"13":[["CC, art. 1.359",["Art. 1.359. Resolvida a propriedade pelo implemento da condição ou pelo advento do termo, entendem-se também resolvidos os direitos reais concedidos na sua pendência, e o proprietário, em cujo favor se opera a resolução, pode reivindicar a coisa do poder de quem a possua ou detenha."]],["CC, art. 1.360",["Art. 1.360. Se a propriedade se resolver por outra causa superveniente, o possuidor, que a tiver adquirido por título anterior à sua resolução, será considerado proprietário perfeito, restando à pessoa, em cujo benefício houve a resolução, ação contra aquele cuja propriedade se resolveu para haver a própria coisa ou o seu valor."]],["CC, art. 1.361",["Art. 1.361. Considera-se fiduciária a propriedade resolúvel de coisa móvel infungível que o devedor, com escopo de garantia, transfere ao credor.","§ 1º Constitui-se a propriedade fiduciária com o registro do contrato, celebrado por instrumento público ou particular, que lhe serve de título, no Registro de Títulos e Documentos do domicílio do devedor, ou, em se tratando de veículos, na repartição competente para o licenciamento, fazendo-se a anotação no certificado de registro.","§ 2º Com a constituição da propriedade fiduciária, dá-se o desdobramento da posse, tornando-se o devedor possuidor direto da coisa.","§ 3º A propriedade superveniente, adquirida pelo devedor, torna eficaz, desde o arquivamento, a transferência da propriedade fiduciária."]],["CC, art. 1.362",["Art. 1.362. O contrato, que serve de título à propriedade fiduciária, conterá:","I - o total da dívida, ou sua estimativa;","II - o prazo, ou a época do pagamento;","III - a taxa de juros, se houver;","IV - a descrição da coisa objeto da transferência, com os elementos indispensáveis à sua identificação."]],["CC, art. 1.363",["Art. 1.363. Antes de vencida a dívida, o devedor, a suas expensas e risco, pode usar a coisa segundo sua destinação, sendo obrigado, como depositário:","I - a empregar na guarda da coisa a diligência exigida por sua natureza;","II - a entregá-la ao credor, se a dívida não for paga no vencimento."]],["CC, art. 1.364",["Art. 1.364. Vencida a dívida, e não paga, fica o credor obrigado a vender, judicial ou extrajudicialmente, a coisa a terceiros, a aplicar o preço no pagamento de seu crédito e das despesas de cobrança, e a entregar o saldo, se houver, ao devedor."]],["CC, art. 1.365",["Art. 1.365. É nula a cláusula que autoriza o proprietário fiduciário a ficar com a coisa alienada em garantia, se a dívida não for paga no vencimento.","Parágrafo único. O devedor pode, com a anuência do credor, dar seu direito eventual à coisa em pagamento da dívida, após o vencimento desta."]],["CC, art. 1.366",["Art. 1.366. Quando, vendida a coisa, o produto não bastar para o pagamento da dívida e das despesas de cobrança, continuará o devedor obrigado pelo restante."]],["CC, art. 1.367",["Art. 1.367. A propriedade fiduciária em garantia de bens móveis ou imóveis sujeita-se às disposições do Capítulo I do Título X do Livro III da Parte Especial deste Código e, no que for específico, à legislação especial pertinente, não se equiparando, para quaisquer efeitos, à propriedade plena de que trata o art. 1.231. (Artigo com redação dada pela Lei nº 13.043, de 13/11/2014)"]],["CC, art. 1.368",["Art. 1.368. O terceiro, interessado ou não, que pagar a dívida, se sub-rogará de pleno direito no crédito e na propriedade fiduciária."]],["CC, art. 1.368-A",["Art. 1.368-A. As demais espécies de propriedade fiduciária ou de titularidade fiduciária submetem-se à disciplina específica das respectivas leis especiais, somente se aplicando as disposições deste Código naquilo que não for incompatível com a legislação especial. (Artigo acrescido pela Lei nº 10.931, de 2/8/2004)"]],["CC, art. 1.368-B",["Art. 1.368-B. A alienação fiduciária em garantia de bem móvel ou imóvel confere direito real de aquisição ao fiduciante, seu cessionário ou sucessor.","Parágrafo único. O credor fiduciário que se tornar proprietário pleno do bem, por efeito de realização da garantia, mediante consolidação da propriedade, adjudicação, dação ou outra forma pela qual lhe tenha sido transmitida a propriedade plena, passa a responder pelo pagamento dos tributos sobre a propriedade e a posse, taxas, despesas condominiais e quaisquer outros encargos, tributários ou não, incidentes sobre o bem objeto da garantia, a partir da data em que vier a ser imitido na posse direta do bem. (Artigo acrescido pela Lei nº 13.043, de 13/11/2014)"]]]},"13":{"0":[["CC, art. 1.225",["Art. 1.225. São direitos reais:","I - a propriedade;","II - a superfície;","III - as servidões;","IV - o usufruto;","V - o uso;","VI - a habitação;","VII - o direito do promitente comprador do imóvel;","VIII - o penhor;","IX - a hipoteca;","X - a anticrese;","XI - a concessão de uso especial para fins de moradia; (Inciso acrescido pela Lei nº 11.481, de 31/5/2007)","XII - a concessão de direito real de uso; (Inciso acrescido pela Lei nº 11.481, de 31/5/2007, e com nova redação dada pela Lei nº 14.620, de 13/7/2023)","XIII - a laje; (Inciso acrescido pela Medida Provisória nº 759, de 22/12/2016, convertida na Lei nº 13.465, de 11/7/2017, e com nova redação dada pela Lei nº 14.620, de 13/7/2023)","XIV - os direitos oriundos da imissão provisória na posse, quando concedida à União, aos Estados, ao Distrito Federal, aos Municípios ou às suas entidades delegadas e a respectiva cessão e promessa de cessão. (Inciso acrescido pela Lei nº 14.620, de 13/7/2023)"]]],"1":[["CC, art. 1.369",["Art. 1.369. O proprietário pode conceder a outrem o direito de construir ou de plantar em seu terreno, por tempo determinado, mediante escritura pública devidamente registrada no Cartório de Registro de Imóveis.","Parágrafo único. O direito de superfície não autoriza obra no subsolo, salvo se for inerente ao objeto da concessão."]],["CC, art. 1.370",["Art. 1.370. A concessão da superfície será gratuita ou onerosa; se onerosa, estipularão as partes se o pagamento será feito de uma só vez, ou parceladamente."]],["CC, art. 1.371",["Art. 1.371. O superficiário responderá pelos encargos e tributos que incidirem sobre o imóvel."]],["CC, art. 1.372",["Art. 1.372. O direito de superfície pode transferir-se a terceiros e, por morte do superficiário, aos seus herdeiros.","Parágrafo único. Não poderá ser estipulado pelo concedente, a nenhum título, qualquer pagamento pela transferência."]],["CC, art. 1.373",["Art. 1.373. Em caso de alienação do imóvel ou do direito de superfície, o superficiário ou o proprietário tem direito de preferência, em igualdade de condições."]],["CC, art. 1.374",["Art. 1.374. Antes do termo final, resolver-se-á a concessão se o superficiário der ao terreno destinação diversa daquela para que foi concedida."]],["CC, art. 1.375",["Art. 1.375. Extinta a concessão, o proprietário passará a ter a propriedade plena sobre o terreno, construção ou plantação, independentemente de indenização, se as partes não houverem estipulado o contrário."]],["CC, art. 1.376",["Art. 1.376. No caso de extinção do direito de superfície em conseqüência de desapropriação, a indenização cabe ao proprietário e ao superficiário, no valor correspondente ao direito real de cada um."]],["CC, art. 1.377",["Art. 1.377. O direito de superfície, constituído por pessoa jurídica de direito público interno, rege-se por este Código, no que não for diversamente disciplinado em lei especial."]],["CC, art. 21",["Art. 21. A vida privada da pessoa natural é inviolável, e o juiz, a requerimento do interessado, adotará as providências necessárias para impedir ou fazer cessar ato contrário a esta norma. (Vide ADIN nº 4.815/2012, publicada no DOU de 26/6/2015, p. 1)"]],["CC, art. 22",["Art. 22. Desaparecendo uma pessoa do seu domicílio sem dela haver notícia, se não houver deixado representante ou procurador a quem caiba administrar-lhe os bens, o juiz, a requerimento de qualquer interessado ou do Ministério Público, declarará a ausência, e nomear-lhe-á curador."]],["CC, art. 23",["Art. 23. Também se declarará a ausência, e se nomeará curador, quando o ausente deixar mandatário que não queira ou não possa exercer ou continuar o mandato, ou se os seus poderes forem insuficientes."]],["CC, art. 24",["Art. 24. O juiz, que nomear o curador, fixar-lhe-á os poderes e obrigações, conforme as circunstâncias, observando, no que for aplicável, o disposto a respeito dos tutores e curadores."]]],"2":[["CC, art. 1.378",["Art. 1.378. A servidão proporciona utilidade para o prédio dominante, e grava o prédio serviente, que pertence a diverso dono, e constitui-se mediante declaração expressa dos proprietários, ou por testamento, e subseqüente registro no Cartório de Registro de Imóveis."]],["CC, art. 1.379",["Art. 1.379. O exercício incontestado e contínuo de uma servidão aparente, por dez anos, nos termos do art. 1.242, autoriza o interessado a registrá-la em seu nome no Registro de Imóveis, valendo-lhe como título a sentença que julgar consumado a usucapião.","Parágrafo único. Se o possuidor não tiver título, o prazo da usucapião será de vinte anos."]],["CC, art. 1.380",["Art. 1.380. O dono de uma servidão pode fazer todas as obras necessárias à sua conservação e uso, e, se a servidão pertencer a mais de um prédio, serão as despesas rateadas entre os respectivos donos."]],["CC, art. 1.381",["Art. 1.381. As obras a que se refere o artigo antecedente devem ser feitas pelo dono do prédio dominante, se o contrário não dispuser expressamente o título."]],["CC, art. 1.382",["Art. 1.382. Quando a obrigação incumbir ao dono do prédio serviente, este poderá exonerar-se, abandonando, total ou parcialmente, a propriedade ao dono do dominante.","Parágrafo único. Se o proprietário do prédio dominante se recusar a receber a propriedade do serviente, ou parte dela, caber-lhe-á custear as obras."]],["CC, art. 1.383",["Art. 1.383. O dono do prédio serviente não poderá embaraçar de modo algum o exercício legítimo da servidão."]],["CC, art. 1.384",["Art. 1.384. A servidão pode ser removida, de um local para outro, pelo dono do prédio serviente e à sua custa, se em nada diminuir as vantagens do prédio dominante, ou pelo dono deste e à sua custa, se houver considerável incremento da utilidade e não prejudicar o prédio serviente."]],["CC, art. 1.385",["Art. 1.385. Restringir-se-á o exercício da servidão às necessidades do prédio dominante, evitando-se, quanto possível, agravar o encargo ao prédio serviente.","§ 1º Constituída para certo fim, a servidão não se pode ampliar a outro.","§ 2º Nas servidões de trânsito, a de maior inclui a de menor ônus, e a menor exclui a mais onerosa.","§ 3º Se as necessidades da cultura, ou da indústria, do prédio dominante impuserem à servidão maior largueza, o dono do serviente é obrigado a sofrê-la; mas tem direito a ser indenizado pelo excesso."]],["CC, art. 1.386",["Art. 1.386. As servidões prediais são indivisíveis, e subsistem, no caso de divisão dos imóveis, em benefício de cada uma das porções do prédio dominante, e continuam a gravar cada uma das do prédio serviente, salvo se, por natureza, ou destino, só se aplicarem a certa parte de um ou de outro."]],["CC, art. 1.387",["Art. 1.387. Salvo nas desapropriações, a servidão, uma vez registrada, só se extingue, com respeito a terceiros, quando cancelada.","Parágrafo único. Se o prédio dominante estiver hipotecado, e a servidão se mencionar no título hipotecário, será também preciso, para a cancelar, o consentimento do credor."]],["CC, art. 1.388",["Art. 1.388. O dono do prédio serviente tem direito, pelos meios judiciais, ao cancelamento do registro, embora o dono do prédio dominante lho impugne:","I - quando o titular houver renunciado a sua servidão;","II - quando tiver cessado, para o prédio dominante, a utilidade ou a comodidade, que determinou a constituição da servidão;","III - quando o dono do prédio serviente resgatar a servidão."]],["CC, art. 1.389",["Art. 1.389. Também se extingue a servidão, ficando ao dono do prédio serviente a faculdade de fazê-la cancelar, mediante a prova da extinção:","I - pela reunião dos dois prédios no domínio da mesma pessoa;","II - pela supressão das respectivas obras por efeito de contrato, ou de outro título expresso;","III - pelo não uso, durante dez anos contínuos."]]],"3":[["CC, art. 1.390",["Art. 1.390. O usufruto pode recair em um ou mais bens, móveis ou imóveis, em um patrimônio inteiro, ou parte deste, abrangendo-lhe, no todo ou em parte, os frutos e utilidades."]],["CC, art. 1.391",["Art. 1.391. O usufruto de imóveis, quando não resulte de usucapião, constituir-se-á mediante registro no Cartório de Registro de Imóveis."]],["CC, art. 1.392",["Art. 1.392. Salvo disposição em contrário, o usufruto estende-se aos acessórios da coisa e seus acrescidos.","§ 1º Se, entre os acessórios e os acrescidos, houver coisas consumíveis, terá o usufrutuário o dever de restituir, findo o usufruto, as que ainda houver e, das outras, o equivalente em gênero, qualidade e quantidade, ou, não sendo possível, o seu valor, estimado ao tempo da restituição.","§ 2º Se há no prédio em que recai o usufruto florestas ou os recursos minerais a que se refere o art. 1.230, devem o dono e o usufrutuário prefixar-lhe a extensão do gozo e a maneira de exploração.","§ 3º Se o usufruto recai sobre universalidade ou quota-parte de bens, o usufrutuário tem direito à parte do tesouro achado por outrem, e ao preço pago pelo vizinho do prédio usufruído, para obter meação em parede, cerca, muro, vala ou valado."]],["CC, art. 1.393",["Art. 1.393. Não se pode transferir o usufruto por alienação; mas o seu exercício pode ceder-se por título gratuito ou oneroso."]],["CC, art. 1.394",["Art. 1.394. O usufrutuário tem direito à posse, uso, administração e percepção dos frutos."]],["CC, art. 1.395",["Art. 1.395. Quando o usufruto recai em títulos de crédito, o usufrutuário tem direito a perceber os frutos e a cobrar as respectivas dívidas.","Parágrafo único. Cobradas as dívidas, o usufrutuário aplicará, de imediato, a importância em títulos da mesma natureza, ou em títulos da dívida pública federal, com cláusula de atualização monetária segundo índices oficiais regularmente estabelecidos."]],["CC, art. 1.396",["Art. 1.396. Salvo direito adquirido por outrem, o usufrutuário faz seus os frutos naturais, pendentes ao começar o usufruto, sem encargo de pagar as despesas de produção.","Parágrafo único. Os frutos naturais, pendentes ao tempo em que cessa o usufruto, pertencem ao dono, também sem compensação das despesas."]],["CC, art. 1.397",["Art. 1.397. As crias dos animais pertencem ao usufrutuário, deduzidas quantas bastem para inteirar as cabeças de gado existentes ao começar o usufruto."]],["CC, art. 1.398",["Art. 1.398. Os frutos civis, vencidos na data inicial do usufruto, pertencem ao proprietário, e ao usufrutuário os vencidos na data em que cessa o usufruto."]],["CC, art. 1.399",["Art. 1.399. O usufrutuário pode usufruir em pessoa, ou mediante arrendamento, o prédio, mas não mudar-lhe a destinação econômica, sem expressa autorização do proprietário."]],["CC, art. 1.400",["Art. 1.400. O usufrutuário, antes de assumir o usufruto, inventariará, à sua custa, os bens que receber, determinando o estado em que se acham, e dará caução, fidejussória ou real, se lha exigir o dono, de velar-lhes pela conservação, e entregá-los findo o usufruto.","Parágrafo único. Não é obrigado à caução o doador que se reservar o usufruto da coisa doada."]],["CC, art. 1.401",["Art. 1.401. O usufrutuário que não quiser ou não puder dar caução suficiente perderá o direito de administrar o usufruto; e, neste caso, os bens serão administrados pelo proprietário, que ficará obrigado, mediante caução, a entregar ao usufrutuário o rendimento deles, deduzidas as despesas de administração, entre as quais se incluirá a quantia fixada pelo juiz como remuneração do administrador."]],["CC, art. 1.402",["Art. 1.402. O usufrutuário não é obrigado a pagar as deteriorações resultantes do exercício regular do usufruto."]],["CC, art. 1.403",["Art. 1.403 Incumbem ao usufrutuário:","I - as despesas ordinárias de conservação dos bens no estado em que os recebeu;","II - as prestações e os tributos devidos pela posse ou rendimento da coisa usufruída."]],["CC, art. 1.404",["Art. 1.404. Incumbem ao dono as reparações extraordinárias e as que não forem de custo módico; mas o usufrutuário lhe pagará os juros do capital despendido com as que forem necessárias à conservação, ou aumentarem o rendimento da coisa usufruída.","§ 1º Não se consideram módicas as despesas superiores a dois terços do líquido rendimento em um ano.","§ 2º Se o dono não fizer as reparações a que está obrigado, e que são indispensáveis à conservação da coisa, o usufrutuário pode realizá-las, cobrando daquele a importância despendida."]],["CC, art. 1.405",["Art. 1.405. Se o usufruto recair num patrimônio, ou parte deste, será o usufrutuário obrigado aos juros da dívida que onerar o patrimônio ou a parte dele."]],["CC, art. 1.406",["Art. 1.406. O usufrutuário é obrigado a dar ciência ao dono de qualquer lesão produzida contra a posse da coisa, ou os direitos deste."]],["CC, art. 1.407",["Art. 1.407. Se a coisa estiver segurada, incumbe ao usufrutuário pagar, durante o usufruto, as contribuições do seguro.","§ 1º Se o usufrutuário fizer o seguro, ao proprietário caberá o direito dele resultante contra o segurador.","§ 2º Em qualquer hipótese, o direito do usufrutuário fica sub-rogado no valor da indenização do seguro."]],["CC, art. 1.408",["Art. 1.408. Se um edifício sujeito a usufruto for destruído sem culpa do proprietário, não será este obrigado a reconstruí-lo, nem o usufruto se restabelecerá, se o proprietário reconstruir à sua custa o prédio; mas se a indenização do seguro for aplicada à reconstrução do prédio, restabelecer-se-á o usufruto."]],["CC, art. 1.409",["Art. 1.409. Também fica sub-rogada no ônus do usufruto, em lugar do prédio, a indenização paga, se ele for desapropriado, ou a importância do dano, ressarcido pelo terceiro responsável no caso de danificação ou perda."]],["CC, art. 1.410",["Art. 1.410. O usufruto extingue-se, cancelando-se o registro no Cartório de Registro de Imóveis:","I - pela renúncia ou morte do usufrutuário;","II - pelo termo de sua duração;","III - pela extinção da pessoa jurídica, em favor de quem o usufruto foi constituído, ou, se ela perdurar, pelo decurso de trinta anos da data em que se começou a exercer;","IV - pela cessação do motivo de que se origina;","V - pela destruição da coisa, guardadas as disposições dos arts. 1.407, 1.408, 2ª parte, e 1.409;","VI - pela consolidação;","VII - por culpa do usufrutuário, quando aliena, deteriora, ou deixa arruinar os bens, não lhes acudindo com os reparos de conservação, ou quando, no usufruto de títulos de crédito, não dá às importâncias recebidas a aplicação prevista no parágrafo único do art. 1.395;","VIII - Pelo não uso, ou não fruição, da coisa em que o usufruto recai (arts. 1.390 e 1.399)."]],["CC, art. 1.411",["Art. 1.411. Constituído o usufruto em favor de duas ou mais pessoas, extinguir-se-á a parte em relação a cada uma das que falecerem, salvo se, por estipulação expressa, o quinhão desses couber ao sobrevivente."]]],"4":[["CC, art. 1.412",["Art. 1.412. O usuário usará da coisa e perceberá os seus frutos, quanto o exigirem as necessidades suas e de sua família.","§ 1º Avaliar-se-ão as necessidades pessoais do usuário conforme a sua condição social e o lugar onde viver.","§ 2º As necessidades da família do usuário compreendem as de seu cônjuge, dos filhos solteiros e das pessoas de seu serviço doméstico."]],["CC, art. 1.413",["Art. 1.413. São aplicáveis ao uso, no que não for contrário à sua natureza, as disposições relativas ao usufruto."]],["CC, art. 1.414",["Art. 1.414. Quando o uso consistir no direito de habitar gratuitamente casa alheia, o titular deste direito não a pode alugar, nem emprestar, mas simplesmente ocupá-la com sua família."]],["CC, art. 1.415",["Art. 1.415. Se o direito real de habitação for conferido a mais de uma pessoa, qualquer delas que sozinha habite a casa não terá de pagar aluguel à outra, ou às outras, mas não as pode inibir de exercerem, querendo, o direito, que também lhes compete, de habitá-la."]],["CC, art. 1.416",["Art. 1.416. São aplicáveis à habitação, no que não for contrário à sua natureza, as disposições relativas ao usufruto."]]],"5":[["CC, art. 1.225",["Art. 1.225. São direitos reais:","[…]","XI - a concessão de uso especial para fins de moradia; (Inciso acrescido pela Lei nº 11.481, de 31/5/2007)"]]],"6":[["CC, art. 1.417",["Art. 1.417. Mediante promessa de compra e venda, em que se não pactuou arrependimento, celebrada por instrumento público ou particular, e registrada no Cartório de Registro de Imóveis, adquire o promitente comprador direito real à aquisição do imóvel."]],["CC, art. 1.418",["Art. 1.418. O promitente comprador, titular de direito real, pode exigir do promitente vendedor, ou de terceiros, a quem os direitos deste forem cedidos, a outorga da escritura definitiva de compra e venda, conforme o disposto no instrumento preliminar; e, se houver recusa, requerer ao juiz a adjudicação do imóvel."]]],"7":[["CC, art. 1.418",["Art. 1.418. O promitente comprador, titular de direito real, pode exigir do promitente vendedor, ou de terceiros, a quem os direitos deste forem cedidos, a outorga da escritura definitiva de compra e venda, conforme o disposto no instrumento preliminar; e, se houver recusa, requerer ao juiz a adjudicação do imóvel."]]],"8":[["CC, art. 1.419",["Art. 1.419. Nas dívidas garantidas por penhor, anticrese ou hipoteca, o bem dado em garantia fica sujeito, por vínculo real, ao cumprimento da obrigação."]],["CC, art. 1.420",["Art. 1.420. Só aquele que pode alienar poderá empenhar, hipotecar ou dar em anticrese; só os bens que se podem alienar poderão ser dados em penhor, anticrese ou hipoteca.","§ 1º A propriedade superveniente torna eficaz, desde o registro, as garantias reais estabelecidas por quem não era dono.","§ 2º A coisa comum a dois ou mais proprietários não pode ser dada em garantia real, na sua totalidade, sem o consentimento de todos; mas cada um pode individualmente dar em garantia real a parte que tiver."]],["CC, art. 1.421",["Art. 1.421. O pagamento de uma ou mais prestações da dívida não importa exoneração correspondente da garantia, ainda que esta compreenda vários bens, salvo disposição expressa no título ou na quitação."]],["CC, art. 1.422",["Art. 1.422. O credor hipotecário e o pignoratício têm o direito de excutir a coisa hipotecada ou empenhada, e preferir, no pagamento, a outros credores, observada, quanto à hipoteca, a prioridade no registro.","Parágrafo único. Excetuam-se da regra estabelecida neste artigo as dívidas que, em virtude de outras leis, devam ser pagas precipuamente a quaisquer outros créditos."]],["CC, art. 1.423",["Art. 1.423. O credor anticrético tem direito a reter em seu poder o bem, enquanto a dívida não for paga; extingue-se esse direito decorridos quinze anos da data de sua constituição."]],["CC, art. 1.424",["Art. 1.424. Os contratos de penhor, anticrese ou hipoteca declararão, sob pena de não terem eficácia:","I - o valor do crédito, sua estimação, ou valor máximo;","II - o prazo fixado para pagamento;","III - a taxa dos juros, se houver;","IV - o bem dado em garantia com as suas especificações."]],["CC, art. 1.425",["Art. 1.425. A dívida considera-se vencida:","I - se, deteriorando-se, ou depreciando-se o bem dado em segurança, desfalcar a garantia, e o devedor, intimado, não a reforçar ou substituir;","II - se o devedor cair em insolvência ou falir;","III - se as prestações não forem pontualmente pagas, toda vez que deste modo se achar estipulado o pagamento. Neste caso, o recebimento posterior da prestação atrasada importa renúncia do credor ao seu direito de execução imediata;","IV - se perecer o bem dado em garantia, e não for substituído;","V - se se desapropriar o bem dado em garantia, hipótese na qual se depositará a parte do preço que for necessária para o pagamento integral do credor.","§ 1º Nos casos de perecimento da coisa dada em garantia, esta se sub-rogará na indenização do seguro, ou no ressarcimento do dano, em benefício do credor, a quem assistirá sobre ela preferência até seu completo reembolso.","§ 2º Nos casos dos incisos IV e V, só se vencerá a hipoteca antes do prazo estipulado, se o perecimento, ou a desapropriação recair sobre o bem dado em garantia, e esta não abranger outras; subsistindo, no caso contrário, a dívida reduzida, com a respectiva garantia sobre os demais bens, não desapropriados ou destruídos."]],["CC, art. 1.426",["Art. 1.426. Nas hipóteses do artigo anterior, de vencimento antecipado da dívida, não se compreendem os juros correspondentes ao tempo ainda não decorrido."]],["CC, art. 1.427",["Art. 1.427. Salvo cláusula expressa, o terceiro que presta garantia real por dívida alheia não fica obrigado a substituí-la, ou reforçá-la, quando, sem culpa sua, se perca, deteriore, ou desvalorize."]],["CC, art. 1.428",["Art. 1.428. É nula a cláusula que autoriza o credor pignoratício, anticrético ou hipotecário a ficar com o objeto da garantia, se a dívida não for paga no vencimento.","Parágrafo único. Após o vencimento, poderá o devedor dar a coisa em pagamento da dívida."]],["CC, art. 1.429",["Art. 1.429. Os sucessores do devedor não podem remir parcialmente o penhor ou a hipoteca na proporção dos seus quinhões; qualquer deles, porém, pode fazê-lo no todo.","Parágrafo único. O herdeiro ou sucessor que fizer a remição fica sub-rogado nos direitos do credor pelas quotas que houver satisfeito."]],["CC, art. 1.430",["Art. 1.430. Quando, excutido o penhor, ou executada a hipoteca, o produto não bastar para pagamento da dívida e despesas judiciais, continuará o devedor obrigado pessoalmente pelo restante."]]],"9":[["CC, art. 1.428",["Art. 1.428. É nula a cláusula que autoriza o credor pignoratício, anticrético ou hipotecário a ficar com o objeto da garantia, se a dívida não for paga no vencimento.","Parágrafo único. Após o vencimento, poderá o devedor dar a coisa em pagamento da dívida."]]],"12":[["CC, art. 1.506",["Art. 1.506. Pode o devedor ou outrem por ele, com a entrega do imóvel ao credor, ceder-lhe o direito de perceber, em compensação da dívida, os frutos e rendimentos.","§ 1º É permitido estipular que os frutos e rendimentos do imóvel sejam percebidos pelo credor à conta de juros, mas se o seu valor ultrapassar a taxa máxima permitida em lei para as operações financeiras, o remanescente será imputado ao capital.","§ 2º Quando a anticrese recair sobre bem imóvel, este poderá ser hipotecado pelo devedor ao credor anticrético, ou a terceiros, assim como o imóvel hipotecado poderá ser dado em anticrese."]],["CC, art. 1.507",["Art. 1.507. O credor anticrético pode administrar os bens dados em anticrese e fruir seus frutos e utilidades, mas deverá apresentar anualmente balanço, exato e fiel, de sua administração.","§ 1º Se o devedor anticrético não concordar com o que se contém no balanço, por ser inexato, ou ruinosa a administração, poderá impugná-lo, e, se o quiser, requerer a transformação em arrendamento, fixando o juiz o valor mensal do aluguel, o qual poderá ser corrigido anualmente.","§ 2º O credor anticrético pode, salvo pacto em sentido contrário, arrendar os bens dados em anticrese a terceiro, mantendo, até ser pago, direito de retenção do imóvel, embora o aluguel desse arrendamento não seja vinculativo para o devedor."]],["CC, art. 1.508",["Art. 1.508. O credor anticrético responde pelas deteriorações que, por culpa sua, o imóvel vier a sofrer, e pelos frutos e rendimentos que, por sua negligência, deixar de perceber."]],["CC, art. 1.509",["Art. 1.509. O credor anticrético pode vindicar os seus direitos contra o adquirente dos bens, os credores quirografários e os hipotecários posteriores ao registro da anticrese.","§ 1º Se executar os bens por falta de pagamento da dívida, ou permitir que outro credor o execute, sem opor o seu direito de retenção ao exeqüente, não terá preferência sobre o preço.","§ 2º O credor anticrético não terá preferência sobre a indenização do seguro, quando o prédio seja destruído, nem, se forem desapropriados os bens, com relação à desapropriação."]],["CC, art. 1.510",["Art. 1.510. O adquirente dos bens dados em anticrese poderá remi-los, antes do vencimento da dívida, pagando a sua totalidade à data do pedido de remição e imitir-se-á, se for o caso, na sua posse."]]],"13":[["CC, art. 1.510-A",["Art. 1.510-A. O proprietário de uma construção-base poderá ceder a superfície superior ou inferior de sua construção a fim de que o titular da laje mantenha unidade distinta daquela originalmente construída sobre o solo. (“Caput” do artigo acrescido pela Medida Provisória nº 759, de 22/12/2016, convertida e com redação dada pela Lei nº 13.465, de 11/7/2017)","§ 1º O direito real de laje contempla o espaço aéreo ou o subsolo de terrenos públicos ou privados, tomados em projeção vertical, como unidade imobiliária autônoma, não contemplando as demais áreas edificadas ou não pertencentes ao proprietário da construção-base. (Parágrafo acrescido pela Medida Provisória nº 759, de 22/12/2016, convertida e com redação dada pela Lei nº 13.465, de 11/7/2017)","§ 2º O titular do direito real de laje responderá pelos encargos e tributos que incidirem sobre a sua unidade. (Parágrafo acrescido pela Medida Provisória nº 759, de 22/12/2016, convertida e com redação dada pela Lei nº 13.465, de 11/7/2017)","§ 3º Os titulares da laje, unidade imobiliária autônoma constituída em matrícula própria, poderão dela usar, gozar e dispor. (Parágrafo acrescido pela Lei nº 13.465, de 11/7/2017)","§ 4º A instituição do direito real de laje não implica a atribuição de fração ideal de terreno ao titular da laje ou a participação proporcional em áreas já edificadas. (Parágrafo acrescido pela Medida Provisória nº 759, de 22/12/2016, convertida e com redação dada pela Lei nº 13.465, de 11/7/2017)","§ 5º Os Municípios e o Distrito Federal poderão dispor sobre posturas edilícias e urbanísticas associadas ao direito real de laje. (Parágrafo acrescido pela Medida Provisória nº 759, de 22/12/2016, convertida na Lei nº 13.465, de 11/7/2017)","§ 6º O titular da laje poderá ceder a superfície de sua construção para a instituição de um sucessivo direito real de laje, desde que haja autorização expressa dos titulares da construção-base e das demais lajes, respeitadas as posturas edilícias e urbanísticas vigentes. (Parágrafo acrescido pela Lei nº 13.465, de 11/7/2017)"]],["CC, art. 1.510-B",["Art. 1.510-B. É expressamente vedado ao titular da laje prejudicar com obras novas ou com falta de reparação a segurança, a linha arquitetônica ou o arranjo estético do edifício, observadas as posturas previstas em legislação local. (Artigo acrescido pela Lei nº 13.465, de 11/7/2017)"]],["CC, art. 1.510-C",["Art. 1.510-C. Sem prejuízo, no que couber, das normas aplicáveis aos condomínios edilícios, para fins do direito real de laje, as despesas necessárias à conservação e fruição das partes que sirvam a todo o edifício e ao pagamento de serviços de interesse comum serão partilhadas entre o proprietário da construção-base e o titular da laje, na proporção que venha a ser estipulada em contrato.","§ 1º São partes que servem a todo o edifício:","I - os alicerces, colunas, pilares, paredes-mestras e todas as partes restantes que constituam a estrutura do prédio;","II - o telhado ou os terraços de cobertura, ainda que destinados ao uso exclusivo do titular da laje;","III - as instalações gerais de água, esgoto, eletricidade, aquecimento, ar condicionado, gás, comunicações e semelhantes que sirvam a todo o edifício; e","IV - em geral, as coisas que sejam afetadas ao uso de todo o edifício.","§ 2º É assegurado, em qualquer caso, o direito de qualquer interessado em promover reparações urgentes na construção na forma do parágrafo único do art. 249 deste Código. (Artigo acrescido pela Lei nº 13.465, de 11/7/2017)"]],["CC, art. 1.510-D",["Art. 1.510-D. Em caso de alienação de qualquer das unidades sobrepostas, terão direito de preferência, em igualdade de condições com terceiros, os titulares da construção-base e da laje, nessa ordem, que serão cientificados por escrito para que se manifestem no prazo de trinta dias, salvo se o contrato dispuser de modo diverso.","§ 1º O titular da construção-base ou da laje a quem não se der conhecimento da alienação poderá, mediante depósito do respectivo preço, haver para si a parte alienada a terceiros, se o requerer no prazo decadencial de cento e oitenta dias, contado da data de alienação.","§ 2º Se houver mais de uma laje, terá preferência, sucessivamente, o titular das lajes ascendentes e o titular das lajes descendentes, assegurada a prioridade para a laje mais próxima à unidade sobreposta a ser alienada. (Artigo acrescido pela Lei nº 13.465, de 11/7/2017)"]],["CC, art. 1.510-E",["Art. 1.510-E. A ruína da construção-base implica extinção do direito real de laje, salvo: (“caput” do artigo acrescido pela Lei nº 13.465, de 11/7/2017)","I - se este tiver sido instituído sobre o subsolo; (Inciso acrescido pela Lei nº 13.465, de 11/7/2017)","II - se a construção-base for reconstruída no prazo de 5 (cinco) anos. (Inciso acrescido pela Lei nº 13.465, de 11/7/2017 , com redação dada pela Lei nº 14.382, de 27/6/2022)","Parágrafo único. O disposto neste artigo não afasta o direito a eventual reparação civil contra o culpado pela ruína. (Parágrafo único acrescido pela Lei nº 13.465, de 11/7/2017)"]]]},"14":{"0":[["CF/88, art. 226",["Art. 226. A família, base da sociedade, tem especial proteção do Estado.","§ 1º O casamento é civil e gratuita a celebração.","§ 2º O casamento religioso tem efeito civil, nos termos da lei.","§ 3º Para efeito da proteção do Estado, é reconhecida a união estável entre o homem e a mulher como entidade familiar, devendo a lei facilitar sua conversão em casamento.","§ 4º Entende-se, também, como entidade familiar a comunidade formada por qualquer dos pais e seus descendentes.","§ 5º Os direitos e deveres referentes à sociedade conjugal são exercidos igualmente pelo homem e pela mulher.","§ 6º O casamento civil pode ser dissolvido pelo divórcio.","§ 7º Fundado nos princípios da dignidade da pessoa humana e da paternidade responsável, o planejamento familiar é livre decisão do casal, competindo ao Estado propiciar recursos educacionais e científicos para o exercício desse direito, vedada qualquer forma coercitiva por parte de instituições oficiais ou privadas.","§ 8º O Estado assegurará a assistência à família na pessoa de cada um dos que a integram, criando mecanismos para coibir a violência no âmbito de suas relações."]],["CC, art. 1.511",["Art. 1.511. O casamento estabelece comunhão plena de vida, com base na igualdade de direitos e deveres dos cônjuges."]]],"2":[["CC, art. 1.521",["Art. 1.521. Não podem casar:","I - os ascendentes com os descendentes, seja o parentesco natural ou civil;","II - os afins em linha reta;","III - o adotante com quem foi cônjuge do adotado e o adotado com quem o foi do adotante;","IV - os irmãos, unilaterais ou bilaterais, e demais colaterais, até o terceiro grau inclusive;","V - o adotado com o filho do adotante;","VI - as pessoas casadas;","VII - o cônjuge sobrevivente com o condenado por homicídio ou tentativa de homicídio contra o seu consorte."]],["CC, art. 1.522",["Art. 1.522. Os impedimentos podem ser opostos, até o momento da celebração do casamento, por qualquer pessoa capaz.","Parágrafo único. Se o juiz, ou o oficial de registro, tiver conhecimento da existência de algum impedimento, será obrigado a declará-lo."]],["CC, art. 1.523",["Art. 1.523. Não devem casar:","I - o viúvo ou a viúva que tiver filho do cônjuge falecido, enquanto não fizer inventário dos bens do casal e der partilha aos herdeiros;","II - a viúva, ou a mulher cujo casamento se desfez por ser nulo ou ter sido anulado, até dez meses depois do começo da viuvez, ou da dissolução da sociedade conjugal;","III - o divorciado, enquanto não houver sido homologada ou decidida a partilha dos bens do casal;","IV - o tutor ou o curador e os seus descendentes, ascendentes, irmãos, cunhados ou sobrinhos, com a pessoa tutelada ou curatelada, enquanto não cessar a tutela ou curatela, e não estiverem saldadas as respectivas contas.","Parágrafo único. É permitido aos nubentes solicitar ao juiz que não lhes sejam aplicadas as causas suspensivas previstas nos incisos I, III e IV deste artigo, provando-se a inexistência de prejuízo, respectivamente, para o herdeiro, para o ex-cônjuge e para a pessoa tutelada ou curatelada; no caso do inciso II, a nubente deverá provar nascimento de filho, ou inexistência de gravidez, na fluência do prazo."]],["CC, art. 1.524",["Art. 1.524. As causas suspensivas da celebração do casamento podem ser argüidas pelos parentes em linha reta de um dos nubentes, sejam consangüíneos ou afins, e pelos colaterais em segundo grau, sejam também consangüíneos ou afins."]],["CC, art. 1.641",["Art. 1.641. É obrigatório o regime da separação de bens no casamento:","I - das pessoas que o contraírem com inobservância das causas suspensivas da celebração do casamento;","II - da pessoa maior de 70 (setenta) anos; (Inciso com redação dada pela Lei nº 12.344, de 9/12/2010)","III - de todos os que dependerem, para casar, de suprimento judicial."]]],"3":[["CC, art. 1.548",["Art. 1.548. É nulo o casamento contraído:","I - (Revogado pela Lei nº 13.146, de 6/7/2015, publicada no DOU de 7/7/2015, em vigor 180 dias após a publicação)","II - por infringência de impedimento."]],["CC, art. 1.549",["Art. 1.549. A decretação de nulidade de casamento, pelos motivos previstos no artigo antecedente, pode ser promovida mediante ação direta, por qualquer interessado, ou pelo Ministério Público."]],["CC, art. 1.550",["Art. 1.550. É anulável o casamento:","I - de quem não completou a idade mínima para casar;","II - do menor em idade núbil, quando não autorizado por seu representante legal;","III - por vício da vontade, nos termos dos arts. 1.556 a 1.558;","IV - do incapaz de consentir ou manifestar, de modo inequívoco, o consentimento;","V - realizado pelo mandatário, sem que ele ou o outro contraente soubesse da revogação do mandato, e não sobrevindo coabitação entre os cônjuges;","VI - por incompetência da autoridade celebrante.","§ 1º Equipara-se à revogação a invalidade do mandato judicialmente decretada. (Parágrafo único transformado em § 1º pela Lei nº 13.146, de 6/7/2015, publicada no DOU de 7/7/2015, em vigor 180 dias após a publicação)","§ 2º A pessoa com deficiência mental ou intelectual em idade núbia poderá contrair matrimônio, expressando sua vontade diretamente ou por meio de seu responsável ou curador. (Parágrafo acrescido pela Lei nº 13.146, de 6/7/2015, publicada no DOU de 7/7/2015, em vigor 180 dias após a publicação)"]],["CC, art. 1.551",["Art. 1.551. Não se anulará, por motivo de idade, o casamento de que resultou gravidez."]],["CC, art. 1.552",["Art. 1.552. A anulação do casamento dos menores de dezesseis anos será requerida:","I - pelo próprio cônjuge menor;","II - por seus representantes legais;","III - por seus ascendentes."]],["CC, art. 1.553",["Art. 1.553. O menor que não atingiu a idade núbil poderá, depois de completá-la, confirmar seu casamento, com a autorização de seus representantes legais, se necessária, ou com suprimento judicial."]],["CC, art. 1.554",["Art. 1.554. Subsiste o casamento celebrado por aquele que, sem possuir a competência exigida na lei, exercer publicamente as funções de juiz de casamentos e, nessa qualidade, tiver registrado o ato no Registro Civil."]],["CC, art. 1.555",["Art. 1.555. O casamento do menor em idade núbil, quando não autorizado por seu representante legal, só poderá ser anulado se a ação for proposta em cento e oitenta dias, por iniciativa do incapaz, ao deixar de sê-lo, de seus representantes legais ou de seus herdeiros necessários.","§ 1º O prazo estabelecido neste artigo será contado do dia em que cessou a incapacidade, no primeiro caso; a partir do casamento, no segundo; e, no terceiro, da morte do incapaz.","§ 2º Não se anulará o casamento quando à sua celebração houverem assistido os representantes legais do incapaz, ou tiverem, por qualquer modo, manifestado sua aprovação."]],["CC, art. 1.556",["Art. 1.556. O casamento pode ser anulado por vício da vontade, se houve por parte de um dos nubentes, ao consentir, erro essencial quanto à pessoa do outro."]],["CC, art. 1.557",["Art. 1.557. Considera-se erro essencial sobre a pessoa do outro cônjuge:","I - o que diz respeito à sua identidade, sua honra e boa fama, sendo esse erro tal que o seu conhecimento ulterior torne insuportável a vida em comum ao cônjuge enganado;","II - a ignorância de crime, anterior ao casamento, que, por sua natureza, torne insuportável a vida conjugal;","III - a ignorância, anterior ao casamento, de defeito físico irremediável que não caracterize deficiência ou de moléstia grave e transmissível, por contágio ou por herança, capaz de pôr em risco a saúde do outro cônjuge ou de sua descendência; (Inciso com redação dada pela Lei nº 13.146, de 6/7/2015, publicada no DOU de 7/7/2015, em vigor 180 dias após a publicação)","IV - (Revogado pela Lei nº 13.146, de 6/7/2015, publicada no DOU de 7/7/2015, em vigor 180 dias após a publicação)"]],["CC, art. 1.558",["Art. 1.558. É anulável o casamento em virtude de coação, quando o consentimento de um ou de ambos os cônjuges houver sido captado mediante fundado temor de mal considerável e iminente para a vida, a saúde e a honra, sua ou de seus familiares."]],["CC, art. 1.559",["Art. 1.559. Somente o cônjuge que incidiu em erro, ou sofreu coação, pode demandar a anulação do casamento; mas a coabitação, havendo ciência do vício, valida o ato, ressalvadas as hipóteses dos incisos III e IV do art. 1.557."]],["CC, art. 1.560",["Art. 1.560. O prazo para ser intentada a ação de anulação do casamento, a contar da data da celebração, é de:","I - cento e oitenta dias, no caso do inciso IV do art. 1.550;","II - dois anos, se incompetente a autoridade celebrante;","III - três anos, nos casos dos incisos I a IV do art. 1.557;","IV - quatro anos, se houver coação.","§ 1º Extingue-se, em cento e oitenta dias, o direito de anular o casamento dos menores de dezesseis anos, contado o prazo para o menor do dia em que perfez essa idade; e da data do casamento, para seus representantes legais ou ascendentes.","§ 2º Na hipótese do inciso V do art. 1.550, o prazo para anulação do casamento é de cento e oitenta dias, a partir da data em que o mandante tiver conhecimento da celebração."]],["CC, art. 1.561",["Art. 1.561. Embora anulável ou mesmo nulo, se contraído de boa-fé por ambos os cônjuges, o casamento, em relação a estes como aos filhos, produz todos os efeitos até o dia da sentença anulatória.","§ 1º Se um dos cônjuges estava de boa-fé ao celebrar o casamento, os seus efeitos civis só a ele e aos filhos aproveitarão.","§ 2º Se ambos os cônjuges estavam de má-fé ao celebrar o casamento, os seus efeitos civis só aos filhos aproveitarão."]],["CC, art. 1.562",["Art. 1.562. Antes de mover a ação de nulidade do casamento, a de anulação, a de separação judicial, a de divórcio direto ou a de dissolução de união estável, poderá requerer a parte, comprovando sua necessidade, a separação de corpos, que será concedida pelo juiz com a possível brevidade."]],["CC, art. 1.563",["Art. 1.563. A sentença que decretar a nulidade do casamento retroagirá à data da sua celebração, sem prejudicar a aquisição de direitos, a título oneroso, por terceiros de boa-fé, nem a resultante de sentença transitada em julgado."]],["CC, art. 1.564",["Art. 1.564. Quando o casamento for anulado por culpa de um dos cônjuges, este incorrerá:","I - na perda de todas as vantagens havidas do cônjuge inocente;","II - na obrigação de cumprir as promessas que lhe fez no contrato antenupcial."]]],"4":[["CC, art. 1.565",["Art. 1.565. Pelo casamento, homem e mulher assumem mutuamente a condição de consortes, companheiros e responsáveis pelos encargos da família.","§ 1º Qualquer dos nubentes, querendo, poderá acrescer ao seu o sobrenome do outro.","§ 2º O planejamento familiar é de livre decisão do casal, competindo ao Estado propiciar recursos educacionais e financeiros para o exercício desse direito, vedado qualquer tipo de coerção por parte de instituições privadas ou públicas."]],["CC, art. 1.566",["Art. 1.566. São deveres de ambos os cônjuges:","I - fidelidade recíproca;","II - vida em comum, no domicílio conjugal;","III - mútua assistência;","IV - sustento, guarda e educação dos filhos;","V - respeito e consideração mútuos."]],["CC, art. 1.567",["Art. 1.567. A direção da sociedade conjugal será exercida, em colaboração, pelo marido e pela mulher, sempre no interesse do casal e dos filhos.","Parágrafo único. Havendo divergência, qualquer dos cônjuges poderá recorrer ao juiz, que decidirá tendo em consideração aqueles interesses."]],["CC, art. 1.568",["Art. 1.568. Os cônjuges são obrigados a concorrer, na proporção de seus bens e dos rendimentos do trabalho, para o sustento da família e a educação dos filhos, qualquer que seja o regime patrimonial."]],["CC, art. 1.569",["Art. 1.569. O domicílio do casal será escolhido por ambos os cônjuges, mas um e outro podem ausentar-se do domicílio conjugal para atender a encargos públicos, ao exercício de sua profissão, ou a interesses particulares relevantes."]],["CC, art. 1.570",["Art. 1.570. Se qualquer dos cônjuges estiver em lugar remoto ou não sabido, encarcerado por mais de cento e oitenta dias, interditado judicialmente ou privado, episodicamente, de consciência, em virtude de enfermidade ou de acidente, o outro exercerá com exclusividade a direção da família, cabendo-lhe a administração dos bens."]],["CC, art. 1.571",["Art. 1.571. A sociedade conjugal termina:","I - pela morte de um dos cônjuges;","II – pela nulidade ou anulação do casamento;","III - pela separação judicial;","IV - pelo divórcio.","§ 1º O casamento válido só se dissolve pela morte de um dos cônjuges ou pelo divórcio, aplicando-se a presunção estabelecida neste Código quanto ao ausente.","§ 2º Dissolvido o casamento pelo divórcio direto ou por conversão, o cônjuge poderá manter o nome de casado; salvo, no segundo caso, dispondo em contrário a sentença de separação judicial."]],["CC, art. 1.572",["Art. 1.572. Qualquer dos cônjuges poderá propor a ação de separação judicial, imputando ao outro qualquer ato que importe grave violação dos deveres do casamento e torne insuportável a vida em comum.","§ 1º A separação judicial pode também ser pedida se um dos cônjuges provar ruptura da vida em comum há mais de um ano e a impossibilidade de sua reconstituição.","§ 2º O cônjuge pode ainda pedir a separação judicial quando o outro estiver acometido de doença mental grave, manifestada após o casamento, que torne impossível a continuação da vida em comum, desde que, após uma duração de dois anos, a enfermidade tenha sido reconhecida de cura improvável.","§ 3º No caso do parágrafo 2 o , reverterão ao cônjuge enfermo, que não houver pedido a separação judicial, os remanescentes dos bens que levou para o casamento, e se o regime dos bens adotado o permitir, a meação dos adquiridos na constância da sociedade conjugal."]],["CC, art. 1.573",["Art. 1.573. Podem caracterizar a impossibilidade da comunhão de vida a ocorrência de algum dos seguintes motivos:","I – adultério;","II - tentativa de morte;","III - sevícia ou injúria grave;","IV - abandono voluntário do lar conjugal, durante um ano contínuo;","V - condenação por crime infamante;","VI - conduta desonrosa.","Parágrafo único. O juiz poderá considerar outros fatos que tornem evidente a impossibilidade da vida em comum."]],["CC, art. 1.574",["Art. 1.574. Dar-se-á a separação judicial por mútuo consentimento dos cônjuges se forem casados por mais de um ano e o manifestarem perante o juiz, sendo por ele devidamente homologada a convenção.","Parágrafo único. O juiz pode recusar a homologação e não decretar a separação judicial se apurar que a convenção não preserva suficientemente os interesses dos filhos ou de um dos cônjuges."]],["CC, art. 1.575",["Art. 1.575. A sentença de separação judicial importa a separação de corpos e a partilha de bens.","Parágrafo único. A partilha de bens poderá ser feita mediante proposta dos cônjuges e homologada pelo juiz ou por este decidida."]],["CC, art. 1.576",["Art. 1.576. A separação judicial põe termo aos deveres de coabitação e fidelidade recíproca e ao regime de bens.","Parágrafo único. O procedimento judicial da separação caberá somente aos cônjuges, e, no caso de incapacidade, serão representados pelo curador, pelo ascendente ou pelo irmão."]],["CC, art. 1.577",["Art. 1.577. Seja qual for a causa da separação judicial e o modo como esta se faça, é lícito aos cônjuges restabelecer, a todo tempo, a sociedade conjugal, por ato regular em juízo.","Parágrafo único. A reconciliação em nada prejudicará o direito de terceiros, adquirido antes e durante o estado de separado, seja qual for o regime de bens."]],["CC, art. 1.578",["Art. 1.578. O cônjuge declarado culpado na ação de separação judicial perde o direito de usar o sobrenome do outro, desde que expressamente requerido pelo cônjuge inocente e se a alteração não acarretar:","I - evidente prejuízo para a sua identificação;","II - manifesta distinção entre o seu nome de família e o dos filhos havidos da união dissolvida;","III - dano grave reconhecido na decisão judicial.","§ 1º O cônjuge inocente na ação de separação judicial poderá renunciar, a qualquer momento, ao direito de usar o sobrenome do outro.","§ 2º Nos demais casos caberá a opção pela conservação do nome de casado."]],["CC, art. 1.579",["Art. 1.579. O divórcio não modificará os direitos e deveres dos pais em relação aos filhos.","Parágrafo único. Novo casamento de qualquer dos pais, ou de ambos, não poderá importar restrições aos direitos e deveres previstos neste artigo."]],["CC, art. 1.580",["Art. 1.580. Decorrido um ano do trânsito em julgado da sentença que houver decretado a separação judicial, ou da decisão concessiva da medida cautelar de separação de corpos, qualquer das partes poderá requerer sua conversão em divórcio.","§ 1º A conversão em divórcio da separação judicial dos cônjuges será decretada por sentença, da qual não constará referência à causa que a determinou.","§ 2º O divórcio poderá ser requerido, por um ou por ambos os cônjuges, no caso de comprovada separação de fato por mais de dois anos."]],["CC, art. 1.581",["Art. 1.581. O divórcio pode ser concedido sem que haja prévia partilha de bens."]],["CC, art. 1.582",["Art. 1.582. O pedido de divórcio somente competirá aos cônjuges.","Parágrafo único. Se o cônjuge for incapaz para propor a ação ou defender-se, poderá fazê-lo o curador, o ascendente ou o irmão."]],["CF/88, art. 226",["Art. 226. A família, base da sociedade, tem especial proteção do Estado.","[…]","§ 6º O casamento civil pode ser dissolvido pelo divórcio."]]],"5":[["CC, art. 1.591",["Art. 1.591. São parentes em linha reta as pessoas que estão umas para com as outras na relação de ascendentes e descendentes."]],["CC, art. 1.592",["Art. 1.592. São parentes em linha colateral ou transversal, até o quarto grau, as pessoas provenientes de um só tronco, sem descenderem uma da outra."]],["CC, art. 1.593",["Art. 1.593. O parentesco é natural ou civil, conforme resulte de consangüinidade ou outra origem."]],["CC, art. 1.594",["Art. 1.594. Contam-se, na linha reta, os graus de parentesco pelo número de gerações, e, na colateral, também pelo número delas, subindo de um dos parentes até ao ascendente comum, e descendo até encontrar o outro parente."]],["CC, art. 1.595",["Art. 1.595. Cada cônjuge ou companheiro é aliado aos parentes do outro pelo vínculo da afinidade.","§ 1º O parentesco por afinidade limita-se aos ascendentes, aos descendentes e aos irmãos do cônjuge ou companheiro.","§ 2º Na linha reta, a afinidade não se extingue com a dissolução do casamento ou da união estável."]]],"6":[["CF/88, art. 227",["Art. 227 É dever da família, da sociedade e do Estado assegurar à criança, ao adolescente e ao jovem, com absoluta prioridade, o direito à vida, à saúde, à alimentação, à educação, ao lazer, à profissionalização, à cultura, à dignidade, ao respeito, à liberdade e à convivência familiar e comunitária, além de colocá-los a salvo de toda forma de negligência, discriminação, exploração, violência, crueldade e opressão.","§ 1º O Estado promoverá programas de assistência integral à saúde da criança, do adolescente e do jovem, admitida a participação de entidades não governamentais, mediante políticas específicas e obedecendo aos seguintes preceitos:","I - aplicação de percentual dos recursos públicos destinados à saúde na assistência materno-infantil;","II - criação de programas de prevenção e atendimento especializado para as pessoas portadoras de deficiência física, sensorial ou mental, bem como de integração social do adolescente e do jovem portador de deficiência, mediante o treinamento para o trabalho e a convivência, e a facilitação do acesso aos bens e serviços coletivos, com a eliminação de obstáculos arquitetônicos e de todas as formas de discriminação.","§ 2º A lei disporá sobre normas de construção dos logradouros e dos edifícios de uso público e de fabricação de veículos de transporte coletivo, a fim de garantir acesso adequado às pessoas portadoras de deficiência.","§ 3º O direito a proteção especial abrangerá os seguintes aspectos:","I - idade mínima de quatorze anos para admissão ao trabalho, observado o disposto no art. 7º, XXXIII;","II - garantia de direitos previdenciários e trabalhistas;","III - garantia de acesso do trabalhador adolescente e jovem à escola;","IV - garantia de pleno e formal conhecimento da atribuição de ato infracional, igualdade na relação processual e defesa técnica por profissional habilitado, segundo dispuser a legislação tutelar específica;","V - obediência aos princípios de brevidade, excepcionalidade e respeito à condição peculiar de pessoa em desenvolvimento, quando da aplicação de qualquer medida privativa da liberdade;","VI - estímulo do poder público, através de assistência jurídica, incentivos fiscais e subsídios, nos termos da lei, ao acolhimento, sob a forma de guarda, de criança ou adolescente órfão ou abandonado;","VII - programas de prevenção e atendimento especializado à criança, ao adolescente e ao jovem dependente de entorpecentes e drogas afins.","§ 4º A lei punirá severamente o abuso, a violência e a exploração sexual da criança e do adolescente.","§ 5º A adoção será assistida pelo poder público, na forma da lei, que estabelecerá casos e condições de sua efetivação por parte de estrangeiros.","§ 6º Os filhos, havidos ou não da relação do casamento, ou por adoção, terão os mesmos direitos e qualificações, proibidas quaisquer designações discriminatórias relativas à filiação.","§ 7º No atendimento dos direitos da criança e do adolescente levar-se-á em consideração o disposto no art. 204.","§ 8º A lei estabelecerá:","I - o estatuto da juventude, destinado a regular os direitos dos jovens;","II - o plano nacional de juventude, de duração decenal, visando à articulação das várias esferas do poder público para a execução de políticas públicas."]],["CC, art. 1.596",["Art. 1.596. Os filhos, havidos ou não da relação de casamento, ou por adoção, terão os mesmos direitos e qualificações, proibidas quaisquer designações discriminatórias relativas à filiação."]],["CC, art. 1.597",["Art. 1.597. Presumem-se concebidos na constância do casamento os filhos:","I - nascidos cento e oitenta dias, pelo menos, depois de estabelecida a convivência conjugal;","II - nascidos nos trezentos dias subsequentes à dissolução da sociedade conjugal, por morte, separação judicial, nulidade e anulação do casamento;","III - havidos por fecundação artificial homóloga, mesmo que falecido o marido;","IV - havidos, a qualquer tempo, quando se tratar de embriões excedentários, decorrentes de concepção artificial homóloga;","V - havidos por inseminação artificial heteróloga, desde que tenha prévia autorização do marido."]],["CC, art. 1.598",["Art. 1.598. Salvo prova em contrário, se, antes de decorrido o prazo previsto no inciso II do art. 1.523, a mulher contrair novas núpcias e lhe nascer algum filho, este se presume do primeiro marido, se nascido dentro dos trezentos dias a contar da data do falecimento deste e, do segundo, se o nascimento ocorrer após esse período e já decorrido o prazo a que se refere o inciso I do art. 1597."]],["CC, art. 1.599",["Art. 1.599. A prova da impotência do cônjuge para gerar, à época da concepção, ilide a presunção da paternidade."]],["CC, art. 1.600",["Art. 1.600. Não basta o adultério da mulher, ainda que confessado, para ilidir a presunção legal da paternidade."]],["CC, art. 1.601",["Art. 1.601. Cabe ao marido o direito de contestar a paternidade dos filhos nascidos de sua mulher, sendo tal ação imprescritível.","Parágrafo único. Contestada a filiação, os herdeiros do impugnante têm direito de prosseguir na ação."]],["CC, art. 1.602",["Art. 1.602. Não basta a confissão materna para excluir a paternidade."]],["CC, art. 1.603",["Art. 1.603. A filiação prova-se pela certidão do termo de nascimento registrada no Registro Civil."]],["CC, art. 1.604",["Art. 1.604. Ninguém pode vindicar estado contrário ao que resulta do registro de nascimento, salvo provando-se erro ou falsidade do registro."]],["CC, art. 1.605",["Art. 1.605. Na falta, ou defeito, do termo de nascimento, poderá provar-se a filiação por qualquer modo admissível em direito:","I - quando houver começo de prova por escrito, proveniente dos pais, conjunta ou separadamente;","II - quando existirem veementes presunções resultantes de fatos já certos."]],["CC, art. 1.606",["Art. 1.606. A ação de prova de filiação compete ao filho, enquanto viver, passando aos herdeiros, se ele morrer menor ou incapaz.","Parágrafo único. Se iniciada a ação pelo filho, os herdeiros poderão continuá-la, salvo se julgado extinto o processo."]],["CC, art. 1.607",["Art. 1.607. O filho havido fora do casamento pode ser reconhecido pelos pais, conjunta ou separadamente."]],["CC, art. 1.608",["Art. 1.608. Quando a maternidade constar do termo do nascimento do filho, a mãe só poderá contestá-la, provando a falsidade do termo, ou das declarações nele contidas."]],["CC, art. 1.609",["Art. 1.609. O reconhecimento dos filhos havidos fora do casamento é irrevogável e será feito:","I - no registro do nascimento;","II - por escritura pública ou escrito particular, a ser arquivado em cartório;","III - por testamento, ainda que incidentalmente manifestado;","IV - por manifestação direta e expressa perante o juiz, ainda que o reconhecimento não haja sido o objeto único e principal do ato que o contém.","Parágrafo único. O reconhecimento pode preceder o nascimento do filho ou ser posterior ao seu falecimento, se ele deixar descendentes."]],["CC, art. 1.610",["Art. 1.610. O reconhecimento não pode ser revogado, nem mesmo quando feito em testamento."]],["CC, art. 1.611",["Art. 1.611. O filho havido fora do casamento, reconhecido por um dos cônjuges, não poderá residir no lar conjugal sem o consentimento do outro."]],["CC, art. 1.612",["Art. 1.612. O filho reconhecido, enquanto menor, ficará sob a guarda do genitor que o reconheceu, e, se ambos o reconheceram e não houver acordo, sob a de quem melhor atender aos interesses do menor."]],["CC, art. 1.613",["Art. 1.613. São ineficazes a condição e o termo apostos ao ato de reconhecimento do filho."]],["CC, art. 1.614",["Art. 1.614. O filho maior não pode ser reconhecido sem o seu consentimento, e o menor pode impugnar o reconhecimento, nos quatro anos que se seguirem à maioridade, ou à emancipação."]],["CC, art. 1.615",["Art. 1.615. Qualquer pessoa, que justo interesse tenha, pode contestar a ação de investigação de paternidade, ou maternidade."]],["CC, art. 1.616",["Art. 1.616. A sentença que julgar procedente a ação de investigação produzirá os mesmos efeitos do reconhecimento; mas poderá ordenar que o filho se crie e eduque fora da companhia dos pais ou daquele que lhe contestou essa qualidade."]],["CC, art. 1.617",["Art. 1.617. A filiação materna ou paterna pode resultar de casamento declarado nulo, ainda mesmo sem as condições do putativo."]]],"8":[["CC, art. 1.630",["Art. 1.630. Os filhos estão sujeitos ao poder familiar, enquanto menores."]],["CC, art. 1.631",["Art. 1.631. Durante o casamento e a união estável, compete o poder familiar aos pais; na falta ou impedimento de um deles, o outro o exercerá com exclusividade.","Parágrafo único. Divergindo os pais quanto ao exercício do poder familiar, é assegurado a qualquer deles recorrer ao juiz para solução do desacordo."]],["CC, art. 1.632",["Art. 1.632. A separação judicial, o divórcio e a dissolução da união estável não alteram as relações entre pais e filhos senão quanto ao direito, que aos primeiros cabe, de terem em sua companhia os segundos."]],["CC, art. 1.633",["Art. 1.633. O filho, não reconhecido pelo pai, fica sob poder familiar exclusivo da mãe; se a mãe não for conhecida ou capaz de exercê-lo, dar-se-á tutor ao menor."]],["CC, art. 1.634",["Art. 1.634. Compete a ambos os pais, qualquer que seja a sua situação conjugal, o pleno exercício do poder familiar, que consiste em, quanto aos filhos: (“Caput” do artigo com redação dada pela Lei nº 13.058, de 22/12/2014)","I - dirigir-lhes a criação e a educação; (Inciso com redação dada pela Lei nº 13.058, de 22/12/2014)","II - exercer a guarda unilateral ou compartilhada nos termos do art. 1.584; (Inciso com redação dada pela Lei nº 13.058, de 22/12/2014)","III - conceder-lhes ou negar-lhes consentimento para casarem; (Inciso com redação dada pela Lei nº 13.058, de 22/12/2014)","IV - conceder-lhes ou negar-lhes consentimento para viajarem ao exterior; (Inciso acrescido pela Lei nº 13.058, de 22/12/2014)","V - conceder-lhes ou negar-lhes consentimento para mudarem sua residência permanente para outro Município; (Inciso acrescido pela Lei nº 13.058, de 22/12/2014)","VI - nomear-lhes tutor por testamento ou documento autêntico, se o outro dos pais não lhe sobreviver, ou o sobrevivo não puder exercer o poder familiar; (Primitivo inciso IV renumerado pela Lei nº 13.058, de 22/12/2014)","VII - representá-los judicial e extrajudicialmente até os 16 (dezesseis) anos, nos atos da vida civil, e assisti-los, após essa idade, nos atos em que forem partes, suprindo-lhes o consentimento; (Primitivo inciso V renumerado e com redação dada pela Lei nº 13.058, de 22/12/2014)","VIII - reclamá-los de quem ilegalmente os detenha; (Primitivo inciso VI renumerado pela Lei nº 13.058, de 22/12/2014)","IX - exigir que lhes prestem obediência, respeito e os serviços próprios de sua idade e condição. (Primitivo inciso VII renumerado pela Lei nº 13.058, de 22/12/2014)"]],["CC, art. 1.635",["Art. 1.635. Extingue-se o poder familiar:","I - pela morte dos pais ou do filho;","II - pela emancipação, nos termos do art. 5 o , parágrafo único;","III - pela maioridade;","IV - pela adoção;","V - por decisão judicial, na forma do artigo 1.638."]],["CC, art. 1.636",["Art 1.636. O pai ou a mãe que contrai novas núpcias, ou estabelece união estável, não perde, quanto aos filhos do relacionamento anterior, os direitos ao poder familiar, exercendo-os sem qualquer interferência do novo cônjuge ou companheiro.","Parágrafo único. Igual preceito ao estabelecido neste artigo aplica-se ao pai ou à mãe solteiros que casarem ou estabelecerem união estável."]],["CC, art. 1.637",["Art. 1.637. Se o pai, ou a mãe, abusar de sua autoridade, faltando aos deveres a eles inerentes ou arruinando os bens dos filhos, cabe ao juiz, requerendo algum parente, ou o Ministério Público, adotar a medida que lhe pareça reclamada pela segurança do menor e seus haveres, até suspendendo o poder familiar, quando convenha.","Parágrafo único. Suspende-se igualmente o exercício do poder familiar ao pai ou à mãe condenados por sentença irrecorrível, em virtude de crime cuja pena exceda a dois anos de prisão."]],["CC, art. 1.638",["Art. 1.638. Perderá por ato judicial o poder familiar o pai ou a mãe que:","I - castigar imoderadamente o filho;","II - deixar o filho em abandono;","III - praticar atos contrários à moral e aos bons costumes;","IV - incidir, reiteradamente, nas faltas previstas no artigo antecedente;","V - entregar de forma irregular o filho a terceiros para fins de adoção. (Inciso acrescido pela Lei nº 13.509, de 22/11/2017)","Parágrafo único. Perderá também por ato judicial o poder familiar aquele que:","I - praticar contra outrem igualmente titular do mesmo poder familiar:","a) homicídio, feminicídio ou lesão corporal de natureza grave ou seguida de morte, quando se tratar de crime doloso envolvendo violência doméstica e familiar ou menosprezo ou discriminação à condição de mulher;","b) estupro ou outro crime contra a dignidade sexual sujeito à pena de reclusão;","II - praticar contra filho, filha ou outro descendente:","a) homicídio, feminicídio ou lesão corporal de natureza grave ou seguida de morte, quando se tratar de crime doloso envolvendo violência doméstica e familiar ou menosprezo ou discriminação à condição de mulher;","b) estupro, estupro de vulnerável ou outro crime contra a dignidade sexual sujeito à pena de reclusão. (Parágrafo único acrescido pela Lei nº 13.715, de 24/9/2018)"]]],"9":[["CC, art. 1.583",["Art. 1.583 A guarda será unilateral ou compartilhada. (“Caput” do artigo com redação dada pela Lei nº 11.698, de 13/6/2008, publicada no DOU de 16/6/2008, em vigor 60 dias após sua publicação)","§ 1º Compreende-se por guarda unilateral a atribuída a um só dos genitores ou a alguém que o substitua (art. 1.584, § 5º) e, por guarda compartilhada a responsabilização conjunta e o exercício de direitos e deveres do pai e da mãe que não vivam sob o mesmo teto, concernentes ao poder familiar dos filhos comuns. (Parágrafo acrescido pela Lei nº 11.698, de 13/6/2008, publicada no DOU de 16/6/2008, em vigor 60 dias após sua publicação)","§ 2º Na guarda compartilhada, o tempo de convívio com os filhos deve ser dividido de forma equilibrada com a mãe e com o pai, sempre tendo em vista as condições fáticas e os interesses dos filhos. (Parágrafo acrescido pela Lei nº 11.698, de 13/6/2008, com redação dada pela Lei nº 13.058, de 22/12/2014)","I - (Inciso acrescido pela Lei nº 11.698, de 13/6/2008, e revogado pela Lei nº 13.058, de 22/12/2014)","II - (Inciso acrescido pela Lei nº 11.698, de 13/6/2008, e revogado pela Lei nº 13.058, de 22/12/2014)","III - (Inciso acrescido pela Lei nº 11.698, de 13/6/2008, e revogado pela Lei nº 13.058, de 22/12/2014)","§ 3º Na guarda compartilhada, a cidade considerada base de moradia dos filhos será aquela que melhor atender aos interesses dos filhos. (Parágrafo acrescido pela Lei nº 11.698, de 13/6/2008, com redação dada pela Lei nº 13.058, de 22/12/2014)","§ 4º (VETADO na Lei nº 11.698, de 13/6/2008, publicada no DOU de 16/6/2008, em vigor 60 dias após sua publicação)","§ 5º A guarda unilateral obriga o pai ou a mãe que não a detenha a supervisionar os interesses dos filhos, e, para possibilitar tal supervisão, qualquer dos genitores sempre será parte legítima para solicitar informações e/ou prestação de contas, objetivas ou subjetivas, em assuntos ou situações que direta ou indiretamente afetem a saúde física e psicológica e a educação de seus filhos. (Parágrafo acrescido pela Lei nº 13.058, de 22/12/2014)"]],["CC, art. 1.584",["Art. 1.584 A guarda, unilateral ou compartilhada, poderá ser: (“Caput” do artigo com redação dada pela Lei nº 11.698, de 13/6/2008, publicada no DOU de 16/6/2008, em vigor 60 dias após sua publicação)","I - requerida, por consenso, pelo pai e pela mãe, ou por qualquer deles, em ação autônoma de separação, de divórcio, de dissolução de união estável ou em medida cautelar; (Inciso acrescido pela Lei nº 11.698, de 13/6/2008, publicada no DOU de 16/6/2008, em vigor 60 dias após sua publicação)","II - decretada pelo juiz, em atenção a necessidades específicas do filho, ou em razão da distribuição de tempo necessário ao convívio deste com o pai e com a mãe. (Inciso acrescido pela Lei nº 11.698, de 13/6/2008, publicada no DOU de 16/6/2008, em vigor 60 dias após sua publicação)","§ 1º Na audiência de conciliação, o juiz informará ao pai e à mãe o significado da guarda compartilhada, a sua importância, a similitude de deveres e direitos atribuídos aos genitores e as sanções pelo descumprimento de suas cláusulas. (Parágrafo acrescido pela Lei nº 11.698, de 13/6/2008, publicada no DOU de 16/6/2008, em vigor 60 dias após sua publicação)","§ 2º Quando não houver acordo entre a mãe e o pai quanto à guarda do filho, encontrando-se ambos os genitores aptos a exercer o poder familiar, será aplicada a guarda compartilhada, salvo se um dos genitores declarar ao magistrado que não deseja a guarda da criança ou do adolescente ou quando houver elementos que evidenciem a probabilidade de risco de violência doméstica ou familiar. (Parágrafo acrescido pela Lei nº 11.698, de 13/6/2008, e com nova redação dada pela Lei nº 14.713, de 30/10/2023)","§ 3º Para estabelecer as atribuições do pai e da mãe e os períodos de convivência sob guarda compartilhada, o juiz, de ofício ou a requerimento do Ministério Público, poderá basear-se em orientação técnico-profissional ou de equipe interdisciplinar, que deverá visar à divisão equilibrada do tempo com o pai e com a mãe. (Parágrafo acrescido pela Lei nº 11.698, de 13/6/2008, com redação dada pela Lei nº 13.058, de 22/12/2014)","§ 4º A alteração não autorizada ou o descumprimento imotivado de cláusula de guarda unilateral ou compartilhada poderá implicar a redução de prerrogativas atribuídas ao seu detentor. (Parágrafo acrescido pela Lei nº 11.698, de 13/6/2008, com redação dada pela Lei nº 13.058, de 22/12/2014)","§ 5º Se o juiz verificar que o filho não deve permanecer sob a guarda do pai ou da mãe, deferirá a guarda a pessoa que revele compatibilidade com a natureza da medida, considerados, de preferência, o grau de parentesco e as relações de afinidade e afetividade. (Parágrafo acrescido pela Lei nº 11.698, de 13/6/2008, com redação dada pela Lei nº 13.058, de 22/12/2014)","§ 6º Qualquer estabelecimento público ou privado é obrigado a prestar informações a qualquer dos genitores sobre os filhos destes, sob pena de multa de R$ 200,00 (duzentos reais) a R$ 500,00 (quinhentos reais) por dia pelo não atendimento da solicitação. (Parágrafo acrescido pela Lei nº 13.058, de 22/12/2014)"]],["CPC, art. 699-A",["Art. 699-A. Nas ações de guarda, antes de iniciada a audiência de mediação e conciliação de que trata o art. 695 deste Código, o juiz indagará às partes e ao Ministério Público se há risco de violência doméstica ou familiar, fixando o prazo de 5 (cinco) dias para a apresentação de prova ou de indícios pertinentes. (Artigo acrescido pela Lei nº 14.713, de 30/10/2023)"]]],"11":[["CC, art. 1.667",["Art. 1.667. O regime de comunhão universal importa a comunicação de todos os bens presentes e futuros dos cônjuges e suas dívidas passivas, com as exceções do artigo seguinte."]],["CC, art. 1.668",["Art. 1.668. São excluídos da comunhão:","I - os bens doados ou herdados com a cláusula de incomunicabilidade e os sub-rogados em seu lugar;","II - os bens gravados de fideicomisso e o direito do herdeiro fideicomissário, antes de realizada a condição suspensiva;","III - as dívidas anteriores ao casamento, salvo se provierem de despesas com seus aprestos, ou reverterem em proveito comum;","IV - as doações antenupciais feitas por um dos cônjuges ao outro com a cláusula de incomunicabilidade;","V - Os bens referidos nos incisos V a VII do art. 1.659."]],["CC, art. 1.669",["Art. 1.669. A incomunicabilidade dos bens enumerados no artigo antecedente não se estende aos frutos, quando se percebam ou vençam durante o casamento."]],["CC, art. 1.670",["Art. 1.670. Aplica-se ao regime da comunhão universal o disposto no Capítulo antecedente, quanto à administração dos bens."]],["CC, art. 1.671",["Art. 1.671. Extinta a comunhão, e efetuada a divisão do ativo e do passivo, cessará a responsabilidade de cada um dos cônjuges para com os credores do outro."]],["CC, art. 1.672",["Art. 1.672. No regime de participação final nos aqüestos, cada cônjuge possui patrimônio próprio, consoante disposto no artigo seguinte, e lhe cabe, à época da dissolução da sociedade conjugal, direito à metade dos bens adquiridos pelo casal, a título oneroso, na constância do casamento."]],["CC, art. 1.673",["Art. 1.673. Integram o patrimônio próprio os bens que cada cônjuge possuía ao casar e os por ele adquiridos, a qualquer título, na constância do casamento.","Parágrafo único. A administração desses bens é exclusiva de cada cônjuge, que os poderá livremente alienar, se forem móveis."]],["CC, art. 1.674",["Art. 1.674. Sobrevindo a dissolução da sociedade conjugal, apurar-se-á o montante dos aqüestos, excluindo-se da soma dos patrimônios próprios:","I - os bens anteriores ao casamento e os que em seu lugar se sub-rogaram;","II - os que sobrevieram a cada cônjuge por sucessão ou liberalidade;","III - as dívidas relativas a esses bens.","Parágrafo único. Salvo prova em contrário, presumem-se adquiridos durante o casamento os bens móveis."]],["CC, art. 1.675",["Art. 1.675. Ao determinar-se o montante dos aqüestos, computar-se-á o valor das doações feitas por um dos cônjuges, sem a necessária autorização do outro; nesse caso, o bem poderá ser reivindicado pelo cônjuge prejudicado ou por seus herdeiros, ou declarado no monte partilhável, por valor equivalente ao da época da dissolução."]],["CC, art. 1.676",["Art. 1.676. Incorpora-se ao monte o valor dos bens alienados em detrimento da meação, se não houver preferência do cônjuge lesado, ou de seus herdeiros, de os reivindicar."]],["CC, art. 1.677",["Art. 1.677. Pelas dívidas posteriores ao casamento, contraídas por um dos cônjuges, somente este responderá, salvo prova de terem revertido, parcial ou totalmente, em benefício do outro."]],["CC, art. 1.678",["Art. 1.678. Se um dos cônjuges solveu uma dívida do outro com bens do seu patrimônio, o valor do pagamento deve ser atualizado e imputado, na data da dissolução, à meação do outro cônjuge."]],["CC, art. 1.679",["Art. 1.679. No caso de bens adquiridos pelo trabalho conjunto, terá cada um dos cônjuges uma quota igual no condomínio ou no crédito por aquele modo estabelecido."]],["CC, art. 1.680",["Art. 1.680. As coisas móveis, em face de terceiros, presumem-se do domínio do cônjuge devedor, salvo se o bem for de uso pessoal do outro."]],["CC, art. 1.681",["Art. 1.681. Os bens imóveis são de propriedade do cônjuge cujo nome constar no registro.","Parágrafo único. Impugnada a titularidade, caberá ao cônjuge proprietário provar a aquisição regular dos bens."]],["CC, art. 1.682",["Art. 1.682. O direito à meação não é renunciável, cessível ou penhorável na vigência do regime matrimonial."]],["CC, art. 1.683",["Art. 1.683. Na dissolução do regime de bens por separação judicial ou por divórcio, verificar-se-á o montante dos aqüestos à data em que cessou a convivência."]],["CC, art. 1.684",["Art. 1.684. Se não for possível nem conveniente a divisão de todos os bens em natureza, calcular-se-á o valor de alguns ou de todos para reposição em dinheiro ao cônjuge não-proprietário.","Parágrafo único. Não se podendo realizar a reposição em dinheiro, serão avaliados e, mediante autorização judicial, alienados tantos bens quantos bastarem."]],["CC, art. 1.685",["Art. 1.685. Na dissolução da sociedade conjugal por morte, verificar-se-á a meação do cônjuge sobrevivente de conformidade com os artigos antecedentes, deferindo-se a herança aos herdeiros na forma estabelecida neste Código."]],["CC, art. 1.686",["Art. 1.686. As dívidas de um dos cônjuges, quando superiores à sua meação, não obrigam ao outro, ou a seus herdeiros."]],["CC, art. 1.687",["Art. 1.687. Estipulada a separação de bens, estes permanecerão sob a administração exclusiva de cada um dos cônjuges, que os poderá livremente alienar ou gravar de ônus real."]],["CC, art. 1.688",["Art. 1.688. Ambos os cônjuges são obrigados a contribuir para as despesas do casal na proporção dos rendimentos de seu trabalho e de seus bens, salvo estipulação em contrário no pacto antenupcial."]]],"12":[["CC, art. 1.641",["Art. 1.641. É obrigatório o regime da separação de bens no casamento:","[…]","II - da pessoa maior de 70 (setenta) anos; (Inciso com redação dada pela Lei nº 12.344, de 9/12/2010)"]]],"13":[["CC, art. 1.694",["Art. 1.694. Podem os parentes, os cônjuges ou companheiros pedir uns aos outros os alimentos de que necessitem para viver de modo compatível com a sua condição social, inclusive para atender às necessidades de sua educação.","§ 1º Os alimentos devem ser fixados na proporção das necessidades do reclamante e dos recursos da pessoa obrigada.","§ 2º Os alimentos serão apenas os indispensáveis à subsistência, quando a situação de necessidade resultar de culpa de quem os pleiteia."]],["CC, art. 1.695",["Art. 1.695. São devidos os alimentos quando quem os pretende não tem bens suficientes, nem pode prover, pelo seu trabalho, à própria mantença, e aquele, de quem se reclamam, pode fornecê-los, sem desfalque do necessário ao seu sustento."]],["CC, art. 1.696",["Art. 1.696. O direito à prestação de alimentos é recíproco entre pais e filhos, e extensivo a todos os ascendentes, recaindo a obrigação nos mais próximos em grau, uns em falta de outros."]],["CC, art. 1.697",["Art. 1.697. Na falta dos ascendentes cabe a obrigação aos descendentes, guardada a ordem de sucessão e, faltando estes, aos irmãos, assim germanos como unilaterais."]],["CC, art. 1.698",["Art. 1.698. Se o parente, que deve alimentos em primeiro lugar, não estiver em condições de suportar totalmente o encargo, serão chamados a concorrer os de grau imediato; sendo várias as pessoas obrigadas a prestar alimentos, todas devem concorrer na proporção dos respectivos recursos, e, intentada ação contra uma delas, poderão as demais ser chamadas a integrar a lide."]],["CC, art. 1.699",["Art. 1.699. Se, fixados os alimentos, sobrevier mudança na situação financeira de quem os supre, ou na de quem os recebe, poderá o interessado reclamar ao juiz, conforme as circunstâncias, exoneração, redução ou majoração do encargo."]],["CC, art. 1.700",["Art. 1.700. A obrigação de prestar alimentos transmite-se aos herdeiros do devedor, na forma do art. 1.694."]],["CC, art. 1.701",["Art. 1.701. A pessoa obrigada a suprir alimentos poderá pensionar o alimentando, ou dar-lhe hospedagem e sustento, sem prejuízo do dever de prestar o necessário à sua educação, quando menor.","Parágrafo único. Compete ao juiz, se as circunstâncias o exigirem, fixar a forma do cumprimento da prestação."]],["CC, art. 1.702",["Art. 1.702. Na separação judicial litigiosa, sendo um dos cônjuges inocente e desprovido de recursos, prestar-lhe-á o outro a pensão alimentícia que o juiz fixar, obedecidos os critérios estabelecidos no art. 1.694."]],["CC, art. 1.703",["Art. 1.703. Para a manutenção dos filhos, os cônjuges separados judicialmente contribuirão na proporção de seus recursos."]],["CC, art. 1.704",["Art. 1.704. Se um dos cônjuges separados judicialmente vier a necessitar de alimentos, será o outro obrigado a prestá-los mediante pensão a ser fixada pelo juiz, caso não tenha sido declarado culpado na ação de separação judicial.","Parágrafo único. Se o cônjuge declarado culpado vier a necessitar de alimentos, e não tiver parentes em condições de prestá-los, nem aptidão para o trabalho, o outro cônjuge será obrigado a assegurá-los, fixando o juiz o valor indispensável à sobrevivência."]],["CC, art. 1.705",["Art. 1.705. Para obter alimentos, o filho havido fora do casamento pode acionar o genitor, sendo facultado ao juiz determinar, a pedido de qualquer das partes, que a ação se processe em segredo de justiça."]],["CC, art. 1.706",["Art. 1.706. Os alimentos provisionais serão fixados pelo juiz, nos termos da lei processual."]],["CC, art. 1.707",["Art. 1.707. Pode o credor não exercer, porém lhe é vedado renunciar o direito a alimentos, sendo o respectivo crédito insuscetível de cessão, compensação ou penhora."]],["CC, art. 1.708",["Art. 1.708. Com o casamento, a união estável ou o concubinato do credor, cessa o dever de prestar alimentos.","Parágrafo único. Com relação ao credor cessa, também, o direito a alimentos, se tiver procedimento indigno em relação ao devedor."]],["CC, art. 1.709",["Art. 1.709. O novo casamento do cônjuge devedor não extingue a obrigação constante da sentença de divórcio."]],["CC, art. 1.710",["Art. 1.710. As prestações alimentícias, de qualquer natureza, serão atualizadas segundo índice oficial regularmente estabelecido."]]],"14":[["CC, art. 1.711",["Art. 1.711. Podem os cônjuges, ou a entidade familiar, mediante escritura pública ou testamento, destinar parte de seu patrimônio para instituir bem de família, desde que não ultrapasse um terço do patrimônio líquido existente ao tempo da instituição, mantidas as regras sobre a impenhorabilidade do imóvel residencial estabelecida em lei especial.","Parágrafo único. O terceiro poderá igualmente instituir bem de família por testamento ou doação, dependendo a eficácia do ato da aceitação expressa de ambos os cônjuges beneficiados ou da entidade familiar beneficiada."]],["CC, art. 1.712",["Art. 1.712. O bem de família consistirá em prédio residencial urbano ou rural, com suas pertenças e acessórios, destinando-se em ambos os casos a domicílio familiar, e poderá abranger valores mobiliários, cuja renda será aplicada na conservação do imóvel e no sustento da família."]],["CC, art. 1.713",["Art. 1.713. Os valores mobiliários, destinados aos fins previstos no artigo antecedente, não poderão exceder o valor do prédio instituído em bem de família, à época de sua instituição.","§ 1º Deverão os valores mobiliários ser devidamente individualizados no instrumento de instituição do bem de família.","§ 2º Se se tratar de títulos nominativos, a sua instituição como bem de família deverá constar dos respectivos livros de registro.","§ 3º O instituidor poderá determinar que a administração dos valores mobiliários seja confiada a instituição financeira, bem como disciplinar a forma de pagamento da respectiva renda aos beneficiários, caso em que a responsabilidade dos administradores obedecerá às regras do contrato de depósito."]],["CC, art. 1.714",["Art. 1.714. O bem de família, quer instituído pelos cônjuges ou por terceiro, constitui-se pelo registro de seu título no Registro de Imóveis."]],["CC, art. 1.715",["Art. 1.715. O bem de família é isento de execução por dívidas posteriores à sua instituição, salvo as que provierem de tributos relativos ao prédio, ou de despesas de condomínio.","Parágrafo único. No caso de execução pelas dívidas referidas neste artigo, o saldo existente será aplicado em outro prédio, como bem de família, ou em títulos da dívida pública, para sustento familiar, salvo se motivos relevantes aconselharem outra solução, a critério do juiz."]],["CC, art. 1.716",["Art. 1.716. A isenção de que trata o artigo antecedente durará enquanto viver um dos cônjuges, ou, na falta destes, até que os filhos completem a maioridade."]],["CC, art. 1.717",["Art. 1.717. O prédio e os valores mobiliários, constituídos como bem da família, não podem ter destino diverso do previsto no art. 1.712 ou serem alienados sem o consentimento dos interessados e seus representantes legais, ouvido o Ministério Público."]],["CC, art. 1.718",["Art. 1.718. Qualquer forma de liquidação da entidade administradora, a que se refere o § 3 o do art. 1.713, não atingirá os valores a ela confiados, ordenando o juiz a sua transferência para outra instituição semelhante, obedecendo-se, no caso de falência, ao disposto sobre pedido de restituição."]],["CC, art. 1.719",["Art. 1.719. Comprovada a impossibilidade da manutenção do bem de família nas condições em que foi instituído, poderá o juiz, a requerimento dos interessados, extingui-lo ou autorizar a sub-rogação dos bens que o constituem em outros, ouvidos o instituidor e o Ministério Público."]],["CC, art. 1.720",["Art. 1.720. Salvo disposição em contrário do ato de instituição, a administração do bem de família compete a ambos os cônjuges, resolvendo o juiz em caso de divergência.","Parágrafo único. Com o falecimento de ambos os cônjuges, a administração passará ao filho mais velho, se for maior, e, do contrário, a seu tutor."]],["CC, art. 1.721",["Art. 1.721. A dissolução da sociedade conjugal não extingue o bem de família.","Parágrafo único. Dissolvida a sociedade conjugal pela morte de um dos cônjuges, o sobrevivente poderá pedir a extinção do bem de família, se for o único bem do casal."]],["CC, art. 1.722",["Art. 1.722. Extingue-se, igualmente, o bem de família com a morte de ambos os cônjuges e a maioridade dos filhos, desde que não sujeitos a curatela."]]],"15":[["CC, art. 1.723",["Art. 1.723. É reconhecida como entidade familiar a união estável entre o homem e a mulher, configurada na convivência pública, contínua e duradoura e estabelecida com o objetivo de constituição de família. (Vide ADPF nº 132/2008 e ADIn nº 4.277/2009)","§ 1º A união estável não se constituirá se ocorrerem os impedimentos do art. 1.521; não se aplicando a incidência do inciso VI no caso de a pessoa casada se achar separada de fato ou judicialmente.","§ 2º As causas suspensivas do art. 1.523 não impedirão a caracterização da união estável."]],["CC, art. 1.724",["Art. 1.724. As relações pessoais entre os companheiros obedecerão aos deveres de lealdade, respeito e assistência, e de guarda, sustento e educação dos filhos."]],["CC, art. 1.725",["Art. 1.725. Na união estável, salvo contrato escrito entre os companheiros, aplica-se às relações patrimoniais, no que couber, o regime da comunhão parcial de bens."]],["CC, art. 1.726",["Art. 1.726. A união estável poderá converter-se em casamento, mediante pedido dos companheiros ao juiz e assento no Registro Civil."]],["CC, art. 1.727",["Art. 1.727. As relações não eventuais entre o homem e a mulher, impedidos de casar, constituem concubinato."]],["CF/88, art. 226",["Art. 226. A família, base da sociedade, tem especial proteção do Estado.","§ 1º O casamento é civil e gratuita a celebração.","§ 2º O casamento religioso tem efeito civil, nos termos da lei.","§ 3º Para efeito da proteção do Estado, é reconhecida a união estável entre o homem e a mulher como entidade familiar, devendo a lei facilitar sua conversão em casamento.","§ 4º Entende-se, também, como entidade familiar a comunidade formada por qualquer dos pais e seus descendentes.","§ 5º Os direitos e deveres referentes à sociedade conjugal são exercidos igualmente pelo homem e pela mulher.","§ 6º O casamento civil pode ser dissolvido pelo divórcio.","§ 7º Fundado nos princípios da dignidade da pessoa humana e da paternidade responsável, o planejamento familiar é livre decisão do casal, competindo ao Estado propiciar recursos educacionais e científicos para o exercício desse direito, vedada qualquer forma coercitiva por parte de instituições oficiais ou privadas.","§ 8º O Estado assegurará a assistência à família na pessoa de cada um dos que a integram, criando mecanismos para coibir a violência no âmbito de suas relações."]]]},"15":{"0":[["CC, art. 1.784",["Art. 1.784. Aberta a sucessão, a herança transmite-se, desde logo, aos herdeiros legítimos e testamentários."]],["CC, art. 1.785",["Art. 1.785. A sucessão abre-se no lugar do último domicílio do falecido."]],["CC, art. 1.786",["Art. 1.786. A sucessão dá-se por lei ou por disposição de última vontade."]],["CC, art. 1.787",["Art. 1.787. Regula a sucessão e a legitimação para suceder a lei vigente ao tempo da abertura daquela."]],["CC, art. 1.788",["Art. 1.788. Morrendo a pessoa sem testamento, transmite a herança aos herdeiros legítimos; o mesmo ocorrerá quanto aos bens que não forem compreendidos no testamento; e subsiste a sucessão legítima se o testamento caducar, ou for julgado nulo."]],["CC, art. 1.789",["Art. 1.789. Havendo herdeiros necessários, o testador só poderá dispor da metade da herança."]],["CC, art. 1.790",["Art. 1.790. A companheira ou o companheiro participará da sucessão do outro, quanto aos bens adquiridos onerosamente na vigência da união estável, nas condições seguintes:","I - se concorrer com filhos comuns, terá direito a uma quota equivalente à que por lei for atribuída ao filho;","II - se concorrer com descendentes só do autor da herança, tocar-lhe-á a metade do que couber a cada um daqueles;","III - se concorrer com outros parentes sucessíveis, terá direito a um terço da herança;","IV - não havendo parentes sucessíveis, terá direito à totalidade da herança."]],["CC, art. 1.791",["Art. 1.791. A herança defere-se como um todo unitário, ainda que vários sejam os herdeiros.","Parágrafo único. Até a partilha, o direito dos co-herdeiros, quanto à propriedade e posse da herança, será indivisível, e regular-se-á pelas normas relativas ao condomínio."]]],"1":[["CC, art. 1.784",["Art. 1.784. Aberta a sucessão, a herança transmite-se, desde logo, aos herdeiros legítimos e testamentários."]]],"2":[["CC, art. 1.791",["Art. 1.791. A herança defere-se como um todo unitário, ainda que vários sejam os herdeiros.","Parágrafo único. Até a partilha, o direito dos co-herdeiros, quanto à propriedade e posse da herança, será indivisível, e regular-se-á pelas normas relativas ao condomínio."]],["CC, art. 1.792",["Art. 1.792. O herdeiro não responde por encargos superiores às forças da herança; incumbe-lhe, porém, a prova do excesso, salvo se houver inventário que a escuse, demostrando o valor dos bens herdados."]],["CC, art. 1.793",["Art. 1.793. O direito à sucessão aberta, bem como o quinhão de que disponha o co-herdeiro, pode ser objeto de cessão por escritura pública.","§ 1º Os direitos, conferidos ao herdeiro em conseqüência de substituição ou de direito de acrescer, presumem-se não abrangidos pela cessão feita anteriormente.","§ 2º É ineficaz a cessão, pelo co-herdeiro, de seu direito hereditário sobre qualquer bem da herança considerado singularmente.","§ 3º Ineficaz é a disposição, sem prévia autorização do juiz da sucessão, por qualquer herdeiro, de bem componente do acervo hereditário, pendente a indivisibilidade."]],["CC, art. 1.794",["Art. 1.794. O co-herdeiro não poderá ceder a sua quota hereditária a pessoa estranha à sucessão, se outro co-herdeiro a quiser, tanto por tanto."]],["CC, art. 1.795",["Art. 1.795. O co-herdeiro, a quem não se der conhecimento da cessão, poderá, depositado o preço, haver para si a quota cedida a estranho, se o requerer até cento e oitenta dias após a transmissão.","Parágrafo único. Sendo vários os co-herdeiros a exercer a preferência, entre eles se distribuirá o quinhão cedido, na proporção das respectivas quotas hereditárias."]],["CC, art. 1.796",["Art. 1.796. No prazo de trinta dias, a contar da abertura da sucessão, instaurar-se-á inventário do patrimônio hereditário, perante o juízo competente no lugar da sucessão, para fins de liquidação e, quando for o caso, de partilha da herança."]],["CC, art. 1.797",["Art. 1.797. Até o compromisso do inventariante, a administração da herança caberá, sucessivamente:","I - ao cônjuge ou companheiro, se com o outro convivia ao tempo da abertura da sucessão;","II - ao herdeiro que estiver na posse e administração dos bens, e, se houver mais de um nessas condições, ao mais velho;","III - ao testamenteiro;","IV - a pessoa de confiança do juiz, na falta ou escusa das indicadas nos incisos antecedentes, ou quando tiverem de ser afastadas por motivo grave levado ao conhecimento do juiz."]]],"3":[["CC, art. 1.798",["Art. 1.798. Legitimam-se a suceder as pessoas nascidas ou já concebidas no momento da abertura da sucessão."]],["CC, art. 1.799",["Art. 1.799. Na sucessão testamentária podem ainda ser chamados a suceder:","I - os filhos, ainda não concebidos, de pessoas indicadas pelo testador, desde que vivas estas ao abrir-se a sucessão;","II - as pessoas jurídicas;","III - as pessoas jurídicas, cuja organização for determinada pelo testador sob a forma de fundação."]],["CC, art. 1.800",["Art. 1.800. No caso do inciso I do artigo antecedente, os bens da herança serão confiados, após a liquidação ou partilha, a curador nomeado pelo juiz.","§ 1º Salvo disposição testamentária em contrário, a curatela caberá à pessoa cujo filho o testador esperava ter por herdeiro, e, sucessivamente, às pessoas indicadas no art. 1.775.","§ 2º Os poderes, deveres e responsabilidades do curador, assim nomeado, regem-se pelas disposições concernentes à curatela dos incapazes, no que couber.","§ 3º Nascendo com vida o herdeiro esperado, ser-lhe-á deferida a sucessão, com os frutos e rendimentos relativos à deixa, a partir da morte do testador.","§ 4º Se, decorridos dois anos após a abertura da sucessão, não for concebido o herdeiro esperado, os bens reservados, salvo disposição em contrário do testador, caberão aos herdeiros legítimos."]],["CC, art. 1.801",["Art. 1.801. Não podem ser nomeados herdeiros nem legatários:","I - a pessoa que, a rogo, escreveu o testamento, nem o seu cônjuge ou companheiro, ou os seus ascendentes e irmãos;","II - as testemunhas do testamento;","III - o concubino do testador casado, salvo se este, sem culpa sua, estiver separado de fato do cônjuge há mais de cinco anos;","IV - o tabelião, civil ou militar, ou o comandante ou escrivão, perante quem se fizer, assim como o que fizer ou aprovar o testamento."]],["CC, art. 1.802",["Art. 1.802. São nulas as disposições testamentárias em favor de pessoas não legitimadas a suceder, ainda quando simuladas sob a forma de contrato oneroso, ou feitas mediante interposta pessoa.","Parágrafo único. Presumem-se pessoas interpostas os ascendentes, os descendentes, os irmãos e o cônjuge ou companheiro do não legitimado a suceder."]],["CC, art. 1.803",["Art. 1.803. É lícita a deixa ao filho do concubino, quando também o for do testador."]]],"4":[["CC, art. 1.804",["Art. 1.804. Aceita a herança, torna-se definitiva a sua transmissão ao herdeiro, desde a abertura da sucessão.","Parágrafo único. A transmissão tem-se por não verificada quando o herdeiro renuncia à herança."]],["CC, art. 1.805",["Art. 1.805. A aceitação da herança, quando expressa, faz-se por declaração escrita; quando tácita, há de resultar tão-somente de atos próprios da qualidade de herdeiro.","§ 1º Não exprimem aceitação de herança os atos oficiosos, como o funeral do finado, os meramente conservatórios, ou os de administração e guarda provisória.","§ 2º Não importa igualmente aceitação a cessão gratuita, pura e simples, da herança, aos demais co-herdeiros."]],["CC, art. 1.806",["Art. 1.806. A renúncia da herança deve constar expressamente de instrumento público ou termo judicial."]],["CC, art. 1.807",["Art. 1.807. O interessado em que o herdeiro declare se aceita, ou não, a herança, poderá, vinte dias após aberta a sucessão, requerer ao juiz prazo razoável, não maior de trinta dias, para, nele, se pronunciar o herdeiro, sob pena de se haver a herança por aceita."]],["CC, art. 1.808",["Art. 1.808. Não se pode aceitar ou renunciar a herança em parte, sob condição ou a termo.","§ 1º O herdeiro, a quem se testarem legados, pode aceitá-los, renunciando a herança; ou, aceitando-a, repudiá-los.","§ 2º O herdeiro, chamado, na mesma sucessão, a mais de um quinhão hereditário, sob títulos sucessórios diversos, pode livremente deliberar quanto aos quinhões que aceita e aos que renuncia."]],["CC, art. 1.809",["Art. 1.809. Falecendo o herdeiro antes de declarar se aceita a herança, o poder de aceitar passa-lhe aos herdeiros, a menos que se trate de vocação adstrita a uma condição suspensiva, ainda não verificada.","Parágrafo único. Os chamados à sucessão do herdeiro falecido antes da aceitação, desde que concordem em receber a segunda herança, poderão aceitar ou renunciar a primeira."]],["CC, art. 1.810",["Art. 1.810. Na sucessão legítima, a parte do renunciante acresce à dos outros herdeiros da mesma classe e, sendo ele o único desta, devolve-se aos da subseqüente."]],["CC, art. 1.811",["Art. 1.811. Ninguém pode suceder, representando herdeiro renunciante. Se, porém, ele for o único legítimo da sua classe, ou se todos os outros da mesma classe renunciarem a herança, poderão os filhos vir à sucessão, por direito próprio, e por cabeça."]],["CC, art. 1.812",["Art. 1.812. São irrevogáveis os atos de aceitação ou de renúncia da herança."]],["CC, art. 1.813",["Art. 1.813. Quando o herdeiro prejudicar os seus credores, renunciando à herança, poderão eles, com autorização do juiz, aceitá-la em nome do renunciante.","§ 1º A habilitação dos credores se fará no prazo de trinta dias seguintes ao conhecimento do fato.","§ 2º Pagas as dívidas do renunciante, prevalece a renúncia quanto ao remanescente, que será devolvido aos demais herdeiros."]]],"5":[["CC, art. 1.814",["Art. 1.814. São excluídos da sucessão os herdeiros ou legatários:","I - que houverem sido autores, co-autores ou partícipes de homicídio doloso, ou tentativa deste, contra a pessoa de cuja sucessão se tratar, seu cônjuge, companheiro, ascendente ou descendente;","II - que houverem acusado caluniosamente em juízo o autor da herança ou incorrerem em crime contra a sua honra, ou de seu cônjuge ou companheiro;","III - que, por violência ou meios fraudulentos, inibirem ou obstarem o autor da herança de dispor livremente de seus bens por ato de última vontade."]],["CC, art. 1.815",["Art. 1.815. A exclusão do herdeiro ou legatário, em qualquer desses casos de indignidade, será declarada por sentença.","§ 1º O direito de demandar a exclusão do herdeiro ou legatário extingue-se em quatro anos, contados da abertura da sucessão. (Parágrafo único transformado em § 1º pela Lei nº 13.532, de 7/12/2017)","§ 2º Na hipótese do inciso I do art. 1.814, o Ministério Público tem legitimidade para demandar a exclusão do herdeiro ou legatário. (Parágrafo acrescido pela Lei nº 13.532, de 7/12/2017)"]],["CC, art. 1.815-A",["Art. 1.815-A. Em qualquer dos casos de indignidade previstos no art. 1.814, o trânsito em julgado da sentença penal condenatória acarretará a imediata exclusão do herdeiro ou legatário indigno, independentemente da sentença prevista no caput do art. 1.815 deste Código. (Artigo acrescido pela Lei nº 14.661, de 23/8/2023)"]],["CC, art. 1.816",["Art. 1.816. São pessoais os efeitos da exclusão; os descendentes do herdeiro excluído sucedem, como se ele morto fosse antes da abertura da sucessão.","Parágrafo único. O excluído da sucessão não terá direito ao usufruto ou à administração dos bens que a seus sucessores couberem na herança, nem à sucessão eventual desses bens."]],["CC, art. 1.817",["Art. 1.817. São válidas as alienações onerosas de bens hereditários a terceiros de boa-fé, e os atos de administração legalmente praticados pelo herdeiro, antes da sentença de exclusão; mas aos herdeiros subsiste, quando prejudicados, o direito de demandar-lhe perdas e danos.","Parágrafo único. O excluído da sucessão é obrigado a restituir os frutos e rendimentos que dos bens da herança houver percebido, mas tem direito a ser indenizado das despesas com a conservação deles."]],["CC, art. 1.818",["Art. 1.818. Aquele que incorreu em atos que determinem a exclusão da herança será admitido a suceder, se o ofendido o tiver expressamente reabilitado em testamento, ou em outro ato autêntico.","Parágrafo único. Não havendo reabilitação expressa, o indigno, contemplado em testamento do ofendido, quando o testador, ao testar, já conhecia a causa da indignidade, pode suceder no limite da disposição testamentária."]],["CC, art. 1.961",["Art. 1.961. Os herdeiros necessários podem ser privados de sua legítima, ou deserdados, em todos os casos em que podem ser excluídos da sucessão."]],["CC, art. 1.962",["Art. 1.962. Além das causas mencionadas no art. 1.814, autorizam a deserdação dos descendentes por seus ascendentes:","I - ofensa física;","II - injúria grave;","III - relações ilícitas com a madrasta ou com o padrasto;","IV - desamparo do ascendente em alienação mental ou grave enfermidade."]],["CC, art. 1.963",["Art. 1.963. Além das causas enumeradas no art. 1.814, autorizam a deserdação dos ascendentes pelos descendentes:","I - ofensa física;","II - injúria grave;","III - relações ilícitas com a mulher ou companheira do filho ou a do neto, ou com o marido ou companheiro da filha ou o da neta;","IV - desamparo do filho ou neto com deficiência mental ou grave enfermidade."]],["CC, art. 1.964",["Art. 1.964. Somente com expressa declaração de causa pode a deserdação ser ordenada em testamento."]],["CC, art. 1.965",["Art. 1.965. Ao herdeiro instituído, ou àquele a quem aproveite a deserdação, incumbe provar a veracidade da causa alegada pelo testador.","Parágrafo único. O direito de provar a causa da deserdação extingue-se no prazo de quatro anos, a contar da data da abertura do testamento."]]],"6":[["CC, art. 1.819",["Art. 1.819. Falecendo alguém sem deixar testamento nem herdeiro legítimo notoriamente conhecido, os bens da herança, depois de arrecadados, ficarão sob a guarda e administração de um curador, até a sua entrega ao sucessor devidamente habilitado ou à declaração de sua vacância."]],["CC, art. 1.820",["Art. 1.820. Praticadas as diligências de arrecadação e ultimado o inventário, serão expedidos editais na forma da lei processual, e, decorrido um ano de sua primeira publicação, sem que haja herdeiro habilitado, ou penda habilitação, será a herança declarada vacante."]],["CC, art. 1.821",["Art. 1.821. É assegurado aos credores o direito de pedir o pagamento das dívidas reconhecidas, nos limites das forças da herança."]],["CC, art. 1.822",["Art. 1.822. A declaração de vacância da herança não prejudicará os herdeiros que legalmente se habilitarem; mas, decorridos cinco anos da abertura da sucessão, os bens arrecadados passarão ao domínio do Município ou do Distrito Federal, se localizados nas respectivas circunscrições, incorporando-se ao domínio da União quando situados em território federal.","Parágrafo único. Não se habilitando até a declaração de vacância, os colaterais ficarão excluídos da sucessão."]],["CC, art. 1.823",["Art. 1.823. Quando todos os chamados a suceder renunciarem à herança, será esta desde logo declarada vacante."]],["CC, art. 1.824",["Art. 1.824. O herdeiro pode, em ação de petição de herança, demandar o reconhecimento de seu direito sucessório, para obter a restituição da herança, ou de parte dela, contra quem, na qualidade de herdeiro, ou mesmo sem título, a possua."]],["CC, art. 1.825",["Art. 1.825. A ação de petição de herança, ainda que exercida por um só dos herdeiros, poderá compreender todos os bens hereditários."]],["CC, art. 1.826",["Art. 1.826. O possuidor da herança está obrigado à restituição dos bens do acervo, fixando-se-lhe a responsabilidade segundo a sua posse, observado o disposto nos arts. 1.214 a 1.222.","Parágrafo único. A partir da citação, a responsabilidade do possuidor se há de aferir pelas regras concernentes à posse de má-fé e à mora."]],["CC, art. 1.827",["Art. 1.827. O herdeiro pode demandar os bens da herança, mesmo em poder de terceiros, sem prejuízo da responsabilidade do possuidor originário pelo valor dos bens alienados.","Parágrafo único. São eficazes as alienações feitas, a título oneroso, pelo herdeiro aparente a terceiro de boa-fé."]],["CC, art. 1.828",["Art. 1.828. O herdeiro aparente, que de boa-fé houver pago um legado, não está obrigado a prestar o equivalente ao verdadeiro sucessor, ressalvado a este o direito de proceder contra quem o recebeu."]]],"7":[["CC, art. 1.829",["Art. 1.829. A sucessão legítima defere-se na ordem seguinte:","I - aos descendentes, em concorrência com o cônjuge sobrevivente, salvo se casado este com o falecido no regime da comunhão universal, ou no da separação obrigatória de bens (art. 1.640, parágrafo único); ou se, no regime da comunhão parcial, o autor da herança não houver deixado bens particulares;","II - aos ascendentes, em concorrência com o cônjuge;","III - ao cônjuge sobrevivente;","IV - aos colaterais."]]],"8":[["CC, art. 1.829",["Art. 1.829. A sucessão legítima defere-se na ordem seguinte:","I - aos descendentes, em concorrência com o cônjuge sobrevivente, salvo se casado este com o falecido no regime da comunhão universal, ou no da separação obrigatória de bens (art. 1.640, parágrafo único); ou se, no regime da comunhão parcial, o autor da herança não houver deixado bens particulares;","II - aos ascendentes, em concorrência com o cônjuge;","III - ao cônjuge sobrevivente;","IV - aos colaterais."]],["CC, art. 1.790",["Art. 1.790. A companheira ou o companheiro participará da sucessão do outro, quanto aos bens adquiridos onerosamente na vigência da união estável, nas condições seguintes:","I - se concorrer com filhos comuns, terá direito a uma quota equivalente à que por lei for atribuída ao filho;","II - se concorrer com descendentes só do autor da herança, tocar-lhe-á a metade do que couber a cada um daqueles;","III - se concorrer com outros parentes sucessíveis, terá direito a um terço da herança;","IV - não havendo parentes sucessíveis, terá direito à totalidade da herança."]]],"9":[["CC, art. 1.845",["Art. 1.845. São herdeiros necessários os descendentes, os ascendentes e o cônjuge."]],["CC, art. 1.846",["Art. 1.846. Pertence aos herdeiros necessários, de pleno direito, a metade dos bens da herança, constituindo a legítima."]],["CC, art. 1.847",["Art. 1.847. Calcula-se a legítima sobre o valor dos bens existentes na abertura da sucessão, abatidas as dívidas e as despesas do funeral, adicionando-se, em seguida, o valor dos bens sujeitos a colação."]],["CC, art. 1.848",["Art. 1.848. Salvo se houver justa causa, declarada no testamento, não pode o testador estabelecer cláusula de inalienabilidade, impenhorabilidade, e de incomunicabilidade, sobre os bens da legítima.","§ 1º Não é permitido ao testador estabelecer a conversão dos bens da legítima em outros de espécie diversa.","§ 2º Mediante autorização judicial e havendo justa causa, podem ser alienados os bens gravados, convertendo-se o produto em outros bens, que ficarão sub-rogados nos ônus dos primeiros."]],["CC, art. 1.849",["Art. 1.849. O herdeiro necessário, a quem o testador deixar a sua parte disponível, ou algum legado, não perderá o direito à legítima."]],["CC, art. 1.850",["Art. 1.850. Para excluir da sucessão os herdeiros colaterais, basta que o testador disponha de seu patrimônio sem os contemplar."]]],"10":[["CC, art. 1.851",["Art. 1.851. Dá-se o direito de representação, quando a lei chama certos parentes do falecido a suceder em todos os direitos, em que ele sucederia, se vivo fosse."]],["CC, art. 1.852",["Art. 1.852. O direito de representação dá-se na linha reta descendente, mas nunca na ascendente."]],["CC, art. 1.853",["Art. 1.853. Na linha transversal, somente se dá o direito de representação em favor dos filhos de irmãos do falecido, quando com irmãos deste concorrerem."]],["CC, art. 1.854",["Art. 1.854. Os representantes só podem herdar, como tais, o que herdaria o representado, se vivo fosse."]],["CC, art. 1.855",["Art. 1.855. O quinhão do representado partir-se-á por igual entre os representantes."]],["CC, art. 1.856",["Art. 1.856. O renunciante à herança de uma pessoa poderá representá-la na sucessão de outra.","TITULO III","DA SUCESSÃO TESTAMENTÁRIA","CAPITULO I","DO TESTAMENTO EM GERAL"]]],"11":[["CC, art. 1.857",["Art. 1.857. Toda pessoa capaz pode dispor, por testamento, da totalidade dos seus bens, ou de parte deles, para depois de sua morte.","§ 1º A legítima dos herdeiros necessários não poderá ser incluída no testamento.","§ 2º São válidas as disposições testamentárias de caráter não patrimonial, ainda que o testador somente a elas se tenha limitado."]],["CC, art. 1.858",["Art. 1.858. O testamento é ato personalíssimo, podendo ser mudado a qualquer tempo."]],["CC, art. 1.859",["Art. 1.859. Extingue-se em cinco anos o direito de impugnar a validade do testamento, contado o prazo da data do seu registro."]],["CC, art. 1.860",["Art. 1.860. Além dos incapazes, não podem testar os que, no ato de fazê-lo, não tiverem pleno discernimento.","Parágrafo único. Podem testar os maiores de dezesseis anos."]],["CC, art. 1.861",["Art. 1.861. A incapacidade superveniente do testador não invalida o testamento, nem o testamento do incapaz se valida com a superveniência da capacidade."]],["CC, art. 1.862",["Art. 1.862. São testamentos ordinários:","I - o público;","II - o cerrado;","III - o particular."]],["CC, art. 1.863",["Art. 1.863. É proibido o testamento conjuntivo, seja simultâneo, recíproco ou correspectivo."]],["CC, art. 1.864",["Art. 1.864. São requisitos essenciais do testamento público:","I - ser escrito por tabelião ou por seu substituto legal em seu livro de notas, de acordo com as declarações do testador, podendo este servir-se de minuta, notas ou apontamentos;","II - lavrado o instrumento, ser lido em voz alta pelo tabelião ao testador e a duas testemunhas, a um só tempo; ou pelo testador, se o quiser, na presença destas e do oficial;","III - ser o instrumento, em seguida à leitura, assinado pelo testador, pelas testemunhas e pelo tabelião.","Parágrafo único. O testamento público pode ser escrito manualmente ou mecanicamente, bem como ser feito pela inserção da declaração de vontade em partes impressas de livro de notas, desde que rubricadas todas as páginas pelo testador, se mais de uma."]],["CC, art. 1.865",["Art. 1.865. Se o testador não souber, ou não puder assinar, o tabelião ou seu substituto legal assim o declarará, assinando, neste caso, pelo testador, e, a seu rogo, uma das testemunhas instrumentárias."]],["CC, art. 1.866",["Art. 1.866. O indivíduo inteiramente surdo, sabendo ler, lerá o seu testamento, e, se não o souber, designará quem o leia em seu lugar, presentes as testemunhas."]],["CC, art. 1.867",["Art. 1.867. Ao cego só se permite o testamento público, que lhe será lido, em voz alta, duas vezes, uma pelo tabelião ou por seu substituto legal, e a outra por uma das testemunhas, designada pelo testador, fazendo-se de tudo circunstanciada menção no testamento."]],["CC, art. 1.868",["Art. 1.868. O testamento escrito pelo testador, ou por outra pessoa, a seu rogo, e por aquele assinado, será válido se aprovado pelo tabelião ou seu substituto legal, observadas as seguintes formalidades:","I - que o testador o entregue ao tabelião em presença de duas testemunhas;","II - que o testador declare que aquele é o seu testamento e quer que seja aprovado;","III - que o tabelião lavre, desde logo, o auto de aprovação, na presença de duas testemunhas, e o leia, em seguida, ao testador e testemunhas;","IV - que o auto de aprovação seja assinado pelo tabelião, pelas testemunhas e pelo testador.","Parágrafo único. O testamento cerrado pode ser escrito mecanicamente, desde que seu subscritor numere e autentique, com a sua assinatura, todas as paginas."]],["CC, art. 1.869",["Art. 1.869. O tabelião deve começar o auto de aprovação imediatamente depois da última palavra do testador, declarando, sob sua fé, que o testador lhe entregou para ser aprovado na presença das testemunhas; passando a cerrar e coser o instrumento aprovado.","Parágrafo único. Se não houver espaço na última folha do testamento, para início da aprovação, o tabelião aporá nele o seu sinal público, mencionando a circunstância no auto."]],["CC, art. 1.870",["Art. 1.870. Se o tabelião tiver escrito o testamento a rogo do testador, poderá, não obstante, aprová-lo."]],["CC, art. 1.871",["Art. 1.871. O testamento pode ser escrito em língua nacional ou estrangeira, pelo próprio testador, ou por outrem, a seu rogo."]],["CC, art. 1.872",["Art. 1.872. Não pode dispor de seus bens em testamento cerrado quem não saiba ou não possa ler."]],["CC, art. 1.873",["Art. 1.873. Pode fazer testamento cerrado o surdo-mudo, contanto que o escreva todo, e o assine de sua mão, e que, ao entregá-lo ao oficial público, ante as duas testemunhas, escreva, na face externa do papel ou do envoltório, que aquele é o seu testamento, cuja aprovação lhe pede."]],["CC, art. 1.874",["Art. 1.874. Depois de aprovado e cerrado, será o testamento entregue ao testador, e o tabelião lançará, no seu livro, nota do lugar, dia, mês e ano em que o testamento foi aprovado e entregue."]],["CC, art. 1.875",["Art. 1.875. Falecido o testador, o testamento será apresentado ao juiz, que o abrirá e o fará registrar, ordenando seja cumprido, se não achar vício externo que o torne eivado de nulidade ou suspeito de falsidade."]],["CC, art. 1.876",["Art. 1.876. O testamento particular pode ser escrito de próprio punho ou mediante processo mecânico.","§ 1º Se escrito de próprio punho, são requisitos essenciais à sua validade seja lido e assinado por quem o escreveu, na presença de pelo menos três testemunhas, que o devem subscrever.","§ 2º Se elaborado por processo mecânico, não pode conter rasuras ou espaços em branco, devendo ser assinado pelo testador, depois de o ter lido na presença de pelo menos três testemunhas, que o subscreverão."]],["CC, art. 1.877",["Art. 1.877. Morto o testador, publicar-se-á em juízo o testamento, com citação dos herdeiros legítimos."]],["CC, art. 1.878",["Art. 1.878. Se as testemunhas forem contestes sobre o fato da disposição, ou, ao menos, sobre a sua leitura perante elas, e se reconhecerem as próprias assinaturas, assim como a do testador, o testamento será confirmado.","Parágrafo único. Se faltarem testemunhas, por morte ou ausência, e se pelo menos uma delas o reconhecer, o testamento poderá ser confirmado, se, a critério do juiz, houver prova suficiente de sua veracidade."]],["CC, art. 1.879",["Art. 1.879. Em circunstâncias excepcionais declaradas na cédula, o testamento particular de próprio punho e assinado pelo testador, sem testemunhas, poderá ser confirmado, a critério do juiz."]],["CC, art. 1.880",["Art. 1.880. O testamento particular pode ser escrito em língua estrangeira, contanto que as testemunhas a compreendam."]],["CC, art. 1.860",["Art. 1.860. Além dos incapazes, não podem testar os que, no ato de fazê-lo, não tiverem pleno discernimento.","Parágrafo único. Podem testar os maiores de dezesseis anos."]]],"12":[["CC, art. 1.881",["Art. 1.881. Toda pessoa capaz de testar poderá, mediante escrito particular seu, datado e assinado, fazer disposições especiais sobre o seu enterro, sobre esmolas de pouca monta a certas e determinadas pessoas, ou, indeterminadamente, aos pobres de certo lugar, assim como legar móveis, roupas ou jóias, de pouco valor, de seu uso pessoal."]],["CC, art. 1.882",["Art. 1.882. Os atos a que se refere o artigo antecedente, salvo direito de terceiro, valerão como codicilos, deixe ou não testamento o autor."]],["CC, art. 1.883",["Art. 1.883. Pelo modo estabelecido no art. 1.881, poder-se-ão nomear ou substituir testamenteiros."]],["CC, art. 1.884",["Art. 1.884. Os atos previstos nos artigos antecedentes revogam-se por atos iguais, e consideram-se revogados, se, havendo testamento posterior, de qualquer natureza, este os não confirmar ou modificar."]],["CC, art. 1.885",["Art. 1.885. Se estiver fechado o codicilo, abrir-se-á do mesmo modo que o testamento cerrado."]],["CC, art. 1.886",["Art. 1.886. São testamentos especiais:","I - o marítimo;","II - o aeronáutico;","III - o militar."]],["CC, art. 1.887",["Art. 1.887. Não se admitem outros testamentos especiais além dos contemplados neste Código."]],["CC, art. 1.888",["Art. 1.888. Quem estiver em viagem, a bordo de navio nacional, de guerra ou mercante, pode testar perante o comandante, em presença de duas testemunhas, por forma que corresponda ao testamento público ou ao cerrado.","Parágrafo único. O registro do testamento será feito no diário de bordo."]],["CC, art. 1.889",["Art. 1.889. Quem estiver em viagem, a bordo de aeronave militar ou comercial, pode testar perante pessoa designada pelo comandante, observado o disposto no artigo antecedente."]],["CC, art. 1.890",["Art. 1.890. O testamento marítimo ou aeronáutico ficará sob a guarda do comandante, que o entregará às autoridades administrativas do primeiro porto ou aeroporto nacional, contra recibo averbado no diário de bordo."]],["CC, art. 1.891",["Art. 1.891. Caducará o testamento marítimo, ou aeronáutico, se o testador não morrer na viagem, nem nos noventa dias subseqüentes ao seu desembarque em terra, onde possa fazer, na forma ordinária, outro testamento."]],["CC, art. 1.892",["Art. 1.892. Não valerá o testamento marítimo, ainda que feito no curso de uma viagem, se, ao tempo em que se fez, o navio estava em porto onde o testador pudesse desembarcar e testar na forma ordinária."]],["CC, art. 1.893",["Art. 1.893. O testamento dos militares e demais pessoas a serviço das Forças Armadas em campanha, dentro do País ou fora dele, assim como em praça sitiada, ou que esteja de comunicações interrompidas, poderá fazer-se, não havendo tabelião ou seu substituto legal, ante duas, ou três testemunhas, se o testador não puder, ou não souber assinar, caso em que assinará por ele uma delas.","§ 1º Se o testador pertencer a corpo ou seção de corpo destacado, o testamento será escrito pelo respectivo comandante, ainda que de graduação ou posto inferior.","§ 2º Se o testador estiver em tratamento em hospital, o testamento será escrito pelo respectivo oficial de saúde, ou pelo diretor do estabelecimento.","§ 3º Se o testador for o oficial mais graduado, o testamento será escrito por aquele que o substituir."]],["CC, art. 1.894",["Art. 1.894. Se o testador souber escrever, poderá fazer o testamento de seu punho, contanto que o date e assine por extenso, e o apresente aberto ou cerrado, na presença de duas testemunhas ao auditor, ou ao oficial de patente, que lhe faça as vezes neste mister.","Parágrafo único. O auditor, ou o oficial a quem o testamento se apresente notará, em qualquer parte dele, lugar, dia, mês e ano, em que lhe for apresentado, nota esta que será assinada por ele e pelas testemunhas."]],["CC, art. 1.895",["Art. 1.895. Caduca o testamento militar, desde que, depois dele, o testador esteja, noventa dias seguidos, em lugar onde possa testar na forma ordinária, salvo se esse testamento apresentar as solenidades prescritas no parágrafo único do artigo antecedente."]],["CC, art. 1.896",["Art. 1.896. As pessoas designadas no art. 1.893, estando empenhadas em combate, ou feridas, podem testar oralmente, confiando a sua última vontade a duas testemunhas.","Parágrafo único. Não terá efeito o testamento se o testador não morrer na guerra ou convalescer do ferimento."]]],"14":[["CC, art. 1.969",["Art. 1.969. O testamento pode ser revogado pelo mesmo modo e forma como pode ser feito."]],["CC, art. 1.970",["Art. 1.970. A revogação do testamento pode ser total ou parcial.","Parágrafo único. Se parcial, ou se o testamento posterior não contiver cláusula revogatória expressa, o anterior subsiste em tudo que não for contrário ao posterior."]],["CC, art. 1.971",["Art. 1.971. A revogação produzirá seus efeitos, ainda quando o testamento, que a encerra, vier a caducar por exclusão, incapacidade ou renúncia do herdeiro nele nomeado; não valerá, se o testamento revogatório for anulado por omissão ou infração de solenidades essenciais ou por vícios intrínsecos."]],["CC, art. 1.972",["Art. 1.972. O testamento cerrado que o testador abrir ou dilacerar, ou for aberto ou dilacerado com seu consentimento, haver-se-á como revogado."]],["CC, art. 1.973",["Art. 1.973. Sobrevindo descendente sucessível ao testador, que não o tinha ou não o conhecia quando testou, rompe-se o testamento em todas as suas disposições, se esse descendente sobreviver ao testador."]],["CC, art. 1.974",["Art. 1.974. Rompe-se também o testamento feito na ignorância de existirem outros herdeiros necessários."]],["CC, art. 1.975",["Art. 1.975. Não se rompe o testamento, se o testador dispuser da sua metade, não contemplando os herdeiros necessários de cuja existência saiba, ou quando os exclua dessa parte."]],["CC, art. 1.976",["Art. 1.976. O testador pode nomear um ou mais testamenteiros, conjuntos ou separados, para lhe darem cumprimento às disposições de última vontade."]],["CC, art. 1.977",["Art. 1.977. O testador pode conceder ao testamenteiro a posse e a administração da herança, ou de parte dela, não havendo cônjuge ou herdeiros necessários.","Parágrafo único. Qualquer herdeiro pode requerer partilha imediata, ou devolução da herança, habilitando o testamenteiro com os meios necessários para o cumprimento dos legados, ou dando caução de prestá-los."]],["CC, art. 1.978",["Art. 1.978. Tendo o testamenteiro a posse e a administração dos bens, incumbe-lhe requerer inventário e cumprir o testamento."]],["CC, art. 1.979",["Art. 1.979. O testamenteiro nomeado, ou qualquer parte interessada, pode requerer, assim como o juiz pode ordenar, de ofício, ao detentor do testamento, que o leve a registro."]],["CC, art. 1.980",["Art. 1.980. O testamenteiro é obrigado a cumprir as disposições testamentárias, no prazo marcado pelo testador, e a dar contas do que recebeu e despendeu, subsistindo sua responsabilidade enquanto durar a execução do testamento."]],["CC, art. 1.981",["Art. 1.981. Compete ao testamenteiro, com ou sem o concurso do inventariante e dos herdeiros instituídos, defender a validade do testamento."]],["CC, art. 1.982",["Art. 1.982. Além das atribuições exaradas nos artigos antecedentes, terá o testamenteiro as que lhe conferir o testador, nos limites da lei."]],["CC, art. 1.983",["Art. 1.983. Não concedendo o testador prazo maior, cumprirá o testamenteiro o testamento e prestará contas em cento e oitenta dias, contados da aceitação da testamentaria.","Parágrafo único. Pode esse prazo ser prorrogado se houver motivo suficiente."]],["CC, art. 1.984",["Art. 1.984. Na falta de testamenteiro nomeado pelo testador, a execução testamentária compete a um dos cônjuges, e, em falta destes, ao herdeiro nomeado pelo juiz."]],["CC, art. 1.985",["Art. 1.985. O encargo da testamentaria não se transmite aos herdeiros do testamenteiro, nem é delegável; mas o testamenteiro pode fazer-se representar em juízo e fora dele, mediante mandatário com poderes especiais."]],["CC, art. 1.986",["Art. 1.986. Havendo simultaneamente mais de um testamenteiro, que tenha aceitado o cargo, poderá cada qual exercê-lo, em falta dos outros; mas todos ficam solidariamente obrigados a dar conta dos bens que lhes forem confiados, salvo se cada um tiver, pelo testamento, funções distintas, e a elas se limitar."]],["CC, art. 1.987",["Art. 1.987. Salvo disposição testamentária em contrário, o testamenteiro, que não seja herdeiro ou legatário, terá direito a um prêmio, que, se o testador não o houver fixado, será de um a cinco por cento, arbitrado pelo juiz, sobre a herança líquida, conforme a importância dela e maior ou menor dificuldade na execução do testamento.","Parágrafo único. O prêmio arbitrado será pago à conta da parte disponível, quando houver herdeiro necessário."]],["CC, art. 1.988",["Art. 1.988. O herdeiro ou o legatário nomeado testamenteiro poderá preferir o prêmio à herança ou ao legado."]],["CC, art. 1.989",["Art. 1.989. Reverterá à herança o prêmio que o testamenteiro perder, por ser removido ou por não ter cumprido o testamento."]],["CC, art. 1.990",["Art. 1.990. Se o testador tiver distribuído toda a herança em legados, exercerá o testamenteiro as funções de inventariante."]]],"15":[["CC, art. 1.991",["Art. 1.991. Desde a assinatura do compromisso até a homologação da partilha, a administração da herança será exercida pelo inventariante."]],["CC, art. 1.992",["Art.1.992. O herdeiro que sonegar bens da herança, não os descrevendo no inventário quando estejam em seu poder, ou, com o seu conhecimento, no de outrem, ou que os omitir na colação, a que os deva levar, ou que deixar de restituí-los, perderá o direito que sobre eles lhe cabia."]],["CC, art. 1.993",["Art. 1.993. Além da pena cominada no artigo antecedente, se o sonegador for o próprio inventariante, remover-se-á, em se provando a sonegação, ou negando ele a existência dos bens, quando indicados."]],["CC, art. 1.994",["Art.1.994. A pena de sonegados só se pode requerer e impor em ação movida pelos herdeiros ou pelos credores da herança.","Parágrafo único. A sentença que se proferir na ação de sonegados, movida por qualquer dos herdeiros ou credores, aproveita aos demais interessados."]],["CC, art. 1.995",["Art. 1.995. Se não se restituírem os bens sonegados, por já não os ter o sonegador em seu poder, pagará ele a importância dos valores que ocultou, mais as perdas e danos."]],["CC, art. 1.996",["Art. 1.996. Só se pode argüir de sonegação o inventariante depois de encerrada a descrição dos bens, com a declaração, por ele feita, de não existirem outros por inventariar e partir, assim como argüir o herdeiro, depois de declarar-se no inventário que não os possui."]],["CC, art. 1.997",["Art. 1.997. A herança responde pelo pagamento das dívidas do falecido; mas, feita a partilha, só respondem os herdeiros, cada qual em proporção da parte que na herança lhe coube.","§ 1º Quando, antes da partilha, for requerido no inventário o pagamento de dívidas constantes de documentos, revestidos de formalidades legais, constituindo prova bastante da obrigação, e houver impugnação, que não se funde na alegação de pagamento, acompanhada de prova valiosa, o juiz mandará reservar, em poder do inventariante, bens suficientes para solução do débito, sobre os quais venha a recair oportunamente a execução.","§ 2º No caso previsto no parágrafo antecedente, o credor será obrigado a iniciar a ação de cobrança no prazo de trinta dias, sob pena de se tornar de nenhum efeito a providência indicada."]],["CC, art. 1.998",["Art. 1.998. As despesas funerárias, haja ou não herdeiros legítimos, sairão do monte da herança; mas as de sufrágios por alma do falecido só obrigarão a herança quando ordenadas em testamento ou codicilo."]],["CC, art. 1.999",["Art. 1.999. Sempre que houver ação regressiva de uns contra outros herdeiros, a parte do co-herdeiro insolvente dividir-se-á em proporção entre os demais."]],["CC, art. 2.000",["Art. 2.000. Os legatários e credores da herança podem exigir que do patrimônio do falecido se discrimine o do herdeiro, e, em concurso com os credores deste, ser-lhes-ão preferidos no pagamento."]],["CC, art. 2.001",["Art. 2.001. Se o herdeiro for devedor ao espólio, sua dívida será partilhada igualmente entre todos, salvo se a maioria consentir que o débito seja imputado inteiramente no quinhão do devedor."]],["CC, art. 2.002",["Art. 2.002. Os descendentes que concorrerem à sucessão do ascendente comum são obrigados, para igualar as legítimas, a conferir o valor das doações que dele em vida receberam, sob pena de sonegação.","Parágrafo único. Para cálculo da legítima, o valor dos bens conferidos será computado na parte indisponível, sem aumentar a disponível."]],["CC, art. 2.003",["Art. 2.003. A colação tem por fim igualar, na proporção estabelecida neste Código, as legítimas dos descendentes e do cônjuge sobrevivente, obrigando também os donatários que, ao tempo do falecimento do doador, já não possuírem os bens doados.","Parágrafo único. Se, computados os valores das doações feitas em adiantamento de legítima, não houver no acervo bens suficientes para igualar as legítimas dos descendentes e do cônjuge, os bens assim doados serão conferidos em espécie, ou, quando deles já não disponha o donatário, pelo seu valor ao tempo da liberalidade."]],["CC, art. 2.004",["Art. 2.004. O valor de colação dos bens doados será aquele, certo ou estimativo, que lhes atribuir o ato de liberalidade.","§ 1º Se do ato de doação não constar valor certo, nem houver estimação feita naquela época, os bens serão conferidos na partilha pelo que então se calcular valessem ao tempo da liberalidade.","§ 2º Só o valor dos bens doados entrará em colação; não assim o das benfeitorias acrescidas, as quais pertencerão ao herdeiro donatário, correndo também à conta deste os rendimentos ou lucros, assim como os danos e perdas que eles sofrerem."]],["CC, art. 2.005",["Art. 2.005. São dispensadas da colação as doações que o doador determinar saiam da parte disponível, contanto que não a excedam, computado o seu valor ao tempo da doação.","Parágrafo único. Presume-se imputada na parte disponível a liberalidade feita a descendente que, ao tempo do ato, não seria chamado à sucessão na qualidade de herdeiro necessário."]],["CC, art. 2.006",["Art. 2.006. A dispensa da colação pode ser outorgada pelo doador em testamento, ou no próprio título de liberalidade."]],["CC, art. 2.007",["Art. 2.007. São sujeitas à redução as doações em que se apurar excesso quanto ao que o doador poderia dispor, no momento da liberalidade.","§ 1º O excesso será apurado com base no valor que os bens doados tinham, no momento da liberalidade.","§ 2º A redução da liberalidade far-se-á pela restituição ao monte do excesso assim apurado; a restituição será em espécie, ou, se não mais existir o bem em poder do donatário, em dinheiro, segundo o seu valor ao tempo da abertura da sucessão, observadas, no que forem aplicáveis, as regras deste Código sobre a redução das disposições testamentárias.","§ 3º Sujeita-se a redução, nos termos do parágrafo antecedente, a parte da doação feita a herdeiros necessários que exceder a legítima e mais a quota disponível.","§ 4º Sendo várias as doações a herdeiros necessários, feitas em diferentes datas, serão elas reduzidas a partir da última, até a eliminação do excesso."]],["CC, art. 2.008",["Art. 2.008. Aquele que renunciou a herança ou dela foi excluído, deve, não obstante, conferir as doações recebidas, para o fim de repor o que exceder o disponível."]],["CC, art. 2.009",["Art. 2.009. Quando os netos, representando os seus pais, sucederem aos avós, serão obrigados a trazer à colação, ainda que não o hajam herdado, o que os pais teriam de conferir."]],["CC, art. 2.010",["Art. 2.010. Não virão à colação os gastos ordinários do ascendente com o descendente, enquanto menor, na sua educação, estudos, sustento, vestuário, tratamento nas enfermidades, enxoval, assim como as despesas de casamento, ou as feitas no interesse de sua defesa em processo-crime."]],["CC, art. 2.011",["Art. 2.011. As doações remuneratórias de serviços feitos ao ascendente também não estão sujeitas a colação."]],["CC, art. 2.012",["Art. 2.012. Sendo feita a doação por ambos os cônjuges, no inventário de cada um se conferirá por metade."]]],"16":[["CC, art. 1.831",["Art. 1.831. Ao cônjuge sobrevivente, qualquer que seja o regime de bens, será assegurado, sem prejuízo da participação que lhe caiba na herança, o direito real de habitação relativamente ao imóvel destinado à residência da família, desde que seja o único daquela natureza a inventariar."]]]}};})(window);
